INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xocomil/fullstack-dinos/angular-forms', 'angular-forms', 'xocomil', 'fullstack-dinos', 'community', 'angular-forms xocomil fullstack-dinos community angular-forms enables developers to build type-safe, reactive forms using Angular''s Signal Forms API, providing automatic two-way binding and schema-based validation. Angular Signal Forms 提供自动双向绑定、基于模式的验证和响应式字段状态 Angular Signal Forms は自動二重バインディング、スキーマベースの検証、リアクティブフィールド状態を提供する Angular Signal Forms 는 자동 양방향 바인딩, 스키마 기반 유효성 검사 및 반응형 필드 상태를 제공합니다 La API de Signal Forms de Angular permite crear formularios reactivos y seguros con enlace de datos automático y validación basada en esquemas L''API Signal Forms d''Angular permet de créer des formulaires réactifs et sécurisés avec un lien de données automatique et une validation basée sur des schémas Die Signal-Forms-API von Angular ermöglicht die Erstellung reaktiver und sicherer Formulare mit automatischer Datenbindung und schema-basierter Validierung O Signal Forms API do Angular permite criar formulários reativos e seguros. Aprenda a configurar e utilizar esta tecnologia. Signal Forms API в Angular позволяет создавать реактивные и безопасные формы. Узнайте, как настроить и использовать эту технологию. يسمح Signal Forms API في Angular بإنشاء نماذج متفاعلة وآمنة. تعلم كيفية إعداد وتشغيل هذه التكنولوجيا. how to use angular-forms angular-forms tutorial angular-forms vs reactive forms angular-forms install guide angular-forms setup tutorial what is angular-forms angular-forms alternative angular signal forms api Angular Signal Forms Angular 表单设置 Signal Forms 最佳实践 响应式表单 类型安全 自动双向绑定 AIエージェント Provides automatic two-way binding using Angular''s Signal Forms API Offers schema-based validation for reactive forms Supports reactive field state management Enables building of type-safe forms using TypeScript Includes experimental features in Angular v21 angular-forms is a feature of Angular that provides a way to build type-safe, reactive forms using the Signal Forms API, offering automatic two-way binding and schema-based validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lbruton/StakTrakr/retail-provider-fix', 'community', 'lbruton', 'StakTrakr', 'lbruton/StakTrakr', 'retail-provider-fix', 2, 1, 42, '2026-02-26T11:50:11Z', '2026-03-06T07:06:56.266Z', '4451ecad7e37dcdadc6a99f0333cf61d37edc71d5b928453a62bebe510febc51', '{"id":"lbruton/StakTrakr/retail-provider-fix","name":"retail-provider-fix","description":{"en":"The retail-provider-fix skill diagnoses and fixes scraping failures for individual dealers in the StakTrakr retail pipeline, running entirely in the browser. It benefits developers and users of precious metals portfolio trackers.","zh":"零售提供商修复工具是一种强大的诊断和修复工具，用于解决StakTrakr零售管道中的抓取失败问题。它运行在Fly.io容器中，使用Firecrawl进行诊断","ja":"Retail Provider Fixは、StakTrakrの小売パイプラインにおけるスクラピング失敗を診断して修復する強力なツールです。Fly.ioコンテナ内で実行され、Firecrawlを使用して診断します","ko":"零售 공급자 수정 도구는 StakTrakr의 소매 파이프라인에서 스크래핑 실패를 진단하고 수정하는 강력한 도구입니다. Fly.io 컨테이너에서 실행되며 Firecrawl을 사용하여 진단합니다","es":"Retail-provider-fix es una herramienta para diagnosticar y solucionar errores de scrap en la canalización de retail de StakTrakr. Se ejecuta dentro del contenedor de Fly.io","fr":"Retail-provider-fix est un outil pour diagnostiquer et corriger les échecs de scraping dans le pipeline de vente au détail de StakTrakr. Il s''exécute à l''intérieur du conteneur Fly.io","de":"Retail-provider-fix ist ein Tool zum Diagnose und Behebung von Scraping-Fehlern im Einzelhandels-Pipeline von StakTrakr. Es läuft innerhalb des Fly.io-Containers","pt":"O Retail Provider Fix é uma ferramenta poderosa para diagnosticar e corrigir falhas de scraping para dealers individuais na pipeline de varejo StakTrakr","ru":"Retail Provider Fix - это мощный инструмент для диагностики и исправления ошибок скрапинга для отдельных дилеров в розничной трубопроводе StakTrakr","ar":"Retail Provider Fix هو أداة قوية لتشخيص وأصلاح عيوب الحصاد للوكلاء الفرديين في خط 