INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rudironsoni/Synaxis/dotnet-add-testing', 'dotnet-add-testing', 'rudironsoni', 'Synaxis', 'community', 'dotnet-add-testing rudironsoni Synaxis community dotnet-add-testing adds test infrastructure to .NET projects, creating test projects with xUnit and configuring code coverage. This skill benefits .NET developers by streamlining test setup. dotnet-add-testing 为 .NET 项目添加测试基础设施，包括 xUnit 和 coverlet dotnet-add-testing は、.NET プロジェクトに xUnit と coverlet を含むテストインフラストラクチャを追加 dotnet-add-testing는 .NET 프로젝트에 xUnit 및 coverlet를 포함한 테스트 인프라를 추가 dotnet-add-testing agrega infraestructura de pruebas a proyectos .NET existentes con xUnit y coverlet dotnet-add-testing ajoute une infrastructure de test aux projets .NET existants avec xUnit et coverlet dotnet-add-testing fügt Testinfrastruktur zu bestehenden .NET-Projekten mit xUnit und coverlet hinzu O dotnet-add-testing adiciona infraestrutura de testes ao seu projeto .NET, criando projetos de teste com xUnit e configurando cobertura de código com coverlet dotnet-add-testing добавляет инфраструктуру тестирования в ваш проект .NET, создавая тестовые проекты с xUnit и настраивая покрытие кода с coverlet يضيف dotnet-add-testing بنية اختبار إلى مشروع .NET الخاص بك، حيث ينشئ مشاريع اختبار مع xUnit ويفعل تغطية التعليمات البرمجية مع coverlet how to use dotnet-add-testing dotnet-add-testing setup guide dotnet-add-testing alternative dotnet-add-testing vs nunit dotnet-add-testing install what is dotnet-add-testing dotnet-add-testing xunit dotnet-add-testing coverlet dotnet test infrastructure dotnet-add-testing xUnit coverlet .NET 测试 AI 工具 测试基础设施 代码覆盖率 传统目录结构 Creates test projects with xUnit Configures code coverage with coverlet Sets up conventional directory structure (tests/ mirroring src/) Wires project references and test SDK configuration Supports test project creation with xUnit and coverlet dotnet-add-testing is a skill that adds test infrastructure scaffolding to existing .NET projects, including test project creation and code coverage configuration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ricable/cli-skills-builder/ruvector-nervous-system-wasm', 'community', 'ricable', 'cli-skills-builder', 'ricable/cli-skills-builder', 'ruvector-nervous-system-wasm', 1, 0, 42, '2026-02-13T02:21:57Z', '2026-03-06T07:12:52.577Z', '214a408c180a8df0bd5bf98e974ed4106c88a9270fdf2888b8ec97690ced96dc', '{"id":"ricable/cli-skills-builder/ruvector-nervous-system-wasm","name":"ruvector-nervous-system-wasm","description":{"en":"ruvector-nervous-system-wasm provides bio-inspired AI components for developers, enabling ultra-fast classification and one-shot learning. It benefits AI agent developers seeking efficient computing solutions.","zh":"ruvector-nervous-system-wasm是一种基于WebAssembly的生物启发AI组件，实现超维计算和行为时间尺度突触可塑性","ja":"ruvector-nervous-system-wasmはWebAssemblyを用いた生物启発AIコンポーネントであり、超次元計算と行動時間尺度の可塑性を実現する","ko":"ruvector-nervous-system-wasm은 WebAssembly 기반 바이오启发 AI 컴포넌트로 초차원 컴퓨팅 및 행동 시간 규모의 시냅스 가소성을 구현합니다","es":"ruvector-nervous-system-wasm es un componente de IA que implementa computación hiperdimensional y plasticidad sináptica para el aprendizaje ultra-rápidas","fr":"ruvector-nervous-system-wasm est un composant IA qui met en œuvre la computation hyperdimensionnelle et la plasticité synaptique pour un apprentissage ultra-rapide","de":"ruvector-nervous-system-wasm ist ein KI-Modul, der hyperdimensionale Computertechniken und synaptische Plastizität für ultra-schnelles Lernen implementiert","pt":"O ruvector-nervous-system-wasm é uma biblioteca de componentes de IA inspirados em biologia, compilados para WebAssembly, que implementam Computação Hiperdimensional e Plasticidade Sináptica Comportamental","ru":"ruvector-nervous-system-wasm - это библиотека биоинспирированных компонентов ИИ, скомпилированных в WebAssembly, реализующих Гиперразмерную Вычислительную Технику и Пластичность Синапсов","ar":"ruvector-nervous-system-wasm هي مكتبة مكونات ذكية متقدمة، مترجمة إلى WebAssembly، وت implements الحوسبة الأبعاد العالية واللدونة الشبكية السلوكية"},"seo":{"title":{"en":"ruvector-nervous-system-wasm: Hyperdimensional Computing ...","zh":"ruvector-nervous-system-wasm Setup Guide: 基于WebAssembly的生...","ja":"ruvector-nervous-system-wasm セットアップガイド: WebAssemblyを用いた生物...","ko":"ruvector-nervous-system-wasm 설정 가이드: WebAssembly 기반 바이오启发...","es":"Guía de configuración de ruvector-nervous-system-wasm par...","fr":"Mise en place de ruvector-nervous-system-wasm pour les dé...","de":"Einrichtungsleitfaden für ruvector-nervous-system-wasm-En...","pt":"Guia de Configuração do ruvector-nervous-system-wasm para...","ru":"Настройка ruvector-nervous-system-wasm для ИИ Агентов","ar":"دليل إعداد ruvector-nervous-system-wasm للأدوات الذكية"},"description":{"en":"Unlock ultra-fast classification with ruvector-nervous-system-wasm. Learn how to implement Hyperdimensional Computing and Behavioral Time-Scale Synaptic Plas...","zh":"了解ruvector-nervous-system-wasm的技术细节，包括超维计算和行为时间尺度突触可塑性。实现AIエージェント的快速分类和一-shot学习","ja":"ruvector-nervous-system-wasmの技術的詳細を学ぶ、超次元計算と行動時間尺度の可塑性を含む。AIエージェントの高速分類と一-shot学習を実現する","ko":"ruvector-nervous-system-wasm의 기술적 세부 사항을 알아보세요. 초차원 컴퓨팅 및 행동 시간 규모의 시냅스 가소성을 포함하여 AI 도구의 빠른 분류 및 일샷 학습을 구현합니다","es":"Aprende a utilizar ruvector-nervous-system-wasm, un componente de IA inspirado en la biología, para desarrollar aplicaciones web con capacidades de aprendiza...","fr":"Découvrez comment utiliser ruvector-nervous-system-wasm, un composant IA bio-inspiré, pour développer des applications web avec des capacités d''apprentissage...","de":"Erfahren Sie, wie Sie ruvector-nervous-system-wasm, ein bio-inspiriertes KI-Modul, verwenden können, um Webanwendungen mit ultra-schnellen Lernfähigkeiten zu...","pt":"Aprenda a usar o ruvector-nervous-system-wasm para criar componentes de IA inspirados em biologia com WebAssembly","ru":"Изучите возможности ruvector-nervous-system-wasm для создания биоинспирированных компонентов ИИ с WebAssembly","ar":"اكتشف كيفية استخدام ruvector-nervous-system-wasm لإنشاء مكونات ذكية متقدمة مع WebAssembly"},"definition":{"en":"ruvector-nervous-system-wasm is a WebAssembly-based library implementing Hyperdimensional Computing, Behavioral Time-Scale Synaptic Plasticity, and neuromorphic spiking network primitives for AI agents.","zh":"ruvector-nervous-system-wasm是一种生物启发AI组件，使用WebAssembly实现超维计算和行为时间尺度突触可塑性","ja":"ruvector-nervous-system-wasmは、WebAssemblyを用いた生物启発AIコンポーネントであり、超次元計算と行動時間尺度の可塑性を実現する","ko":"ruvector-nervous-system-wasm은 WebAssembly 기반 바이오启发 AI 컴포넌트로 초차원 컴퓨팅 및 행동 시간 규모의 시냅스 가소성을 구현하는 기술입니다","es":"ruvector-nervous-system-wasm es un componente de IA bio-inspirado que utiliza WebAssembly para proporcionar capacidades de aprendizaje ultra-rápidas","fr":"ruvector-nervous-system-wasm est un composant IA bio-inspiré qui utilise WebAssembly pour fournir des capacités d''apprentissage ultra-rapides","de":"ruvector-nervous-system-wasm ist ein bio-inspiriertes KI-Modul, das WebAssembly verwendet, um ultra-schnelle Lernfähigkeiten bereitzustellen","pt":"O que é ruvector-nervous-system-wasm? É uma biblioteca de componentes de IA inspirados em biologia","ru":"Что такое ruvector-nervous-system-wasm? Это библиотека биоинспирированных компонентов ИИ","ar":"ما هو ruvector-nervous-system-wasm؟ هو مكتبة مكونات ذكية متقدمة"},"features":{"en":["Implements Hyperdimensional Computing (HDC) for ultra-fast classification","Supports Behavioral Time-Scale Synaptic Plasticity (BTSP) for one-shot learning","Provides neuromorphic spiking network primitives","Compiled to WebAssembly for efficient execution","Initializes with `await init()` command","Encodes data using `hdc.encode` method"],"zh":["基于WebAssembly的生物启发AI组件","超维计算（HDC）实现高速分类","行为时间尺度突触可塑性（BTSP）实现一-shot学习","神经形态脉冲网络原语","使用import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';进行导入"],"ja":["WebAssemblyを用いた生物启発AIコンポーネント","超次元計算（HDC）による高速分類","行動時間尺度の可塑性（BTSP）による一-shot学習","神経形態のパルスネットワーク原語","import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';を使用してインポート"],"ko":["WebAssembly 기반 바이오启发 AI 컴포넌트","초차원 컴퓨팅（HDC）을 사용한 빠른 분류","행동 시간 규모의 시냅스 가소성（BTSP）을 사용한 일샷 학습","신경형태의 펄스 네트워크 원시","import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';를 사용하여 가져오기"],"es":["Implementación de computación hiperdimensional (HDC) para clasificación ultra-rápida","Soporte para plasticidad sináptica a escala de tiempo conductual (BTSP) para aprendizaje de un solo disparo","Primitivas de red neuronal espiking neuromórficas","Compilación a WebAssembly para una integración fácil en aplicaciones web","Importación y inicialización sencilla con la biblioteca @ruvector/nervous-system-wasm"],"fr":["Mise en œuvre de la computation hyperdimensionnelle (HDC) pour une classification ultra-rapide","Prise en charge de la plasticité synaptique à l''échelle de temps comportementale (BTSP) pour un apprentissage à un seul tir","Primitives de réseau neuronal à spikes neuromorphiques","Compilation en WebAssembly pour une intégration facile dans les applications web","Importation et initialisation simples avec la bibliothèque @ruvector/nervous-system-wasm"],"de":["Implementierung von hyperdimensionaler Computertechnik (HDC) für ultra-schnelle Klassifizierung","Unterstützung für synaptische Plastizität auf Verhaltenszeitmasstab (BTSP) für Ein-Schuss-Lernen","Primitiven für neuromorphe spiking-Neuronennetze","Kompilierung in WebAssembly für eine einfache Integration in Webanwendungen","Einfache Importierung und Initialisierung mit der Bibliothek @ruvector/nervous-system-wasm"],"pt":["Implementação de Computação Hiperdimensional (HDC) para classificação ultra-rápida","Suporte à Plasticidade Sináptica Comportamental (BTSP) para aprendizado em uma única iteração","Primitivas de rede neural neuromórfica de spiking","Compilação para WebAssembly para desempenho otimizado","Importação fácil com `import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';`"],"ru":["Реализация Гиперразмерной Вычислительной Техники (HDC) для ультрабыстрой классификации","Поддержка Пластичности Синапсов Comportamental (BTSP) для обучения за одну итерацию","Примитивы нейронной сети нейроморфной спайкинг","Компиляция в WebAssembly для оптимизированного производительности","Лёгкий импорт с `import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';`"],"ar":["تنفيذ الحوسبة الأبعاد العالية (HDC) للتصنيف السريع","دعم اللدونة الشبكية السلوكية (BTSP) للتعلم في جولة واحدة","مكونات الشبكة العصبية النيرومورفية","ترجمة إلى WebAssembly لتحقيق أداء محسن","استيراد سهل مع `import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';`"]},"keywords":{"en":["how to use ruvector-nervous-system-wasm","ruvector-nervous-system-wasm vs tensorflow","ruvector-nervous-system-wasm install guide","what is ruvector-nervous-system-wasm","ruvector-nervous-system-wasm alternative","ruvector-nervous-system-wasm setup tutorial","hyperdimensional computing examples","behavioral time-scale synaptic plasticity tutorial","webassembly ai libraries"],"zh":["ruvector-nervous-system-wasm","生物启发AI组件","WebAssembly","超维计算","行为时间尺度突触可塑性","AIエージェント","一-shot学习","神经形态脉冲网络"],"ja":["ruvector-nervous-system-wasm","生物启発AIコンポーネント","WebAssembly","超次元計算","行動時間尺度の可塑性","AIエージェント","一-shot学習","神経形態のパルスネットワーク"],"ko":["ruvector-nervous-system-wasm","바이오启发 AI 컴포넌트","WebAssembly","초차원 컴퓨팅","행동 시간 규모의 시냅스 가소성","AI 도구","일샷 학습","신경형태의 펄스 네트워크"],"es":["ruvector-nervous-system-wasm","IA bio-inspirada","computación hiperdimensional","plasticidad sináptica","aprendizaje ultra-rápido","WebAssembly","desarrollo de aplicaciones web","herramientas de IA para desarrolladores","agentes de IA"],"fr":["ruvector-nervous-system-wasm","IA bio-inspirée","computation hyperdimensionnelle","plasticité synaptique","apprentissage ultra-rapide","WebAssembly","développement d''applications web","outils d''IA pour les développeurs","agents d''IA","outils de développement d''IA"],"de":["ruvector-nervous-system-wasm","bio-inspirierte KI","hyperdimensionale Computertechnik","synaptische Plastizität","ultra-schnelles Lernen","WebAssembly","Entwicklung von Webanwendungen","KI-Tools für Entwickler","KI-Agents","KI-Entwicklungstools"],"pt":["ruvector-nervous-system-wasm","componentes de IA inspirados em biologia","WebAssembly","Computação Hiperdimensional","Plasticidade Sináptica Comportamental","rede neural neuromórfica","desenvolvimento de IA","bibliotecas de IA"],"ru":["ruvector-nervous-system-wasm","биоинспирированные компоненты ИИ","WebAssembly","Гиперразмерная Вычислительная Техника","Пластичность Синапсов","нейронная сеть нейроморфная","разработка ИИ","библиотеки ИИ"],"ar":["ruvector-nervous-system-wasm","مكونات ذكية متقدمة","WebAssembly","الحوسبة الأبعاد العالية","اللدونة الشبكية السلوكية","شبكة عصبية نيرومورفية","تطوير الذكاء الاصطناعي","مكتبات الذكاء الاصطناعي"]}},"owner":"ricable","repo":"cli-skills-builder","repoPath":"ricable/cli-skills-builder","stars":1,"forks":0,"updatedAt":"2026-02-13T02:21:57Z","topics":[],"category":"community","skillMd":{"name":"ruvector-nervous-system-wasm","description":"Bio-inspired AI components in WASM: Hyperdimensional Computing, BTSP synaptic plasticity, and neuromorphic spiking networks. Use when building brain-inspired classifiers, implementing one-shot learning with HDC, or simulating spiking neural networks in browsers.","bodyPreview":"# @ruvector/nervous-system-wasm\n\nBio-inspired AI components compiled to WebAssembly. Implements Hyperdimensional Computing (HDC) for ultra-fast classification, Behavioral Time-Scale Synaptic Plasticity (BTSP) for one-shot learning, and neuromorphic spiking network primitives.\n\n## Quick Reference\n\n| Task | Code |\n|------|------|\n| Import | `import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';` |\n| Initialize | `await init();` |\n| HDC encode | `hdc.encod","body":"# @ruvector/nervous-system-wasm\n\nBio-inspired AI components compiled to WebAssembly. Implements Hyperdimensional Computing (HDC) for ultra-fast classification, Behavioral Time-Scale Synaptic Plasticity (BTSP) for one-shot learning, and neuromorphic spiking network primitives.\n\n## Quick Reference\n\n| Task | Code |\n|------|------|\n| Import | `import { HyperdimensionalComputing, BTSP, SpikingNetwork } from ''@ruvector/nervous-system-wasm'';` |\n| Initialize | `await init();` |\n| HDC encode | `hdc.encode(data)` |\n| HDC classify | `hdc.classify(vector)` |\n| BTSP learn | `btsp.learn(input, target)` |\n| Spiking sim | `snn.step(input)` |\n\n## Installation\n\n```bash\nnpx @ruvector/nervous-system-wasm@latest\n```\n\n## Node.js Usage\n\n```typescript\nimport init, {\n  HyperdimensionalComputing,\n  BTSP,\n  SpikingNetwork,\n} from ''@ruvector/nervous-system-wasm'';\n\nawait init();\n\n// Hyperdimensional Computing: encode and classify\nconst hdc = new HyperdimensionalComputing({\n  dimensions: 10_000,\n  numClasses: 5,\n  encoding: ''random-projection'',\n});\n\n// Train on labeled data\nhdc.train(''cat'', new Float32Array([0.1, 0.8, 0.2, 0.9]));\nhdc.train(''dog'', new Float32Array([0.9, 0.2, 0.8, 0.1]));\n\n// Classify new input\nconst result = hdc.classify(new Float32Array([0.15, 0.75, 0.25, 0.85]));\nconsole.log(`Class: ${result.label}, confidence: ${result.confidence}`);\n\n// BTSP: one-shot synaptic plasticity\nconst btsp = new BTSP({\n  inputSize: 100,\n  outputSize: 50,\n  plasticityRate: 0.1,\n  plateauDuration: 10,\n});\n\nconst input = new Float32Array(100).fill(0.5);\nconst target = new Float32Array(50).fill(1.0);\nbtsp.learn(input, target);  // Single-exposure learning\n\nconst output = btsp.forward(input);\nconsole.log(''BTSP output correlation:'', btsp.correlation(output, target));\n\n// Spiking Neural Network\nconst snn = new SpikingNetwork({\n  neurons: 1000,\n  excitatory: 800,\n  inhibitory: 200,\n  connectivity: 0.1,\n  model: ''izhikevich'',\n});\n\nconst spikes = snn.step(new Float32Array(1000));\nconsole.log(`Active neurons: ${spikes.filter(s => s > 0).length}`);\n```\n\n## Browser Usage\n\n```html\n<script type=\"module\">\n  import init, { HyperdimensionalComputing } from ''@ruvector/nervous-system-wasm'';\n  await init();\n\n  const hdc = new HyperdimensionalComputing({ dimensions: 10000, numClasses: 3 });\n  hdc.train(''A'', new Float32Array([1, 0, 0]));\n  hdc.train(''B'', new Float32Array([0, 1, 0]));\n  const result = hdc.classify(new Float32Array([0.9, 0.1, 0]));\n  console.log(result.label); // ''A''\n</script>\n```\n\n## Key API\n\n### HyperdimensionalComputing\n\nUltra-fast classification using high-dimensional binary vectors.\n\n```typescript\nconst hdc = new HyperdimensionalComputing(config: HDCConfig);\n```\n\n**HDCConfig:**\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `dimensions` | `number` | `10000` | Hypervector dimensionality |\n| `numClasses` | `number` | required | Number of classes |\n| `encoding` | `''random-projection'' \\| ''thermometer'' \\| ''level''` | `''random-projection''` | Encoding method |\n| `similarity` | `''cosine'' \\| ''hamming''` | `''cosine''` | Similarity metric |\n\n```typescript\nhdc.train(label: string, features: Float32Array): void\nhdc.classify(features: Float32Array): ClassifyResult\nhdc.batchClassify(batch: Float32Array[]): ClassifyResult[]\nhdc.encode(features: Float32Array): Float32Array  // Raw hypervector\nhdc.retrain(): void  // Re-optimize class prototypes\nhdc.accuracy(testData: Array<{ features: Float32Array; label: string }>): number\n```\n\n**ClassifyResult:** `{ label: string; confidence: number; scores: Record<string, number> }`\n\n### BTSP\n\nBehavioral Time-Scale Synaptic Plasticity for one-shot learning.\n\n```typescript\nconst btsp = new BTSP(config: BTSPConfig);\n```\n\n**BTSPConfig:**\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `inputSize` | `number` | required | Input neurons |\n| `outputSize` | `number` | required | Output neurons |\n| `plasticityRate` | `number` | `0.1` | Learning rate |\n| `plateauDuration` | `number` | `10` | Plateau potential duration |\n| `decayRate` | `number` | `0.01` | Weight decay |\n\n```typescript\nbtsp.learn(input: Float32Array, target: Float32Array): void\nbtsp.forward(input: Float32Array): Float32Array\nbtsp.correlation(output: Float32Array, target: Float32Array): number\nbtsp.weights(): Float32Array\nbtsp.reset(): void\n```\n\n### SpikingNetwork\n\nSpiking Neural Network with configurable neuron models.\n\n```typescript\nconst snn = new SpikingNetwork(config: SNNConfig);\n```\n\n**SNNConfig:**\n| Parameter | Type | Default | Description |\n|-----------|------|---------|-------------|\n| `neurons` | `number` | `1000` | Total neurons |\n| `excitatory` | `number` | `800` | Excitatory count |\n| `inhibitory` | `number` | `200` | Inhibitory count |\n| `connectivity` | `number` | `0.1` | Connection probability |\n| `model` | `''izhikevich'' \\| ''lif'' \\| ''hodgkin-huxley''` | `''izhikevich''` | Neuron model |\n| `dt` | `number` | `0.5` | Timestep (ms) |\n\n```typescript\nsnn.step(input: Float32Array): Float32Array          // One timestep, returns spikes\nsnn.stepN(input: Float32Array, n: number): Float32Array[]  // N timesteps\nsnn.membranePotentials(): Float32Array\nsnn.firingRates(): Float32Array\nsnn.reset(): void\n```\n\n## References\n\n- [API Reference](references/commands.md)\n- [npm](https://www.npmjs.com/package/@ruvector/nervous-system-wasm)\n"},"lastSynced":"2026-03-06T07:12:52.577Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing ultra-fast classification and one-shot learning capabilities with bio-inspired components","zh":"适用于需要超快分类和一击学习能力的生物启发组件的AI代理","ja":"超高速分類とワンショット学習機能を備えたバイオインスパイアコンポーネントを必要とするAIエージェントに最適","ko":"초高速 분류 및 원샷 학습 기능이 있는 생명체启发 컴포넌트가 필요한 AI 에이전트에 적합","es":"Perfecto para agentes de IA que necesitan capacidades de clasificación ultra-rápidas y de aprendizaje en un solo paso con componentes bio-inspirados","fr":"Parfait pour les agents d''IA ayant besoin de capacités de classification ultra-rapides et d''apprentissage en un seul coup avec des composants bio-inspirés","de":"Perfekt für KI-Agents, die ultra-schnelle Klassifizierungs- und One-Shot-Lernfähigkeiten mit bio-inspirierten Komponenten benötigen","pt":"Perfeito para Agentes de IA que necessitam de classificação ultra-rápida e capacidades de aprendizado em uma única tentativa com componentes bio-inspirados","ru":"Идеально для агентов ИИ, которым необходимы сверхбыстрая классификация и возможности обучения за один проход с био-инспирированными компонентами","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى التصنيف السريع للغاية وقدرات التعلم في جولة واحدة مع المكونات الملهمة بيولوجيًا"},"recommendation":{"en":"Empowers agents to leverage Hyperdimensional Computing (HDC) for rapid classification, Behavioral Time-Scale Synaptic Plasticity (BTSP) for one-shot learning, and neuromorphic spiking network primitives compiled to WebAssembly, enhancing their efficiency in computing solutions","zh":"赋予代理使用超维计算（HDC）进行快速分类，使用行为时间尺度突触可塑性（BTSP）进行一击学习，并使用编译为WebAssembly的神经形态脉冲网络原语，从而提高其在计算解决方案中的效率","ja":"エージェントにHyperdimensional Computing（HDC）を使用した高速分類、Behavioral Time-Scale Synaptic Plasticity（BTSP）を使用したワンショット学習、およびWebAssemblyにコンパイルされた神経形態スパイクネットワークのプリミティブを使用して、コンピューティングソリューションの効率を高めることができる","ko":"에이전트가 하이퍼 차원 컴퓨팅(HDC)을 사용하여 빠른 분류를 수행하고, 행동 시간尺度 시냅스 가소성(BTSP)을 사용하여 원샷 학습을 수행하며, WebAssembly로 컴파일된 신경형태 펄스 네트워크 원시 기능을 사용하여 컴퓨팅 솔루션의 효율성을提高할 수 있도록 함","es":"Habilita a los agentes a aprovechar la Computación Hiperdimensional (HDC) para una clasificación rápida, la Plasticidad Sináptica de Escala de Tiempo Conductual (BTSP) para el aprendizaje en un solo paso y primitivas de redes de picos neuromórficas compiladas a WebAssembly, mejorando su eficiencia en soluciones de computación","fr":"Permet aux agents d''exploiter l''informatique hyperdimensionnelle (HDC) pour une classification rapide, la plasticité synaptique à l''échelle de temps comportementale (BTSP) pour l''apprentissage en un seul coup et les primitives de réseaux de pointes neuromorphes compilées en WebAssembly, améliorant leur efficacité dans les solutions de calcul","de":"Ermächtigt Agents, Hyperdimensional Computing (HDC) für schnelle Klassifizierung, Behavioral Time-Scale Synaptic Plasticity (BTSP) für One-Shot-Lernen und neuromorphe Spiking-Netzwerk-Primitiven, die in WebAssembly kompiliert sind, zu nutzen, um ihre Effizienz in Rechenlösungen zu verbessern","pt":"Habilita os agentes a utilizar Computação Hiperdimensional (HDC) para classificação rápida, Plasticidade Sináptica de Escala de Tempo Comportamental (BTSP) para aprendizado em uma única tentativa e primitivos de rede de disparo neuromórfica compilados para WebAssembly, melhorando sua eficiência em soluções de computação","ru":"Предоставляет агентам возможность использовать Гиперразмерную Вычислительную Технику (HDC) для быстрой классификации, Пластичность Синапсов по Поведенческой Шкале Времени (BTSP) для обучения за один проход и нейроморфные примитивы сети всплесков, скомпилированные в WebAssembly, повышая их эффективность в вычислительных решениях","ar":"تمكين الوكلاء من استخدام الحوسبة الأبعاد الفائقة (HDC) للتصنيف السريع واللدونة الشبكية وفقًا للمقياس الزمني السلوكي (BTSP) للتعلم في جولة واحدة والأرضيات الشبكية النمطية المجمعة إلى WebAssembly، مما يعزز كفاءتهم في حلول الحوسبة"},"useCases":{"en":["Implementing ultra-fast classification models using Hyperdimensional Computing","Enabling one-shot learning capabilities with Behavioral Time-Scale Synaptic Plasticity","Developing neuromorphic spiking networks for advanced AI applications"],"zh":["使用超维计算实现超快分类模型","使用行为时间尺度突触可塑性实现一击学习功能","开发用于高级AI应用的神经形态脉冲网络"],"ja":["Hyperdimensional Computingを使用した超高速分類モデルの実装","Behavioral Time-Scale Synaptic Plasticityを使用したワンショット学習機能の実現","高度なAIアプリケーション用の神経形態スパイクネットワークの開発"],"ko":["하이퍼 차원 컴퓨팅을 사용하여 초高速 분류 모델 구현","행동 시간尺度 시냅스 가소성을 사용하여 원샷 학습 기능 구현","고급 AI 애플리케이션을 위한 신경형태 펄스 네트워크 개발"],"es":["Implementar modelos de clasificación ultra-rápidos utilizando Computación Hiperdimensional","Habilitar capacidades de aprendizaje en un solo paso con Plasticidad Sináptica de Escala de Tiempo Conductual","Desarrollar redes de picos neuromórficas para aplicaciones de IA avanzadas"],"fr":["Mettre en œuvre des modèles de classification ultra-rapides à l''aide de l''informatique hyperdimensionnelle","Activer les capacités d''apprentissage en un seul coup avec la plasticité synaptique à l''échelle de temps comportementale","Développer des réseaux de pointes neuromorphes pour des applications d''IA avancées"],"de":["Implementieren von ultra-schnellen Klassifizierungsmodellen unter Verwendung von Hyperdimensional Computing","Ermöglichen von One-Shot-Lernfähigkeiten mit Behavioral Time-Scale Synaptic Plasticity","Entwickeln von neuromorphen Spiking-Netzwerken für fortschrittliche KI-Anwendungen"],"pt":["Implementação de modelos de classificação ultra-rápidos usando Computação Hiperdimensional","Habilitação de capacidades de aprendizado em uma única tentativa com Plasticidade Sináptica de Escala de Tempo Comportamental","Desenvolvimento de redes de disparo neuromórficas para aplicações avançadas de IA"],"ru":["Реализация сверхбыстрых моделей классификации с помощью Гиперразмерной Вычислительной Техники","Включение возможностей обучения за один проход с Пластичностью Синапсов по Поведенческой Шкале Времени","Разработка нейроморфных сетей всплесков для продвинутых приложений ИИ"],"ar":["تنفيذ نماذج التصنيف السريع للغاية باستخدام الحوسبة الأبعاد الفائقة","تمكين قدرات التعلم في جولة واحدة باللدونة الشبكية وفقًا للمقياس الزمني السلوكي","تطوير الشبكات النمطية للنشر المتقدم لتطبيقات الذكاء الاصطناعي"]},"limitations":{"en":["Requires WebAssembly compatibility","Specific to bio-inspired AI components and Hyperdimensional Computing"],"zh":["需要WebAssembly兼容性","特定于生物启发式AI组件和超维计算"],"ja":["WebAssemblyの互換性が必要","バイオインスパイアAIコンポーネントとHyperdimensional Computingに特化"],"ko":["WebAssembly 호환성이 필요","생명체启发 AI 컴포넌트 및 하이퍼 차원 컴퓨팅에 특화"],"es":["Requiere compatibilidad con WebAssembly","Específico para componentes de IA bio-inspirados y Computación Hiperdimensional"],"fr":["Nécessite la compatibilité avec WebAssembly","Spécifique aux composants d''IA bio-inspirés et à l''informatique hyperdimensionnelle"],"de":["Benötigt WebAssembly-Kompatibilität","Spezifisch für bio-inspirierte KI-Komponenten und Hyperdimensional Computing"],"pt":["Requer compatibilidade com WebAssembly","Específico para componentes de IA bio-inspirados e Computação Hiperdimensional"],"ru":["Требует совместимости с WebAssembly","Конкретно для био-инспирированных компонентов ИИ и Гиперразмерной Вычислительной Техники"],"ar":["يتطلب توافقًا مع WebAssembly","محدد للمكونات الملهمة بيولوجيًا للذكاء الاصطناعي والحوسبة الأبعاد الفائقة"]},"version":4},"contentHash":"214a408c180a8df0bd5bf98e974ed4106c88a9270fdf2888b8ec97690ced96dc","qualityScore":42}');
