INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ricable/cli-skills-builder/ruvector-nervous-system-wasm', 'ruvector-nervous-system-wasm', 'ricable', 'cli-skills-builder', 'community', 'ruvector-nervous-system-wasm ricable cli-skills-builder community ruvector-nervous-system-wasm provides bio-inspired AI components for developers, enabling ultra-fast classification and one-shot learning. It benefits AI agent developers seeking efficient computing solutions. ruvector-nervous-system-wasm是一种基于WebAssembly的生物启发AI组件，实现超维计算和行为时间尺度突触可塑性 ruvector-nervous-system-wasmはWebAssemblyを用いた生物启発AIコンポーネントであり、超次元計算と行動時間尺度の可塑性を実現する ruvector-nervous-system-wasm은 WebAssembly 기반 바이오启发 AI 컴포넌트로 초차원 컴퓨팅 및 행동 시간 규모의 시냅스 가소성을 구현합니다 ruvector-nervous-system-wasm es un componente de IA que implementa computación hiperdimensional y plasticidad sináptica para el aprendizaje ultra-rápidas ruvector-nervous-system-wasm est un composant IA qui met en œuvre la computation hyperdimensionnelle et la plasticité synaptique pour un apprentissage ultra-rapide ruvector-nervous-system-wasm ist ein KI-Modul, der hyperdimensionale Computertechniken und synaptische Plastizität für ultra-schnelles Lernen implementiert O ruvector-nervous-system-wasm é uma biblioteca de componentes de IA inspirados em biologia, compilados para WebAssembly, que implementam Computação Hiperdimensional e Plasticidade Sináptica Comportamental ruvector-nervous-system-wasm - это библиотека биоинспирированных компонентов ИИ, скомпилированных в WebAssembly, реализующих Гиперразмерную Вычислительную Технику и Пластичность Синапсов ruvector-nervous-system-wasm هي مكتبة مكونات ذكية متقدمة، مترجمة إلى WebAssembly، وت implements الحوسبة الأبعاد العالية واللدونة الشبكية السلوكية how to use ruvector-nervous-system-wasm ruvector-nervous-system-wasm vs tensorflow ruvector-nervous-system-wasm install guide what is ruvector-nervous-system-wasm ruvector-nervous-system-wasm alternative ruvector-nervous-system-wasm setup tutorial hyperdimensional computing examples behavioral time-scale synaptic plasticity tutorial webassembly ai libraries ruvector-nervous-system-wasm 生物启发AI组件 WebAssembly 超维计算 行为时间尺度突触可塑性 AIエージェント 一-shot学习 神经形态脉冲网络 Implements Hyperdimensional Computing (HDC) for ultra-fast classification Supports Behavioral Time-Scale Synaptic Plasticity (BTSP) for one-shot learning Provides neuromorphic spiking network primitives Compiled to WebAssembly for efficient execution Initializes with `await init()` command Encodes data using `hdc.encode` method ruvector-nervous-system-wasm is a WebAssembly-based library implementing Hyperdimensional Computing, Behavioral Time-Scale Synaptic Plasticity, and neuromorphic spiking network primitives for AI agents.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('77DidO/CRAutomatique2/openai-patterns', 'community', '77DidO', 'CRAutomatique2', '77DidO/CRAutomatique2', 'openai-patterns', 1, 0, 42, '2026-02-26T16:55:38Z', '2026-03-06T07:13:51.235Z', '9713e9959f7c07fee06613a4886e14b7cf399e214a3d0a98ba4ea651a1bef2f6', '{"id":"77DidO/CRAutomatique2/openai-patterns","name":"openai-patterns","description":{"en":"The openai-patterns skill creates automatic reports using the OpenAI API. It benefits developers who need to automate tasks such as detection and extraction.","zh":"OpenAI 模式是一个创建自动化的应用，使用 OpenAI 包和客户端工厂","ja":"OpenAI パターンは、OpenAI パッケージとクライアントファクトリーを使用して自動化を作成するアプリケーションです","ko":"OpenAI 패턴은 OpenAI 패키지와 클라이언트 팩토리를 사용하여 자동화를 생성하는 애플리케이션입니다","es":"Openai-patterns es una aplicación que crea un comprobante automático utilizando el paquete openai y cliente factory","fr":"Openai-patterns est une application qui crée un compte rendu automatique en utilisant le paquet openai et client factory","de":"Openai-patterns ist eine Anwendung, die ein automatisches Protokoll mit dem OpenAI-Paket und Client-Factory erstellt","pt":"O openai-patterns é uma aplicação que cria um compe rendu automatique com o pacote openai e cliente factory.","ru":"Openai-patterns — это приложение, которое создает автоматический комперенду с пакетом openai и фабрикой клиентов.","ar":"openai-patterns هو تطبيق يقوم بإنشاء عرض automatique باستخدام حزمة openai و مصنع العميل"},"seo":{"title":{"en":"openai-patterns: Dual-Model Strategy Setup Guide | AI Age...","zh":"OpenAI 模式设置指南","ja":"OpenAI パターン ベストプラクティス","ko":"OpenAI 패턴 설정 가이드","es":"Guía de configuración de openai-patterns para agentes de IA","fr":"Guide de mise en place de openai-patterns pour les outils...","de":"Einrichtungsleitfaden für openai-patterns in KI-Agenten","pt":"Guia de Configuração do openai-patterns para Desenvolvedores","ru":"Настройка openai-patterns: Руководство для Разработчиков ...","ar":"دليل إعداد openai-patterns للاستفادة من أدوات الإي الأجنت"},"description":{"en":"Unlock the power of OpenAI patterns with our expert guide. Learn how to set up a dual-model strategy for detection and extraction tasks. Get started now!","zh":"了解 OpenAI 模式的技术细节，包括包和客户端工厂，适用于开发人员","ja":"OpenAI パターンの技術的詳細を学び、開発者向けのベストプラクティスを確認する","ko":"OpenAI 패턴의 기술적 세부 사항을 살펴보고 개발자용 설정 가이드를 확인하세요","es":"Aprende a configurar openai-patterns para crear aplicaciones de IA automáticas con el paquete openai y cliente factory","fr":"Découvrez comment configurer openai-patterns pour créer des applications d''IA automatisées avec le paquet openai et client factory","de":"Erfahren Sie, wie Sie openai-patterns für die Erstellung von KI-Anwendungen mit dem OpenAI-Paket und Client-Factory einrichten","pt":"Aprenda a configurar o openai-patterns com o pacote openai e cliente factory para criar aplicações de Inteligência Artificial","ru":"Узнайте, как настроить openai-patterns с пакетом openai и фабрикой клиентов для создания приложений ИИ Агентов","ar":"تعرف على كيفية إعداد openai-patterns باستخدام حزمة openai و مصنع العميل لتطوير تطبيقات الإي الأجنت"},"definition":{"en":"openai-patterns is a skill that utilizes the OpenAI API to create automatic reports, leveraging a dual-model strategy for efficient detection and extraction tasks.","zh":"OpenAI 模式是一种使用 OpenAI 包创建自动化的技术","ja":"OpenAI パターンは、OpenAI パッケージを使用して自動化を作成する技術です","ko":"OpenAI 패턴은 OpenAI 패키지를 사용하여 자동화를 생성하는 기술입니다","es":"Openai-patterns es una aplicación de IA que utiliza el paquete openai para crear comprobantes automáticos","fr":"Openai-patterns est un outil d''IA qui utilise le paquet openai pour créer des comptes rendus automatiques","de":"Openai-patterns ist ein KI-Tool, das das OpenAI-Paket verwendet, um automatische Protokolle zu erstellen","pt":"O que é openai-patterns? É uma aplicação que utiliza o pacote openai para criar aplicações de Inteligência Artificial","ru":"Что такое openai-patterns? Это приложение, которое использует пакет openai для создания приложений ИИ Агентов","ar":"ما هو openai-patterns؟ هو تطبيق يستخدم حزمة openai لإنشاء تطبيقات الإي الأجنت"},"features":{"en":["Utilizes the OpenAI API with package version ^4.0.0","Employs a client factory from backend/src/services/openai/client-factory.ts","Supports configuration via OPENAI_API_KEY in .env or OPENAI_BASE_URL for local LLM","Deploys a dual-model strategy for detection and extraction tasks","Uses the gpt-4o-mini model for classification and low-cost detection","Extracts atomic facts with efficient processing"],"zh":["使用 OpenAI 包（^4.0.0）","客户端工厂（backend/src/services/openai/client-factory.ts）","配置 OPENAI_API_KEY 和 OPENAI_BASE_URL","支持双模型策略（Detection type reunion 和 Extraction facts atomiques）","使用 gpt-4o-mini 模型进行分类和事实抽取"],"ja":["OpenAI パッケージ（^4.0.0）を使用","クライアントファクトリー（backend/src/services/openai/client-factory.ts）","OPENAI_API_KEY と OPENAI_BASE_URL を設定","デュアルモデル戦略（Detection type reunion と Extraction facts atomiques）をサポート","gpt-4o-mini モデルを使用して分類と事実抽出を行う"],"ko":["OpenAI 패키지（^4.0.0）를 사용","클라이언트 팩토리（backend/src/services/openai/client-factory.ts）","OPENAI_API_KEY 와 OPENAI_BASE_URL 를 설정","듀얼 모델 전략（Detection type reunion 와 Extraction facts atomiques）을 지원","gpt-4o-mini 모델을 사용하여 분류와 事実抽出를 수행"],"es":["Utiliza el paquete openai versión 4.0.0","Incorpora un cliente factory para la configuración","Soporta la detección de tipo de reunión con el modelo gpt-4o-mini","Permite la extracción de hechos atómicos","Configuración mediante la variable de entorno OPENAI_API_KEY","Compatibilidad con el modelo de lenguaje local vLLM"],"fr":["Utilise le paquet openai version 4.0.0","Intègre un client factory pour la configuration","Prend en charge la détection de type de réunion avec le modèle gpt-4o-mini","Permet l''extraction de faits atomiques","Configuration via la variable d''environnement OPENAI_API_KEY","Compatibilité avec le modèle de langage local vLLM"],"de":["Verwendet das OpenAI-Paket Version 4.0.0","Enthält einen Client-Factory für die Konfiguration","Unterstützt die Erkennung von Besprechungstypen mit dem Modell gpt-4o-mini","Ermöglicht die Extraktion von atomaren Fakten","Konfiguration über die Umgebungsvariable OPENAI_API_KEY","Kompatibilität mit dem lokalen Sprachmodell vLLM"],"pt":["Utiliza o pacote openai ^4.0.0","Cliente factory em backend/src/services/openai/client-factory.ts","Configuração via OPENAI_API_KEY em .env","Suporte a modelo dual com gpt-4o-mini","Classificação simples e extração de fatos atômicos"],"ru":["Использует пакет openai ^4.0.0","Фабрика клиентов в backend/src/services/openai/client-factory.ts","Конфигурация через OPENAI_API_KEY в .env","Поддержка двойного моделирования с gpt-4o-mini","Простая классификация и извлечение атомарных фактов"],"ar":["يستخدم حزمة openai ^4.0.0","مصنع العميل في backend/src/services/openai/client-factory.ts","التكوين عبر OPENAI_API_KEY في .env","دعم نموذج مزدوج مع gpt-4o-mini","التصنيف البسيط و استخراج الحقائق الذرية"]},"keywords":{"en":["how to use openai-patterns","openai-patterns setup guide","openai-patterns alternative","openai-patterns vs Anthropic SDK","openai-patterns install","what is openai-patterns","openai-patterns dual-model strategy","openai-patterns API configuration","openai-patterns local LLM setup"],"zh":["OpenAI 模式","AI 工具","自动化","OpenAI 包","客户端工厂","双模型策略","gpt-4o-mini 模型","AI开发","机器学习"],"ja":["OpenAI パターン","AI エージェント","自動化","OpenAI パッケージ","クライアントファクトリー","デュアルモデル戦略","gpt-4o-mini モデル","AI 開発","機械学習"],"ko":["OpenAI 패턴","AI 에이전트","자동화","OpenAI 패키지","클라이언트 팩토리","듀얼 모델 전략","gpt-4o-mini 모델","AI 개발","기계학습"],"es":["openai-patterns","agentes de IA","herramientas de IA","paquete openai","cliente factory","modelo gpt-4o-mini","detección de tipo de reunión","extracción de hechos atómicos","configuración de IA"],"fr":["openai-patterns","outils d''IA","agents d''IA","paquet openai","client factory","modèle gpt-4o-mini","détection de type de réunion","extraction de faits atomiques","configuration d''IA"],"de":["openai-patterns","KI-Tools","KI-Agenten","OpenAI-Paket","Client-Factory","Modell gpt-4o-mini","Erkennung von Besprechungstypen","Extraktion von atomaren Fakten","KI-Konfiguration"],"pt":["openai-patterns","Inteligência Artificial","pacote openai","cliente factory","configuração openai","modelo dual","gpt-4o-mini","classificação simples","extração de fatos atômicos"],"ru":["openai-patterns","ИИ Агенты","пакет openai","фабрика клиентов","конфигурация openai","двойное моделирование","gpt-4o-mini","простая классификация","извлечение атомарных фактов"],"ar":["openai-patterns","الإي الأجنت","حزمة openai","مصنع العميل","تكوين openai","نموذج مزدوج","gpt-4o-mini","التصنيف البسيط","استخراج الحقائق الذرية"]}},"owner":"77DidO","repo":"CRAutomatique2","repoPath":"77DidO/CRAutomatique2","stars":1,"forks":0,"updatedAt":"2026-02-26T16:55:38Z","topics":[],"category":"community","skillMd":{"name":"openai-patterns","description":"Patterns dutilisation de lAPI OpenAI dans CRAutomatique2. Mod\\xE8les gpt-4o/gpt-4o-mini, structured output Zod, dual-model, anti-hallucination. Utilis\\xE9 quand on modifie les prompts, le client OpenAI ou la g\\xE9n\\xE9ration structur\\xE9e.","bodyPreview":"# Patterns OpenAI — CRAutomatique2\n\n## Package et client\n\n- **Package** : `openai` ^4.0.0 (PAS Anthropic SDK, PAS `@azure/openai`)\n- **Client factory** : `backend/src/services/openai/client-factory.ts`\n- **Configuration** : `OPENAI_API_KEY` dans `.env` (ou vLLM local via `OPENAI_BASE_URL`)\n\n## Strategie dual-model\n\n| Usage | Modele | Pourquoi |\n|-------|--------|----------|\n| Detection type reunion | `gpt-4o-mini` | Classification simple, low-cost, 3000 chars max |\n| Extraction facts atomiques |","body":"# Patterns OpenAI — CRAutomatique2\n\n## Package et client\n\n- **Package** : `openai` ^4.0.0 (PAS Anthropic SDK, PAS `@azure/openai`)\n- **Client factory** : `backend/src/services/openai/client-factory.ts`\n- **Configuration** : `OPENAI_API_KEY` dans `.env` (ou vLLM local via `OPENAI_BASE_URL`)\n\n## Strategie dual-model\n\n| Usage | Modele | Pourquoi |\n|-------|--------|----------|\n| Detection type reunion | `gpt-4o-mini` | Classification simple, low-cost, 3000 chars max |\n| Extraction facts atomiques | `gpt-4o-mini` | JSON structure, temperature 0 |\n| Generation brief complet | `gpt-4o` | Qualite editoriale, structured output |\n\n## Structured output\n\n```typescript\n// Detection (JSON simple)\nconst response = await client.chat.completions.create({\n  model: ''gpt-4o-mini'',\n  messages: [{ role: ''user'', content: prompt }],\n  response_format: { type: ''json_object'' },\n  temperature: 0,\n});\n\n// Generation brief (schema Zod)\nconst response = await client.chat.completions.create({\n  model: ''gpt-4o'',\n  messages: [{ role: ''system'', content: systemPrompt }, { role: ''user'', content: userPrompt }],\n  response_format: { type: ''json_object'' },\n  temperature: 0.1,\n});\nconst brief = BriefStructuredSchema.parse(JSON.parse(content));\n```\n\n**Schemas Zod** definis dans `backend/src/types/brief.ts` :\n- `BriefStructuredSchema` — schema principal\n- `BriefMetadataSchema` — metadata (meetingType, date, duration)\n- `ComexContentSchema`, `CodirContentSchema`, `EncoursContentSchema` — contenu par type\n\n## Anti-hallucination (3 couches)\n\n### Couche 1 — Pre-extraction deterministe (AVANT le LLM)\n- Fichier : `backend/src/services/pre-extraction.ts`\n- Scan regex : montants financiers (avec interpretations brut/x1000/x1M), dates, personnes, entites\n- Output : `pre-extracted-facts.json` dans chaque job\n- Inject : `buildFactsConstraintSection()` produit un bloc de contraintes injecte dans le prompt\n\n### Couche 2 — Post-processings deterministes (APRES le LLM)\n- ~70 sanitizers/enrichers/guards dans `applyComexPostProcessings()`\n- Corrigent les erreurs LLM : kind budget, revenue, attributions, formulations\n- Voir skill `/comex-rules` pour la chaine complete\n\n### Couche 3 — Validation post-extraction\n- Fichier : `backend/src/services/openai/validation.ts`\n- Verifie montants financiers du brief contre la transcription\n- Valide noms responsables contre voice profiles\n- Output : `validation-report.json` dans chaque job\n\n## Prompts\n\nChaque type de reunion a son prompt dedie :\n- `prompts/detect-meeting-type.ts` — detection (excerpt 3000 chars)\n- `prompts/generate-comex.ts` — generation brief COMEX\n- `prompts/generate-codir.ts` — generation brief CODIR\n- `prompts/generate-chantier.ts` — generation brief ENCOURS\n- `prompts/extract-chantier-facts.ts` — extraction facts ENCOURS\n\nLes prompts recoivent les contraintes pre-extraites via `buildFactsConstraintSection()`.\n\n## Regles\n\n- **Ne jamais faire confiance au LLM** sur les champs structurels (`budget.kind`, attributions)\n- **Temperature 0** pour classification/extraction, **0.1** pour generation editoriale\n- **Pas de retry auto** cote app — le pipeline gere les erreurs via `safe()` wrapper\n- **Toujours valider** la sortie JSON avec le schema Zod avant utilisation\n- **Tronquer** la transcription a la taille contexte du modele (32768 tokens pour vLLM local)\n\n## Fichiers cles\n\n- `backend/src/services/openai/client-factory.ts` — creation client OpenAI\n- `backend/src/services/openai/structured-generation.ts` — orchestration generation + post-processings\n- `backend/src/services/openai/prompts/` — tous les prompts par type\n- `backend/src/services/openai/validation.ts` — validation anti-hallucination\n- `backend/src/services/pre-extraction.ts` — pre-extraction deterministe\n- `backend/src/types/brief.ts` — schemas Zod (BriefStructured, ComexContent, etc.)\n"},"lastSynced":"2026-03-06T07:13:51.235Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing automatic report generation and task automation via the OpenAI API.","zh":"非常适合需要通过 OpenAI API 自动生成报告和任务自动化的 AI Agent。","ja":"OpenAI API を介して自動レポート生成およびタスク自動化を必要とする AI エージェントに最適です。","ko":"OpenAI API를 통해 자동 보고서 생성 및 작업 자동화가 필요한 AI 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan generación automática de informes y automatización de tareas a través de la OpenAI API.","fr":"Parfait pour les agents IA nécessitant une génération automatique de rapports et une automation de tâches via l''OpenAI API.","de":"Perfekt für KI-Agents, die eine automatische Berichterstellung und eine Automatisierung von Aufgaben über die OpenAI API benötigen.","pt":"Perfeito para Agentes de IA que necessitam de geração automática de relatórios e automação de tarefas via a OpenAI API.","ru":"Идеально подходит для агентов ИИ, которым необходима автоматическая генерация отчетов и автоматизация задач через OpenAI API.","ar":"مثالي لعميل الذكاء الاصطناعي الذي يحتاج إلى توليد تقارير آلي وتأتمة المهام من خلال واجهة برمجة تطبيقات OpenAI."},"recommendation":{"en":"Empowers agents to automate detection and extraction tasks using the OpenAI API, specifically with models like `gpt-4o-mini`, and leverage client factories for seamless integration, all configurable via `.env` files and compatible with `@azure/openai`.","zh":"赋予代理自动化检测和提取任务的能力，使用 OpenAI API，特别是使用像 `gpt-4o-mini` 这样的模型，并利用客户端工厂实现无缝集成，所有配置均可通过 `.env` 文件进行配置，并且兼容 `@azure/openai`。","ja":"OpenAI API を使用して、特に `gpt-4o-mini` などのモデルを使用して、エージェントが検出および抽出タスクを自動化する能力を提供し、クライアント ファクトリを使用してシームレスな統合を実現し、すべての設定を `.env` ファイルで構成可能であり、`@azure/openai` と互換性があります。","ko":"OpenAI API를 사용하여 에이전트가 검출 및 추출 작업을 자동화 할 수 있는 기능을 제공하며, 특히 `gpt-4o-mini`와 같은 모델을 사용하며, 클라이언트 팩토리를 사용하여 무결점 통합을 제공하며, 모든 설정을 `.env` 파일을 통해 구성할 수 있으며, `@azure/openai`와 호환됩니다.","es":"Habilita a los agentes a automatizar tareas de detección y extracción utilizando la OpenAI API, específicamente con modelos como `gpt-4o-mini`, y aprovechar fábricas de clientes para una integración sin problemas, todo configurable a través de archivos `.env` y compatible con `@azure/openai`.","fr":"Permet aux agents d''automatiser les tâches de détection et d''extraction en utilisant l''OpenAI API, notamment avec des modèles tels que `gpt-4o-mini`, et de tirer parti des usines de clients pour une intégration transparente, le tout configurable via des fichiers `.env` et compatible avec `@azure/openai`.","de":"Ermächtigt Agents, Aufgaben zur Erkennung und Extraktion zu automatisieren, indem sie die OpenAI API verwenden, insbesondere mit Modellen wie `gpt-4o-mini`, und ermöglicht es, Client-Fabriken für eine nahtlose Integration zu nutzen, alles konfigurierbar über `.env`-Dateien und kompatibel mit `@azure/openai`.","pt":"Habilita os agentes a automatizar a detecção e extração de tarefas usando a OpenAI API, especificamente com modelos como `gpt-4o-mini`, e aproveitar fábricas de clientes para integração transparente, tudo configurável via arquivos `.env` e compatível com `@azure/openai`.","ru":"Позволяет агентам автоматизировать задачи обнаружения и извлечения с помощью OpenAI API, в частности с моделями типа `gpt-4o-mini`, и использовать фабрики клиентов для бесшовной интеграции, все настраиваемое через файлы `.env` и совместимое с `@azure/openai`.","ar":"تمكن الوكلاء من تأتمة مهام الكشف والاستخلاص باستخدام واجهة برمجة تطبيقات OpenAI، وخاصة مع نماذج مثل `gpt-4o-mini`، وتحقيق مصانع العملاء من أجل التكامل السلس، وكل شيء يمكن تحديده من خلال الملفات `.env` ومتوافق مع `@azure/openai`."},"useCases":{"en":["Automating detection of reunion types","Extracting atomic facts using dual-model strategies","Generating automatic reports with comprehensive content analysis"],"zh":["自动检测团聚类型","使用双模型策略提取原子事实","生成具有综合内容分析的自动报告"],"ja":["再会タイプの自動検出","双モデル戦略を使用した原子的事実の抽出","包括的なコンテンツ分析を備えた自動レポートの生成"],"ko":["재합류 유형 자동 감지","이중 모델 전략을 사용한 원자적 사실 추출","포괄적인 내용 분석을 갖춘 자동 보고서 생성"],"es":["Automatización de la detección de tipos de reunión","Extracción de hechos atómicos utilizando estrategias de modelo dual","Generación de informes automáticos con análisis de contenido integral"],"fr":["Automatisation de la détection des types de réunions","Extraction de faits atomiques en utilisant des stratégies de modèle double","Génération de rapports automatiques avec analyse de contenu complète"],"de":["Automatisierung der Erkennung von Treffttypen","Extraktion von atomaren Fakten unter Verwendung von Dual-Modell-Strategien","Generierung von automatischen Berichten mit umfassender Inhaltsanalyse"],"pt":["Automatizar a detecção de tipos de reunião","Extrair fatos atômicos usando estratégias de modelo duplo","Gerar relatórios automáticos com análise de conteúdo abrangente"],"ru":["Автоматизировать обнаружение типов встреч","Извлекать атомарные факты с помощью двумодельных стратегий","Генерировать автоматические отчеты с комплексным контент-анализом"],"ar":["تأتمة كشف أنواع الاجتماعات","استخلاص الحقائق الذرية باستخدام استراتيجيات نموذج مزدوج","توليد تقارير آلي مع تحليل محتوى شامل"]},"limitations":{"en":["Requires OpenAI API Key stored in `.env`","Dependent on `openai` package version ^4.0.0","Limited to 3000 characters max for simple classification tasks"],"zh":[".env 文件中需要存储 OpenAI API 密钥","依赖于 `openai` 包版本 ^4.0.0","简单分类任务的最大字符限制为 3000"],"ja":[".env ファイルに OpenAI API キーを格納する必要がある","`openai` パッケージのバージョン ^4.0.0 に依存する","シンプルな分類タスクの最大文字数は 3000"],"ko":[".env 파일에 OpenAI API 키를 저장해야 함","`openai` 패키지 버전 ^4.0.0에 의존","단순 분류 작업의 최대 문자 수는 3000"],"es":["Requiere una clave de API de OpenAI almacenada en `.env`","Dependiente de la versión del paquete `openai` ^4.0.0","Limitado a 3000 caracteres como máximo para tareas de clasificación simples"],"fr":["Nécessite une clé API OpenAI stockée dans `.env`","Dépendant de la version du paquet `openai` ^4.0.0","Limité à 3000 caractères maximum pour les tâches de classification simples"],"de":["Benötigt einen OpenAI-API-Schlüssel, der in `.env` gespeichert ist","Abhängig von der Version des `openai`-Pakets ^4.0.0","Begrenzt auf 3000 Zeichen maximal für einfache Klassifizierungsaufgaben"],"pt":["Requer chave de API da OpenAI armazenada em `.env`","Dependente da versão do pacote `openai` ^4.0.0","Limitado a 3000 caracteres máximo para tarefas de classificação simples"],"ru":["Требуется ключ API OpenAI, хранящийся в `.env`","Зависит от версии пакета `openai` ^4.0.0","Ограничен 3000 символами максимум для простых задач классификации"],"ar":["يتطلب مفتاح واجهة برمجة تطبيقات OpenAI المخزّن في `.env`","يعتمد على إصدار حزمة `openai` ^4.0.0","محدود ب 3000 حرف كحد أقصى لمهام التصنيف البسيطة"]},"version":4},"contentHash":"9713e9959f7c07fee06613a4886e14b7cf399e214a3d0a98ba4ea651a1bef2f6","qualityScore":42}');
