INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('77DidO/CRAutomatique2/openai-patterns', 'openai-patterns', '77DidO', 'CRAutomatique2', 'community', 'openai-patterns 77DidO CRAutomatique2 community The openai-patterns skill creates automatic reports using the OpenAI API. It benefits developers who need to automate tasks such as detection and extraction. OpenAI 模式是一个创建自动化的应用，使用 OpenAI 包和客户端工厂 OpenAI パターンは、OpenAI パッケージとクライアントファクトリーを使用して自動化を作成するアプリケーションです OpenAI 패턴은 OpenAI 패키지와 클라이언트 팩토리를 사용하여 자동화를 생성하는 애플리케이션입니다 Openai-patterns es una aplicación que crea un comprobante automático utilizando el paquete openai y cliente factory Openai-patterns est une application qui crée un compte rendu automatique en utilisant le paquet openai et client factory Openai-patterns ist eine Anwendung, die ein automatisches Protokoll mit dem OpenAI-Paket und Client-Factory erstellt O openai-patterns é uma aplicação que cria um compe rendu automatique com o pacote openai e cliente factory. Openai-patterns — это приложение, которое создает автоматический комперенду с пакетом openai и фабрикой клиентов. openai-patterns هو تطبيق يقوم بإنشاء عرض automatique باستخدام حزمة openai و مصنع العميل how to use openai-patterns openai-patterns setup guide openai-patterns alternative openai-patterns vs Anthropic SDK openai-patterns install what is openai-patterns openai-patterns dual-model strategy openai-patterns API configuration openai-patterns local LLM setup OpenAI 模式 AI 工具 自动化 OpenAI 包 客户端工厂 双模型策略 gpt-4o-mini 模型 AI开发 机器学习 Utilizes the OpenAI API with package version ^4.0.0 Employs a client factory from backend/src/services/openai/client-factory.ts Supports configuration via OPENAI_API_KEY in .env or OPENAI_BASE_URL for local LLM Deploys a dual-model strategy for detection and extraction tasks Uses the gpt-4o-mini model for classification and low-cost detection Extracts atomic facts with efficient processing openai-patterns is a skill that utilizes the OpenAI API to create automatic reports, leveraging a dual-model strategy for efficient detection and extraction tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('twofoldtech-dakota/plugin-migration-planner/principal-architect', 'community', 'twofoldtech-dakota', 'plugin-migration-planner', 'twofoldtech-dakota/plugin-migration-planner', 'principal-architect', 1, 0, 42, '2026-03-04T00:30:32Z', '2026-03-06T07:18:37.247Z', 'fd3294864fadcccc0f1770c3d5a5b7b535a0fc956d4dc83fa4653f3740139b7a', '{"id":"twofoldtech-dakota/plugin-migration-planner/principal-architect","name":"principal-architect","description":{"en":"The Principal-Architect skill guides architects through Sitecore XP on AWS to Sitecore XP on Azure infrastructure migrations, providing structured discovery and client-ready deliverables. It benefits architects and developers working with Sitecore XP.","zh":"Principal Architect 是一款 Claude Code 插件，帮助架构师将 Sitecore XP 从 AWS 迁移到 Azure 基础设施，提供结构化发现、交叉引用分析等功能","ja":"Principal Architect は Claude Code のプラグインであり、エンジニアが Sitecore XP を AWS から Azure インフラストラクチャに移行するのを支援し、構造化された発見、クロスリファレンス分析などを提供します","ko":"Principal Architect는 Claude Code 플러그인으로서 개발자가 Sitecore XP를 AWS에서 Azure 인프라로 마이그레이션하는 것을 지원하며 구조화된 발견, 교차 참조 분석 등을 제공합니다","es":"El plugin Principal Architect de Claude Code facilita la migración de Sitecore XP de AWS a Azure, proporcionando un análisis estructurado y una generación de entregables para clientes.","fr":"Le plugin Principal Architect de Claude Code facilite la migration de Sitecore XP d''AWS vers Azure, en fournissant une analyse structurée et une génération de livrables pour les clients.","de":"Das Principal Architect-Plugin von Claude Code erleichtert die Migration von Sitecore XP von AWS zu Azure, indem es eine strukturierte Analyse und eine Generierung von Kundenlieferungen bietet.","pt":"O Principal-Arquiteto é um plugin do Claude Code que auxilia arquitetos na migração de Sitecore XP da AWS para a Azure. Fornece descoberta estruturada, análise de referênci