INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('twofoldtech-dakota/plugin-migration-planner/principal-architect', 'principal-architect', 'twofoldtech-dakota', 'plugin-migration-planner', 'community', 'principal-architect twofoldtech-dakota plugin-migration-planner community The Principal-Architect skill guides architects through Sitecore XP on AWS to Sitecore XP on Azure infrastructure migrations, providing structured discovery and client-ready deliverables. It benefits architects and developers working with Sitecore XP. Principal Architect 是一款 Claude Code 插件，帮助架构师将 Sitecore XP 从 AWS 迁移到 Azure 基础设施，提供结构化发现、交叉引用分析等功能 Principal Architect は Claude Code のプラグインであり、エンジニアが Sitecore XP を AWS から Azure インフラストラクチャに移行するのを支援し、構造化された発見、クロスリファレンス分析などを提供します Principal Architect는 Claude Code 플러그인으로서 개발자가 Sitecore XP를 AWS에서 Azure 인프라로 마이그레이션하는 것을 지원하며 구조화된 발견, 교차 참조 분석 등을 제공합니다 El plugin Principal Architect de Claude Code facilita la migración de Sitecore XP de AWS a Azure, proporcionando un análisis estructurado y una generación de entregables para clientes. Le plugin Principal Architect de Claude Code facilite la migration de Sitecore XP d''AWS vers Azure, en fournissant une analyse structurée et une génération de livrables pour les clients. Das Principal Architect-Plugin von Claude Code erleichtert die Migration von Sitecore XP von AWS zu Azure, indem es eine strukturierte Analyse und eine Generierung von Kundenlieferungen bietet. O Principal-Arquiteto é um plugin do Claude Code que auxilia arquitetos na migração de Sitecore XP da AWS para a Azure. Fornece descoberta estruturada, análise de referência cruzada e geração de entregáveis prontos para o cliente. Principal-Architect — это плагин Claude Code, который помогает архитекторам мигрировать Sitecore XP с AWS на Azure. Предоставляет структурированное обнаружение, анализ кросс-справки и генерацию клиентских доставок. رئيس مهندس معماري هو إضافة Claude Code التي تساعد المعماريين على نقل Sitecore XP من AWS إلى Azure. توفر اكتشافا منظما وتحليلا متقاطعا وتوليد تقارير جاهزة للعميل. how to use principal-architect principal-architect setup guide sitecore xp migration tools principal-architect vs sitecore migration alternatives what is principal-architect principal-architect install sitecore xp on azure infrastructure principal-architect for ai agents sitecore xp migration best practices AI 工具 Sitecore XP 迁移 Azure 基础设施 结构化发现 交叉引用分析 阶段估算 客户准备就绪的交付物生成 Provides structured discovery for Sitecore XP on AWS to Azure migrations Performs cross-reference analysis for accurate migration planning Generates client-ready deliverables for streamlined communication Enforces existing patterns for consistent architectural decisions Decides where code belongs for optimal organization Principal-architect is a Claude Code plugin that facilitates Sitecore XP infrastructure migrations, offering phased estimation, cross-reference analysis, and deliverable generation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('growthxai/context-os-starterkit/account-health-scoring', 'community', 'growthxai', 'context-os-starterkit', 'growthxai/context-os-starterkit', 'account-health-scoring', 1, 2, 42, '2026-03-04T08:17:05Z', '2026-03-06T07:19:43.331Z', 'b36e1018b002581a4375c4f2e1402981976a4bdc93c39a0d85598e77f6d2c4b0', '{"id":"growthxai/context-os-starterkit/account-health-scoring","name":"account-health-scoring","description":{"en":"The account-health-scoring skill scores GrowthX client accounts on 5 dimensions using Andi''s rubric and compares them to EM self-reported scores, benefiting developers and companies using AI agents.","zh":"账户健康评分是使用Andi的评分标准来评估GrowthX客户账户的一种方法。它涉及数据收集和评分","ja":"アカウントヘルススコアリングは、GrowthXのクライアントアカウントをAndiの評価基準で評価する方法です。データ収集と評価が含まれます","ko":"계정 건강 점수는 Andi의 평가 기준을 사용하여 GrowthX 고객 계정을 평가하는 방법입니다. 데이터 수집 및 평가가 포함됩니다","es":"La puntuación de salud de cuenta es una función que utiliza Andi''s rubric para puntuar las cuentas de GrowthX. Extrae señales relevantes de fuentes como Fireflies transcripts, Slack history y Notion pages","fr":"Le scoring de santé de compte est une fonction qui utilise Andi''s rubric pour noter les comptes GrowthX. Elle extrait des signaux pertinents à partir de sources telles que les transcripts Fireflies, l''historique Slack et les pages Notion","de":"Der Kontogesundheitsscore ist eine Funktion, die Andi''s Rubrik verwendet, um GrowthX-Konten zu bewerten. Sie extrahiert relevante Signale aus Quellen wie Fireflies-Transkripten, Slack-Verlauf und Notion-Seiten","pt":"O Context OS é uma base de conhecimento estruturada para empresas que usam agentes de IA, permitindo a pontuação de saúde de conta em 5 dimensões","ru":"Context OS - это структурированная база знаний для компаний, использующих ИИ Агенты, позволяющая оценивать здоровье счета по 5 измерениям","ar":"Context OS هي قاعدة معرفة منظمة للشركات التي تستخدم أدوات الذكاء الاصطناعي، مما يسمح بتقييم صحة الحساب في 5 أبعاد"},"seo":{"title":{"en":"account-health-scoring: Setup Guide for AI Agents","zh":"账户健康评分设置指南 - 使用Andi的评分标准","ja":"アカウントヘルススコアリングのベストプラクティス - AIエージェントを利用した評価","ko":"계정 건강 점수 설정 가이드 - Andi의 평가 기준을 사용하여","es":"Guía de Configuración para Puntuación de Salud de Cuenta ...","fr":"Guide de Mise en Place pour le Scoring de Santé de Compte...","de":"Einrichtungsleitfaden für Kontogesundheitsscore mit KI-Ag...","pt":"Configuração de Pontuação de Saúde de Conta - Guia de Imp...","ru":"Настройка оценки здоровья счета - Руководство по настройк...","ar":"إعداد تقييم صحة الحساب - دليل الإعداد لأدوات الذكاء الاصط..."},"description":{"en":"Discover how to implement account-health-scoring for GrowthX clients, score accounts 1-5, and flag misalignments - get started now!","zh":"了解账户健康评分的技术细节，包括数据收集和评分标准。使用Andi的评分标准来评估GrowthX客户账户","ja":"アカウントヘルススコアリングの技術的な詳細を学習し、AIエージェントを利用した評価を実施する","ko":"계정 건강 점수의 기술적인 세부 정보를 확인하고 Andi의 평가 기준을 사용하여 GrowthX 고객 계정을 평가하십시오","es":"Aprende a configurar la puntuación de salud de cuenta con agentes de inteligencia artificial. Mejora la toma de decisiones con nuestra guía paso a paso","fr":"Découvrez comment configurer le scoring de santé de compte avec les outils d''intelligence artificielle. Améliorez la prise de décision avec notre guide étape...","de":"Erfahren Sie, wie Sie den Kontogesundheitsscore mit KI-Agents einrichten. Verbessern Sie die Entscheidungsfindung mit unserem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar a pontuação de saúde de conta com o Context OS, uma base de conhecimento estruturada para empresas que usam agentes de IA","ru":"Узнайте, как настроить оценку здоровья счета с помощью Context OS, структурированной базы знаний для компаний, использующих ИИ Агенты","ar":"تعرف على كيفية إعداد تقييم صحة الحساب مع Context OS، قاعدة معرفة منظمة للشركات التي تستخدم أدوات الذكاء الاصطناعي"},"definition":{"en":"account-health-scoring is a structured knowledge base skill that evaluates client accounts based on sequential data gathering from sources like Fireflies transcripts, Slack history, and Notion pages.","zh":"账户健康评分是一种使用Andi的评分标准来评估客户账户健康程度的方法","ja":"アカウントヘルススコアリングは、Andiの評価基準を使用してクライアントアカウントの健康度を評価する方法です","ko":"계정 건강 점수는 Andi의 평가 기준을 사용하여 고객 계정의 건강 상태를 평가하는 방법입니다","es":"La puntuación de salud de cuenta es una función que evalúa la salud de una cuenta utilizando cinco dimensiones y Andi''s rubric","fr":"Le scoring de santé de compte est une fonction qui évalue la santé d''un compte en utilisant cinq dimensions et Andi''s rubric","de":"Der Kontogesundheitsscore ist eine Funktion, die die Gesundheit eines Kontos anhand von fünf Dimensionen und Andi''s Rubrik bewertet","pt":"A pontuação de saúde de conta é uma avaliação de 1 a 5 em 5 dimensões, que compara as pontuações auto-relatadas com as pontuações calculadas pelo Andi","ru":"Оценка здоровья счета - это оценка от 1 до 5 по 5 измерениям, которая сравнивает самооцененные баллы с баллами, рассчитанными Андии","ar":"تقييم صحة الحساب هو تقييم من 1 إلى 5 في 5 أبعاد، يقارن بين الدرجات المبلغة ذاتيًا ودرجات Andi المحسوبة"},"features":{"en":["Scores GrowthX client accounts 1-5 on 5 dimensions using Andi''s rubric","Compares scores to EM self-reported scores and flags misalignments","Gathers data sequentially from Fireflies transcripts, Slack history, and Notion pages","Extracts relevant signals from each data source before moving on","Generates a compact scorecard (~1,000-1,500 words) for easy review"],"zh":["使用Andi的评分标准来评估客户账户","数据收集从Fireflies transcripts、Slack history和Notion pages开始","评分结果基于5个维度的评估","与EM自报成绩进行比较以发现差异","紧凑的评分卡，约1000-1500字"],"ja":["Andiの評価基準を使用してクライアントアカウントを評価する","データ収集はFireflies transcripts、Slack history、Notion pagesから始まる","評価結果は5つの要素に基づく評価","EM自報成績と比較して差異を発見する","コンパクトなスコアカード、約1000-1500字"],"ko":["Andi의 평가 기준을 사용하여 고객 계정을 평가","데이터 수집은 Fireflies transcripts, Slack 기록 및 Notion 페이지에서 시작","평가 결과는 5개 요소에 기반한 평가","EM 자기 보고 성적과 비교하여 차이를 발견","콤팩트한 점수 카드, 약 1000-1500 단어"],"es":["Utiliza Andi''s rubric para puntuar las cuentas de GrowthX","Extrae señales relevantes de fuentes como Fireflies transcripts, Slack history y Notion pages","Compara los resultados con los scores autoinformados de EM","Identifica las desviaciones entre los scores","Proporciona un panel de control compacto con los resultados"],"fr":["Utilise Andi''s rubric pour noter les comptes GrowthX","Extrait des signaux pertinents à partir de sources telles que les transcripts Fireflies, l''historique Slack et les pages Notion","Compare les résultats avec les scores auto-déclarés de EM","Identifie les écarts entre les scores","Fournit un tableau de bord compact avec les résultats"],"de":["Verwendet Andi''s Rubrik, um GrowthX-Konten zu bewerten","Extrahiert relevante Signale aus Quellen wie Fireflies-Transkripten, Slack-Verlauf und Notion-Seiten","Vergleicht die Ergebnisse mit den selbst gemeldeten Scores von EM","Identifiziert Abweichungen zwischen den Scores","Bietet ein kompaktes Dashboard mit den Ergebnissen"],"pt":["Pontuação de saúde de conta em 5 dimensões","Comparação com pontuações auto-relatadas","Sinalização de desalinhamento","Coleta sequencial de dados de fontes como Fireflies, Slack e Notion","Extração de sinais relevantes antes de mover para a próxima fonte"],"ru":["Оценка здоровья счета по 5 измерениям","Сравнение с самооцененными баллами","Сигнализация несоответствия","Последовательный сбор данных из источников, таких как Fireflies, Slack и Notion","Извлечение релевантных сигналов до перехода к следующему источнику"],"ar":["تقييم صحة الحساب في 5 أبعاد","مقارنة بالدرجات المبلغة ذاتيًا","إشارة التناقض","جمع البيانات بشكل متتالي من مصادر مثل Fireflies و Slack و Notion","استخراج الإشارات ذات الصلة قبل الانتقال إلى المصدر التالي"]},"keywords":{"en":["how to use account-health-scoring","what is account-health-scoring","account-health-scoring alternative","account-health-scoring setup guide","account-health-scoring install","GrowthX client account scoring","Andi''s rubric for account scoring","EM self-reported score comparison"],"zh":["账户健康评分","Andi评分标准","数据收集","评分卡","AI工具","客户账户评估","GrowthX","Fireflies transcripts","Slack history","Notion pages"],"ja":["アカウントヘルススコアリング","Andiの評価基準","データ収集","評価カード","AIエージェント","クライアントアカウント評価","GrowthX","Fireflies transcripts","Slack history","Notion pages"],"ko":["계정 건강 점수","Andi의 평가 기준","데이터 수집","평가 카드","AI 도구","고객 계정 평가","GrowthX","Fireflies transcripts","Slack 기록","Notion 페이지"],"es":["puntuación de salud de cuenta","agentes de inteligencia artificial","Andi''s rubric","GrowthX","Fireflies transcripts","Slack history","Notion pages","scoring de salud de cuenta","evaluación de cuentas"],"fr":["scoring de santé de compte","outils d''intelligence artificielle","Andi''s rubric","GrowthX","transcripts Fireflies","historique Slack","pages Notion","notation de santé de compte","évaluation de comptes"],"de":["Kontogesundheitsscore","KI-Agents","Andi''s Rubrik","GrowthX","Fireflies-Transkripte","Slack-Verlauf","Notion-Seiten","Bewertung von Konten","Kontogesundheitsbewertung"],"pt":["pontuação de saúde de conta","Context OS","agentes de IA","Andi","Fireflies","Slack","Notion","coleta de dados","análise de dados"],"ru":["оценка здоровья счета","Context OS","ИИ Агенты","Andi","Fireflies","Slack","Notion","сбор данных","анализ данных"],"ar":["تقييم صحة الحساب","Context OS","أدوات الذكاء الاصطناعي","Andi","Fireflies","Slack","Notion","جمع البيانات","تحليل البيانات"]}},"owner":"growthxai","repo":"context-os-starterkit","repoPath":"growthxai/context-os-starterkit","stars":1,"forks":2,"updatedAt":"2026-03-04T08:17:05Z","topics":[],"category":"community","skillMd":{"name":"account-health-scoring","description":"|","bodyPreview":"# Account Health Scoring\n\nScore a GrowthX client account 1-5 on 5 dimensions using Andi''s rubric, compare against EM self-reported scores, flag misalignment. Compact scorecard (~1,000-1,500 words), not a narrative report.\n\n## Architecture: Sequential Data Gathering\n\nData gathering is **heavy** — Fireflies transcripts, Slack history, and Notion pages can each be large. Gather each source sequentially, extracting only the relevant signals before moving on. Never dump raw transcripts or message his","body":"# Account Health Scoring\n\nScore a GrowthX client account 1-5 on 5 dimensions using Andi''s rubric, compare against EM self-reported scores, flag misalignment. Compact scorecard (~1,000-1,500 words), not a narrative report.\n\n## Architecture: Sequential Data Gathering\n\nData gathering is **heavy** — Fireflies transcripts, Slack history, and Notion pages can each be large. Gather each source sequentially, extracting only the relevant signals before moving on. Never dump raw transcripts or message histories into the output — distill findings into structured evidence summaries.\n\n```\nWorkflow:\n  1. Clarify scope\n  2. Determine engagement stage (Notion)\n  3. Gather Fireflies evidence → extract structured summary\n  4. Gather Slack evidence → extract structured summary\n  5. Gather Notion evidence → extract structured summary\n  6. Assemble evidence buckets per dimension\n  7. Score each dimension against rubric\n  8. Compare, analyze, save\n```\n\n## Workflow\n\n### Step 1 — Clarify Scope\n\n1. Ask which client to score\n2. Resolve client slug for Slack channels (`#d-int-{clientslug}`, `#d-ext-{clientslug}`)\n3. Optionally ask if there''s a specific concern (does NOT override independence rule — all 5 dimensions still scored independently)\n\n### Step 2 — Determine Engagement Stage\n\nQuery Sprint Tracker (Notion DB `2102ba60-bc74-8058-b988-000b509f811f`) for the client.\n\n| Stage | Criteria | Performance/ROI Scoring |\n|-------|----------|------------------------|\n| SPRINT | Pre-Transition Date | Foundation-building |\n| NEW | 0-3 months since Transition Date | Foundation-building |\n| ESTABLISHED | 3+ months since Transition Date | Outcomes-based |\n\n### Step 3 — Gather Evidence (3 Sources, Sequential)\n\nFor each source, read the data-sources reference file first for extraction targets.\n\n**Reference file:** `references/data-sources.md`\n\n#### Source A — Fireflies\n\n1. Use Fireflies MCP tools to find all calls for this client from the last 60-90 days\n2. For each call, fetch the transcript and/or summary\n3. Tag each call with its date\n\nExtract a structured summary organized by dimension:\n\n- **Calls Found:** List each with title and date\n- **Evidence by Dimension:** Relationship, Quantity, Content Quality, Performance/ROI, Strategy — with specific signals and dates\n- **EM Assessment (Optional):** Questions asked, dimensions covered/missing, communication style\n- **Red Flags / Green Flags observed**\n\n#### Source B — Slack\n\nSearch these channels:\n1. `#d-int-{clientslug}` — last 60-90 days (internal)\n2. `#d-ext-{clientslug}` — last 60-90 days (external/client-facing)\n3. `#d-at-risk-alerts` — all time, filter for client name\n\nExtract structured summary:\n- **Channels Searched:** message count / date range per channel\n- **Evidence by Dimension:** with dates\n- **Key Signals:** silence periods, escalation threads, at-risk alerts, leadership messages\n- **EM Slack Behavior (Optional):** response frequency, follow-up patterns, proactive vs reactive\n- **Red Flags / Green Flags observed**\n\n**IMPORTANT:** Never quote DMs. Paraphrase only.\n\n#### Source C — Notion\n\nGather from 3 Notion sources:\n\n1. **ClientDB** — EM-reported health scores (all 5 dimensions), Health Flag, MRR, Renewal Date, Pod, EM, ME, historical scores\n2. **Sprint Tracker** (DB ID: `2102ba60-bc74-8058-b988-000b509f811f`) — Sprint Kickoff Date, Sprint Length, Transition Date, Sprint Status\n3. **Sync Notes** — last 60-90 days, key discussion points, client feedback, action items\n\nExtract structured summary:\n- **Account Metadata:** Client, Pod, EM, ME, MRR, Renewal, Health Flag\n- **EM-Reported Scores** (latest table)\n- **Historical Scores** if available\n- **Engagement Stage Data** with calculated stage\n- **Evidence by Dimension** from sync notes\n\n### Step 4 — Assemble Evidence Buckets\n\nCombine all structured summaries into **per-dimension buckets**:\n\n1. **Relationship** — Relationship sections from all 3 sources\n2. **Quantity** — Quantity sections from all 3 sources\n3. **Content Quality** — Content Quality sections from all 3 sources\n4. **Performance/ROI** — Performance sections + engagement stage\n5. **Strategy** — Strategy sections from all 3 sources\n6. **EM Assessment** (optional) — only if user requested\n\nAlso collect: red flags, green flags, data gaps, evidence source metadata.\n\n### Step 5 — Score Each Dimension\n\nRead `references/scoring-rubric.md` for full criteria, flags, and independence rules.\n\nScore in order: Relationship → Quantity → Content Quality → Performance/ROI → Strategy.\n\nFor each dimension:\n1. **Isolate** — use ONLY this dimension''s evidence bucket\n2. **Apply rubric** — map evidence to 1-5 criteria\n3. **Check flags** — identify red/green flags present\n4. **Recency weight** — apply exponential decay: weight = 2^(-days_ago / 14). 14-day half-life.\n5. **Score** — assign 1-5 with 1-2 sentence justification citing specific evidence\n6. **Self-check** — \"If I cover up all other scores, does THIS score still make sense based ONLY on THIS dimension''s criteria?\"\n7. **Confidence** — High (multiple recent sources) / Medium (1-2 sources or older data) / Low (minimal evidence)\n\nPerformance/ROI: use engagement stage (NEW = foundation criteria, ESTABLISHED = outcomes criteria).\n\n**After all 5 scored:** Check for halo/horn contamination — all scores identical or all moving same direction without dimension-specific justification → re-score affected dimensions.\n\n### Step 6 — Compare, Analyze, Save\n\nRead `assets/output-template.md` for the exact output format.\n\n1. **Retrieve prior agent scores:** Search `Reports/` for the most recent prior health score file for this client (pattern: `{Client_Name}_Health_Score_*.md`). Extract the previous agent scores per dimension.\n2. Build scorecard: Agent Score | EM Score | Gap for each dimension\n3. Flag misalignment where |Agent - EM| >= 2\n4. *(Optional)* Write EM Effectiveness Assessment if user requested\n5. List action triggers per rubric (score <= 2 → director ticket; drop >= 1 → flag; red flag → document). No added recommendations — just which thresholds fired.\n6. Document data gaps\n7. Save to `Reports/{Client_Name}_Health_Score_{YYYY-MM-DD}.md`\n\nRead `references/rules.md` for scope boundaries, DM rules, and the verification checklist.\n\n## Key Rules\n\n- **Independence is mandatory.** Each dimension scored in isolation.\n- **Rubric is source of truth.** Apply Andi''s criteria exactly.\n- **Always score.** Never refuse due to missing data. Score with confidence qualifier (H/M/L) and document gaps.\n- **No DM quotes.** Paraphrase only.\n- **No compensation info.** Never include salary, bonus, or raise details.\n- **Compact output.** ~1,000-1,500 words. Scorecard with numbers, not prose narrative.\n- **No recommendations.** Action triggers flag which thresholds fired — Andi decides what to do.\n- **Quantity scores low even if client is the blocker.** Explicitly stated in rubric.\n"},"lastSynced":"2026-03-06T07:19:43.331Z","agentAnalysis":{"suitability":{"en":"Perfect for Analysis Agents needing advanced account health evaluation capabilities using Andi''s rubric","zh":"非常适合需要使用Andi的评估标准进行高级账户健康评估的分析代理","ja":"Andiのルーブリックを使用した高度なアカウントヘルス評価機能を必要とする分析エージェントに最適","ko":"Andi의 기준을 사용하여 고급 계정 건강 평가 기능을 필요로 하는 분석 에이전트에 적합","es":"Perfecto para agentes de análisis que necesitan capacidades avanzadas de evaluación de salud de cuenta utilizando la rúbrica de Andi","fr":"Parfait pour les agents d''analyse ayant besoin de capacités avancées d''évaluation de la santé des comptes utilisant la rubrique d''Andi","de":"Perfekt für Analyseagenten, die erweiterte Kontogesundheitsbewertungsfunktionen unter Verwendung der Andi-Rubrik benötigen","pt":"Perfeito para Agentes de Análise que necessitam de capacidades avançadas de avaliação da saúde da conta usando a rubrica da Andi","ru":"Идеально для аналитических агентов, которым необходимы продвинутые возможности оценки состояния счета с помощью рубрики Andi","ar":"مثالي ل وكلاء التحليل الذين يحتاجون إلى قدرات متقدمة لتقييم صحة الحساب باستخدام ربرك أنداي"},"recommendation":{"en":"Empowers agents to score GrowthX client accounts on 5 dimensions, comparing them to EM self-reported scores using sequential data gathering from Fireflies transcripts, Slack history, and Notion pages, and flagging misalignment through compact scorecards","zh":"赋予代理商能力，根据5个维度对GrowthX客户账户进行评分，比较EM自我报告的评分，使用来自Fireflies转录、Slack历史和Notion页面的顺序数据收集，并通过紧凑的评分卡标记不一致","ja":"エージェントに、5つの要素を使用してGrowthXクライアントアカウントをスコアリングする能力を付与し、EMの自己報告スコアと比較し、Firefliesの転記、Slackの履歴、Notionページからの順序データ収集を使用し、コンパクトなスコアカードを使用して不一致をフラグ付け","ko":"에이전트에게 GrowthX 클라이언트 계정에 대한 5가지 차원의 점수를 매기고, EM이 자체적으로 보고한 점수와 비교하고, Fireflies의 전사, Slack의 기록, Notion 페이지의 순차적 데이터 수집을 사용하여 불일치를紧凑한 점수카드를 통해 표시하는 능력을 부여","es":"Habilita a los agentes a puntuar las cuentas de los clientes de GrowthX en 5 dimensiones, comparándolas con las puntuaciones autoinformadas de EM utilizando la recopilación de datos secuenciales de las transcripciones de Fireflies, el historial de Slack y las páginas de Notion, y marcando la falta de alineación a través de tarjetas de puntuación compactas","fr":"Permet aux agents de noter les comptes clients de GrowthX sur 5 dimensions, en les comparant aux scores auto-déclarés de l''EM en utilisant la collecte de données séquentielles des transcriptions de Fireflies, de l''historique de Slack et des pages de Notion, et en signalant les désalignements via des cartes de scores compactes","de":"Ermöglicht es Agenten, GrowthX-Kundenkonten in 5 Dimensionen zu bewerten, indem sie sie mit den selbst gemeldeten EM-Punktzahlen vergleichen, die mithilfe der sequenziellen Datenerfassung aus Fireflies-Transkripten, Slack-Verlauf und Notion-Seiten gewonnen werden, und Abweichungen durch kompakte Punktekarten kennzeichnen","pt":"Habilita os agentes a pontuar contas de clientes do GrowthX em 5 dimensões, comparando-as com as pontuações auto-relatadas da EM usando coleta de dados sequenciais de transcrições do Fireflies, histórico do Slack e páginas do Notion, e sinalizando desalinhamento por meio de cartões de pontuação compactos","ru":"Наделяет агентов возможностью оценить счета клиентов GrowthX по 5 измерениям, сравнивая их с самооцененными баллами EM при помощи последовательного сбора данных из транскриптов Fireflies, истории Slack и страниц Notion, и флагируя несоответствие через компактные карточки оценки","ar":"يمكن للوكلاء من خلاله تقييم حسابات العملاء في GrowthX في 5 أبعاد، ومقارنتها مع درجات EM المبلّغة عن نفسها باستخدام جمع البيانات التسلسلي من نصوص Fireflies وتسجيلات Slack وصفحات Notion، وتحديد انحياز غير متوافق من خلال بطاقات درجات مدمجة"},"useCases":{"en":["Evaluating account health using Andi''s rubric","Comparing EM self-reported scores against actual performance data","Identifying misalignment in account health scores through sequential data analysis"],"zh":["使用Andi的评估标准评估账户健康","比较EM自我报告的评分与实际绩效数据","通过顺序数据分析识别账户健康评分中的不一致"],"ja":["Andiのルーブリックを使用したアカウントヘルスの評価","EMの自己報告スコアと実際のパフォーマンスデータの比較","順序データ分析を使用したアカウントヘルススコアの不一致の特定"],"ko":["Andi의 기준을 사용하여 계정 건강을 평가","EM이 자체적으로 보고한 점수와 실제 성과 데이터를 비교","순차적 데이터 분석을 통해 계정 건강 점수中的 불일치를 식별"],"es":["Evaluación de la salud de la cuenta utilizando la rúbrica de Andi","Comparación de las puntuaciones autoinformadas de EM con datos de rendimiento real","Identificación de la falta de alineación en las puntuaciones de salud de la cuenta a través del análisis de datos secuenciales"],"fr":["Évaluation de la santé du compte à l''aide de la rubrique d''Andi","Comparaison des scores auto-déclarés de l''EM avec les données de performance réelles","Identification des désalignements dans les scores de santé du compte via l''analyse de données séquentielles"],"de":["Bewertung der Kontogesundheit unter Verwendung der Andi-Rubrik","Vergleich der selbst gemeldeten EM-Punktzahlen mit den tatsächlichen Leistungsdaten","Identifizierung von Abweichungen in den Kontogesundheitspunktzahlen durch sequenzielle Datenanalyse"],"pt":["Avaliar a saúde da conta usando a rubrica da Andi","Comparar as pontuações auto-relatadas da EM com dados de desempenho reais","Identificar desalinhamento nos escores de saúde da conta por meio da análise de dados sequenciais"],"ru":["Оценка состояния счета с помощью рубрики Andi","Сравнение самооцененных баллов EM с реальными данными производительности","Определение несоответствия в баллах состояния счета посредством последовательного анализа данных"],"ar":["تقييم صحة الحساب باستخدام ربرك أنداي","مقارنة درجات EM المبلّغة عن نفسها مع بيانات الأداء الفعلية","تحديد انحياز غير متوافق في درجات صحة الحساب من خلال تحليل البيانات التسلسلي"]},"limitations":{"en":["Requires access to Fireflies transcripts, Slack history, and Notion pages","Sequential data gathering may be heavy due to large data sources","Limited to scoring on 5 dimensions using Andi''s rubric"],"zh":["需要访问Fireflies转录、Slack历史和Notion页面","顺序数据收集可能由于大型数据源而繁重","仅限使用Andi的评估标准在5个维度上进行评分"],"ja":["Firefliesの転記、Slackの履歴、Notionページへのアクセスが必要","順序データ収集は大規模なデータソースにより重くなる可能性がある","Andiのルーブリックを使用した5つの要素でのみスコアリング"],"ko":["Fireflies의 전사, Slack의 기록, Notion 페이지에 대한 접근이 필요","순차적 데이터 수집은 큰 데이터 소스 때문에 무거울 수 있음","Andi의 기준을 사용하여 5가지 차원에서만 점수를 매길 수 있음"],"es":["Requiere acceso a transcripciones de Fireflies, historial de Slack y páginas de Notion","La recopilación de datos secuenciales puede ser pesada debido a las grandes fuentes de datos","Limitado a la puntuación en 5 dimensiones utilizando la rúbrica de Andi"],"fr":["Nécessite l''accès aux transcriptions de Fireflies, à l''historique de Slack et aux pages de Notion","La collecte de données séquentielles peut être lourde en raison de grandes sources de données","Limité à la notation sur 5 dimensions en utilisant la rubrique d''Andi"],"de":["Erfordert den Zugriff auf Fireflies-Transkripte, Slack-Verlauf und Notion-Seiten","Die sequenzielle Datenerfassung kann aufgrund der großen Datenquellen umfangreich sein","Begrenzt auf die Bewertung in 5 Dimensionen unter Verwendung der Andi-Rubrik"],"pt":["Requer acesso a transcrições do Fireflies, histórico do Slack e páginas do Notion","A coleta de dados sequenciais pode ser pesada devido a grandes fontes de dados","Limitado a pontuação em 5 dimensões usando a rubrica da Andi"],"ru":["Требует доступа к транскриптам Fireflies, истории Slack и страницам Notion","Последовательный сбор данных может быть тяжелым из-за больших источников данных","Ограничен оценкой по 5 измерениям с помощью рубрики Andi"],"ar":["يتطلب الوصول إلى نصوص Fireflies وسجلات Slack وصفحات Notion","يمكن أن يكون جمع البيانات التسلسلي متعبًا بسبب مصادر البيانات الكبيرة","محدود بالتقييم على 5 أبعاد باستخدام ربرك أنداي"]},"version":4},"contentHash":"b36e1018b002581a4375c4f2e1402981976a4bdc93c39a0d85598e77f6d2c4b0","qualityScore":42}');
