INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Psqasim/personal-ai-employee/kafka-event-driven', 'kafka-event-driven', 'Psqasim', 'personal-ai-employee', 'community', 'kafka-event-driven Psqasim personal-ai-employee community The kafka-event-driven skill enables developers to build scalable event-driven systems with Apache Kafka, supporting autonomous task execution and integration with various tools. Kafka 事件驱动架构是一种分布式事件流平台，提供发布和订阅、存储和处理事件流的能力 Kafka イベント駆動アーキテクチャは、イベントストリームの公開とサブスクライブ、ストレージ、処理などの機能を提供する分散イベントストリーミングプラットフォームです Kafka 이벤트 드리븐 아키텍처는 이벤트 스트림의 발행 및 구독, 저장, 처리 등의 기능을 제공하는 분산 이벤트 스트리밍 플랫폼입니다 kafka-event-driven es una arquitectura de eventos que utiliza Apache Kafka para crear sistemas escalables y en tiempo real kafka-event-driven est une architecture orientée événements qui utilise Apache Kafka pour créer des systèmes événementiels escalables et en temps réel kafka-event-driven ist eine Event-Driven-Architektur, die Apache Kafka verwendet, um skalierbare Echtzeit-Event-Systeme zu erstellen O kafka-event-driven é uma habilidade que permite a criação de sistemas escaláveis de arquitetura orientada a eventos com Apache Kafka. kafka-event-driven - это навык, который позволяет создавать масштабируемые системы архитектуры, основанной на событиях, с Apache Kafka. kafka-event-driven هو مهارة يسمح بإنشاء أنظمة قابلة للتوسيع لهندسة مدفوعة بالأحداث مع Apache Kafka. how to use kafka-event-driven kafka-event-driven architecture apache kafka event streaming kafka-event-driven setup guide kafka-event-driven vs rabbitmq kafka-event-driven install event-driven architecture with kafka kafka-event-driven use cases kafka-event-driven tutorial Kafka 事件驱动架构 事件驱动系统 Apache Kafka 事件流平台 发布和订阅 存储和处理 Odoo 账务集成 Claude 代码 Utilizes Apache Kafka for distributed event streaming Supports publish and subscribe capabilities for event streams Provides durable storage for event streams with fault tolerance Enables real-time or retrospective processing of event streams Integrates with tools like Claude Code and Obsidian for autonomous task execution Includes human-in-the-loop approval workflow for enhanced control kafka-event-driven is a skill that utilizes Apache Kafka for building event-driven architectures, enabling publish and subscribe, store, and process event streams in real-time or retrospectively.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Abhi5415/clarido-marketing/blog-voice-analyzer', 'community', 'Abhi5415', 'clarido-marketing', 'Abhi5415/clarido-marketing', 'blog-voice-analyzer', 0, 0, 42, '2026-03-03T14:41:35Z', '2026-03-07T03:43:12.042Z', 'fd1b4423afaf836382ef89c9e6e294ebd6011f2207b05589b7420d17db35a7ce', '{"id":"Abhi5415/clarido-marketing/blog-voice-analyzer","name":"blog-voice-analyzer","description":{"en":"The blog-voice-analyzer skill analyzes blog articles for AI-sounding patterns using NLP, helping developers and writers create more human-like content and avoid Google''s helpful content signals.","zh":"Blog Voice Analyzer 使用 NLP 分析博客文章，帮助改善写作质量，避免被 Google 的有用内容信号标记","ja":"Blog Voice Analyzer は NLP を使用してブログ記事を分析し、文章の品質を向上させます","ko":"Blog Voice Analyzer는 NLP를 사용하여 블로그 게시물을 분석하고 글쓰기 품질을 향상시킵니다","es":"Blog Voice Analyzer utiliza NLP para analizar artículos de blog y detectar patrones de IA, mejorando la escritura antes de publicar.","fr":"Blog Voice Analyzer utilise NLP pour analyser les articles de blog et détecter les modèles d''IA, améliorant l''écriture avant de publier.","de":"Blog Voice Analyzer verwendet NLP, um Blogartikel zu analysieren und KI-Muster zu erkennen, um die Schreibweise vor der Veröffentlichung zu verbessern.","pt":"O Blog Voice Analyzer é uma ferramenta que analisa artigos de blog para padrões de IA usando NLP","ru":"ИИ Агент Blog Voice Analyzer анализирует статьи блогов на наличие закономерностей ИИ с помощью NLP","ar":"يحلل تحليل صوت المدونة المقالات لتحديد الأنماط الذكية باستخدام معالجة اللغة الطبيعية"},"seo":{"title":{"en":"blog-voice-analyzer: AI Pattern Detection for Human-Like ...","zh":"Blog Voice Analyzer 安装指南：使用 NLP 分析博客文章","ja":"Blog Voice Analyzer セットアップガイド：AIエージェントを使用したブログ記事分析","ko":"Blog Voice Analyzer 설정 가이드: NLP를 사용한 블로그 게시물 분석","es":"Guía de configuración de Blog Voice Analyzer para patrone...","fr":"Guide de configuration de Blog Voice Analyzer pour les mo...","de":"Einrichtungsleitfaden für Blog Voice Analyzer zur Erkennu...","pt":"Guia de Configuração do Blog Voice Analyzer para Ferramen...","ru":"Настройка ИИ Агента Blog Voice Analyzer: Руководство","ar":"إعداد تحليل صوت المدونة لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to analyze blog articles for AI-sounding patterns and improve your writing with the blog-voice-analyzer skill - try it now and enhance your content","zh":"使用 Blog Voice Analyzer 分析博客文章中的 AI 模式，改善写作质量，避免被 Google 的有用内容信号标记","ja":"ブログ記事を分析し、AIパターンを検出し、文章の品質を向上させ、Googleの有用コンテンツシグナルによるフラグを避ける","ko":"블로그 게시물에서 AI 패턴을 분석하고 글쓰기 품질을 향상시키며 Google의 유용한 콘텐츠 신호에 의해 플래그되는 것을 피합니다","es":"Analiza artículos de blog para detectar patrones de IA con NLP y mejora la escritura antes de publicar con Blog Voice Analyzer","fr":"Analysez les articles de blog pour détecter les modèles d''IA avec NLP et améliorez l''écriture avant de publier avec Blog Voice Analyzer","de":"Analysieren Sie Blogartikel auf KI-Muster mit NLP und verbessern Sie die Schreibweise vor der Veröffentlichung mit Blog Voice Analyzer","pt":"Aprenda a usar o Blog Voice Analyzer para detectar padrões de IA em artigos de blog e melhorar a escrita antes da publicação","ru":"Узнайте, как использовать ИИ Агент Blog Voice Analyzer для анализа статей блогов на наличие закономерностей ИИ","ar":"تعرف على كيفية استخدام تحليل صوت المدونة لتحديد الأنماط الذكية في المقالات وتحسين الكتابة قبل النشر"},"definition":{"en":"blog-voice-analyzer is a skill that uses Natural Language Processing (NLP) to detect AI patterns in blog articles and provide diagnostics for improvement","zh":"Blog Voice Analyzer 是一种使用 NLP 分析博客文章的工具，帮助识别 AI 模式","ja":"Blog Voice Analyzer は、ブログ記事を分析し、AIパターンを検出する AIエージェント の一種です","ko":"Blog Voice Analyzer는 블로그 게시물을 분석하여 AI 패턴을 식별하는 도구입니다","es":"Blog Voice Analyzer es una herramienta de análisis de IA que utiliza NLP para detectar patrones de IA en artículos de blog.","fr":"Blog Voice Analyzer est un outil d''analyse d''IA qui utilise NLP pour détecter les modèles d''IA dans les articles de blog.","de":"Blog Voice Analyzer ist ein KI-Analyse-Tool, das NLP verwendet, um KI-Muster in Blogartikeln zu erkennen.","pt":"O Blog Voice Analyzer é uma ferramenta de IA que detecta padrões de escrita artificial em artigos de blog","ru":"ИИ Агент Blog Voice Analyzer - это инструмент, который обнаруживает закономерности искусственного написания в статьях блогов","ar":"تحليل صوت المدونة هو أداة ذكاء اصطناعي لتحديد الأنماط الكتابية الاصطناعية في المقالات"},"features":{"en":["Invoked by the user with `/blog-voice-analyzer` command","Analyzes blog articles for AI-sounding patterns using NLP","Provides diagnostics to improve writing before publishing","Uses `pipenv run python3 scripts/blog/ai_voice_analyzer.py` for execution","Accepts `<path-to-mark>` as input for blog post analysis","Helps avoid being flagged by Google''s helpful content signals"],"zh":["使用 NLP 分析博客文章","识别 AI 模式","改善写作质量","避免被 Google 的有用内容信号标记","支持 CLI 命令行界面","使用 Python 脚本实现"],"ja":["NLP を使用してブログ記事を分析する","AIパターンを検出する","文章の品質を向上させる","Googleの有用コンテンツシグナルによるフラグを避ける","CLI コマンドラインインターフェースをサポートする","Python スクリプトを使用して実現する"],"ko":["NLP를 사용하여 블로그 게시물을 분석한다","AI 패턴을 식별한다","글쓰기 품질을 향상시킨다","Google의 유용한 콘텐츠 신호에 의해 플래그되는 것을 피한다","CLI 명령행 인터페이스를 지원한다","Python 스크립트를 사용하여 구현한다"],"es":["Análisis de patrones de IA con NLP","Mejora de la escritura antes de publicar","Invocación mediante comando `/blog-voice-analyzer`","Uso de Python 3 para la ejecución","Compatibilidad con pipenv para la gestión de dependencias"],"fr":["Analyse de modèles d''IA avec NLP","Amélioration de l''écriture avant de publier","Invocation via la commande `/blog-voice-analyzer`","Utilisation de Python 3 pour l''exécution","Compatibilité avec pipenv pour la gestion des dépendances"],"de":["Analyse von KI-Mustern mit NLP","Verbesserung der Schreibweise vor der Veröffentlichung","Aufruf über den Befehl `/blog-voice-analyzer`","Verwendung von Python 3 für die Ausführung","Kompatibilität mit pipenv für die Verwaltung von Abhängigkeiten"],"pt":["Análise de padrões de IA em artigos de blog usando NLP","Detecção de escrita artificial antes da publicação","Melhoria da escrita para evitar ser sinalizada por sinais de conteúdo útil do Google","Invocação via CLI com pipenv","Suporte a análise de artigos de blog locais"],"ru":["Анализ закономерностей ИИ в статьях блогов с помощью NLP","Обнаружение искусственного написания до публикации","Улучшение написания для избежания сигналов полезного контента Google","Вызов через CLI с pipenv","Поддержка анализа локальных статей блогов"],"ar":["تحليل الأنماط الذكية في المقالات باستخدام معالجة اللغة الطبيعية","التحقق من الكتابة الاصطناعية قبل النشر","تحسين الكتابة لتجنب إشارات المحتوى المفيد من جوجل","التشغيل عبر واجهة سطر الأوامر مع pipenv","دعم تحليل المقالات المحلية"]},"keywords":{"en":["how to use blog-voice-analyzer","what is blog-voice-analyzer","blog-voice-analyzer alternative","blog-voice-analyzer setup guide","blog-voice-analyzer install","natural language processing for blog writing","ai pattern detection in content","google helpful content signals avoidance"],"zh":["Blog Voice Analyzer","NLP","AI 模式","博客文章分析","写作质量改善","Google 有用内容信号","CLI","Python"],"ja":["Blog Voice Analyzer","NLP","AIエージェント","ブログ記事分析","文章の品質向上","Google 有用コンテンツシグナル","CLI","Python"],"ko":["Blog Voice Analyzer","NLP","AI 도구","블로그 게시물 분석","글쓰기 품질 향상","Google 유용한 콘텐츠 신호","CLI","Python"],"es":["Blog Voice Analyzer","análisis de IA","NLP","patrones de IA","mejora de la escritura","herramientas de IA","desarrollo de contenido","optimización de contenido"],"fr":["Blog Voice Analyzer","analyse d''IA","NLP","modèles d''IA","amélioration de l''écriture","outils d''IA","développement de contenu","optimisation de contenu"],"de":["Blog Voice Analyzer","KI-Analyse","NLP","KI-Muster","Verbesserung der Schreibweise","KI-Tools","Inhaltsentwicklung","Inhaltsoptimierung"],"pt":["Blog Voice Analyzer","Ferramentas de IA para escrita","Análise de padrões de IA","NLP para artigos de blog","Otimização de conteúdo para Google","Desenvolvimento de ferramentas de IA","CLI para análise de artigos","Pipenv para desenvolvimento de IA"],"ru":["ИИ Агент Blog Voice Analyzer","ИИ инструменты для написания","Анализ закономерностей ИИ","NLP для статей блогов","Оптимизация контента для Google","Разработка ИИ инструментов","CLI для анализа статей","Pipenv для разработки ИИ"],"ar":["تحليل صوت المدونة","أدوات الذكاء الاصطناعي للكتابة","تحليل الأنماط الذكية","معالجة اللغة الطبيعية للمقالات","تحسين المحتوى لجوجل","تطوير أدوات الذكاء الاصطناعي","واجهة سطر الأوامر لتحليل المقالات","Pipenv لتطوير الذكاء الاصطناعي"]}},"owner":"Abhi5415","repo":"clarido-marketing","repoPath":"Abhi5415/clarido-marketing","stars":0,"forks":0,"updatedAt":"2026-03-03T14:41:35Z","topics":[],"category":"community","skillMd":{"name":"blog-voice-analyzer","description":"Run the AI Voice Analyzer on blog content to detect AI-sounding patterns and get actionable rewrite suggestions. Use when reviewing or improving blog articles before publishing.","bodyPreview":"# Blog Voice Analyzer\n\nAnalyze blog articles for AI-sounding patterns using NLP, then use the diagnostics to improve the writing before publishing. The goal is content that reads more human than virtually all other blog articles — and avoids being flagged by Google''s helpful content signals.\n\nInvoked by the user with `/blog-voice-analyzer` or when asked to \"check\" or \"analyze\" a blog post for AI patterns.\n\n## Quick Start\n\n```bash\npipenv run python3 scripts/blog/ai_voice_analyzer.py <path-to-mark","body":"# Blog Voice Analyzer\n\nAnalyze blog articles for AI-sounding patterns using NLP, then use the diagnostics to improve the writing before publishing. The goal is content that reads more human than virtually all other blog articles — and avoids being flagged by Google''s helpful content signals.\n\nInvoked by the user with `/blog-voice-analyzer` or when asked to \"check\" or \"analyze\" a blog post for AI patterns.\n\n## Quick Start\n\n```bash\npipenv run python3 scripts/blog/ai_voice_analyzer.py <path-to-markdown-file>\n```\n\nThe script accepts any text file (markdown, plain text). It strips frontmatter, HTML, and markdown formatting before analysis.\n\n## What It Detects\n\nThe analyzer runs 18 independent checks organized into four categories. Each scores 0-100 (higher = more human), and the overall score is a weighted average.\n\n### Structural Patterns\n\n| Check | What It Measures | AI Signature | Human Signature |\n|-------|-----------------|--------------|-----------------|\n| **Sentence length variance** | Std dev of word counts per sentence | Clusters around 15-20 words (std dev < 4) | Wild variation: 3-word fragments mixed with 30-word sentences (std dev 8+) |\n| **Sentence opener diversity** | POS patterns of first 2 tokens in each sentence | 40%+ start with \"The\" or \"This\" | Fragments, questions, conjunctions, inversions, prepositional phrases |\n| **Clause depth variety** | Max dependency tree depth per sentence | Uniform depth across sentences | Mix of flat simple sentences and deeply nested complex ones |\n| **Paragraph size variety** | Coefficient of variation of paragraph word counts | Every paragraph roughly the same length | One-liners mixed with long blocks |\n\n### Vocabulary & Word Choice\n\n| Check | What It Measures | AI Signature | Human Signature |\n|-------|-----------------|--------------|-----------------|\n| **Vocabulary diversity (TTR)** | Type-token ratio of content words | Low TTR (< 45%) — recycles same words | Higher TTR, though some writers deliberately use simple vocabulary |\n| **Hedge/filler phrases** | Exact match against ~50 AI-marker phrases + ~35 signal words | \"It''s important to note\", \"multifaceted\", \"leverage\", \"delve\", \"cornerstone\" | Zero matches |\n| **Weak adverbs** | Density of \"really\", \"very\", \"literally\", \"significantly\", etc. | > 1% density | Replaced with stronger verbs or cut entirely |\n| **Nominalization density** | Nouns ending in -tion, -ment, -ness, -ity, -ence, -ance | > 5% — \"reduction\", \"transition\", \"consumption\" instead of active verbs | < 3% — prefers \"reduce\", \"shift to\", \"consume\" |\n| **Vague verb phrases** | \"contributes to\", \"remains a\", \"poses a\", \"provides a\", \"aims to\", etc. | 4-6+ per article | Zero — uses direct assertions |\n| **Word repetition** | Content words exceeding expected frequency (topic words get higher threshold) | \"Substantial\" 4x in 300 words | Topic words may repeat naturally; non-topic words stay varied |\n\n### Voice & Personality\n\n| Check | What It Measures | AI Signature | Human Signature |\n|-------|-----------------|--------------|-----------------|\n| **Personal voice** | First person (\"I\", \"we\"), second person (\"you\"), contractions (\"don''t\", \"it''s\") | Zero of all three | First person for opinions, second person for engagement, contractions for warmth |\n| **Questions asked** | Sentences ending with `?` | Zero questions — pure declaration | 5-10% of sentences are questions (rhetorical or direct) |\n| **Concrete specifics (NER)** | Named entities: people, places, dates, numbers, orgs | Zero — everything abstract and generic | Names, dates, numbers, real examples |\n| **Readability register** | Flesch-Kincaid grade + avg syllables per word | Grade 14+ (academic), avg syllables > 1.8 | Grade 6-10 (conversational), avg syllables < 1.6 |\n\n### Micro Patterns\n\n| Check | What It Measures | AI Signature | Human Signature |\n|-------|-----------------|--------------|-----------------|\n| **Passive voice** | Dependency labels `nsubjpass` / `auxpass` | > 15% of sentences | < 10% |\n| **Transition word openers** | \"However\", \"Furthermore\", \"Additionally\" at sentence start | > 0.5 per paragraph | Let ideas flow without signposting |\n| **Triple-item lists** | \"X, Y, and Z\" coordinated patterns | > 2 per 1000 words | Not everything comes in threes |\n| **Paired adjective cliches** | \"ADJ and ADJ\" via dependency parse (\"smooth and swift\", \"widespread and uniform\") | > 3 per 1000 words | Picks the stronger word |\n\n## How to Read the Output\n\n### Overall Score\n\n| Range | Interpretation |\n|-------|---------------|\n| **75-100** | Reads naturally. Minor tweaks on flagged items. |\n| **55-74** | Some AI patterns visible. Targeted rewrites recommended. |\n| **35-54** | Clear AI voice. Significant rewriting needed. |\n| **0-34** | Strongly AI-generated. Full rewrite recommended. |\n\n### Flagged Sentences\n\nOnly sentences with **2+ issues** are flagged (reduces noise). Each is labeled HIGH/MED severity with specific diagnostics like:\n\n```\n[HIGH] #13:\n\"The variability in charging station availability, especially in rural areas, poses a challenge...\"\n  → Vague verb: \"poses a\"\n  → Nominalization-heavy (4): variability, station, availability, distance\n  → Length (20w) ≈ average (21w)\n```\n\nThese are the sentences to rewrite first.\n\n### Priority Fixes\n\nThe summary lists the 5 worst-scoring dimensions with specific actions. Address these in order.\n\n## How to Use the Output to Improve Content\n\n### Step 1: Run the Analyzer\n\n```bash\npipenv run python3 scripts/blog/ai_voice_analyzer.py path/to/article.md\n```\n\n### Step 2: Fix Priority Items Top-Down\n\nWork through the priority fixes list. The most impactful improvements by category:\n\n**If Personality scores low (< 70):**\n- Add contractions throughout: \"do not\" → \"don''t\", \"it is\" → \"it''s\", \"you are\" → \"you''re\"\n- Add first person for opinions: \"I find...\", \"In my experience...\", \"We''ve all been there\"\n- Add second person to engage the reader: \"You know that feeling when...\"\n\n**If Questions score low (< 50):**\n- Turn topic sentences into questions: \"Decision fatigue depletes willpower\" → \"Why does making too many choices drain you?\"\n- Add rhetorical questions that make the reader feel seen: \"Ever notice how the simplest decisions feel impossible by 8pm?\"\n- End sections with a question that leads to the next point\n\n**If Readability scores low (< 70):**\n- Replace latinate words with shorter ones: \"utilize\" → \"use\", \"approximately\" → \"about\", \"demonstrate\" → \"show\"\n- Break long sentences at semicolons and em dashes\n- Read it out loud — if you wouldn''t say it to a friend, simplify it\n\n**If Nominalization scores low (< 70):**\n- Find every -tion/-ment/-ness noun and convert to active verb:\n  - \"The reduction of stress\" → \"Reducing stress\"\n  - \"The implementation of the system\" → \"Implementing the system\"\n  - \"His contribution to the project\" → \"He contributed to the project\"\n\n**If Hedge Phrases are detected:**\n- Delete them. Every single one. They add no meaning:\n  - \"It''s important to note that X\" → \"X\"\n  - \"In today''s fast-paced world\" → delete entirely\n  - \"multifaceted\" → \"complex\" or just describe the specific facets\n\n**If Vague Verbs are detected:**\n- Replace with direct assertions:\n  - \"X contributes to Y\" → \"X causes Y\" or \"X increases Y\"\n  - \"X remains a significant challenge\" → \"X is still hard\" or explain specifically why\n  - \"X aims to achieve Y\" → \"X does Y\" or \"X tries to Y\"\n\n**If Sentence Variance is low (< 70):**\n- Add 3-5 word fragment sentences: \"That''s the point.\" / \"And it works.\" / \"Here''s why.\"\n- Break one paragraph''s longest sentence into two\n- Start a sentence with \"But\" or \"And\"\n\n### Step 3: Re-run and Compare\n\n```bash\npipenv run python3 scripts/blog/ai_voice_analyzer.py path/to/article-v2.md\n```\n\nTarget: overall score > 80, zero HIGH-severity flagged sentences.\n\n### Step 4 (Optional): Run the Model Benchmark\n\nTo compare how different AI models perform on similar prompts:\n\n```bash\npipenv run python3 scripts/blog/benchmark_models.py\n```\n\nThis generates 3 articles per model (Claude Sonnet, Haiku; GPT-4o, 4o-mini, o3-mini) on psychology/productivity topics and scores them all. Edit `TOPICS` and `MODELS` in the script to customize.\n\n## Known Limitations\n\n**Things the analyzer catches well:**\n- Vocabulary patterns (hedge phrases, signal words, nominalizations, vague verbs)\n- Structural monotony (sentence length, opener repetition, clause depth)\n- Voice absence (no personality, no questions, no contractions)\n- Register mismatch (academic grade level for blog content)\n\n**Things the analyzer does NOT catch:**\n- **Semantic emptiness** — a sentence can sound varied and use no hedge phrases but still say nothing substantive. The tool can''t judge whether content is insightful vs. generic platitudes.\n- **Template structure at the section level** — Topic → Explanation → Topic → Explanation repeating throughout a piece is a strong AI pattern, but the tool only looks at sentence and paragraph level, not section-level templates.\n- **Cliche ideas** — the tool checks *how* you write, not *what* you write. An article full of obvious advice (\"get enough sleep\", \"exercise regularly\") will score fine structurally.\n- **Over-hedging without trigger phrases** — a passage can be wishy-washy and non-committal without using any of the specific phrases in our list.\n- **Images, formatting, and layout** — the tool only analyzes prose text.\n- **Short text** — articles under ~300 words produce unreliable scores because statistical measures need volume. Some dimensions (TTR, sentence variance) are especially noisy on short texts.\n- **Topic word inflation** — the word repetition detector tries to exclude topic words (extracted from the title and first paragraph), but it''s imperfect. If your article''s subject uses common words, they may still get flagged.\n- **Style vs. defect** — some writers deliberately use simple vocabulary (low TTR), avoid questions (declarative style), or write uniformly-sized paragraphs. The tool treats these as weaknesses because they correlate with AI output, but they may be intentional style choices. Use judgment.\n- **False paired adjective flags** — some paired adjectives are natural and effective (\"fast and powerful\"). The tool applies a per-1000-words density threshold but can still flag good writing.\n\n## Benchmark Reference Scores\n\nFrom testing across known human and AI text:\n\n| Text | Score | Notes |\n|------|-------|-------|\n| Paul Graham essays | 85-86 | Gold standard for clear, human prose |\n| Clarido blog post (AI-written, edited) | 84 | Well-crafted AI output with personality |\n| Claude Haiku (default prompt) | 82 avg | Best out-of-the-box AI model |\n| Claude Sonnet (default prompt) | 77 avg | Higher grade level, more nominalizations |\n| GPT-4o-mini (default prompt) | 70 avg | Low personality, no contractions |\n| o3-mini (default prompt) | 68 avg | Zero contractions, impersonal |\n| GPT-4o (default prompt) | 66 avg | Worst personality, fewest questions |\n| Raw ChatGPT (no prompting) | 40 | Clear AI voice across all dimensions |\n\n**Target for published content: 80+** with zero HIGH-severity flagged sentences.\n\n## Technical Details\n\n**Dependencies:** `spacy`, `textstat` (Python, installed via pipenv). Requires the `en_core_web_sm` spaCy model.\n\n**How scoring works:** Each of the 18 dimensions scores 0-100. The overall score is a weighted average with personality (0.12), hedge phrases (0.10), entity density (0.08), sentence variance (0.08), and vague verbs (0.07) weighted highest. Full weight table is in `scripts/blog/ai_voice_analyzer.py` in the `analyze()` function.\n\n**Sentence flagging threshold:** Only sentences with 2+ co-occurring issues are flagged. Single-issue sentences are not surfaced to reduce noise. The \"length close to average\" flag only triggers when the document''s overall sentence length std dev is below 6 (indicating genuine monotony).\n\n## Files\n\n| File | Purpose |\n|------|---------|\n| `scripts/blog/ai_voice_analyzer.py` | Main analyzer — run on any text file |\n| `scripts/blog/benchmark_models.py` | Generate + score articles across Claude and GPT models |\n| `tmp/benchmark/` | Cached generated articles and results.json from benchmark runs |\n"},"lastSynced":"2026-03-07T03:43:12.042Z","agentAnalysis":{"suitability":{"en":"Perfect for NLP Agents needing advanced blog content analysis and human-like writing pattern detection.","zh":"适合需要高级博客内容分析和人类写作模式检测的 NLP 代理。","ja":"NLP エージェントが高度なブログコンテンツ分析と人間のような書き込みパターン検出を必要とする場合に適しています。","ko":"고급 블로그 콘텐츠 분석 및 인간 같은 글쓰기 패턴 감지를 필요로 하는 NLP 에이전트에게 적합합니다.","es":"Perfecto para agentes de NLP que necesitan un análisis avanzado de contenido de blog y detección de patrones de escritura humanos.","fr":"Parfait pour les agents NLP ayant besoin d''une analyse avancée de contenu de blog et de détection de modèles d''écriture humaine.","de":"Perfekt für NLP-Agents, die eine erweiterte Analyse von Blog-Inhalten und eine Erkennung von schriftlichen Mustern benötigen, die wie menschliche Texte klingen.","pt":"Perfeito para Agentes de NLP que precisam de análise avançada de conteúdo de blog e detecção de padrões de escrita humanos.","ru":"Идеально для агентов NLP, которым требуется продвинутый анализ контента блогов и обнаружение закономерностей human-like написания.","ar":"مثالي للوكلاء NLP الذين يحتاجون إلى تحليل متقدم للمحتوى الإلكتروني وتحديد أنماط الكتابة البشرية."},"recommendation":{"en":"Empowers agents to analyze blog articles for AI-sounding patterns using NLP, providing diagnostics to improve writing and avoid Google''s helpful content signals through Python scripts and pipenv-run execution.","zh":"使代理能够使用 NLP 分析博客文章以检测 AI 声音模式，并通过 Python 脚本和 pipenv-run 执行提供诊断以改善写作并避免 Google 的有帮助的内容信号。","ja":"エージェントが NLP を使用してブログ記事を分析し、AI のようなパターンを検出し、Python スクリプトと pipenv-run 実行を介して診断を提供し、書き込みを改善し、Google の有益なコンテンツ信号を回避できるようにします。","ko":"에이전트가 NLP를 사용하여 블로그 게시물에서 AI 같은 패턴을 감지하고, Python 스크립트와 pipenv-run 실행을 통해 진단을 제공하여 글쓰기를 개선하고 Google의 유용한 콘텐츠 신호를 피할 수 있도록 합니다.","es":"Permite a los agentes analizar artículos de blog para detectar patrones que suenan como IA utilizando NLP, proporcionando diagnósticos para mejorar la escritura y evitar las señales de contenido útil de Google a través de scripts de Python y ejecución de pipenv-run.","fr":"Permet aux agents d''analyser les articles de blog pour détecter des modèles qui sonnent comme l''IA en utilisant le NLP, fournissant des diagnostics pour améliorer l''écriture et éviter les signaux de contenu utile de Google via des scripts Python et une exécution pipenv-run.","de":"Ermächtigt die Agents, Blog-Artikel auf Muster zu analysieren, die wie künstliche Intelligenz (KI) klingen, unter Verwendung von NLP, und liefert Diagnosen, um das Schreiben zu verbessern und Googles nützliche Inhalts-Signale durch Python-Skripte und pipenv-run-Ausführung zu vermeiden.","pt":"Habilita os agentes a analisar artigos de blog para padrões que soam como IA usando NLP, fornecendo diagnósticos para melhorar a escrita e evitar os sinais de conteúdo útil do Google por meio de scripts Python e execução pipenv-run.","ru":"Наделяет агентов возможностью анализировать блог-посты на наличие закономерностей, похожих на ИИ, с помощью NLP, предоставляя диагностику для улучшения стиля написания и избежания сигналов полезного контента Google с помощью скриптов Python и запуска pipenv-run.","ar":"تمكين الوكلاء من تحليل مقالات المدونة لاكتشاف الأنماط التي تُظهر أنها تشبه الذكاء الاصطناعي باستخدام NLP، وتقديم تشخيصات لتحسين الكتابة وتجنب إشارات المحتوى المفيد من جوجل من خلال سكريبتات بايثون وتنفيذ pipenv-run."},"useCases":{"en":["Analyzing blog posts for AI-generated content detection","Improving blog article writing style to sound more human-like","Debugging content to avoid Google''s helpful content signals"],"zh":["分析博客帖子以检测 AI 生成的内容","改进博客文章的写作风格以使其听起来更像人类","调试内容以避免 Google 的有帮助的内容信号"],"ja":["AI 生成コンテンツの検出のためにブログ投稿を分析する","ブログ記事の書き込みスタイルを改善してより人間のように聞こえるようにする","Google の有益なコンテンツシグナルを回避するためにコンテンツをデバッグする"],"ko":["AI 생성 콘텐츠 감지를 위한 블로그 게시물 분석","블로그 게시물의 글쓰기 스타일을 개선하여 더 인간적으로 들리게 하는 것","Google의 유용한 콘텐츠 신호를 피하기 위한 콘텐츠 디버깅"],"es":["Análisis de publicaciones de blog para la detección de contenido generado por IA","Mejora del estilo de escritura de artículos de blog para que suene más como un humano","Depuración de contenido para evitar las señales de contenido útil de Google"],"fr":["Analyse de billets de blog pour la détection de contenu généré par l''IA","Amélioration du style d''écriture d''articles de blog pour qu''il sonne plus comme un humain","Débogage de contenu pour éviter les signaux de contenu utile de Google"],"de":["Analyse von Blog-Beiträgen zur Erkennung von KI-generiertem Inhalt","Verbesserung des Schreibstils von Blog-Artikeln, um ihn menschlicher klingen zu lassen","Fehlerbehebung von Inhalten, um Googles nützliche Inhalts-Signale zu vermeiden"],"pt":["Analisar posts de blog para detecção de conteúdo gerado por IA","Melhorar o estilo de escrita de artigos de blog para soar mais humanos","Depurar conteúdo para evitar sinais de conteúdo útil do Google"],"ru":["Анализ блог-постов для обнаружения контента, сгенерированного ИИ","Улучшение стиля написания блог-постов, чтобы звучать более human-like","Отладка контента, чтобы избежать сигналов полезного контента Google"],"ar":["تحليل منشورات المدونة لاكتشاف المحتوى المتولد بواسطة الذكاء الاصطناعي","تحسين أسلوب كتابة مقالات المدونة لجعلها تُظهر أنها مكتوبة بالطريقة البشرية","تصحيح أخطاء المحتوى لتجنب إشارات المحتوى المفيد من جوجل"]},"limitations":{"en":["Requires Python 3 execution environment","Needs access to blog article text data","Limited to analyzing text-based blog content"],"zh":["需要 Python 3 执行环境","需要访问博客文章文本数据","仅限于分析基于文本的博客内容"],"ja":["Python 3 実行環境が必要","ブログ記事のテキストデータにアクセスする必要がある","テキストベースのブログコンテンツの分析のみ"],"ko":["Python 3 실행 환경 필요","블로그 게시물 텍스트 데이터에 접근할 수 필요","텍스트 기반 블로그 콘텐츠 분석만 가능"],"es":["Requiere un entorno de ejecución de Python 3","Necesita acceso a datos de texto de artículos de blog","Limitado a analizar contenido de blog basado en texto"],"fr":["Nécessite un environnement d''exécution Python 3","A besoin d''accès aux données de texte d''articles de blog","Limité à l''analyse de contenu de blog basé sur du texte"],"de":["Benötigt eine Python-3-Ausführungsumgebung","Benötigt Zugriff auf Textdaten von Blog-Artikeln","Begrenzt auf die Analyse von textbasiertem Blog-Inhalt"],"pt":["Requer ambiente de execução Python 3","Necessita acesso a dados de texto de artigos de blog","Limitado à análise de conteúdo de blog baseado em texto"],"ru":["Требуется среда выполнения Python 3","Необходим доступ к данным текста блог-постов","Ограничен анализом текстового контента блогов"],"ar":["يتطلب بيئة تشغيل بايثون 3","يحتاج إلى الوصول إلى بيانات نص مقالات المدونة","محدود بالتحليل المحتوى النصي للمدونة"]},"version":4},"contentHash":"fd1b4423afaf836382ef89c9e6e294ebd6011f2207b05589b7420d17db35a7ce","qualityScore":42}');
