INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('matrixshader/matrix-shader/oracle', 'oracle', 'matrixshader', 'matrix-shader', 'community', 'oracle matrixshader matrix-shader community The Oracle skill processes pending FAQ questions and drafts accurate answers by reading the codebase. It flags business questions for humans and identifies spam for cleanup, requiring user approval for each action. Oracle AI工具自动处理MatrixShader支持页的FAQ，读取代码库并分类问题 Oracle AIエージェントはMatrixShaderサポートページのFAQを自動処理し、コードベースを読み込んで質問を分類します Oracle AI 에이전트는 MatrixShader 지원 페이지의 FAQ를 자동으로 처리하며 코드베이스를 읽어 질문을 분류합니다 Oracle es una herramienta que procesa preguntas pendientes y proporciona respuestas precisas para Matrix rain en Windows Terminal Oracle est un outil qui traite les questions en attente et fournit des réponses précises pour Matrix rain sous Windows Terminal Oracle ist ein Tool, das ausstehende Fragen bearbeitet und genaue Antworten für Matrix rain unter Windows Terminal liefert O Oracle é um agente que processa perguntas pendentes e fornece respostas precisas para o Matrix Rain no Windows Terminal. ИИ Агент Oracle - это агент, который обрабатывает_pending вопросы и предоставляет точные ответы для Matrix Rain в Windows Terminal Oracle هو وسيط يقوم بمعالجة الأسئلة المعلقة ويوفر إجابات دقيقة ل Matrix Rain في Terminal Windows how to use oracle what is oracle oracle alternative oracle vs matrixshader oracle install oracle setup guide matrix rain windows terminal ai agent skills for windows terminal automating faq questions Oracle AI工具 MatrixShader支持页FAQ 自动处理FAQ 代码库读取 问题分类 AI工具开发 FAQ自动回答 Fetches pending questions via GET /api/faq?status=pending with Bearer auth Reads codebase files to build answer context Classifies questions into CAN ANSWER, NEEDS HUMAN, or SPAM categories Requires user approval before executing each action Supports drafting accurate answers using the codebase Identifies spam for cleanup Oracle is a Matrix rain AI agent skill for Windows Terminal that automates FAQ question processing and answering.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('haenel881988/speicher-analyse/add-tauri-command', 'community', 'haenel881988', 'speicher-analyse', 'haenel881988/speicher-analyse', 'add-tauri-command', 0, 0, 42, '2026-02-21T18:18:44Z', '2026-03-07T03:46:50.639Z', 'e115835bb4e725350628f42e07bab011f1f295ed64d3fa8abc533bb0e12969e3', '{"id":"haenel881988/speicher-analyse/add-tauri-command","name":"add-tauri-command","description":{"en":"The add-tauri-command skill allows developers to add new commands to the Speicher Analyse app, enhancing its functionality. It benefits developers working with Tauri and Electron desktop apps","zh":"添加 Tauri 命令以增强 Speicher Analyse App 的功能，包括系统优化和硬盘分析。使用 Electron 框架开发的桌面应用。","ja":"Tauri コマンドを追加して Speicher Analyse App の機能を強化します。システム最適化とハードディスク分析を含む Electron フレームワークで開発されたデスクトップアプリ。","ko":"Tauri 명령어를 추가하여 Speicher Analyse App의 기능을 강화합니다. 시스템 최적화와 하드디스크 분석을 포함하는 Electron 프레임워크로 개발된 데스크톱 애플리케이션.","es":"El comando ''add-tauri-command'' permite agregar nuevos comandos a la aplicación de análisis de disco para mejorar su funcionalidad","fr":"La commande ''add-tauri-command'' permet d''ajouter de nouvelles commandes à l''application d''analyse de disque pour améliorer ses fonctionnalités","de":"Der Befehl ''add-tauri-command'' ermöglicht das Hinzufügen neuer Befehle zur Festplattenanalyse-App, um deren Funktionalität zu verbessern","pt":"O comando add-tauri-command permite adicionar novos comandos Tauri à aplicação de análise de disco. Ele aceita argumentos como nome do comando e descrição","ru":"Команда add-tauri-command позволяет добавлять новые команды Tauri к приложению анализа диска. Она принимает аргументы, такие как имя команды и описание","ar":"الأمر add-tauri-command يسمح بإضافة أوامر Tauri جديدة إلى تطبيق تحليل القرص. وهو يقبل معاملات مثل اسم الأمر ووصفه"},"seo":{"title":{"en":"add-tauri-command: Tauri Command Setup Guide | AI Agent S...","zh":"Tauri 命令添加指南 - AI エージェント集成","ja":"Tauri コマンド追加セットアップガイド - AI エージェント","ko":"Tauri 명령어 추가 설정 가이드 - AI 에이전트","es":"Guía de configuración para agregar comandos Tauri","fr":"Guide d''installation pour ajouter des commandes Tauri","de":"Einrichtungsanleitung zum Hinzufügen von Tauri-Befehlen","pt":"Adicionar Comando Tauri: Guia de Configuração","ru":"Добавление Команды Tauri: Лучшие Практики для ИИ Агентов","ar":"إضافة أمر Tauri: دليل الإعداد للآلات الذكية"},"description":{"en":"Learn how to add new Tauri commands to your Speicher Analyse app with this step-by-step guide. Discover the power of custom commands and optimize your system","zh":"了解如何向 Speicher Analyse App 添加 Tauri 命令，优化 Windows 系统性能 - AI 工具","ja":"Speicher Analyse App に Tauri コマンドを追加して Windows システムを最適化する方法を学ぶ - AI エージェント","ko":"Speicher Analyse App에 Tauri 명령어를 추가하여 Windows 시스템을 최적화하는 방법 - AI 에이전트","es":"Aprende a agregar comandos personalizados a tu aplicación de análisis de disco con Tauri y mejora su funcionalidad","fr":"Découvrez comment ajouter des commandes personnalisées à votre application d''analyse de disque avec Tauri et améliorez ses fonctionnalités","de":"Erfahren Sie, wie Sie benutzerdefinierte Befehle zu Ihrer Festplattenanalyse-App mit Tauri hinzufügen und deren Funktionalität verbessern","pt":"Aprenda a adicionar comandos Tauri à sua aplicação de análise de disco com Electron. Descubra como melhorar a otimização do sistema","ru":"Узнайте, как добавить команды Tauri к вашему приложению анализа диска с Electron. Откройте для себя, как улучшить оптимизацию системы с помощью ИИ Агентов","ar":"تعرف على كيفية إضافة أوامر Tauri إلى تطبيق تحليل القرص الخاص بك مع Electron. اكتشف كيف تحسن تحسين النظام باستخدام الآلات الذكية"},"definition":{"en":"add-tauri-command is a skill that enables the addition of new Tauri commands to the Speicher Analyse app, facilitating custom system optimization and analysis","zh":"Tauri 命令添加是向 Speicher Analyse App 添加新命令的过程，用于系统优化和硬盘分析","ja":"Tauri コマンド追加は、S