INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('haenel881988/speicher-analyse/add-tauri-command', 'add-tauri-command', 'haenel881988', 'speicher-analyse', 'community', 'add-tauri-command haenel881988 speicher-analyse community The add-tauri-command skill allows developers to add new commands to the Speicher Analyse app, enhancing its functionality. It benefits developers working with Tauri and Electron desktop apps 添加 Tauri 命令以增强 Speicher Analyse App 的功能，包括系统优化和硬盘分析。使用 Electron 框架开发的桌面应用。 Tauri コマンドを追加して Speicher Analyse App の機能を強化します。システム最適化とハードディスク分析を含む Electron フレームワークで開発されたデスクトップアプリ。 Tauri 명령어를 추가하여 Speicher Analyse App의 기능을 강화합니다. 시스템 최적화와 하드디스크 분석을 포함하는 Electron 프레임워크로 개발된 데스크톱 애플리케이션. El comando ''add-tauri-command'' permite agregar nuevos comandos a la aplicación de análisis de disco para mejorar su funcionalidad La commande ''add-tauri-command'' permet d''ajouter de nouvelles commandes à l''application d''analyse de disque pour améliorer ses fonctionnalités Der Befehl ''add-tauri-command'' ermöglicht das Hinzufügen neuer Befehle zur Festplattenanalyse-App, um deren Funktionalität zu verbessern O comando add-tauri-command permite adicionar novos comandos Tauri à aplicação de análise de disco. Ele aceita argumentos como nome do comando e descrição Команда add-tauri-command позволяет добавлять новые команды Tauri к приложению анализа диска. Она принимает аргументы, такие как имя команды и описание الأمر add-tauri-command يسمح بإضافة أوامر Tauri جديدة إلى تطبيق تحليل القرص. وهو يقبل معاملات مثل اسم الأمر ووصفه how to use add-tauri-command add-tauri-command setup guide Tauri command implementation Speicher Analyse app customization add-tauri-command vs Electron commands install add-tauri-command Tauri 命令添加 Speicher Analyse App Electron 框架 系统优化 硬盘分析 AI 工具 AI エージェント 桌面应用开发 Adds new Tauri commands to the Speicher Analyse app using snake_case naming convention Supports optional command descriptions for better documentation Utilizes the src-tauri/src/commands/ module for command implementation Follows the re-export structure defined in src-tauri/src/commands/mod.rs Enables custom system optimization and analysis through Tauri commands add-tauri-command is a skill that enables the addition of new Tauri commands to the Speicher Analyse app, facilitating custom system optimization and analysis');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('muhammadwaheedairi/Personal-AI-Employee/whatsapp-triage', 'community', 'muhammadwaheedairi', 'Personal-AI-Employee', 'muhammadwaheedairi/Personal-AI-Employee', 'whatsapp-triage', 0, 1, 42, '2026-02-26T02:26:05Z', '2026-03-07T13:06:18.735Z', '4fdfe9257c3352cbcdaf06def4bc1a70afb1ecf2ec6ee69bfa608b03ec5f872e', '{"id":"muhammadwaheedairi/Personal-AI-Employee/whatsapp-triage","name":"whatsapp-triage","description":{"en":"The whatsapp-triage skill automates workflows by monitoring emails, finances, and tasks, and delivers weekly CEO briefings. It benefits developers and CEOs by executing workflows via MCP agents and routing actions to pending approval.","zh":"WhatsApp Triage 是一个本地优先的自治 AI 员工，监控电子邮件、财务和任务，执行工作流并提供每周 CEO 简报","ja":"WhatsApp Triage はローカルファーストの自律型 AI エージェントで、メール、財務、タスクを監視し、ワークフローを実行して毎週 CEOブリーフィングを提供する","ko":"WhatsApp Triage는 로컬 우선의 자율적인 AI 직원으로, 이메일, 재무, 작업을 모니터링하고 워크플로우를 실행하여 매주 CEO 브리핑을 제공합니다","es":"whatsapp-triage es un agente de inteligencia artificial que monitorea correos electrónicos, finanzas y tareas, ejecuta flujos de trabajo y entrega informes semanales al CEO","fr":"whatsapp-triage est un agent d''intelligence artificielle qui surveille les emails, les finances et les tâches, exécute les flux de travail et fournit des rapports hebdomadaires au CEO","de":"whatsapp-triage ist ein künstlicher Intelligenzagent, der E-Mails, Finanzen und Aufgaben überwacht, Workflows ausführt und dem CEO wöchentliche Berichte liefert","pt":"O WhatsApp Triage é um agente de IA que automatiza fluxos de trabalho, detecta intenções e atribui prioridades para melhorar a produtividade","ru":"WhatsApp Triage - это агент ИИ, который автоматизирует рабочие процессы, обнаруживает намерения и присваивает приоритеты для повышения производительности","ar":"WhatsApp Triage هو وکیل ذكاء اصطناعي يلقم سير العمل، يكشف النيات ويعين الأولويات لتحسين الإنتاجية"},"seo":{"title":{"en":"whatsapp-triage: Autonomous Workflow Automation for AI Ag...","zh":"WhatsApp Triage 技术集成指南","ja":"WhatsApp Triage のベストプラクティス","ko":"WhatsApp Triage 셋업 가이드","es":"Guía de configuración de whatsapp-triage para automatizac...","fr":"Guide de mise en place de whatsapp-triage pour l''automati...","de":"Einrichtungsleitfaden für whatsapp-triage zur Workflownau...","pt":"Guia de Configuração do WhatsApp Triage: Automação de Flu...","ru":"Настройка WhatsApp Triage: Руководство по автоматизации р...","ar":"دليل إعداد WhatsApp Triage: تلقيم سير العمل مع وكلاء الذك..."},"description":{"en":"Discover how whatsapp-triage streamlines tasks and finances with autonomous AI agents. Learn how to setup and optimize your workflow with our expert guide.","zh":"了解 WhatsApp Triage 的技术优势，实现自动化工作流和提高生产力","ja":"WhatsApp Triage を使用して自動化ワークフローを実現し、生産性を向上させる","ko":"WhatsApp Triage로 자동화 워크플로우를 구현하고 생산성을 향상시키는 방법","es":"Aprende a configurar whatsapp-triage para automatizar flujos de trabajo y mejorar la productividad con nuestra guía paso a paso","fr":"Découvrez comment configurer whatsapp-triage pour automatiser les flux de travail et améliorer la productivité avec notre guide étape par étape","de":"Erfahren Sie, wie Sie whatsapp-triage konfigurieren, um Workflows zu automatisieren und die Produktivität zu steigern, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o WhatsApp Triage para automatizar fluxos de trabalho e melhorar a produtividade com nossa guia passo a passo","ru":"Узнайте, как настроить WhatsApp Triage для автоматизации рабочих процессов и повышения производительности с нашей пошаговой инструкцией","ar":"تعرف على كيفية إعداد WhatsApp Triage لتلقيم سير العمل وتحسين الإنتاجية مع دليلنا المتواصل"},"definition":{"en":"whatsapp-triage is a local-first autonomous AI employee that detects intent, assigns priority, and creates action plans based on WhatsApp messages.","zh":"WhatsApp Triage 是一种 AI 工具，用于自动化工作流和提高生产力","ja":"WhatsApp Triage は AI エージェントで、ワークフローを自動化し、生産性を向上させる","ko":"WhatsApp Triage는 워크플로우를 자동화하고 생산성을 향상시키는 AI 도구입니다","es":"whatsapp-triage es un agente de inteligencia artificial que automatiza flujos de trabajo y mejora la productividad","fr":"whatsapp-triage est un agent d''intelligence artificielle qui automatise les flux de travail et améliore la productivité","de":"whatsapp-triage ist ein künstlicher Intelligenzagent, der Workflows automatisiert und die Produktivität steigert","pt":"O que é WhatsApp Triage? Um agente de IA que automatiza fluxos de trabalho e detecta intenções para melhorar a produtividade","ru":"Что такое WhatsApp Triage? Это агент ИИ, который автоматизирует рабочие процессы и обнаруживает намерения для повышения производительности","ar":"ما هو WhatsApp Triage? وکیل ذكاء اصطناعي يلقم سير العمل ويكشف النيات لتحسين الإنتاجية"},"features":{"en":["Monitors emails, finances, and tasks via MCP agents","Detects intent and assigns priority based on urgent keywords","Creates action plans and routes outgoing actions to /Pending_Approval/","Delivers weekly CEO briefings with real productivity gains","Requires human-in-the-loop (HITL) approval for all WhatsApp sends","Processes WhatsApp messages stored in WHATSAPP_*.md files"],"zh":["监控电子邮件、财务和任务","执行工作流并提供每周 CEO 简报","使用 MCP 代理执行工作流","支持人机协作（HITL）","自动检测意图和优先级","将所有出站操作路由到 /Pending_Approval/"],"ja":["メール、財務、タスクを監視する","ワークフローを実行して毎週 CEOブリーフィングを提供する","MCP エージェントを使用してワークフローを実行する","ヒューマン・イン・ザ・ループ（HITL）をサポートする","意図と優先度を自動で検出する","すべてのアウトバウンド操作を /Pending_Approval/ にルーティングする"],"ko":["이메일, 재무, 작업을 모니터링합니다","워크플로우를 실행하여 매주 CEO 브리핑을 제공합니다","MCP 에이전트를 사용하여 워크플로우를 실행합니다","ヒューマン・イン・ザ・ループ（HITL）를 지원합니다","의도와 우선순위를 자동으로 감지합니다","모든 아웃바운드 작업을 /Pending_Approval/로 라우팅합니다"],"es":["Detección de intención en correos electrónicos","Asignación de prioridad basada en palabras clave urgentes","Creación de planes de acción y enrutamiento de acciones a la carpeta de aprobación pendiente","Integración con MCP agents para la ejecución de flujos de trabajo","Requerimiento de aprobación humana para todas las acciones de envío de WhatsApp"],"fr":["Détection d''intention dans les emails","Attribution de priorité basée sur des mots-clés urgents","Création de plans d''action et routage des actions vers le dossier d''approbation en attente","Intégration avec les agents MCP pour l''exécution des flux de travail","Exigence d''approbation humaine pour toutes les actions d''envoi de WhatsApp"],"de":["Intentionserkennung in E-Mails","Priorisierung basierend auf dringlichen Schlüsselwörtern","Erstellung von Aktionsplänen und Weiterleitung von Aktionen an den Ordner für ausstehende Genehmigung","Integration mit MCP-Agents für die Ausführung von Workflows","Erfordernis der menschlichen Genehmigung für alle WhatsApp-Sendevorgänge"],"pt":["Detecção de intenções com base em padrões de classificação","Atribuição de prioridades com base em palavras-chave urgentes","Criação de planos de ação e encaminhamento para aprovação","Integração com MCP agents para automação de fluxos de trabalho","Requisição de aprovação humana para todas as ações de envio"],"ru":["Обнаружение намерений на основе шаблонов классификации","Присвоение приоритетов на основе срочных ключевых слов","Создание планов действий и направление на утверждение","Интеграция с агентами MCP для автоматизации рабочих процессов","Требование человеческого утверждения для всех действий отправки"],"ar":["كشف النيات على أساس أنماط التصنيف","تعيين الأولويات على أساس الكلمات الرئيسية العاجلة","إنشاء خطط العمل وتوجيهها للموافقة","التكامل مع وكلاء MCP لتلقيم سير العمل","طلب الموافقة البشرية لجميع إجراءات الإرسال"]},"keywords":{"en":["whatsapp-triage setup guide","autonomous AI employee workflow","MCP agent workflow automation","whatsapp-triage vs traditional workflow tools","how to use whatsapp-triage for task automation","whatsapp-triage install and configuration","AI agent workflow optimization","whatsapp-triage alternative solutions","whatsapp-triage for CEO productivity"],"zh":["AI 工具","自动化工作流","提高生产力","WhatsApp Triage","MCP 代理","人机协作","意图检测","优先级分配"],"ja":["AI エージェント","ワークフロー自動化","生産性向上","WhatsApp Triage","MCP エージェント","ヒューマン・イン・ザ・ループ","意図検出","優先度割り当て"],"ko":["AI 도구","자동화 워크플로우","생산성 향상","WhatsApp Triage","MCP 에이전트","ヒューマン・イン・ザ・ループ","의도 감지","우선순위 할당"],"es":["agente de inteligencia artificial","automatización de flujo de trabajo","detección de intención","asignación de prioridad","integración con MCP agents","informes semanales al CEO","productividad","gestión de tareas","gestión de correos electrónicos"],"fr":["agent d''intelligence artificielle","automatisation des flux de travail","détection d''intention","attribution de priorité","intégration avec les agents MCP","rapports hebdomadaires au CEO","productivité","gestion des tâches","gestion des emails"],"de":["künstlicher Intelligenzagent","Workflownautomatisierung","Intentionserkennung","Priorisierung","Integration mit MCP-Agents","wöchentliche Berichte an den CEO","Produktivität","Aufgabenmanagement","E-Mail-Management"],"pt":["whatsapp triage","agente de ia","automação de fluxo de trabalho","detecção de intenções","atribuição de prioridades","mcp agents","aprovação humana","produtividade","eficiência"],"ru":["whatsapp triage","агент ии","автоматизация рабочих процессов","обнаружение намерений","присвоение приоритетов","агенты мcp","человеческое утверждение","производительность","эффективность"],"ar":["whatsapp triage","وکیل ذكاء اصطناعي","تلقيم سير العمل","كشف النيات","تعيين الأولويات","وكلاء مcp","موافقة بشرية","إنتاجية","كفاءة"]}},"owner":"muhammadwaheedairi","repo":"Personal-AI-Employee","repoPath":"muhammadwaheedairi/Personal-AI-Employee","stars":0,"forks":1,"updatedAt":"2026-02-26T02:26:05Z","topics":["ai-agents","autonomous-agents","human-in-the-loop","personal-ai-employee","workflow-automation"],"category":"community","skillMd":{"name":"whatsapp-triage","description":"Triage and process WhatsApp action files from the AI Employee vault. This skill should be used when WHATSAPP_*.md files appear in /Needs_Action folder, or when user asks to handle WhatsApp messages, draft replies, or generate invoices from chat requests. Reads message content, detects intent, creates Plan.md with steps, and always routes replies to /Pending_Approval — never sends directly to WhatsApp without human approval.","bodyPreview":"# WhatsApp Triage\n\nProcess `WHATSAPP_*.md` files from `/Needs_Action/`. Detect intent, assign priority, create action plans, and route all outgoing actions to `/Pending_Approval/`. **All WhatsApp sends require HITL approval** — never act directly.\n\n## Workflow\n\n1. **Read** the `WHATSAPP_*.md` file from `/Needs_Action/`\n2. **Detect intent** — see `references/intents.md` for classification patterns\n3. **Assign priority** based on urgent keywords (already set by watcher):\n   - **high**: urgent, asa","body":"# WhatsApp Triage\n\nProcess `WHATSAPP_*.md` files from `/Needs_Action/`. Detect intent, assign priority, create action plans, and route all outgoing actions to `/Pending_Approval/`. **All WhatsApp sends require HITL approval** — never act directly.\n\n## Workflow\n\n1. **Read** the `WHATSAPP_*.md` file from `/Needs_Action/`\n2. **Detect intent** — see `references/intents.md` for classification patterns\n3. **Assign priority** based on urgent keywords (already set by watcher):\n   - **high**: urgent, asap, invoice, payment, emergency, important\n   - **medium**: help, problem, price, quote, service inquiry\n   - **low**: general conversation, thank you messages\n4. **Create action plan** in `/Plans/PLAN_WHATSAPP_{timestamp}.md` using templates from `references/action-templates.md`\n5. **Route sensitive messages** to `/Pending_Approval/` for human review:\n   - Payment/invoice messages (always)\n   - Urgent/emergency messages (always)\n   - All reply drafts (always — never send without approval)\n6. **Log action** to `/Vault/Logs/YYYY-MM-DD.json`\n7. **Move** source `WHATSAPP_*.md` to `/Done/` when plan is complete\n8. Output `<promise>TASK_COMPLETE</promise>`\n\n## Urgent Keywords (from watcher)\n\nThe WhatsApp watcher automatically flags messages containing these keywords and marks them as **priority: high**:\n- `urgent`\n- `asap`\n- `invoice`\n- `payment`\n- `emergency`\n- `important`\n\nThese are defined in `watchers/whatsapp_watcher.py:18`:\n```python\nURGENT_KEYWORDS = [\"urgent\", \"asap\", \"invoice\", \"payment\", \"emergency\", \"important\"]\n```\n\n## Action Decision Tree\n\n```\nWHATSAPP_*.md arrives in /Needs_Action/\n    │\n    ├─ Contains \"payment\" or \"invoice\"? → Generate invoice plan → /Pending_Approval/ (high priority)\n    │\n    ├─ Contains \"urgent\" or \"emergency\"? → Draft urgent response → /Pending_Approval/ (high priority)\n    │\n    ├─ Contains \"price\" or \"quote\"? → Draft pricing response → /Pending_Approval/ (medium priority)\n    │\n    ├─ Service inquiry? → Draft informative response → /Pending_Approval/ (medium priority)\n    │\n    └─ General message? → Determine if response needed → /Pending_Approval/ or archive\n```\n\n## WHATSAPP_*.md File Format\n\nFiles created by the watcher have this structure:\n\n```markdown\n---\ntype: whatsapp\nsource: whatsapp_web\nreceived: {iso_timestamp}\npriority: high\nstatus: pending\nmsg_id: {hash_id}\n---\n\n# WhatsApp Urgent Message\n\n**Received:** {date_time}\n**Priority:** High\n\n## Message Preview\n{message_text_with_context}\n\n## Matched Keyword In\n{line_that_triggered_urgent_flag}\n\n## Suggested Actions\n- [ ] Reply to sender\n- [ ] Generate invoice if requested\n- [ ] Escalate if payment-related\n```\n\n## Plan.md Template\n\n```markdown\n---\ntype: plan\ncreated: {iso_timestamp}\nsource_file: WHATSAPP_{timestamp}.md\nsource_type: whatsapp\npriority: {high|medium|low}\nstatus: pending\n---\n\n# Plan: WhatsApp — {detected_intent}\n\n## Context\n**Received:** {date}\n**Priority:** {priority}\n**Matched Keywords:** {keywords}\n\n## Objective\n{one-line goal — e.g., \"Draft reply to urgent client inquiry about project status\"}\n\n## Steps\n- [ ] {step 1}\n- [ ] {step 2}\n- [ ] {step 3}\n...\n\n## Completion Rule\nMove this file and source WHATSAPP_*.md to /Done/ when {completion condition}.\n```\n\n## Security Rules\n\n- **NEVER** send WhatsApp messages directly — always write drafts to `/Pending_Approval/`\n- **ALWAYS** route payment/invoice messages to `/Pending_Approval/` for human review\n- **ALWAYS** route urgent messages to `/Pending_Approval/` for immediate human attention\n- **ALWAYS** log every action to `/Vault/Logs/YYYY-MM-DD.json`\n- **NEVER** delete WHATSAPP_*.md files — move to `/Done/` instead\n- **NEVER** confirm payment receipt without explicit human verification\n\n## Approval File Format\n\nWhen routing replies to `/Pending_Approval/`, use this format:\n\n```markdown\n---\ntype: whatsapp_reply\naction: send_whatsapp\nto: {contact_name}\nphone: {phone_number}\nsource_file: WHATSAPP_{timestamp}.md\npriority: {high|medium|low}\ncreated: {iso_timestamp}\nstatus: awaiting_approval\n---\n\n# WhatsApp Reply: {contact_name}\n\n**To:** {contact_name} ({phone_number})\n**Priority:** {priority}\n\n## Message to Send\n\n{reply_text}\n\n---\n\n## Original Message Context\n**Received:** {date}\n**Matched Keywords:** {keywords}\n**Content:** {original message preview}\n\n---\n\n## To Approve\nMove this file to /Approved folder.\n\n## To Reject\nMove this file to /Rejected folder or delete.\n\n---\n*Awaiting human approval before sending*\n```\n\n## Invoice Approval Format\n\nFor invoice generation requests:\n\n```markdown\n---\ntype: invoice\naction: generate_invoice\nclient: {client_name}\nsource_file: WHATSAPP_{timestamp}.md\npriority: high\ncreated: {iso_timestamp}\nstatus: awaiting_approval\n---\n\n# Invoice Request: {client_name}\n\n**Client:** {client_name}\n**Service/Period:** {description}\n**Amount:** ${amount}\n\n## Invoice Details\n\n**To:** {client_name}\n**Email:** {client_email}\n**Amount:** ${amount}\n**Due Date:** {date}\n**Bank Details:** {from Company_Handbook.md}\n\n## Description\n{service description}\n\n---\n\n## Original WhatsApp Request\n**Received:** {date}\n**Content:** {original message}\n\n---\n\n## To Approve\nMove this file to /Approved folder to generate and send invoice.\n\n## To Reject\nMove this file to /Rejected folder.\n\n---\n*Awaiting human approval before generating invoice*\n```\n\n## Intent Detection Guide\n\nSee `references/intents.md` for detailed intent classification patterns:\n1. Invoice Request (high priority, always approve)\n2. Payment Confirmation/Query (high priority, always approve)\n3. Urgent Query/Problem (high priority)\n4. Pricing Query (medium priority)\n5. Service Inquiry (medium priority)\n6. Appointment/Scheduling (medium priority)\n7. General/Informational (low priority)\n\n## Action Templates\n\nSee `references/action-templates.md` for complete plan templates:\n- Reply Plan Template\n- Invoice Generation Plan Template\n- Urgent Escalation Template\n- Payment/Financial Escalation Template\n- Pricing Query Plan Template\n- General Query Plan Template\n\n## Example Scenarios\n\n**Scenario 1: Invoice request**\n```\nInput: WHATSAPP_20260305_120000.md\nContent: \"Hi, can you send me the invoice for this month?\"\nMatched Keywords: \"invoice\"\nPriority: high\nAction: Create invoice generation plan\nOutput: PLAN_WHATSAPP_20260305_120000_invoice.md in /Plans/\nRoute: INVOICE_{client}_{timestamp}.md to /Pending_Approval/\n```\n\n**Scenario 2: Urgent problem**\n```\nInput: WHATSAPP_20260305_140000.md\nContent: \"Urgent! The website is down, clients can''t access it\"\nMatched Keywords: \"urgent\"\nPriority: high\nAction: Draft urgent response plan\nOutput: PLAN_WHATSAPP_20260305_140000_urgent.md in /Plans/\nRoute: WHATSAPP_REPLY_{timestamp}.md to /Pending_Approval/\n```\n\n**Scenario 3: Pricing inquiry**\n```\nInput: WHATSAPP_20260305_160000.md\nContent: \"How much do you charge for web design?\"\nMatched Keywords: \"how much\", \"charge\"\nPriority: medium\nAction: Draft pricing response using /Vault/Accounting/Rates.md\nOutput: PLAN_WHATSAPP_20260305_160000_pricing.md in /Plans/\nRoute: WHATSAPP_REPLY_{timestamp}.md to /Pending_Approval/\n```\n\n**Scenario 4: Payment confirmation**\n```\nInput: WHATSAPP_20260305_180000.md\nContent: \"I just transferred the payment, transaction ID: 12345\"\nMatched Keywords: \"payment\", \"transferred\"\nPriority: high\nAction: Escalate to human for verification (NEVER auto-confirm)\nOutput: PLAN_WHATSAPP_20260305_180000_payment.md in /Plans/\nRoute: Copy WHATSAPP_*.md to /Pending_Approval/ immediately\n```\n\n**Scenario 5: Thank you message**\n```\nInput: WHATSAPP_20260305_200000.md\nContent: \"Thanks for the quick response!\"\nMatched Keywords: \"thanks\"\nPriority: low\nAction: Archive (no response needed)\nOutput: Move WHATSAPP_*.md to /Done/, log action\n```\n\n## Logging Format\n\nEvery WhatsApp action must be logged to `/Vault/Logs/YYYY-MM-DD.json`:\n\n**Triage log:**\n```json\n{\n  \"timestamp\": \"2026-03-05T14:30:00Z\",\n  \"action_type\": \"whatsapp_triage\",\n  \"source_file\": \"WHATSAPP_20260305_143000.md\",\n  \"intent\": \"invoice_request\",\n  \"priority\": \"high\",\n  \"action_taken\": \"created_invoice_plan\",\n  \"plan_file\": \"PLAN_WHATSAPP_20260305_143000_invoice.md\",\n  \"routed_to_approval\": true\n}\n```\n\n**Reply draft log:**\n```json\n{\n  \"timestamp\": \"2026-03-05T14:30:00Z\",\n  \"action_type\": \"whatsapp_draft_created\",\n  \"source_file\": \"WHATSAPP_20260305_143000.md\",\n  \"recipient\": \"Client Name\",\n  \"intent\": \"urgent_query\",\n  \"priority\": \"high\",\n  \"approval_file\": \"WHATSAPP_REPLY_20260305_143000.md\"\n}\n```\n\n**Archive log:**\n```json\n{\n  \"timestamp\": \"2026-03-05T14:30:00Z\",\n  \"action_type\": \"whatsapp_archived\",\n  \"source_file\": \"WHATSAPP_20260305_143000.md\",\n  \"intent\": \"general\",\n  \"priority\": \"low\",\n  \"reason\": \"no_response_needed\"\n}\n```\n\n## Completion Signal\n\nAlways end with: `<promise>TASK_COMPLETE</promise>`"},"lastSynced":"2026-03-07T13:06:18.735Z","agentAnalysis":{"suitability":{"en":"Ideal for Task Management Agents requiring automated workflow triage and CEO briefing capabilities via WhatsApp.","zh":"适用于需要自动化工作流_triage_和通过WhatsApp进行CEO简报的任务管理代理。","ja":"Task Managementエージェントが自動化されたワークフローのトリアージとWhatsApp経由でのCEOブリーフィング機能を必要とする場合に最適です。","ko":"작업 관리 에이전트가 자동화된 워크플로우 트리징 및 WhatsApp를 통한 CEO 브리핑 기능을 필요로 할 때 적합합니다.","es":"Ideal para Agentes de Gestión de Tareas que requieren una triage de flujo de trabajo automatizada y capacidades de informe al CEO a través de WhatsApp.","fr":"Idéal pour les agents de gestion de tâches nécessitant une triage de workflow automatisée et des capacités de briefing du PDG via WhatsApp.","de":"Ideal für Task-Management-Agents, die eine automatisierte Workflow-Triage und CEO-Briefing-Funktionen über WhatsApp erfordern.","pt":"Ideal para Agentes de Gerenciamento de Tarefas que requerem triagem de fluxo de trabalho automatizada e capacidades de briefing do CEO via WhatsApp.","ru":"Идеально подходит для агентов управления задачами, требующих автоматизированной сортировки рабочих процессов и возможностей брифинга CEO через WhatsApp.","ar":"مثالي لعميل إدارة المهام الذي يتطلب فرز تلقائي لتدفق العمل وقدرات إحاطة الرئيس التنفيذي عبر WhatsApp."},"recommendation":{"en":"Empowers agents to detect intent, assign priority, and create action plans from WhatsApp messages stored in `.md` files, routing outgoing actions to `/Pending_Approval/` for human-in-the-loop approval, utilizing file monitoring and intent classification patterns from `references/intents.md`.","zh":"能够使代理检测意图、分配优先级并从存储在`.md`文件中的WhatsApp消息创建操作计划，将外发操作路由到`/Pending_Approval/`以进行人工审批，利用`references/intents.md`中的文件监控和意图分类模式。","ja":"エージェントが意図を検出して優先順位を割り当て、`.md`ファイルに保存されたWhatsAppメッセージからアクションプランを作成し、送信アクションを`/Pending_Approval/`にルーティングしてヒューマン・イン・ザ・ループの承認を得ることができ、`references/intents.md`からのファイル監視と意図分类パターンを利用します。","ko":"에이전트가 의도를 감지하고 우선 순위를 할당하여 `.md` 파일에 저장된 WhatsApp 메시지에서 작업 계획을 생성하고, `/Pending_Approval/`로 ausgehende 동작을 라우팅하여 인간의 루프에서 승인을 받을 수 있으며, `references/intents.md`의 파일 모니터링 및 의도 분류 패턴을 사용합니다.","es":"Permite a los agentes detectar la intención, asignar prioridad y crear planes de acción a partir de mensajes de WhatsApp almacenados en archivos `.md`, enrutando acciones salientes a `/Pending_Approval/` para la aprobación humana en el bucle, utilizando patrones de monitoreo de archivos y clasificación de intenciones de `references/intents.md`.","fr":"Autorise les agents à détecter l''intention, assigner une priorité et créer des plans d''action à partir de messages WhatsApp stockés dans des fichiers `.md`, acheminant les actions sortantes vers `/Pending_Approval/` pour l''approbation humaine dans la boucle, en utilisant des modèles de surveillance de fichiers et de classification d''intention de `references/intents.md`.","de":"Ermächtigt Agents, Absicht zu erkennen, Priorität zuzuweisen und Aktionspläne aus WhatsApp-Nachrichten in `.md`-Dateien zu erstellen, ausgehende Aktionen an `/Pending_Approval/` für die menschliche Freigabe im Loop weiterzuleiten, unter Verwendung von Datei-Überwachungsmustern und Intention-Klassifizierungsmustern aus `references/intents.md`.","pt":"Habilita os agentes a detectar intenção, atribuir prioridade e criar planos de ação a partir de mensagens do WhatsApp armazenadas em arquivos `.md`, encaminhando ações de saída para `/Pending_Approval/` para aprovação humana no loop, utilizando padrões de monitoramento de arquivos e classificação de intenções de `references/intents.md`.","ru":"Наделяет агентов возможностью обнаруживать намерения, присваивать приоритет и создавать планы действий из сообщений WhatsApp, хранящихся в файлах `.md`, направляя исходящие действия в `/Pending_Approval/` для одобрения человека в цикле, используя шаблоны мониторинга файлов и классификации намерений из `references/intents.md`.","ar":"يتمكّن الوكلاء من الكشف عن النية وتعيين الأهمية وإنشاء خطط عمل من رسائل WhatsApp المخزنة في ملفات `.md` ، وتصريف الإجراءات الصادرة إلى `/Pending_Approval/` للموافقة البشرية في الحلقة ، باستخدام أنماط مراقبة الملفات وتصنيف النية من `references/intents.md`."},"useCases":{"en":["Automating workflow triage for CEOs","Generating weekly briefings from WhatsApp messages","Routing urgent actions to pending approval folders"],"zh":["自动化CEO的工作流_triage_","从WhatsApp消息生成每周简报","将紧急操作路由到待审批文件夹"],"ja":["CEOのワークフローのトリアージを自動化する","WhatsAppメッセージから毎週のブリーフィングを生成する","緊急なアクションを保留中の承認フォルダにルーティングする"],"ko":["CEO의 워크플로우 트리징을 자동화하는 것","WhatsApp 메시지에서 매주 브리핑을 생성하는 것","긴급한 동작을 승인 대기 폴더로 라우팅하는 것"],"es":["Automatización de la triage de flujo de trabajo para CEOs","Generación de informes semanales a partir de mensajes de WhatsApp","Enrutamiento de acciones urgentes a carpetas de aprobación pendiente"],"fr":["Automatisation de la triage de workflow pour les PDG","Génération de briefings hebdomadaires à partir de messages WhatsApp","Acheminement d''actions urgentes vers des dossiers d''approbation en attente"],"de":["Automatisierung der Workflow-Triage für CEOs","Erstellung von wöchentlichen Berichten aus WhatsApp-Nachrichten","Weiterleitung dringender Aktionen an Ordner für die ausstehende Genehmigung"],"pt":["Automatizar a triagem de fluxo de trabalho para CEOs","Gerar briefings semanais a partir de mensagens do WhatsApp","Encaminhar ações urgentes para pastas de aprovação pendente"],"ru":["Автоматизировать сортировку рабочих процессов для CEO","Генерировать еженедельные брифинги из сообщений WhatsApp","Направлять срочные действия в папки одобрения"],"ar":["الاستفادة من تلقائي لفرز تدفق العمل للمديرين التنفيذيين","توليد إحاطات أسبوعية من رسائل WhatsApp","توجيه الإجراءات العاجلة إلى مجلدات الموافقة المعلقة"]},"limitations":{"en":["Requires file system access to `/Needs_Action/` and `/Pending_Approval/` directories","All WhatsApp sends require human-in-the-loop approval","Limited to processing `.md` files"],"zh":["需要对 `/Needs_Action/` 和 `/Pending_Approval/` 目录的文件系统访问","所有WhatsApp发送都需要人工审批","仅限处理 `.md` 文件"],"ja":["`/Needs_Action/`および`/Pending_Approval/`ディレクトリへのファイルシステムアクセスが必要","WhatsAppの送信にはすべてヒューマン・イン・ザ・ループの承認が必要","`.md`ファイルのみを処理可能"],"ko":["`/Needs_Action/` 및 `/Pending_Approval/` 디렉토리에 대한 파일 시스템 액세스가 필요","WhatsApp의 모든 전송은 인간의 루프에서 승인이 필요",".md 파일만 처리 가능"],"es":["Requiere acceso al sistema de archivos a los directorios `/Needs_Action/` y `/Pending_Approval/`","Todos los envíos de WhatsApp requieren una aprobación humana en el bucle","Limitado al procesamiento de archivos `.md`"],"fr":["Nécessite un accès au système de fichiers aux répertoires `/Needs_Action/` et `/Pending_Approval/`","Tous les envois de WhatsApp nécessitent une approbation humaine dans la boucle","Limité au traitement de fichiers `.md`"],"de":["Benötigt Zugriff auf das Dateisystem zu den Verzeichnissen `/Needs_Action/` und `/Pending_Approval/`","Alle WhatsApp-Sendungen erfordern eine menschliche Freigabe im Loop","Begrenzt auf die Verarbeitung von `.md`-Dateien"],"pt":["Requer acesso ao sistema de arquivos para os diretórios `/Needs_Action/` e `/Pending_Approval/`","Todos os envios do WhatsApp requerem aprovação humana no loop","Limitado ao processamento de arquivos `.md`"],"ru":["Требует доступа к файловой системе для директорий `/Needs_Action/` и `/Pending_Approval/`","Все отправки WhatsApp требуют одобрения человека в цикле","Ограничен обработкой файлов `.md`"],"ar":["يتطلب الوصول إلى نظام الملفات للمجلدات `/Needs_Action/` و `/Pending_Approval/`","تتطلب جميع عمليات إرسال WhatsApp الموافقة البشرية في الحلقة","محدود بمعالجة ملفات `.md`"]},"version":4},"contentHash":"4fdfe9257c3352cbcdaf06def4bc1a70afb1ecf2ec6ee69bfa608b03ec5f872e","qualityScore":42}');
