INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bretstarr2024/The-Long-Walk/end-session', 'end-session', 'bretstarr2024', 'The-Long-Walk', 'community', 'end-session bretstarr2024 The-Long-Walk community The end-session skill is a write-heavy and procedural tool for Survival simulation game based on Stephen King''s The Long Walk, utilizing Vite, TypeScript, and GPT-5.2 agents. It benefits developers working on similar projects. 结束会话是一种基于Vite和TypeScript的The Long Walk生存模拟，用于canonicalize状态和更新MEMORY.md セッション終了は、ViteとTypeScriptを使用したThe Long Walkサバイバルシミュレーションで、canonicalize状態とMEMORY.mdを更新するために使用されます 세션 종료는 Vite와 TypeScript를 사용한 The Long Walk 생존 시뮬레이션에서 canonicalize 상태와 MEMORY.md를 업데이트하는 데 사용됩니다 End-session es una habilidad de agente de IA que utiliza Vite y TypeScript para una simulación de supervivencia basada en The Long Walk. Reconcilia el estado de la sesión en artefactos duraderos. End-session est une compétence d''agent d''IA qui utilise Vite et TypeScript pour une simulation de survie basée sur The Long Walk. Elle réconcilie l''état de la session en artefacts durables. End-session ist eine Fähigkeit des KI-Agents, die Vite und TypeScript für ein Überlebenssimulations-Spiel basierend auf The Long Walk verwendet. Sie versöhnt den Sitzungsstatus in dauerhaften Artefakten. O end-session é uma simulação de sobrevivência baseada em The Long Walk, construída com Vite, TypeScript e GPT-5.2 agents. End-session - симуляция выживания на основе The Long Walk, построенная с Vite, TypeScript и ИИ Агентами GPT-5.2. end-session هو محاكاة البقاء المبنية على The Long Walk، مبنية مع Vite و TypeScript ووكلاء GPT-5.2 how to use end-session end-session setup guide what is end-session end-session alternative end-session vs other simulation tools end-session install GPT-5.2 agents in simulation Vite development for Survival games TypeScript in AI agent development 结束会话 The Long Walk生存模拟 Vite TypeScript GPT-5.2代理 canonicalize状态 MEMORY.md更新 AIエージェント 写入密集的技能 程序化的技能 Utilizes Vite for development Leverages TypeScript for robust coding Employs GPT-5.2 agents for advanced simulation Reconciles state into durable artifacts Updates MEMORY.md for knowledge retention Executes procedural steps for a seamless experience end-session is a technical skill for closing working sessions on The Long Walk, involving state reconciliation and MEMORY.md updates.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mwathiben/hush-private-bookmarks/solana-security', 'community', 'mwathiben', 'hush-private-bookmarks', 'mwathiben/hush-private-bookmarks', 'solana-security', 0, 0, 42, '2026-03-05T16:54:55Z', '2026-03-07T04:04:17.051Z', '75d5381b6075a5f5020b75a9c62b3f1ade01946c7e6153871c6f3d4862e1ea78', '{"id":"mwathiben/hush-private-bookmarks/solana-security","name":"solana-security","description":{"en":"Solana-security is a systematic security review framework for Solana programs, supporting both Anchor and native Rust implementations, benefiting developers and auditors.","zh":"Solana 安全审计系统是一种系统的安全审计框架，支持 Anchor 和 Native Rust 实现。它提供了一个 5 步的审计流程，确保 Solana 程序的安全性","ja":"Solana セキュリティー監査システムは、アンカーとネイティブ Rust の実装をサポートする体系的なセキュリティ監査フレームワークです。5 段階の監査プロセスを提供し、Solana プログラムのセキュリティを確保します","ko":"Solana 보안 감사 시스템은 앵커와 네이티브 러스트 구현을 지원하는 체계적인 보안 감사 프레임워크입니다. 5 단계의 감사 프로세스를 제공하여 솔라나 프로그램의 보안을 보장합니다","es":"El sistema de auditoría de seguridad de Solana es un marco de revisión sistemática para programas Solana, compatible con Anchor y Rust nativo","fr":"Le système d''audit de sécurité Solana est un cadre de revue systématique pour les programmes Solana, compatible avec Anchor et Rust natif","de":"Das Solana-Sicherheitsaudit-System ist ein systematisches Überprüfungsraster für Solana-Programme, kompatibel mit Anchor und nativem Rust","pt":"O Solana Security é um sistema de auditoria de segurança para programas Solana, que suporta tanto Anchor quanto Rust nativo. Fornece um quadro de revisão sistemática para auditorias de segurança abrangentes.","ru":"Solana Security - это система безопасности для программ Solana, поддерживающая как Anchor, так и Native Rust. Предоставляет систематический каркас для комплексных проверок безопасности.","ar":"Solana Security هو نظام مراجعة أمنية للبرامج Solana، يدعم كل من Anchor و Rust الأصلي. يوفر إطارًا منهجيًا لمراجعات أمنية شاملة"},"seo":{"title":{"en":"Solana-Security: Comprehensive Auditing Setup Guide | AI ...","zh":"Solana 安全审计系统设置指南","ja":"Solana セキュリティー監査システムのベストプラクティス","ko":"Solana 보안 감사 시스템 구축 가이드","es":"Guía de seguridad de Solana: Implementación de AES-256-GCM","fr":"Guide de sécurité Solana: Mise en œuvre de l''encryption A...","de":"Solana-Sicherheitsleitfaden: Implementierung von AES-256-...","pt":"Guia de Configuração do Solana Security: Auditoria de Seg...","ru":"ИИ Агенты: Настройка Solana Security для Защиты Программ","ar":"دليل إعداد Solana Security: مراجعة أمنية شاملة للبرامج So..."},"description":{"en":"Unlock robust security audits for Solana programs with our systematic 5-step review process - get started now and ensure your Anchor and Rust implementations...","zh":"使用 Solana 安全审计系统进行全面安全审计，支持 Anchor 和 Native Rust 实现","ja":"Solana セキュリティー監査システムを使用して、アンカーとネイティブ Rust の実装をサポートした徹底的なセキュリティ監査を実行","ko":"Solana 보안 감사 시스템을 사용하여 앵커와 네이티브 러스트 구현을 지원하는 철저한 보안 감사 수행","es":"Aprende a proteger tus programas Solana con nuestro sistema de auditoría de seguridad y sigue los 5 pasos para una revisión exhaustiva","fr":"Découvrez comment protéger vos programmes Solana avec notre système d''audit de sécurité et suivez les 5 étapes pour une revue exhaustive","de":"Erfahren Sie, wie Sie Ihre Solana-Programme mit unserem Sicherheitsaudit-System schützen und folgen Sie den 5 Schritten für eine umfassende Überprüfung","pt":"Aprenda a configurar o Solana Security para auditorias de segurança em programas Solana, incluindo suporte a Anchor e Rust nativo","ru":"Узнайте, как настроить Solana Security для защиты программ Solana, поддерживающий Anchor и Native Rust","ar":"تعلم كيفية إعداد Solana Security لمراجعة أمنية شاملة للبرامج Solana، بما في ذلك دعم Anchor و Rust الأصلي"},"definition":{"en":"Solana-security is a private bookmark manager with AES-256-GCM encryption and a systematic security review framework for Solana programs.","zh":"Solana 安全审计系统是一种用于审计 Solana 程序安全性的框架","ja":"Solana セキュリティー監査システムは、Solana プログラムのセキュリティを監査するためのフレームワークです","ko":"Solana 보안 감사 시스템은 솔라나 프로그램의 보안을 감사하는 프레임워크입니다","es":"Solana Security es un sistema de auditoría de seguridad para programas Solana que utiliza un marco de revisión sistemática","fr":"La sécurité Solana est un système d''audit de sécurité pour les programmes Solana qui utilise un cadre de revue systématique","de":"Solana-Sicherheit ist ein Sicherheitsaudit-System für Solana-Programme, das ein systematisches Überprüfungsraster verwendet","pt":"O que é Solana Security? É um sistema de auditoria de segurança para programas Solana que visa garantir a segurança dos programas.","ru":"Что такое Solana Security? Это система безопасности для программ Solana, предназначенная для обеспечения безопасности программ.","ar":"ما هو Solana Security؟ نظام مراجعة أمنية للبرامج Solana يهدف إلى ضمان أمن البرامج"},"features":{"en":["Supports systematic 5-step security audits for Solana programs","Compatible with Anchor and native Rust implementations","Checks for Anchor version compatibility and known issues in Cargo.toml","Analyzes dependencies, including Oracle, for security vulnerabilities","Utilizes AES-256-GCM encryption for secure bookmark management"],"zh":["支持 Anchor 和 Native Rust 实现","5 步的审计流程","检查 Anchor 版本和兼容性","检查依赖项和 Oracle","使用 AES-256-GCM 加密"],"ja":["アンカーとネイティブ Rust の実装をサポート","5 段階の監査プロセス","アンカーのバージョンと互換性を確認","依存関係と Oracle を確認","AES-256-GCM 暗号化を使用"],"ko":["앵커와 네이티브 러스트 구현을 지원","5 단계의 감사 프로세스","앵커 버전과 호환성을 확인","의존성과 오라클을 확인","AES-256-GCM 암호화를 사용"],"es":["Compatibilidad con Anchor y Rust nativo","Sistema de revisión sistemática de 5 pasos","Cifrado AES-256-GCM para proteger programas","Análisis de dependencias y oráculos","Compatibilidad con versiones de Anchor"],"fr":["Compatibilité avec Anchor et Rust natif","Système de revue systématique en 5 étapes","Chiffrement AES-256-GCM pour protéger les programmes","Analyse des dépendances et des oracles","Compatibilité avec les versions d''Anchor"],"de":["Kompatibilität mit Anchor und nativem Rust","Systematisches Überprüfungsraster in 5 Schritten","AES-256-GCM-Verschlüsselung zum Schutz von Programmen","Analyse von Abhängigkeiten und Orakeln","Kompatibilität mit Anchor-Versionen"],"pt":["Suporte a Anchor e Rust nativo","Quadro de revisão sistemática para auditorias de segurança","Análise de dependências e compatibilidade com Oracle","Verificação de versão do Anchor e detecção de problemas conhecidos","Criptografia AES-256-GCM para gerenciamento de bookmarks privados"],"ru":["Поддержка Anchor и Native Rust","Систематический каркас для комплексных проверок безопасности","Анализ зависимостей и совместимость с Oracle","Проверка версии Anchor и обнаружение известных проблем","Шифрование AES-256-GCM для управления приватными закладками"],"ar":["دعم Anchor و Rust الأصلي","إطار منهجي لمراجعات أمنية شاملة","تحليل الإعتماديات ومتوافق مع Oracle","فحص إصدار Anchor واكتشاف المشاكل المعروفة","تشفير AES-256-GCM لإدارة الإشارات المرجعية الخاصة"]},"keywords":{"en":["how to use solana-security","solana-security setup guide","solana-security vs anchor","solana-security alternative","solana-security install","what is solana-security","solana-security auditing process","solana-security for rust developers"],"zh":["Solana 安全审计","Solana 安全","Anchor 安全","Native Rust 安全","Solana 程序安全","AES-256-GCM 加密","Solana 开发","Solana 安全最佳实践"],"ja":["Solana セキュリティー監査","Solana セキュリティー","アンカー セキュリティー","ネイティブ Rust セキュリティー","Solana プログラム セキュリティー","AES-256-GCM 暗号化","Solana 開発","Solana セキュリティー ベストプラクティス"],"ko":["Solana 보안 감사","Solana 보안","앵커 보안","네이티브 러스트 보안","솔라나 프로그램 보안","AES-256-GCM 암호화","Solana 개발","Solana 보안 베스트 프랙티스"],"es":["seguridad Solana","auditoría de seguridad","programas Solana","Anchor","Rust nativo","cifrado AES-256-GCM","desarrollo de blockchain","seguridad de blockchain"],"fr":["sécurité Solana","audit de sécurité","programmes Solana","Anchor","Rust natif","chiffrement AES-256-GCM","développement de blockchain","sécurité de blockchain"],"de":["Solana-Sicherheit","Sicherheitsaudit","Solana-Programme","Anchor","natives Rust","AES-256-GCM-Verschlüsselung","Blockchain-Entwicklung","Blockchain-Sicherheit"],"pt":["Solana Security","Auditoria de segurança Solana","Programas Solana","Anchor Solana","Rust Solana","Criptografia AES-256-GCM","Gerenciamento de bookmarks privados","Desenvolvimento de programas Solana"],"ru":["Solana Security","Проверка безопасности Solana","Программы Solana","Anchor Solana","Native Rust Solana","Шифрование AES-256-GCM","Управление приватными закладками","Разработка программ Solana"],"ar":["Solana Security","مراجعة أمنية Solana","برامج Solana","Anchor Solana","Rust الأصلي Solana","تشفير AES-256-GCM","إدارة الإشارات المرجعية الخاصة","تطوير برامج Solana"]}},"owner":"mwathiben","repo":"hush-private-bookmarks","repoPath":"mwathiben/hush-private-bookmarks","stars":0,"forks":0,"updatedAt":"2026-03-05T16:54:55Z","topics":[],"category":"community","skillMd":{"name":"solana-security","description":"Audit Solana programs (Anchor or native Rust) for security vulnerabilities. Use when reviewing smart contract security, finding exploits, analyzing attack vectors, performing security assessments, or when explicitly asked to audit, review security, check for bugs, or find vulnerabilities in Solana programs.","bodyPreview":"# Solana Security Auditing\n\nSystematic security review framework for Solana programs, supporting both Anchor and native Rust implementations.\n\n## Review Process\n\nFollow this systematic 5-step process for comprehensive security audits:\n\n### Step 1: Initial Assessment\n\nUnderstand the program''s context and structure:\n\n- **Framework**: Anchor vs Native Rust (check for `use anchor_lang::prelude::*`)\n- **Anchor version**: Check `Cargo.toml` for compatibility and known issues\n- **Dependencies**: Oracle","body":"# Solana Security Auditing\n\nSystematic security review framework for Solana programs, supporting both Anchor and native Rust implementations.\n\n## Review Process\n\nFollow this systematic 5-step process for comprehensive security audits:\n\n### Step 1: Initial Assessment\n\nUnderstand the program''s context and structure:\n\n- **Framework**: Anchor vs Native Rust (check for `use anchor_lang::prelude::*`)\n- **Anchor version**: Check `Cargo.toml` for compatibility and known issues\n- **Dependencies**: Oracles (Pyth, Switchboard), external programs, token programs\n- **Program structure**: Count instructions, identify account types, analyze state management\n- **Complexity**: Lines of code, instruction count, PDA patterns\n- **Purpose**: DeFi, NFT, governance, gaming, etc.\n\n### Step 2: Systematic Security Review\n\nFor each instruction, perform security checks in this order:\n\n1. **Account Validation** - Verify signer, owner, writable, and initialization checks\n2. **Arithmetic Safety** - Check all math operations use `checked_*` methods\n3. **PDA Security** - Validate canonical bumps and seed uniqueness\n4. **CPI Security** - Ensure cross-program invocations validate target programs\n5. **Oracle/External Data** - Verify price staleness and oracle status checks\n\n**→ See [references/security-checklists.md](references/security-checklists.md) for detailed checklists**\n\n### Step 3: Vulnerability Pattern Detection\n\nScan for common vulnerability patterns:\n\n- Type cosplay attacks\n- Account reloading issues\n- Improper account closing\n- Missing lamports checks\n- PDA substitution attacks\n- Arbitrary CPI vulnerabilities\n- Missing ownership validation\n- Integer overflow/underflow\n\n**→ See [references/vulnerability-patterns.md](references/vulnerability-patterns.md) for code examples and exploit scenarios**\n\n### Step 4: Architecture and Testing Review\n\nEvaluate overall design quality:\n\n- PDA design patterns and collision prevention\n- Account space allocation and rent exemption\n- Error handling approach and coverage\n- Event emission for critical state changes\n- Compute budget optimization\n- Test coverage (unit, integration, fuzz)\n- Upgrade strategy and authority management\n\n### Step 5: Generate Security Report\n\nProvide findings using this structure:\n\n**Severity Levels:**\n- 🔴 **Critical**: Funds can be stolen/lost, protocol completely broken\n- 🟠 **High**: Protocol can be disrupted, partial fund loss possible\n- 🟡 **Medium**: Suboptimal behavior, edge cases, griefing attacks\n- 🔵 **Low**: Code quality, gas optimization, best practices\n- 💡 **Informational**: Recommendations, improvements, documentation\n\n**Finding Format:**\n```markdown\n## 🔴 [CRITICAL] Title\n\n**Location:** `programs/vault/src/lib.rs:45-52`\n\n**Issue:**\nBrief description of the vulnerability\n\n**Vulnerable Code:**\n```rust\n// Show the problematic code\n```\n\n**Exploit Scenario:**\nStep-by-step explanation of how this can be exploited\n\n**Recommendation:**\n```rust\n// Show the secure alternative\n```\n\n**References:**\n- [Link to relevant documentation or similar exploits]\n```\n\n**Report Summary:**\n- Total findings by severity\n- Critical issues first (prioritize by risk)\n- Quick wins (easy fixes with high impact)\n- Recommendations for testing improvements\n\n## Quick Reference\n\n### Essential Checks (Every Instruction)\n\n**Anchor:**\n```rust\n// ✅ Account validation with constraints\n#[derive(Accounts)]\npub struct SecureInstruction<''info> {\n    #[account(\n        mut,\n        has_one = authority,  // Relationship check\n        seeds = [b\"vault\", user.key().as_ref()],\n        bump,  // Canonical bump\n    )]\n    pub vault: Account<''info, Vault>,\n\n    pub authority: Signer<''info>,  // Signer required\n\n    pub token_program: Program<''info, Token>,  // Program validation\n}\n\n// ✅ Checked arithmetic\nlet total = balance.checked_add(amount)\n    .ok_or(ErrorCode::Overflow)?;\n```\n\n**Native Rust:**\n```rust\n// ✅ Manual account validation\nif !authority.is_signer {\n    return Err(ProgramError::MissingRequiredSignature);\n}\n\nif vault.owner != program_id {\n    return Err(ProgramError::IllegalOwner);\n}\n\n// ✅ Checked arithmetic\nlet total = balance.checked_add(amount)\n    .ok_or(ProgramError::ArithmeticOverflow)?;\n```\n\n### Critical Anti-Patterns\n\n❌ **Never Do:**\n- Use `saturating_*` arithmetic methods (hide errors)\n- Use `unwrap()` or `expect()` in production code\n- Use `init_if_needed` without additional checks\n- Skip signer validation (\"they wouldn''t call this...\")\n- Use unchecked arithmetic operations\n- Allow arbitrary CPI targets\n- Forget to reload accounts after mutations\n\n✅ **Always Do:**\n- Use `checked_*` arithmetic (`checked_add`, `checked_sub`, etc.)\n- Use `ok_or(error)?` for Option unwrapping\n- Use explicit `init` with proper validation\n- Require `Signer<''info>` or `is_signer` checks\n- Use `Program<''info, T>` for CPI program validation\n- Reload accounts after external calls that mutate state\n- Validate account ownership, discriminators, and relationships\n\n## Framework-Specific Patterns\n\n### Anchor Security Patterns\n\n**→ See [references/anchor-security.md](references/anchor-security.md) for:**\n- Account constraint best practices\n- Common Anchor-specific vulnerabilities\n- Secure CPI patterns with `CpiContext`\n- Event emission and monitoring\n- Custom error handling\n\n### Native Rust Security Patterns\n\n**→ See [references/native-security.md](references/native-security.md) for:**\n- Manual account validation patterns\n- Secure PDA derivation and signing\n- Low-level CPI security\n- Account discriminator patterns\n- Rent exemption validation\n\n## Modern Practices (2025)\n\n- **Use Anchor 0.30+** for latest security features\n- **Implement Token-2022** with proper extension handling\n- **Use `InitSpace` derive** for automatic space calculation\n- **Emit events** for all critical state changes\n- **Write fuzz tests** with Trident framework\n- **Document invariants** in code comments\n- **Follow progressive roadmap**: Dev → Audit → Testnet → Audit → Mainnet\n\n## Security Fundamentals\n\n**→ See [references/security-fundamentals.md](references/security-fundamentals.md) for:**\n- Security mindset and threat modeling\n- Core validation patterns (signers, owners, mutability)\n- Input validation best practices\n- State management security\n- Arithmetic safety\n- Re-entrancy considerations\n\n## Common Vulnerabilities\n\n**→ See [references/vulnerability-patterns.md](references/vulnerability-patterns.md) for:**\n- Missing signer validation\n- Integer overflow/underflow\n- PDA substitution attacks\n- Account confusion\n- Arbitrary CPI\n- Type cosplay\n- Improper account closing\n- Precision loss in calculations\n\nEach vulnerability includes:\n- ❌ Vulnerable code example\n- 💥 Exploit scenario\n- ✅ Secure alternative\n- 📚 References\n\n## Security Checklists\n\n**→ See [references/security-checklists.md](references/security-checklists.md) for:**\n- Account validation checklist\n- Arithmetic safety checklist\n- PDA and account security checklist\n- CPI security checklist\n- Oracle and external data checklist\n- Token integration checklist\n\n## Known Issues and Caveats\n\n**→ See [references/caveats.md](references/caveats.md) for:**\n- Solana-specific quirks and gotchas\n- Anchor framework limitations\n- Testing blind spots\n- Common misconceptions\n- Version-specific issues\n\n## Security Resources\n\n**→ See [references/resources.md](references/resources.md) for:**\n- Official security documentation\n- Security courses and tutorials\n- Vulnerability databases\n- Audit report examples\n- Security tools (Trident, fuzzers)\n- Security firms and auditors\n\n## Key Questions for Every Audit\n\nAlways verify these critical security properties:\n\n1. **Can an attacker substitute accounts?**\n   - PDA validation, program ID checks, has_one constraints\n\n2. **Can arithmetic overflow or underflow?**\n   - All math uses checked operations, division by zero protected\n\n3. **Are all accounts properly validated?**\n   - Owner, signer, writable, initialized checks present\n\n4. **Can the program be drained?**\n   - Authorization checks, reentrancy protection, account confusion prevention\n\n5. **What happens in edge cases?**\n   - Zero amounts, max values, closed accounts, expired data\n\n6. **Are external dependencies safe?**\n   - Oracle validation (staleness, status), CPI targets verified, token program checks\n\n## Audit Workflow\n\n### Before Starting\n\n1. Understand the protocol purpose and mechanics\n2. Review documentation and specifications\n3. Set up local development environment\n4. Run existing tests and check coverage\n\n### During Audit\n\n1. Follow the 5-step review process systematically\n2. Document findings with severity and remediation\n3. Create proof-of-concept exploits for critical issues\n4. Test fixes and verify they work\n\n### After Audit\n\n1. Present findings clearly prioritized by severity\n2. Provide actionable remediation steps\n3. Re-audit after fixes are implemented\n4. Document lessons learned for the protocol\n\n## Testing for Security\n\nBeyond code review, validate security through testing:\n\n- **Unit tests**: Test each instruction''s edge cases\n- **Integration tests**: Test cross-instruction interactions\n- **Fuzz testing**: Use Trident to discover unexpected behaviors\n- **Exploit scenarios**: Write POCs for found vulnerabilities\n- **Upgrade testing**: Verify migration paths are secure\n\n## Core Principle\n\n**In Solana''s account model, attackers can pass arbitrary accounts to any instruction.**\n\nSecurity requires explicitly validating:\n- ✅ Every account''s ownership\n- ✅ Every account''s type (discriminator)\n- ✅ Every account''s relationships\n- ✅ Every account''s state\n- ✅ Every signer requirement\n- ✅ Every arithmetic operation\n- ✅ Every external call\n\nThere are no implicit guarantees. **Validate everything, trust nothing.**\n"},"lastSynced":"2026-03-07T04:04:17.051Z","agentAnalysis":{"suitability":{"en":"Perfect for Blockchain Agents focused on Solana ecosystem security, needing systematic review frameworks for Anchor and native Rust implementations.","zh":"非常适合专注于Solana生态系统安全的Blockchain Agents，需要系统化的审查框架用于Anchor和原生Rust实现。","ja":"Solanaエコシステムのセキュリティに焦点を当てたBlockchainエージェントに最適で、AnchorおよびネイティブRustの実装に対する体系的なレビュー・フレームワークが必要です。","ko":"Solana 생태계 보안에 중점을 둔 Blockchain 에이전트에게 적합하며, 앵커 및 네이티브 러스트 구현을 위한 체계적인 검토 프레임워크가 필요합니다.","es":"Perfecto para Agentes de Blockchain centrados en la seguridad del ecosistema Solana, que necesitan marcos de revisión sistemáticos para Anchor y implementaciones nativas de Rust.","fr":"Parfait pour les agents de blockchain axés sur la sécurité de l''écosystème Solana, ayant besoin de cadres de révision systématiques pour Anchor et les implémentations natives Rust.","de":"Perfekt für Blockchain-Agents, die auf die Sicherheit des Solana-Ökosystems ausgerichtet sind und systematische Überprüfungsraster für Anchor und native Rust-Implementierungen benötigen.","pt":"Perfeito para Agentes de Blockchain focados na segurança do ecossistema Solana, necessitando de estruturas de revisão sistemática para Anchor e implementações nativas em Rust.","ru":"Идеально подходит для агентов блокчейна, ориентированных на безопасность экосистемы Solana, которым необходимы системные рамки для проверки Anchor и родных реализаций на Rust.","ar":"مثالي لعمليات وكيل البلوكتشين التي تركز على أمن نظام البيئة Solana، وتحتاج إلى إطارات مراجعة منهجية ل.Anchor وتنفيذات Rust الأصلية."},"recommendation":{"en":"Empowers agents to conduct comprehensive security audits of Solana programs, supporting both Anchor and native Rust, with a systematic 5-step review process that checks for framework compatibility, Anchor version, and dependencies like Oracle.","zh":"赋予代理进行Solana程序的全面安全审计的能力，支持Anchor和原生Rust，采用系统化的5步骤审查流程检查框架兼容性、Anchor版本以及Oracle等依赖项。","ja":"エージェントがSolanaプログラムの包括的なセキュリティ監査を実施できるようにし、AnchorおよびネイティブRustをサポートし、フレームワークの互換性、Anchorバージョン、およびOracleなどの依存関係をチェックするための体系的な5ステップのレビュー・プロセスを提供します。","ko":"에이전트가 솔라나 프로그램의 포괄적인 보안 감사를 수행할 수 있도록 하며, 앵커 및 네이티브 러스트를 지원하며, 프레임워크 호환성, 앵커 버전 및 오라클 등의 종속 항목을 확인하는 체계적인 5단계 검토 프로세스를 제공합니다.","es":"Permite a los agentes realizar auditorías de seguridad integrales de los programas Solana, que admiten tanto Anchor como Rust nativo, con un proceso de revisión sistemático de 5 pasos que comprueba la compatibilidad del marco, la versión de Anchor y las dependencias como Oracle.","fr":"Permet aux agents de réaliser des audits de sécurité complets des programmes Solana, prenant en charge à la fois Anchor et Rust natif, avec un processus de révision systématique de 5 étapes qui vérifie la compatibilité du cadre, la version d''Anchor et les dépendances comme Oracle.","de":"Ermöglicht es Agents, umfassende Sicherheitsaudits von Solana-Programmen durchzuführen, die sowohl Anchor als auch native Rust unterstützen, mit einem systematischen 5-Schritt-Überprüfungsprozess, der die Framework-Kompatibilität, die Anchor-Version und Abhängigkeiten wie Oracle überprüft.","pt":"Habilita os agentes a realizar auditorias de segurança abrangentes de programas Solana, suportando tanto Anchor quanto Rust nativo, com um processo de revisão sistemático de 5 etapas que verifica a compatibilidade do framework, a versão do Anchor e dependências como Oracle.","ru":"Наделяет агентов возможностью проводить всесторонние аудиты безопасности программ Solana, поддерживая как Anchor, так и родной Rust, с системным 5-ступенчатым процессом проверки, который проверяет совместимость фреймворка, версию Anchor и зависимости, такие как Oracle.","ar":"يمنح الوكلاء khảية إجراء مراجعات أمنية شاملة لبرامج Solana، داعمة ل cả Anchor و Rust الأصلي، مع عملية مراجعة منهجية بخمس خطوات تحقق من توافق الإطار والنسخة Anchor والاعتماديات مثل Oracle."},"useCases":{"en":["Auditing Solana smart contracts for security vulnerabilities","Analyzing Anchor and native Rust implementations for compatibility issues","Identifying potential security risks in Solana program dependencies"],"zh":["审计Solana智能合约以发现安全漏洞","分析Anchor和原生Rust实现以发现兼容性问题","识别Solana程序依赖项中的潜在安全风险"],"ja":["セキュリティの脆弱性を発見するためにSolanaスマート・コントラクトを監査する","互換性の問題を発見するためにAnchorおよびネイティブRustの実装を分析する","Solanaプログラムの依存関係の中で潜在的なセキュリティリスクを特定する"],"ko":["보안 취약점을 발견하기 위해 솔라나 스마트 계약을 감사합니다","호환성 문제를 발견하기 위해 앵커 및 네이티브 러스트 구현을 분석합니다","솔라나 프로그램 종속 항목에서 잠재적인 보안 위험을 식별합니다"],"es":["Auditoría de contratos inteligentes Solana para vulnerabilidades de seguridad","Análisis de implementaciones de Anchor y Rust nativo para problemas de compatibilidad","Identificación de posibles riesgos de seguridad en las dependencias de los programas Solana"],"fr":["Auditorat des contrats intelligents Solana pour les vulnérabilités de sécurité","Analyse des implémentations d''Anchor et de Rust natif pour les problèmes de compatibilité","Identification des risques de sécurité potentiels dans les dépendances des programmes Solana"],"de":["Auditing von Solana-Smart-Verträgen für Sicherheitsverletzlichkeiten","Analyse von Anchor- und nativer Rust-Implementierungen für Kompatibilitätsprobleme","Identifizierung potenzieller Sicherheitsrisiken in den Abhängigkeiten von Solana-Programmen"],"pt":["Auditoria de contratos inteligentes Solana para vulnerabilidades de segurança","Análise de implementações Anchor e Rust nativo para problemas de compatibilidade","Identificação de riscos de segurança potenciais nas dependências de programas Solana"],"ru":["Аудит смарт-контрактов Solana на предмет уязвимостей безопасности","Анализ реализаций Anchor и родного Rust на предмет проблем совместимости","Определение потенциальных рисков безопасности в зависимостях программ Solana"],"ar":["مراجعة عقود ذكية Solana لأمن الخلل","تحليل تنفيذات Anchor و Rust الأصلية لمشاكل التوافق","تحديد المخاطر الأمنية المحتملة في الاعتماديات لبرامج Solana"]},"limitations":{"en":["Requires knowledge of Solana ecosystem and programming languages like Rust","Limited to Solana programs and does not support other blockchain platforms"],"zh":["需要Solana生态系统和像Rust这样的编程语言的知识","仅限Solana程序，不支持其他区块链平台"],"ja":["SolanaエコシステムおよびRustなどのプログラミング言語の知識が必要","Solanaプログラムのみに限定され、他のブロックチェーン・プラットフォームはサポートされません"],"ko":["솔라나 생태계 및 러스트와 같은 프로그래밍 언어에 대한 지식이 필요합니다","솔라나 프로그램만 해당되며, 다른 블록체인 플랫폼은 지원되지 않습니다"],"es":["Requiere conocimiento del ecosistema Solana y lenguajes de programación como Rust","Limitado a programas Solana y no admite otras plataformas de blockchain"],"fr":["Nécessite une connaissance de l''écosystème Solana et des langages de programmation comme Rust","Limité aux programmes Solana et ne prend pas en charge d''autres plateformes de blockchain"],"de":["Benötigt Kenntnisse des Solana-Ökosystems und Programmiersprachen wie Rust","Begrenzt auf Solana-Programme und unterstützt keine anderen Blockchain-Plattformen"],"pt":["Exige conhecimento do ecossistema Solana e linguagens de programação como Rust","Limitado a programas Solana e não suporta outras plataformas de blockchain"],"ru":["Требует знания экосистемы Solana и языков программирования, таких как Rust","Ограничен программами Solana и не поддерживает другие платформы блокчейна"],"ar":["يتطلب معرفة بنية البيئة Solana ولغات البرمجة مثل Rust","محدود لبرامج Solana ولا يدعم منصات البلوكتشين الأخرى"]},"version":4},"contentHash":"75d5381b6075a5f5020b75a9c62b3f1ade01946c7e6153871c6f3d4862e1ea78","qualityScore":42}');
