INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mwathiben/hush-private-bookmarks/solana-security', 'solana-security', 'mwathiben', 'hush-private-bookmarks', 'community', 'solana-security mwathiben hush-private-bookmarks community Solana-security is a systematic security review framework for Solana programs, supporting both Anchor and native Rust implementations, benefiting developers and auditors. Solana 安全审计系统是一种系统的安全审计框架，支持 Anchor 和 Native Rust 实现。它提供了一个 5 步的审计流程，确保 Solana 程序的安全性 Solana セキュリティー監査システムは、アンカーとネイティブ Rust の実装をサポートする体系的なセキュリティ監査フレームワークです。5 段階の監査プロセスを提供し、Solana プログラムのセキュリティを確保します Solana 보안 감사 시스템은 앵커와 네이티브 러스트 구현을 지원하는 체계적인 보안 감사 프레임워크입니다. 5 단계의 감사 프로세스를 제공하여 솔라나 프로그램의 보안을 보장합니다 El sistema de auditoría de seguridad de Solana es un marco de revisión sistemática para programas Solana, compatible con Anchor y Rust nativo Le système d''audit de sécurité Solana est un cadre de revue systématique pour les programmes Solana, compatible avec Anchor et Rust natif Das Solana-Sicherheitsaudit-System ist ein systematisches Überprüfungsraster für Solana-Programme, kompatibel mit Anchor und nativem Rust O Solana Security é um sistema de auditoria de segurança para programas Solana, que suporta tanto Anchor quanto Rust nativo. Fornece um quadro de revisão sistemática para auditorias de segurança abrangentes. Solana Security - это система безопасности для программ Solana, поддерживающая как Anchor, так и Native Rust. Предоставляет систематический каркас для комплексных проверок безопасности. Solana Security هو نظام مراجعة أمنية للبرامج Solana، يدعم كل من Anchor و Rust الأصلي. يوفر إطارًا منهجيًا لمراجعات أمنية شاملة how to use solana-security solana-security setup guide solana-security vs anchor solana-security alternative solana-security install what is solana-security solana-security auditing process solana-security for rust developers Solana 安全审计 Solana 安全 Anchor 安全 Native Rust 安全 Solana 程序安全 AES-256-GCM 加密 Solana 开发 Solana 安全最佳实践 Supports systematic 5-step security audits for Solana programs Compatible with Anchor and native Rust implementations Checks for Anchor version compatibility and known issues in Cargo.toml Analyzes dependencies, including Oracle, for security vulnerabilities Utilizes AES-256-GCM encryption for secure bookmark management Solana-security is a private bookmark manager with AES-256-GCM encryption and a systematic security review framework for Solana programs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ivanyeors/product-agentic-templates/backend-design', 'community', 'ivanyeors', 'product-agentic-templates', 'ivanyeors/product-agentic-templates', 'backend-design', 0, 0, 42, '2026-03-01T05:04:44Z', '2026-03-07T04:10:25.717Z', 'd811bcd3a12a39e1542f84a383964858863d1fffd416218a5532dda70a14b953', '{"id":"ivanyeors/product-agentic-templates/backend-design","name":"backend-design","description":{"en":"Backend-design skill translates product design artifacts into backend specifications, benefiting backend architects and API designers. It produces API contracts and schema designs for human review.","zh":"后端设计是将发现和产品设计文档转换为可实施的后端规格的过程，包括API合同、架构规范和认证模型的生成","ja":"バックエンド設計は、発見とプロダクト設計文書を実装可能なバックエンド仕様に変換するプロセスであり、APIエージェントを使用してOpenAPIとスキーマ設計を生成する","ko":"백엔드 디자인은 발견과 제품 디자인 문서를 구현 가능한 백엔드 규격으로 변환하는 과정으로, API 계약 및 스키마 설계를 생성하는 것을 포함합니다","es":"El diseño de backend traduce los artefactos de diseño de producto en especificaciones de backend listas para la implementación. Produce contratos de API y diseños de esquema para la revisión humana","fr":"La conception de backend traduit les artefacts de conception de produit en spécifications de backend prêtes à l''implémentation. Produit des contrats d''API et des conceptions de schéma pour la revue humaine","de":"Das Backend-Design übersetzt Produkt-Design-Artefakte in implementierbare Backend-Spezifikationen. Erzeugt API-Verträge und Schema-Designs für die menschliche Überprüfung","pt":"O design de backend traduz artefatos de design de produtos em especificações prontas para implementação, incluindo contratos de API OpenAPI e design de schema","ru":"Проектирование бэкенда переводит артефакты продукта в готовые к реализации спецификации, включая контракты API OpenAPI и схему проектирования","ar":"تصميم الخلفية يترجم مخططات التصميم إلى مواصفات جاهزة للتنفيذ، بما في ذلك عقود واجهة برمجة التطبيقات OpenAPI وتصميم المخطط"},"seo":{"title":{"en":"Backend-Design: API Contract Generation for AI Agents | A...","zh":"后端设计设置指南 - 生成API合同和架构规范","ja":"バックエンド設計ベストプラクティス - APIエージェントによるOpenAPI生成","ko":"백엔드 디자인 설정 가이드 - API 계약 및 스키마 설계","es":"Guía de configuración de diseño de backend con Agentes de IA","fr":"Guide de mise en place de la conception de backend avec l...","de":"Einrichtungsleitfaden für Backend-Design mit KI-Agents","pt":"Guia de Configuração de Design de Backend para Ferramenta...","ru":"Настройка ИИ Агентов: Руководство по проектированию бэкенда","ar":"دليل تصميم الخلفية لعمليات تعزيز PRODUCT Agentic باستخدام..."},"description":{"en":"Discover how backend-design translates discovery into implementation-ready specs. Learn to produce API contracts and schema designs with this AI agent skill.","zh":"了解后端设计的技术细节，包括API合同、架构规范和认证模型的生成","ja":"バックエンド設計の詳細を学び、APIエージェントを使用してOpenAPIとスキーマ設計を生成する","ko":"백엔드 디자인의 기술적인 측면을 살펴보고, API 계약 및 스키마 설계를 생성하는 방법을 알아보세요","es":"Aprende a traducir artefactos de diseño de producto en especificaciones de backend listas para la implementación con nuestra guía de diseño de backend","fr":"Découvrez comment traduire les artefacts de conception de produit en spécifications de backend prêtes à l''implémentation avec notre guide de conception de ba...","de":"Erfahren Sie, wie Sie Produkt-Design-Artefakte in implementierbare Backend-Spezifikationen übersetzen mit unserem Backend-Design-Leitfaden","pt":"Aprenda a traduzir artefatos de design de produtos em especificações de backend prontas para implementação com OpenAPI e schema design","ru":"Изучите, как перевести артефакты продукта в готовые к реализации спецификации бэкенда с помощью OpenAPI и схемы проектирования","ar":"اكتشف كيفية تحويل مخططات التصميم إلى مواصفات خلفية جاهزة للتنفيذ باستخدام OpenAPI وتصميم مخطط"},"definition":{"en":"Backend-design is a process of converting product requirements into implementation-ready backend specifications, including API contracts and schema designs.","zh":"后端设计是指将产品设计文档转换为可实施的后端规格的过程","ja":"バックエンド設計は、プロダクト設計文書を実装可能なバックエンド仕様に変換するプロセスである","ko":"백엔드 디자인은 제품 디자인 문서를 구현 가능한 백엔드 규격으로 변환하는 과정입니다","es":"El diseño de backend es el proceso de traducir artefactos de diseño de producto en especificaciones de backend implementables","fr":"La conception de backend est le processus de traduire les artefacts de conception de produit en spécifications de backend implémentables","de":"Das Backend-Design ist der Prozess der Übersetzung von Produkt-Design-Artefakten in implementierbare Backend-Spezifikationen","pt":"Design de backend é o processo de tradução de artefatos de design de produtos em especificações de backend prontas para implementação","ru":"Проектирование бэкенда - это процесс перевода артефактов продукта в готовые к реализации спецификации бэкенда","ar":"تصميم الخلفية هو عملية تحويل مخططات التصميم إلى مواصفات خلفية جاهزة للتنفيذ"},"features":{"en":["Translates discovery and product design artifacts into implementation-ready backend specifications","Produces API contracts using OpenAPI","Generates schema design for backend implementation","Creates auth model and integration point specs for human review","Validates API and schema specifications for backend engineers"],"zh":["生成API合同（OpenAPI）","架构规范设计","认证模型生成","集成点规格设计","后端实现前的验证"],"ja":["APIエージェントによるOpenAPI生成","スキーマ設計","認証モデル生成","統合ポイント仕様設計","バックエンド実装前の検証"],"ko":["API 계약 생성（OpenAPI）","스키마 설계","인증 모델 생성","통합 점 규격 설계","백엔드 구현 전의 검증"],"es":["Traducción de artefactos de diseño de producto en especificaciones de backend","Generación de contratos de API (OpenAPI)","Diseño de esquema y modelo de autenticación","Especificaciones de puntos de integración para la revisión humana"],"fr":["Traduction des artefacts de conception de produit en spécifications de backend","Génération de contrats d''API (OpenAPI)","Conception de schéma et de modèle d''authentification","Spécifications de points d''intégration pour la revue humaine"],"de":["Übersetzung von Produkt-Design-Artefakten in implementierbare Backend-Spezifikationen","Erzeugung von API-Verträgen (OpenAPI)","Schema-Design und Authentifizierungsmodell","Spezifikationen von Integrationspunkten für die menschliche Überprüfung"],"pt":["Geração de contratos de API OpenAPI","Design de schema para implementação de backend","Modelo de autenticação para integração de sistemas","Especificação de pontos de integração para revisão humana","Validação de requisições de produtos para garantir a implementação correta"],"ru":["Генерация контрактов API OpenAPI","Проектирование схемы для реализации бэкенда","Модель аутентификации для интеграции систем","Спецификация точек интеграции для проверки человеком","Валидация запросов продукта для обеспечения правильной реализации"],"ar":["إنشاء عقود واجهة برمجة التطبيقات OpenAPI","تصميم مخطط لتنفيذ الخلفية","نموذج مصادقة للتكامل النظم","مواصفات نقاط التكامل لمراجعة الإنسان","تحقق من طلبات المنتج لضمان التنفيذ الصحيح"]},"keywords":{"en":["how to use backend-design","backend-design setup guide","what is backend-design","backend-design alternative","backend-design vs API design","backend-design install for AI agents","OpenAPI contract generation","schema design for backend implementation"],"zh":["后端设计","API合同","架构规范","认证模型","集成点规格","后端实现","AIエージェント","后端设计设置","API生成"],"ja":["バックエンド設計","APIエージェント","OpenAPI","スキーマ設計","認証モデル","統合ポイント仕様","バックエンド実装","AIエージェント","バックエンド設計ベストプラクティス"],"ko":["백엔드 디자인","API 계약","스키마 설계","인증 모델","통합 점 규격","백엔드 구현","AI 에이전트","백엔드 디자인 설정","API 생성"],"es":["diseño de backend","agentes de ia","especificaciones de backend","contratos de api","diseño de esquema","modelo de autenticación","puntos de integración","revisión humana","implementación de backend"],"fr":["conception de backend","outils d''ia","spécifications de backend","contrats d''api","conception de schéma","modèle d''authentification","points d''intégration","revue humaine","implémentation de backend"],"de":["backend-design","ki-agenten","backend-spezifikationen","api-verträge","schema-design","authentifizierungsmodell","integrationspunkte","menschliche überprüfung","backend-implementation"],"pt":["design de backend","ferramentas de IA","OpenAPI","schema design","autenticação","integração de sistemas","revisão humana","validação de requisições","implementação de backend"],"ru":["проектирование бэкенда","ИИ Агенты","OpenAPI","схема проектирования","аутентификация","интеграция систем","проверка человеком","валидация запросов","реализация бэкенда"],"ar":["تصميم الخلفية","أدوات الذكاء الاصطناعي","OpenAPI","تصميم مخطط","مصادقة","تكامل النظم","مراجعة الإنسان","تحقق من الطلبات","تنفيذ الخلفية"]}},"owner":"ivanyeors","repo":"product-agentic-templates","repoPath":"ivanyeors/product-agentic-templates","stars":0,"forks":0,"updatedAt":"2026-03-01T05:04:44Z","topics":[],"category":"community","skillMd":{"name":"backend-design","description":"Guides backend design work including API contract specification, database schema design, auth model, and integration point design. Use when designing the API, creating OpenAPI specs, designing database schemas, defining auth and permissions, or when the user says design the API, API contract, schema design, database design, backend design, OpenAPI spec. Requires completed Product Discovery and Product Design artifacts as input.","bodyPreview":"# 04 — Backend Design\n\nTranslates discovery and product design artifacts into implementation-ready backend specifications. Produces API contracts (OpenAPI), schema design, auth model, and integration point specs for human review before Backend Implementation begins.\n\n---\n\n## Job Persona\n\n**Role:** Backend Architect / API Designer\n\n**Core mandate:** Convert PRD requirements and data dictionary into complete, validated API and schema specifications that backend engineers can implement without ambi","body":"# 04 — Backend Design\n\nTranslates discovery and product design artifacts into implementation-ready backend specifications. Produces API contracts (OpenAPI), schema design, auth model, and integration point specs for human review before Backend Implementation begins.\n\n---\n\n## Job Persona\n\n**Role:** Backend Architect / API Designer\n\n**Core mandate:** Convert PRD requirements and data dictionary into complete, validated API and schema specifications that backend engineers can implement without ambiguity. Contract-first — always.\n\n**Non-negotiables:**\n- Every endpoint must be traceable to an FR-ID from the PRD\n- Schema design must align with the data dictionary — no ad-hoc columns\n- Every endpoint must specify success, error, and validation failure responses\n- List endpoints must define pagination from the start\n- Auth and permission model must be designed before implementation — not deferred\n\n**Bad habits to eliminate:**\n- Designing endpoints without error response formats\n- Skipping pagination for list endpoints (\"we''ll add it later\")\n- Leaving auth \"for later\" — it affects every endpoint\n- Adding schema columns without data dictionary alignment\n- Designing only the happy path — error and empty states are required\n\n---\n\n## Phase Flow\n\n```mermaid\nflowchart TD\n    start([Triggered]) --> prereq{Product Design artifacts exist?}\n    prereq -->|No| block[Trigger 02-product-design first]\n    prereq -->|Yes| accept[Accept Handoff Verify No-Go + Read-Back]\n    accept --> hi_check[Check human-interventions/active/ for phase:04-backend-design items]\n    hi_check --> pri[Prioritization Impact/Effort 2x2 for endpoint sequencing]\n    pri --> s1[Phase 1 API Contract Design]\n    s1 --> s2[Phase 2 Request/Response Specification]\n    s2 --> s3[Phase 3 Schema Design]\n    s3 --> s4[Phase 4 Auth & Permission Model]\n    s4 --> s5[Phase 5 Integration Points Design]\n    s5 --> s6[Phase 6 API Documentation]\n    s6 --> gate{Gate 4 Human Approval}\n    gate -->|APPROVED| next[06 Backend Implementation]\n    gate -->|REVISE| revise[Revise flagged artifacts]\n    revise --> gate\n```\n\n---\n\n## Accept Handoff (before starting work)\n\n1. Read the handoff package from Phase 02 (Product Design)\n2. **Verify Release Mode and MVP Scope** — if `Release Mode: MVP`, scope = MVP-tagged FR-IDs only; otherwise full P0.\n3. Verify all No-Go items pass (interpret \"P0\" as MVP scope when in MVP mode):\n   - [ ] PRD exists with FR-IDs for all P0 (or MVP) requirements\n   - [ ] Data dictionary exists (or Phase 5b marked N/A in discovery)\n   - [ ] User flows exist for every P0 (or MVP) user story\n   - [ ] Wireframe specs exist for data-dependent screens\n   - If any fail → **HALT**. Notify orchestrator.\n4. Log Read-Back: restate the backend design intent — \"We are designing the API and schema for [product]. **Release Mode: [Full Production | MVP].** Core entities are [list from data dictionary]. The primary flows requiring backend support are [list]. The constraints we must preserve are: [list from handoff Decisions and Intent table].\"\n5. Raise RFIs: list any unclear data dictionary entries, ambiguous business rules, or missing integration requirements. Resolve from artifacts or escalate to human.\n6. Review inherited Assumptions — flag any that affect API or schema design.\n7. Only after all above: begin Phase 04 work.\n\nSee [handoff-package-template.md](../00-product-workflow/handoff-package-template.md) for the full handoff structure.\n\n---\n\n## Quick Start\n\nBefore starting, confirm these artifacts exist:\n- [ ] PRD with prioritized requirements (FR-IDs)\n- [ ] Data dictionary (entities, attributes, business rules, relationships)\n- [ ] User flow diagrams\n- [ ] Wireframe specifications\n- [ ] Content model (when content-heavy — feeds schema design)\n- [ ] Feedback Channels Plan (when feedback in scope — informs endpoint inventory, e.g. POST /feedback)\n\nIf any are missing, trigger `01-product-discovery` or `02-product-design` first.\n\nAsk the user:\n1. What API style? (REST, GraphQL, or both)\n2. What database? (Postgres, MySQL, MongoDB, etc.)\n3. Any existing API conventions or standards to follow?\n4. Any third-party integrations required? (auth provider, payments, webhooks)\n5. Any versioning strategy? (URL path, header, query param)\n\n---\n\n## Design Phases\n\n### Phase 1: API Contract Design\n- Inventory all endpoints required by user flows and wireframes\n- Map each endpoint to FR-IDs from the PRD\n- Define resource naming (plural nouns, kebab-case)\n- Assign HTTP methods (GET, POST, PATCH, PUT, DELETE)\n- Output: **Endpoint Inventory** (see [artifacts-template.md](artifacts-template.md))\n\n### Phase 2: Request/Response Specification\n- Define request body schemas for each mutation endpoint\n- Define response schemas for each endpoint (success, error, validation)\n- Specify status codes (200, 201, 400, 401, 403, 404, 422, 500)\n- Define standard error format (see [api-design-guide.md](api-design-guide.md))\n- Output: **OpenAPI Schemas** (request/response shapes, error format)\n\n### Phase 3: Schema Design\n- Map data dictionary entities to tables\n- Define columns, types, constraints, defaults\n- Define relationships (foreign keys, junction tables)\n- Design indexes for query patterns (see [schema-design-guide.md](schema-design-guide.md))\n- Output: **Schema Design Document** (tables, columns, indexes, migration plan)\n\n### Phase 4: Auth & Permission Model\n- Define auth strategy (JWT, session, OAuth, API key)\n- Define roles and permissions matrix\n- Map permissions to endpoints (who can access what)\n- Design RLS policies (if Postgres) or equivalent\n- Output: **Auth & Permission Model** (roles, permissions, endpoint mapping)\n\n### Phase 5: Integration Points Design\n- Define webhook payloads (if applicable)\n- Define third-party API contracts (auth provider, payments)\n- Specify event payloads for async flows\n- Output: **Integration Points Specification**\n\n### Phase 6: API Documentation\n- Produce complete OpenAPI 3.x spec\n- Add request/response examples for each endpoint\n- Document migration plan (order of migrations, rollback strategy)\n- Output: **Complete OpenAPI Spec + Migration Plan**\n\n---\n\n## Prioritization\n\nBefore beginning endpoint design, apply the Impact/Effort 2×2 matrix to sequence work. See [pm-prioritization.md](../00-product-workflow/pm-prioritization.md) → Impact/Effort Matrix.\n\n1. List all endpoints identified from user flows and data requirements\n2. Score each: Business Impact (1–5) × Design Effort (1–5)\n3. Map to quadrant\n4. **Sequence:** Quick Wins first → Major Projects → Fill-Ins → defer Thankless Tasks\n5. Design in this priority order — P0 endpoints first, then P1\n\n**Forcing function:** If scope exceeds the sprint, defer Thankless Tasks first. Present this trade-off to the human before proceeding.\n\n---\n\n## MVP Mode Behavior\n\nWhen `Release Mode: MVP` in the handoff package, adjust scope and detail:\n\n| Aspect | Full Production | MVP |\n|--------|-----------------|-----|\n| Endpoints | All P0 (+ P1) | MVP FR-IDs only |\n| Schema | Full schema | Core tables for MVP entities |\n| Auth | Full auth model | Basic auth (login, token) |\n| Pagination | All list endpoints | Defer for non-critical lists |\n| Integration points | Full spec | Core only (auth if required) |\n\n---\n\n## Active Intervention Check\n\nAt the start of every work session and before presenting the gate:\n1. Check `human-interventions/active/` for files tagged `phase: 04-backend-design` or `phase: all`\n2. If `urgency: immediate` — halt and process before continuing\n3. If `urgency: end-of-phase` — integrate before the gate presentation\n4. After resolving, move to `human-interventions/processed/` and note in gate summary\n\n```mermaid\nflowchart TD\n    check[Check human-interventions/active/ for phase: 04-backend-design or phase: all] --> found{Files found?}\n    found -->|No| proceed([Continue phase work])\n    found -->|Yes| urgency{Urgency?}\n    urgency -->|immediate| halt[Halt current work Process intervention first]\n    urgency -->|end-of-phase| queue[Integrate before gate presentation]\n    halt --> archive[Move to processed/ Note in gate summary]\n    queue --> archive\n    archive --> proceed\n```\n\n---\n\n## Feedback & Update Loop\n\n### Receiving feedback\n- **From gate REVISE:** Update only flagged artifacts — do not redesign the entire phase\n- **From human intervention:** Complete Agent Interpretation and Impact Assessment, then integrate\n- **From 02-product-design:** If user flows change, re-audit affected endpoints and schema\n\n### Propagating updates downstream\n- If API contract changes post-approval: create `human-interventions/active/[date]-04-api-update/content.md` — notify `06-backend-implementation` and `07-integration`\n- If schema design changes: document what changed and why in the intervention file\n- Breaking API changes require a full impact assessment before proceeding\n\n### Revision limits\nMax 3 revision cycles at this gate. On the 3rd, escalate to orchestrator. See `00-product-workflow/SKILL.md`.\n\n---\n\n## Human Review Gate\n\nAfter completing all phases, present the design package:\n\n```\nBACKEND DESIGN COMPLETE — HUMAN REVIEW REQUIRED\n\nArtifacts produced:\n- [ ] Endpoint Inventory (all endpoints mapped to FR-IDs)\n- [ ] OpenAPI Spec (request/response schemas, error format)\n- [ ] Schema Design (tables, columns, indexes, migration plan)\n- [ ] Auth & Permission Model (roles, permissions, endpoint mapping)\n- [ ] Integration Points Specification (webhooks, third-party contracts)\n- [ ] Complete OpenAPI 3.x Spec + Examples\n\nPrioritization summary:\n- Quick Wins designed: [list]\n- Major Projects designed: [list]\n- Deferred (Thankless/out of scope): [list]\n\nReview checklist: see backend-design-checklist.md\n\nReply with:\n- APPROVED → begin 06 Backend Implementation\n- REVISE: [feedback] → agent will update and re-present\n```\n\n---\n\n## Design Principles\n\n- **Contract-first** — API spec is the source of truth before any code\n- **Traceability** — every endpoint maps to at least one FR-ID\n- **Schema alignment** — data dictionary drives schema; no orphan columns\n- **Error states required** — every endpoint has defined error responses\n- **Pagination by default** — list endpoints always define pagination\n\n---\n\n## Additional Resources\n\n- [api-design-guide.md](api-design-guide.md) — REST conventions, versioning, pagination, error format\n- [schema-design-guide.md](schema-design-guide.md) — Naming, indexing, migration strategy\n- [artifacts-template.md](artifacts-template.md) — OpenAPI template, schema DDL template\n- [backend-design-checklist.md](backend-design-checklist.md) — human review gate checklist\n- [pm-prioritization.md](../00-product-workflow/pm-prioritization.md) — Impact/Effort 2×2 rubric\n"},"lastSynced":"2026-03-07T04:10:25.717Z","agentAnalysis":{"suitability":{"en":"Ideal for API Designer Agents requiring precise backend specification generation using OpenAPI contracts and schema designs.","zh":"适用于需要使用 OpenAPI 合同和 schema 设计生成精确后端规格的 API 设计师代理。","ja":"OpenAPI コントラクトとスキーマ設計を使用して、正確なバックエンド仕様を生成する必要がある API デザイナー エージェントに最適です。","ko":"OpenAPI 계약 및 스키마 설계를 사용하여 정확한 백엔드 사양을 생성해야 하는 API 디자이너 에이전트에 적합합니다.","es":"Ideal para Agentes de Diseñador de API que requieren una generación de especificaciones de backend precisas utilizando contratos y diseños de esquema de OpenAPI.","fr":"Idéal pour les agents concepteurs d''API nécessitant une génération de spécifications de backend précises utilisant des contrats et des conceptions de schéma OpenAPI.","de":"Ideal für API-Designer-Agents, die eine präzise Generierung von Backendspezifikationen unter Verwendung von OpenAPI-Verträgen und Schemadesigns erfordern.","pt":"Ideal para Agentes de Design de API que requerem geração precisa de especificação de backend usando contratos OpenAPI e designs de schema.","ru":"Идеально для агентов-дизайнеров API, требующих точной генерации спецификации бэкенда с использованием контрактов OpenAPI и схем.","ar":"مثالي لعميل ديزاين API الذي يتطلب توليد دقيق لمواصفات الخلفية باستخدام عقود OpenAPI وتصاميم مخطط"},"recommendation":{"en":"Empowers agents to translate product design artifacts into implementation-ready backend specifications, producing API contracts and schema designs for human review, utilizing OpenAPI and integrating auth models.","zh":"赋予代理将产品设计工件转化为可实施的后端规格，生成 API 合同和 schema 设计以供人类审查，利用 OpenAPI 并集成身份验证模型。","ja":"エージェントが製品設計アーティファクトを実装可能なバックエンド仕様に翻訳し、OpenAPI を利用して API コントラクトとスキーマ設計を生成し、人間によるレビューと認証モデルを統合することができます。","ko":"에이전트가 제품 디자인 아티팩트를 구현 가능한 백엔드 사양으로 번역하고 OpenAPI를 사용하여 API 계약과 스키마 설계를 생성하여 인간의 검토와 인증 모델을 통합할 수 있습니다.","es":"Habilita a los agentes a traducir artefactos de diseño de producto en especificaciones de backend listas para la implementación, produciendo contratos de API y diseños de esquema para revisión humana, utilizando OpenAPI e integrando modelos de autenticación.","fr":"Permet aux agents de traduire les artefacts de conception de produit en spécifications de backend prêtes à l''implémentation, produisant des contrats d''API et des conceptions de schéma pour examen humain, en utilisant OpenAPI et en intégrant des modèles d''authentification.","de":"Ermöglicht es Agenten, Produkt-Design-Artefakte in implementierungsreife Backendspezifikationen zu übersetzen, wodurch API-Verträge und Schemadesigns für die Überprüfung durch Menschen erstellt werden, unter Verwendung von OpenAPI und Integration von Authentifizierungsmodellen.","pt":"Habilita os agentes a traduzir artefatos de design de produto em especificações de backend prontas para implementação, produzindo contratos de API e designs de schema para revisão humana, utilizando OpenAPI e integrando modelos de autenticação.","ru":"Позволяет агентам переводить артефакты дизайна продукта в готовые к реализации спецификации бэкенда, производя контракты API и схемы для рассмотрения человеком, используя OpenAPI и интегрируя модели аутентификации.","ar":"تمكين العميل من ترجمة مكونات التصميم الخاصة بالمنتج إلى مواصفات خلفية جاهزة للتنفيذ ، وإنتاج عقود API وتصاميم مخطط للمراجعة البشرية ، باستخدام OpenAPI وتكامل نماذج المصادقة"},"useCases":{"en":["Generating API contracts for microservices","Designing schema for data-intensive applications","Creating integration point specs for third-party services"],"zh":["为微服务生成 API 合同","为数据密集型应用程序设计 schema","为第三方服务创建集成点规格"],"ja":["マイクロサービス用の API コントラクトを生成する","データ集中型アプリケーションのスキーマを設計する","サードパーティ サービスの統合ポイント仕様を作成する"],"ko":["마이크로 서비스를 위한 API 계약 생성","데이터 집약형 애플리케이션을 위한 스키마 설계","제3자 서비스를 위한 통합 지점 사양 생성"],"es":["Generación de contratos de API para microservicios","Diseño de esquema para aplicaciones intensivas en datos","Creación de especificaciones de puntos de integración para servicios de terceros"],"fr":["Génération de contrats d''API pour les microservices","Conception de schéma pour les applications intensives en données","Création de spécifications de points d''intégration pour les services tiers"],"de":["Generierung von API-Verträgen für Microservices","Entwurf von Schemata für datenintensive Anwendungen","Erstellung von Spezifikationen für Integrationspunkte für Drittanbieterdienste"],"pt":["Geração de contratos de API para microsserviços","Design de schema para aplicações intensivas de dados","Criação de especificações de pontos de integração para serviços de terceiros"],"ru":["Генерация контрактов API для микросервисов","Дизайн схемы для данных интенсивных приложений","Создание спецификаций точек интеграции для сервисов третьих сторон"],"ar":["توليد عقود API لمايكروسيرفس","تصميم مخطط للطبيقات الكثيفة بالبيانات","إنشاء مواصفات نقاط التكامل لخدمات الطرف الثالث"]},"limitations":{"en":["Requires human review before backend implementation","Limited to producing specifications for backend engineers"],"zh":["需要人类在后端实现之前进行审查","仅限生成后端工程师的规格"],"ja":["バックエンドの実装前に人間によるレビューが必要","バックエンド エンジニアの仕様を生成することのみに限定される"],"ko":["백엔드 구현 전에 인간의 검토가 필요","백엔드 엔지니어의 사양을 생성하는 것만으로 제한"],"es":["Requiere revisión humana antes de la implementación de backend","Limitado a producir especificaciones para ingenieros de backend"],"fr":["Nécessite un examen humain avant la mise en œuvre du backend","Limité à produire des spécifications pour les ingénieurs de backend"],"de":["Erfordert eine Überprüfung durch Menschen vor der Implementierung von Backends","Begrenzt auf die Erstellung von Spezifikationen für Back-end-Ingenieure"],"pt":["Requer revisão humana antes da implementação de backend","Limitado a produzir especificações para engenheiros de backend"],"ru":["Требует рассмотрения человеком перед реализацией бэкенда","Ограничен производством спецификаций для инженеров бэкенда"],"ar":["يتطلب مراجعة بشرية قبل تنفيذ الخلفية","محدود في توليد مواصفات لمهندسي الخلفية"]},"version":4},"contentHash":"d811bcd3a12a39e1542f84a383964858863d1fffd416218a5532dda70a14b953","qualityScore":42}');
