INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ivanyeors/product-agentic-templates/backend-design', 'backend-design', 'ivanyeors', 'product-agentic-templates', 'community', 'backend-design ivanyeors product-agentic-templates community Backend-design skill translates product design artifacts into backend specifications, benefiting backend architects and API designers. It produces API contracts and schema designs for human review. 后端设计是将发现和产品设计文档转换为可实施的后端规格的过程，包括API合同、架构规范和认证模型的生成 バックエンド設計は、発見とプロダクト設計文書を実装可能なバックエンド仕様に変換するプロセスであり、APIエージェントを使用してOpenAPIとスキーマ設計を生成する 백엔드 디자인은 발견과 제품 디자인 문서를 구현 가능한 백엔드 규격으로 변환하는 과정으로, API 계약 및 스키마 설계를 생성하는 것을 포함합니다 El diseño de backend traduce los artefactos de diseño de producto en especificaciones de backend listas para la implementación. Produce contratos de API y diseños de esquema para la revisión humana La conception de backend traduit les artefacts de conception de produit en spécifications de backend prêtes à l''implémentation. Produit des contrats d''API et des conceptions de schéma pour la revue humaine Das Backend-Design übersetzt Produkt-Design-Artefakte in implementierbare Backend-Spezifikationen. Erzeugt API-Verträge und Schema-Designs für die menschliche Überprüfung O design de backend traduz artefatos de design de produtos em especificações prontas para implementação, incluindo contratos de API OpenAPI e design de schema Проектирование бэкенда переводит артефакты продукта в готовые к реализации спецификации, включая контракты API OpenAPI и схему проектирования تصميم الخلفية يترجم مخططات التصميم إلى مواصفات جاهزة للتنفيذ، بما في ذلك عقود واجهة برمجة التطبيقات OpenAPI وتصميم المخطط how to use backend-design backend-design setup guide what is backend-design backend-design alternative backend-design vs API design backend-design install for AI agents OpenAPI contract generation schema design for backend implementation 后端设计 API合同 架构规范 认证模型 集成点规格 后端实现 AIエージェント 后端设计设置 API生成 Translates discovery and product design artifacts into implementation-ready backend specifications Produces API contracts using OpenAPI Generates schema design for backend implementation Creates auth model and integration point specs for human review Validates API and schema specifications for backend engineers Backend-design is a process of converting product requirements into implementation-ready backend specifications, including API contracts and schema designs.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EmaBilibili/My-Portfolio/kickbox-automation', 'community', 'EmaBilibili', 'My-Portfolio', 'EmaBilibili/My-Portfolio', 'kickbox-automation', 0, 0, 42, '2026-03-04T00:40:58Z', '2026-03-07T04:11:03.867Z', 'af9fe0d1f5271243ae5584a05649b47db516845e350fa6609ea7289a012f76da', '{"id":"EmaBilibili/My-Portfolio/kickbox-automation","name":"kickbox-automation","description":{"en":"The kickbox-automation skill automates Kickbox operations through Composio''s Kickbox toolkit via Rube MCP, benefiting developers and AI agents. It streamlines processes with prerequisites and setup instructions","zh":"Kickbox Automation通过Composio的工具包和Rube MCP实现自动化。需要Rube MCP连接和Kickbox连接。","ja":"Kickbox AutomationはComposioのツールキットとRube MCPを使用して自動化を実現します。Rube MCPとKickboxの接続が必要です。","ko":"Kickbox Automation은 Composio의 툴킷과 Rube MCP를 사용하여 자동화를 설정합니다. Rube MCP와 Kickbox의 연결이 필요합니다.","es":"La automatización de Kickbox permite a los desarrolladores automatizar operaciones de Kickbox mediante Composio y Rube MCP. Requiere una conexión activa de Kickbox y Rube MCP.","fr":"L''automatisation de Kickbox permet aux développeurs d''automatiser les opérations de Kickbox via Composio et Rube MCP. Une connexion active de Kickbox et Rube MCP est requise.","de":"Die Automatisierung von Kickbox ermöglicht es Entwicklern, Kickbox-Operationen mit Composio und Rube MCP zu automatisieren. Eine aktive Kickbox- und Rube-MCP-Verbindung ist erforderlich.","pt":"O Kickbox-Automation é uma ferramenta que automatiza operações do Kickbox via Rube MCP. Veja como configurar e usar.","ru":"Автоматизация Kickbox - это инструмент, который автоматизирует операции Kickbox через Rube MCP. См. настройку и использование.","ar":"تطبيق Kickbox-Automation هو أداة تطبيق تطبيق Kickbox-Automation عبر Rube MCP. شاهد كيفية الإعداد والاستخدام."},"seo":{"title":{"en":"kickbox-automation: Setup Guide for AI Agents","zh":"Kickbox Automation Setup Guide - Composio工具包","ja":"Kickbox Automationベストプラクティス - AIエージェントとの統合","ko":"Kickbox Automation 설정 가이드 - Composio 툴킷을 이용한 자동화","es":"Guía de Configuración de Automatización de Kickbox","fr":"Guide de Configuration de l''Automatisation de Kickbox","de":"Konfigurationsleitfaden für Kickbox-Automatisierung","pt":"Guia de Configuração do Kickbox-Automation via Rube MCP","ru":"Настройка Автоматизации Kickbox с помощью Rube MCP","ar":"دليل إعداد تطبيق Kickbox-Automation عبر Rube MCP"},"description":{"en":"Discover how to automate Kickbox operations via Composio''s toolkit and Rube MCP. Get started with our setup guide and unlock efficient automation","zh":"通过Composio的Kickbox工具包和Rube MCP实现Kickbox自动化。了解设置和使用方法。","ja":"AIエージェントと統合したKickbox Automationのベストプラクティス。Rube MCPとComposioのツールキットを使用して自动化を実現します。","ko":"Composio의 툴킷과 Rube MCP를 사용하여 Kickbox 자동화를 설정하고 사용하는 방법을 알아보세요.","es":"Aprende a automatizar operaciones de Kickbox con Composio y Rube MCP. Descubre cómo configurar y utilizar la herramienta de automatización de Kickbox.","fr":"Découvrez comment automatiser les opérations de Kickbox avec Composio et Rube MCP. Configurez et utilisez l''outil d''automatisation de Kickbox.","de":"Erfahren Sie, wie Sie Kickbox-Operationen mit Composio und Rube MCP automatisieren. Konfigurieren und verwenden Sie das Kickbox-Automatisierungstool.","pt":"Aprenda a automatizar operações do Kickbox com o toolkit Composio via Rube MCP. Veja como configurar e usar.","ru":"Узнайте, как автоматизировать операции Kickbox с помощью toolkit Composio через Rube MCP. См. настройку и использование.","ar":"تعلم كيفية تطبيق تطبيق Kickbox-Automation باستخدام أداة Composio عبر Rube MCP. شاهد كيفية الإعداد والاستخدام."},"definition":{"en":"kickbox-automation is a skill that enables automation of Kickbox operations through Composio''s toolkit and Rube MCP connection","zh":"Kickbox Automation是通过Composio的工具包和Rube MCP实现的自动化功能。","ja":"Kickbox AutomationはAIエージェントを使用してKickboxの操作を自動化する機能です。","ko":"Kickbox Automation은 Composio의 툴킷과 Rube MCP를 사용하여 Kickbox를 자동화하는 기능입니다.","es":"La automatización de Kickbox es una herramienta que permite a los desarrolladores automatizar operaciones de Kickbox mediante Composio y Rube MCP.","fr":"L''automatisation de Kickbox est un outil qui permet aux développeurs d''automatiser les opérations de Kickbox via Composio et Rube MCP.","de":"Die Automatisierung von Kickbox ist ein Tool, das es Entwicklern ermöglicht, Kickbox-Operationen mit Composio und Rube MCP zu automatisieren.","pt":"O que é Kickbox-Automation? É uma ferramenta de automação de operações do Kickbox via Rube MCP.","ru":"Что такое Автоматизация Kickbox? Это инструмент автоматизации операций Kickbox через Rube MCP.","ar":"ما هو تطبيق Kickbox-Automation? هو أداة تطبيق تطبيق Kickbox-Automation عبر Rube MCP."},"features":{"en":["Automates Kickbox operations via Composio''s Kickbox toolkit","Utilizes Rube MCP connection for efficient automation","Requires RUBE_SEARCH_TOOLS to get current tool schemas","Needs active Kickbox connection via RUBE_MANAGE_CONNECTIONS","Supports setup through Rube MCP serve at https://rube.app/mcp"],"zh":["通过Rube MCP连接实现自动化","使用Composio的Kickbox工具包","需要Rube MCP和Kickbox的连接","支持RUBE_SEARCH_TOOLS和RUBE_MANAGE_CONNECTIONS","自动化Kickbox操作"],"ja":["Rube MCP接続を使用した自動化","ComposioのKickboxツールキットを使用","Rube MCPとKickboxの接続が必要","RUBE_SEARCH_TOOLSとRUBE_MANAGE_CONNECTIONSをサポート","Kickbox操作の自動化"],"ko":["Rube MCP 연결을 사용한 자동화","Composio의 Kickbox 툴킷을 사용","Rube MCP와 Kickbox의 연결이 필요","RUBE_SEARCH_TOOLS와 RUBE_MANAGE_CONNECTIONS를 지원","Kickbox 연산의 자동화"],"es":["Conexión de Rube MCP","Herramienta de automatización de Kickbox","Compatibilidad con Composio","Requiere conexión activa de Kickbox","Utiliza RUBE_SEARCH_TOOLS para obtener esquemas de herramientas actuales"],"fr":["Connexion Rube MCP","Outil d''automatisation de Kickbox","Compatibilité avec Composio","Requiert une connexion active de Kickbox","Utilise RUBE_SEARCH_TOOLS pour obtenir les schémas d''outils actuels"],"de":["Rube-MCP-Verbindung","Kickbox-Automatisierungstool","Kompatibilität mit Composio","Erfordert eine aktive Kickbox-Verbindung","Verwendet RUBE_SEARCH_TOOLS, um aktuelle Tool-Schemas zu erhalten"],"pt":["Automação de operações do Kickbox via Rube MCP","Integração com o toolkit Composio","Requisitos de configuração mínimos","Suporte à chamada de RUBE_SEARCH_TOOLS","Conexão ativa com o Kickbox via RUBE_MANAGE_CONNECTIONS","Documentação do toolkit disponível em composio.dev/toolkits/kickbox"],"ru":["Автоматизация операций Kickbox через Rube MCP","Интеграция с toolkit Composio","Минимальные требования к настройке","Поддержка вызова RUBE_SEARCH_TOOLS","Активное подключение к Kickbox через RUBE_MANAGE_CONNECTIONS","Документация toolkit доступна на composio.dev/toolkits/kickbox"],"ar":["تطبيق تطبيق Kickbox-Automation عبر Rube MCP","التكامل مع أداة Composio","متطلبات التكوين الدنيا","دعم 呼叫 RUBE_SEARCH_TOOLS","اتصال نشط مع Kickbox عبر RUBE_MANAGE_CONNECTIONS","توثيق أداة متوفر على composio.dev/toolkits/kickbox"]},"keywords":{"en":["how to use kickbox-automation","kickbox-automation setup guide","what is kickbox-automation","kickbox-automation alternative","kickbox-automation vs Composio","kickbox-automation install","Rube MCP connection","Composio Kickbox toolkit","automate Kickbox operations"],"zh":["Kickbox Automation","Composio工具包","Rube MCP","自动化","AI工具","Kickbox连接","RUBE_SEARCH_TOOLS","RUBE_MANAGE_CONNECTIONS"],"ja":["Kickbox Automation","AIエージェント","Composioツールキット","Rube MCP","自動化","Kickbox接続","RUBE_SEARCH_TOOLS","RUBE_MANAGE_CONNECTIONS"],"ko":["Kickbox Automation","Composio 툴킷","Rube MCP","자동화","AI 툴","Kickbox 연결","RUBE_SEARCH_TOOLS","RUBE_MANAGE_CONNECTIONS"],"es":["automatización de Kickbox","herramienta de automatización de Kickbox","Composio","Rube MCP","conexión de Kickbox","RUBE_SEARCH_TOOLS","desarrollo de software","automatización de procesos"],"fr":["automatisation de Kickbox","outil d''automatisation de Kickbox","Composio","Rube MCP","connexion de Kickbox","RUBE_SEARCH_TOOLS","développement de logiciels","automatisation de processus"],"de":["Automatisierung von Kickbox","Kickbox-Automatisierungstool","Composio","Rube MCP","Kickbox-Verbindung","RUBE_SEARCH_TOOLS","Softwareentwicklung","Prozessautomatisierung"],"pt":["kickbox-automation","rube mcp","composio toolkit","automação de operações","configuração mínima","RUBE_SEARCH_TOOLS","RUBE_MANAGE_CONNECTIONS","documentação do toolkit"],"ru":["автоматизация kickbox","rube mcp","composio toolkit","автоматизация операций","минимальные требования","RUBE_SEARCH_TOOLS","RUBE_MANAGE_CONNECTIONS","документация toolkit"],"ar":["تطبيق Kickbox-Automation","rube mcp","أداة composio","تطبيق تطبيق","متطلبات التكوين","RUBE_SEARCH_TOOLS","RUBE_MANAGE_CONNECTIONS","توثيق أداة"]}},"owner":"EmaBilibili","repo":"My-Portfolio","repoPath":"EmaBilibili/My-Portfolio","stars":0,"forks":0,"updatedAt":"2026-03-04T00:40:58Z","topics":[],"category":"community","skillMd":{"name":"kickbox-automation","description":"Automate Kickbox tasks via Rube MCP (Composio). Always search tools first for current schemas.","bodyPreview":"# Kickbox Automation via Rube MCP\n\nAutomate Kickbox operations through Composio''s Kickbox toolkit via Rube MCP.\n\n**Toolkit docs**: [composio.dev/toolkits/kickbox](https://composio.dev/toolkits/kickbox)\n\n## Prerequisites\n\n- Rube MCP must be connected (RUBE_SEARCH_TOOLS available)\n- Active Kickbox connection via `RUBE_MANAGE_CONNECTIONS` with toolkit `kickbox`\n- Always call `RUBE_SEARCH_TOOLS` first to get current tool schemas\n\n## Setup\n\n**Get Rube MCP**: Add `https://rube.app/mcp` as an MCP serve","body":"# Kickbox Automation via Rube MCP\n\nAutomate Kickbox operations through Composio''s Kickbox toolkit via Rube MCP.\n\n**Toolkit docs**: [composio.dev/toolkits/kickbox](https://composio.dev/toolkits/kickbox)\n\n## Prerequisites\n\n- Rube MCP must be connected (RUBE_SEARCH_TOOLS available)\n- Active Kickbox connection via `RUBE_MANAGE_CONNECTIONS` with toolkit `kickbox`\n- Always call `RUBE_SEARCH_TOOLS` first to get current tool schemas\n\n## Setup\n\n**Get Rube MCP**: Add `https://rube.app/mcp` as an MCP server in your client configuration. No API keys needed — just add the endpoint and it works.\n\n1. Verify Rube MCP is available by confirming `RUBE_SEARCH_TOOLS` responds\n2. Call `RUBE_MANAGE_CONNECTIONS` with toolkit `kickbox`\n3. If connection is not ACTIVE, follow the returned auth link to complete setup\n4. Confirm connection status shows ACTIVE before running any workflows\n\n## Tool Discovery\n\nAlways discover available tools before executing workflows:\n\n```\nRUBE_SEARCH_TOOLS\nqueries: [{use_case: \"Kickbox operations\", known_fields: \"\"}]\nsession: {generate_id: true}\n```\n\nThis returns available tool slugs, input schemas, recommended execution plans, and known pitfalls.\n\n## Core Workflow Pattern\n\n### Step 1: Discover Available Tools\n\n```\nRUBE_SEARCH_TOOLS\nqueries: [{use_case: \"your specific Kickbox task\"}]\nsession: {id: \"existing_session_id\"}\n```\n\n### Step 2: Check Connection\n\n```\nRUBE_MANAGE_CONNECTIONS\ntoolkits: [\"kickbox\"]\nsession_id: \"your_session_id\"\n```\n\n### Step 3: Execute Tools\n\n```\nRUBE_MULTI_EXECUTE_TOOL\ntools: [{\n  tool_slug: \"TOOL_SLUG_FROM_SEARCH\",\n  arguments: {/* schema-compliant args from search results */}\n}]\nmemory: {}\nsession_id: \"your_session_id\"\n```\n\n## Known Pitfalls\n\n- **Always search first**: Tool schemas change. Never hardcode tool slugs or arguments without calling `RUBE_SEARCH_TOOLS`\n- **Check connection**: Verify `RUBE_MANAGE_CONNECTIONS` shows ACTIVE status before executing tools\n- **Schema compliance**: Use exact field names and types from the search results\n- **Memory parameter**: Always include `memory` in `RUBE_MULTI_EXECUTE_TOOL` calls, even if empty (`{}`)\n- **Session reuse**: Reuse session IDs within a workflow. Generate new ones for new workflows\n- **Pagination**: Check responses for pagination tokens and continue fetching until complete\n\n## Quick Reference\n\n| Operation | Approach |\n|-----------|----------|\n| Find tools | `RUBE_SEARCH_TOOLS` with Kickbox-specific use case |\n| Connect | `RUBE_MANAGE_CONNECTIONS` with toolkit `kickbox` |\n| Execute | `RUBE_MULTI_EXECUTE_TOOL` with discovered tool slugs |\n| Bulk ops | `RUBE_REMOTE_WORKBENCH` with `run_composio_tool()` |\n| Full schema | `RUBE_GET_TOOL_SCHEMAS` for tools with `schemaRef` |\n\n---\n*Powered by [Composio](https://composio.dev)*\n"},"lastSynced":"2026-03-07T04:11:03.867Z","agentAnalysis":{"suitability":{"en":"Perfect for Automation Agents needing streamlined Kickbox operations through Composio''s Kickbox toolkit via Rube MCP.","zh":"适合需要通过Composio的Kickbox工具包和Rube MCP实现Kickbox操作流程化的自动化代理。","ja":"ComposioのKickboxツールキットを通じてRube MCPでKickbox操作の流れを簡素化する必要がある自動化エージェントに適しています。","ko":"Composio의 Kickbox 툴킷 및 Rube MCP를 통해 Kickbox 작업을 간소화해야 하는 자동화 에이전트에 적합합니다.","es":"Perfecto para agentes de automatización que necesitan operaciones de Kickbox optimizadas a través de la herramienta de Kickbox de Composio a través de Rube MCP.","fr":"Parfait pour les agents d''automatisation ayant besoin d''opérations de Kickbox rationalisées via l''outil de Kickbox de Composio via Rube MCP.","de":"Perfekt für Automatisierungsagenten, die gestreamte Kickbox-Operationen über Composios Kickbox-Toolkit via Rube MCP benötigen.","pt":"Perfeito para Agentes de Automação que precisam de operações de Kickbox otimizadas por meio da ferramenta Kickbox da Composio via Rube MCP.","ru":"Идеально подходит для агентов автоматизации, которым необходимы оптимизированные операции Kickbox через инструментарий Kickbox Composio с помощью Rube MCP.","ar":"مثالي للوكلاء الآليين الذين يحتاجون إلى عمليات Kickbox مبسطة من خلال أداة Composio Kickbox عبر Rube MCP."},"recommendation":{"en":"Empowers agents to automate Kickbox operations using Rube MCP, providing prerequisites and setup instructions for efficient process management, and leveraging the Composio Kickbox toolkit for enhanced automation capabilities.","zh":"赋予代理自动化Kickbox操作的能力，通过Rube MCP提供先决条件和设置说明，以实现高效的流程管理，并利用Composio Kickbox工具包增强自动化能力。","ja":"Rube MCPを使用してKickbox操作の自動化を可能にし、効率的なプロセス管理のための前提条件および設定手順を提供し、Composio Kickboxツールキットを使用して自動化機能を強化します。","ko":"Rube MCP를 사용하여 Kickbox 작업의 자동화를 가능하게 하며, 효율적인 프로세스 관리를 위한 전제 조건 및 설정 지침을 제공하며, Composio Kickbox 툴킷을 사용하여 자동화 기능을 강화합니다.","es":"Habilita a los agentes a automatizar operaciones de Kickbox utilizando Rube MCP, proporcionando prérequisitos e instrucciones de configuración para una gestión de procesos eficiente, y aprovechando la herramienta de Kickbox de Composio para capacidades de automatización mejoradas.","fr":"Permet aux agents de mettre en œuvre l''automatisation des opérations de Kickbox en utilisant Rube MCP, en fournissant les prérequis et les instructions de configuration pour une gestion de processus efficiente, et en exploitant l''outil de Kickbox de Composio pour des capacités d''automatisation améliorées.","de":"Ermächtigt Agenten, Kickbox-Operationen mithilfe von Rube MCP zu automatisieren, indem es Voraussetzungen und Einrichtungsanweisungen für eine effiziente Prozessverwaltung bereitstellt und das Composio Kickbox-Toolkit für verbesserte Automatisierungsfunktionen nutzt.","pt":"Habilita os agentes a automatizar as operações do Kickbox usando Rube MCP, fornecendo pré-requisitos e instruções de configuração para gerenciamento de processo eficiente e aproveitando a ferramenta Kickbox da Composio para capacidades de automação aprimoradas.","ru":"Наделяет агентов возможностью автоматизировать операции Kickbox с помощью Rube MCP, предоставляя предварительные условия и инструкции по настройке для эффективного управления процессами, а также использует инструментарий Kickbox Composio для расширенных возможностей автоматизации.","ar":"يُمنح الوكلاء القدرة على توفير عمليات Kickbox باستخدام Rube MCP، وتوفير المتطلبات الأساسية وإرشادات الإعداد لإدارة عملية فعالة، واستخدام أداة Composio Kickbox لتعزيز قدرات التأهيل."},"useCases":{"en":["Automating Kickbox operations via Rube MCP","Streamlining processes with prerequisites and setup instructions","Managing Kickbox connections through RUBE_MANAGE_CONNECTIONS"],"zh":["通过Rube MCP自动化Kickbox操作","使用先决条件和设置说明简化流程","通过RUBE_MANAGE_CONNECTIONS管理Kickbox连接"],"ja":["Rube MCPを介してKickbox操作を自動化する","前提条件および設定手順を使用してプロセスを簡素化する","RUBE_MANAGE_CONNECTIONSを介してKickbox接続を管理する"],"ko":["Rube MCP를 통해 Kickbox 작업을 자동화하는 것","전제 조건 및 설정 지침을 사용하여 프로세스를 간소화하는 것","RUBE_MANAGE_CONNECTIONS를 통해 Kickbox 연결을 관리하는 것"],"es":["Automatizar operaciones de Kickbox a través de Rube MCP","Optimizar procesos con prerequisitos e instrucciones de configuración","Administrar conexiones de Kickbox a través de RUBE_MANAGE_CONNECTIONS"],"fr":["Automatiser les opérations de Kickbox via Rube MCP","Rationaliser les processus avec des prérequis et des instructions de configuration","Gérer les connexions de Kickbox via RUBE_MANAGE_CONNECTIONS"],"de":["Kickbox-Operationen über Rube MCP automatisieren","Prozesse mit Voraussetzungen und Einrichtungsanweisungen optimieren","Kickbox-Verbindungen über RUBE_MANAGE_CONNECTIONS verwalten"],"pt":["Automatizar operações do Kickbox via Rube MCP","Otimizar processos com pré-requisitos e instruções de configuração","Gerenciar conexões do Kickbox por meio de RUBE_MANAGE_CONNECTIONS"],"ru":["Автоматизировать операции Kickbox через Rube MCP","Оптимизировать процессы с предварительными условиями и инструкциями по настройке","Управлять подключениями Kickbox через RUBE_MANAGE_CONNECTIONS"],"ar":["توفير عمليات Kickbox من خلال Rube MCP","تبسيط العمليات مع المتطلبات الأساسية وإرشادات الإعداد","إدارة الاتصالات Kickbox من خلال RUBE_MANAGE_CONNECTIONS"]},"limitations":{"en":["Requires Rube MCP connection with RUBE_SEARCH_TOOLS available","Active Kickbox connection via RUBE_MANAGE_CONNECTIONS with toolkit kickbox required"],"zh":["需要Rube MCP连接，且RUBE_SEARCH_TOOLS可用","需要通过RUBE_MANAGE_CONNECTIONS的活跃Kickbox连接，且需要工具包kickbox"],"ja":["Rube MCP接続が必要であり、RUBE_SEARCH_TOOLSが利用可能であること","RUBE_MANAGE_CONNECTIONS経由でのアクティブなKickbox接続が必要であり、ツールキットkickboxが必要であること"],"ko":["Rube MCP 연결이 필요하며, RUBE_SEARCH_TOOLS가 사용 가능해야 함","RUBE_MANAGE_CONNECTIONS를 통한 활성 Kickbox 연결이 필요하며, 툴킷 kickbox가 필요함"],"es":["Requiere conexión de Rube MCP con RUBE_SEARCH_TOOLS disponible","Conexión de Kickbox activa a través de RUBE_MANAGE_CONNECTIONS con toolkit kickbox requerido"],"fr":["Nécessite une connexion Rube MCP avec RUBE_SEARCH_TOOLS disponible","Connexion de Kickbox active via RUBE_MANAGE_CONNECTIONS avec toolkit kickbox requis"],"de":["Benötigt Rube MCP-Verbindung mit verfügbarer RUBE_SEARCH_TOOLS","Aktive Kickbox-Verbindung über RUBE_MANAGE_CONNECTIONS mit Toolkit kickbox erforderlich"],"pt":["Exige conexão Rube MCP com RUBE_SEARCH_TOOLS disponível","Conexão Kickbox ativa via RUBE_MANAGE_CONNECTIONS com toolkit kickbox necessário"],"ru":["Требует подключения Rube MCP с доступным RUBE_SEARCH_TOOLS","Активное подключение Kickbox через RUBE_MANAGE_CONNECTIONS с необходимым инструментарием kickbox"],"ar":["يتطلب اتصال Rube MCP مع أداة RUBE_SEARCH_TOOLS متاحة","اتصال Kickbox نشط من خلال RUBE_MANAGE_CONNECTIONS مع أداة kickbox مطلوبة"]},"version":4},"contentHash":"af9fe0d1f5271243ae5584a05649b47db516845e350fa6609ea7289a012f76da","qualityScore":42}');
