INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dcep93/firegame/s_catann', 's_catann', 'dcep93', 'firegame', 'community', 's_catann dcep93 firegame community s_catann is a skill that enhances AI agent responses by prepending codex objects and including screenshots. It benefits developers by providing a standardized output format. s_catann 是一个高效的开发工具，提供开发服务器设置和测试输出的处理。它可以预置 { codex: { ... } } 对象，并包含截图作为最终响应的一部分。 s_catann は開発サーバーの設定とテスト出力を処理する効率的な開発ツールです。{ codex: { ... } } オブジェクトをプレフィックスに追加し、スクリーンショットを最終的な応答の一部として含めることができます。 s_catann은 개발 서버 설정 및 테스트 출력 처리를 제공하는 효율적인 개발 도구입니다. { codex: { ... } } 개체를 프리픽스로 추가하고 스크린샷을 최종 응답의 일부로 포함할 수 있습니다. s_catann es una habilidad que permite a los desarrolladores implementar un servidor de desarrollo y gestionar salidas de prueba de forma eficiente s_catann est une compétence qui permet aux développeurs de mettre en place un serveur de développement et de gérer les sorties de test de manière efficace s_catann ist eine Fähigkeit, die es Entwicklern ermöglicht, einen Entwicklungsserver zu implementieren und Testausgaben effizient zu verwalten O s_catann é uma ferramenta que permite a inicialização de um servidor de desenvolvimento e a renderização de saídas com ANSI. Aprenda a configurá-lo para desenvolvedores. S_catann - это инструмент, позволяющий запустить сервер разработки и отрисовать вывод с ANSI. Узнайте, как его настроить для разработчиков. s_catann هو أداة تمكن من تشغيل خادم التطوير وتصيير الإخراج مع ANSI. تعلم كيفية إعداده للمطورين. how to use s_catann what is s_catann s_catann setup guide s_catann alternative s_catann vs other AI skills s_catann install s_catann tutorial s_catann documentation s_catann for AI agents s_catann 开发服务器设置 测试输出处理 AI开发工具 开发流程优化 测试输出优化 Prepends { codex: { ... } } object to final responses Renders human-readable output by removing ANSI color codes Includes screenshots as the first visual part of the final response Supports inclusion of full test_catann.sh output in final responses Starts the dev server for testing and development purposes Handles test output and screenshots even in cases of test failure s_catann is a technical skill that automates the process of formatting AI agent responses, including the removal of ANSI color codes and the inclusion of visual elements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('lastmjs/jordan_michael_last/episode-generate-cover-art', 'community', 'lastmjs', 'jordan_michael_last', 'lastmjs/jordan_michael_last', 'episode-generate-cover-art', 0, 0, 42, '2026-03-05T04:30:53Z', '2026-03-07T04:19:56.927Z', 'cf8a30fdc2d9ecb61ddd96ce9f0d8fc26f892fd64f43d2504564efa04b24b9d6', '{"id":"lastmjs/jordan_michael_last/episode-generate-cover-art","name":"episode-generate-cover-art","description":{"en":"The episode-generate-cover-art skill generates cover art for episodes by leveraging the ElevenLabs API. It benefits developers and content creators by automating the cover art generation process","zh":"episode-generate-cover-art AI エージェント用于生成播客封面艺术，需要 ElevenLabs API 密钥和特定的文件结构","ja":"episode-generate-cover-art AIエージェントは、ポッドキャストのカバーアートを生成するために、ElevenLabs API キーと特定のファイル構造が必要です","ko":"episode-generate-cover-art AI 에이전트는 팟캐스트 커버 아트를 생성하기 위해 ElevenLabs API 키와 특정 파일 구조가 필요합니다","es":"El generador de arte de portada de episodio crea arte de portada personalizado para episodios utilizando ElevenLabs API. Requiere un número de episodio y un archivo de metadatos","fr":"Le générateur d''art de couverture d''épisode crée des artworks de couverture sur mesure pour les épisodes à l''aide de ElevenLabs API. Nécessite un numéro d''épisode et un fichier de métadonnées","de":"Der Episoden-Cover-Art-Generator erstellt individuelles Cover-Art für Episoden mithilfe von ElevenLabs API. Benötigt eine Episodennummer und eine Metadatendatei","pt":"O episode-generate-cover-art é uma habilidade que gera arte de capa para episódios com base em metadados, utilizando a API ElevenLabs para processamento de imagens","ru":"episode-generate-cover-art - это навык, который генерирует обложки для эпизодов на основе метаданных, используя API ElevenLabs для обработки изображений","ar":"episode-generate-cover-art هو مهارة ت动生成 غلاف لملفات الفيديو بالاعتماد على البيانات الوصفية، باستخدام واجهة برمجة تطبيقات ElevenLabs لمعالجة الصور"},"seo":{"title":{"en":"episode-generate-cover-art: Automated Cover Art Generatio...","zh":"AIエージェント：episode-generate-cover-art 设置指南","ja":"AIエージェント：episode-generate-cover-art 導入ガイド","ko":"AI 에이전트: episode-generate-cover-art 설정 가이드","es":"Generador de arte de portada de episodio: Guía de configu...","fr":"Générateur d''art de couverture d''épisode: Meilleures prat...","de":"Episoden-Cover-Art-Generator: Einrichtungsanleitung","pt":"Guia de Configuração do episode-generate-cover-art para D...","ru":"Настройка episode-generate-cover-art: Руководство для Раз...","ar":"دليل إعداد episode-generate-cover-art للطورين"},"description":{"en":"Discover how to generate cover art for episodes using the episode-generate-cover-art skill. Learn how to set up and use this AI agent skill for automated cov...","zh":"了解如何使用 episode-generate-cover-art AI エージェント生成播客封面艺术，包括设置步骤和技术要求","ja":"episode-generate-cover-art AIエージェントを使用してポッドキャストのカバーアートを生成する方法について説明します","ko":"episode-generate-cover-art AI 에이전트를 사용하여 팟캐스트 커버 아트를 생성하는 방법에 대해 알아보세요","es":"Aprenda a configurar el generador de arte de portada de episodio con ElevenLabs API y descubra cómo crear arte de portada personalizado","fr":"Découvrez comment configurer le générateur d''art de couverture d''épisode avec ElevenLabs API et créez des artworks de couverture sur mesure","de":"Erfahren Sie, wie Sie den Episoden-Cover-Art-Generator mit ElevenLabs API einrichten und individuelles Cover-Art erstellen","pt":"Aprenda a configurar o episode-generate-cover-art com nossa guia passo a passo, incluindo integração com a API ElevenLabs e gerenciamento de metadados","ru":"Узнайте, как настроить episode-generate-cover-art с нашей пошаговой инструкцией, включая интеграцию с API ElevenLabs и управление метаданными","ar":"تعرف على كيفية إعداد episode-generate-cover-art بخطوات بسيطة، بما في ذلك التكامل مع واجهة برمجة تطبيقات ElevenLabs وإدارة البيانات الوصفية"},"definition":{"en":"episode-generate-cover-art is a skill that automatically generates cover art for episodes by utilizing input parameters such as episode number and metadata","zh":"episode-generate-cover-art 是一种 AI エージェント，用于生成播客封面艺术","ja":"episode-generate-cover-art は、ポッドキャストのカバーアートを生成する AI エージェントです","ko":"episode-generate-cover-art는 팟캐스트 커버 아트를 생성하는 AI 에이전트입니다","es":"El generador de arte de portada de episodio es una herramienta que crea arte de portada personalizado para episodios","fr":"Le générateur d''art de couverture d''épisode est un outil qui crée des artworks de couverture sur mesure pour les épisodes","de":"Der Episoden-Cover-Art-Generator ist ein Tool, das individuelles Cover-Art für Episoden erstellt","pt":"O que é episode-generate-cover-art? É uma habilidade de IA que gera arte de capa automática para episódios","ru":"Что такое episode-generate-cover-art? Это навык ИИ, который генерирует автоматические обложки для эпизодов","ar":"ما هي episode-generate-cover-art؟ هي مهارة ذكاء اصطناعي لتوليد غلاف آلي لملفات الفيديو"},"features":{"en":["Generates cover art images in PNG format","Creates cover art prompt text files","Supports debugging through request/response artifacts","Utilizes the ElevenLabs API for cover art generation","Requires EPISODE_NUMBER and metadata.json as input parameters","Supports environment variables for API key configuration"],"zh":["支持 ElevenLabs API","生成 cover_art.png 和 cover_art_prompt.txt 文件","需要特定的文件结构（episodes/<EPISODE_NUMBER>/metadata.json）","支持调试模式（episodes/<N>/cover_art_debug/<RUN_ID>/...）","需要 EPISODE_NUMBER 参数","支持环境变量（ELEVEN_LABS_API_KEY 或 ELEVENLABS_API_KEY）"],"ja":["ElevenLabs API をサポート","cover_art.png と cover_art_prompt.txt ファイルを生成","特定のファイル構造（episodes/<EPISODE_NUMBER>/metadata.json）を必要とします","デバッグモード（episodes/<N>/cover_art_debug/<RUN_ID>/...）をサポート","EPISODE_NUMBER パラメータを必要とします","環境変数（ELEVEN_LABS_API_KEY または ELEVENLABS_API_KEY）をサポート"],"ko":["ElevenLabs API 지원","cover_art.png 및 cover_art_prompt.txt 파일 생성","특정 파일 구조（episodes/<EPISODE_NUMBER>/metadata.json） 필요","디버깅 모드（episodes/<N>/cover_art_debug/<RUN_ID>/...） 지원","EPISODE_NUMBER 매개변수 필요","환경 변수（ELEVEN_LABS_API_KEY 또는 ELEVENLABS_API_KEY） 지원"],"es":["Utiliza ElevenLabs API para generar arte de portada","Requiere un número de episodio y un archivo de metadatos","Crea arte de portada personalizado en formato PNG","Almacena arte de portada y archivos de depuración en directorios específicos","Soporta variables de entorno para la clave de API de ElevenLabs","Ejecuta comandos CLI para generar arte de portada"],"fr":["Utilise ElevenLabs API pour générer des artworks de couverture","Nécessite un numéro d''épisode et un fichier de métadonnées","Crée des artworks de couverture sur mesure au format PNG","Stocke les artworks de couverture et les fichiers de débogage dans des répertoires spécifiques","Prend en charge les variables d''environnement pour la clé d''API d''ElevenLabs","Exécute des commandes CLI pour générer des artworks de couverture"],"de":["Verwendet ElevenLabs API zum Erstellen von Cover-Art","Benötigt eine Episodennummer und eine Metadatendatei","Erstellt individuelles Cover-Art im PNG-Format","Speichert Cover-Art und Debug-Dateien in spezifischen Verzeichnissen","Unterstützt Umgebungsvariablen für den ElevenLabs API-Schlüssel","Führt CLI-Befehle aus, um Cover-Art zu erstellen"],"pt":["Geração de arte de capa automática com base em metadados","Integração com a API ElevenLabs para processamento de imagens","Suporte a gerenciamento de metadados em formato JSON","Geração de artefatos de depuração para análise de erros","Compatibilidade com linha de comando para execução automática"],"ru":["Автоматическая генерация обложек на основе метаданных","Интеграция с API ElevenLabs для обработки изображений","Поддержка управления метаданными в формате JSON","Генерация артефактов отладки для анализа ошибок","Совместимость с командной строкой для автоматического выполнения"],"ar":["توليد غلاف آلي بالاعتماد على البيانات الوصفية","التكامل مع واجهة برمجة تطبيقات ElevenLabs لمعالجة الصور","دعم إدارة البيانات الوصفية بформات JSON","توليد مكونات فحص للأخطاء","التوافق مع سطر الأوامر للتشغيل الآلي"]},"keywords":{"en":["how to use episode-generate-cover-art","episode-generate-cover-art setup guide","automated cover art generation","ElevenLabs API integration","episode-generate-cover-art alternative","episode-generate-cover-art vs manual cover art creation","episode-generate-cover-art install","what is episode-generate-cover-art","episode-generate-cover-art tutorial"],"zh":["AI 에ージェнт","episode-generate-cover-art","ElevenLabs API","播客封面艺术","文件结构","环境变量","调试模式"],"ja":["AI エージェント","episode-generate-cover-art","ElevenLabs API","ポッドキャスト カバーアート","ファイル構造","環境変数","デバッグモード"],"ko":["AI 에이전트","episode-generate-cover-art","ElevenLabs API","팟캐스트 커버 아트","파일 구조","환경 변수","디버깅 모드"],"es":["generador de arte de portada de episodio","ElevenLabs API","arte de portada personalizado","episodio","CLI","variables de entorno","API key","Herramientas de AI para desarrolladores","Generación de arte de portada automática"],"fr":["générateur d''art de couverture d''épisode","ElevenLabs API","artworks de couverture sur mesure","épisode","CLI","variables d''environnement","clé d''API","Outils d''IA pour les développeurs","Génération automatique d''artworks de couverture"],"de":["Episoden-Cover-Art-Generator","ElevenLabs API","individuelles Cover-Art","Episoden","CLI","Umgebungsvariablen","API-Schlüssel","AI-Tools für Entwickler","Automatische Cover-Art-Erstellung"],"pt":["episode-generate-cover-art","geração de arte de capa","API ElevenLabs","metadados","JSON","linha de comando","desenvolvimento de software","IA","ferramentas de desenvolvimento"],"ru":["episode-generate-cover-art","генерация обложек","API ElevenLabs","метаданные","JSON","командная строка","разработка программного обеспечения","ИИ","инструменты разработки"],"ar":["episode-generate-cover-art","توليد غلاف","واجهة برمجة تطبيقات ElevenLabs","بيانات وصفية","JSON","سطر الأوامر","تطوير البرمجيات","الذكاء الاصطناعي","أدوات التطوير"]}},"owner":"lastmjs","repo":"jordan_michael_last","repoPath":"lastmjs/jordan_michael_last","stars":0,"forks":0,"updatedAt":"2026-03-05T04:30:53Z","topics":[],"category":"community","skillMd":{"name":"episode-generate-cover-art","description":"Generate podcast episode cover art from episodes/<N>/metadata.json using ElevenLabs image generation and save it to the episode directory.","bodyPreview":"Inputs:\n\n- `EPISODE_NUMBER`: Episode folder number (directory: `episodes/<EPISODE_NUMBER>`)\n\nOutput files:\n\n- `episodes/<N>/cover_art.png`\n- `episodes/<N>/cover_art_prompt.txt`\n- `episodes/<N>/cover_art_debug/<RUN_ID>/...` (request/response/debug artifacts)\n\n1. Ensure `EPISODE_NUMBER` is provided.\n2. Ensure `episodes/${EPISODE_NUMBER}/metadata.json` exists.\n3. Ensure ElevenLabs API key is present in env:\n    - `ELEVEN_LABS_API_KEY`, or\n    - `ELEVENLABS_API_KEY`\n4. Run:\n   `./.agents/skills/epis","body":"Inputs:\n\n- `EPISODE_NUMBER`: Episode folder number (directory: `episodes/<EPISODE_NUMBER>`)\n\nOutput files:\n\n- `episodes/<N>/cover_art.png`\n- `episodes/<N>/cover_art_prompt.txt`\n- `episodes/<N>/cover_art_debug/<RUN_ID>/...` (request/response/debug artifacts)\n\n1. Ensure `EPISODE_NUMBER` is provided.\n2. Ensure `episodes/${EPISODE_NUMBER}/metadata.json` exists.\n3. Ensure ElevenLabs API key is present in env:\n    - `ELEVEN_LABS_API_KEY`, or\n    - `ELEVENLABS_API_KEY`\n4. Run:\n   `./.agents/skills/episode-generate-cover-art/scripts/generate_cover_art_elevenlabs.sh --episode-dir \"episodes/${EPISODE_NUMBER}\"`\n\nBehavior guarantees:\n\n- Uses ElevenLabs API endpoints only.\n- Prompt format is exact:\n    - `Create cover art for the following podcast episode based on this metadata: `\n    - followed by raw `metadata.json` content.\n- Input source is `episodes/<N>/metadata.json`.\n- Discovers/ranks nano-banana model candidates (from `/v1/models` when available), then falls back through nano-banana aliases.\n- Tries multiple endpoint and payload-schema variants for API compatibility.\n- Parses image response from:\n    - binary image body,\n    - JSON URL payload,\n    - JSON/base64 payload.\n- Rejects invalid outputs and retries fallbacks:\n    - non-image content,\n    - tiny files,\n    - too-small dimensions,\n    - low-variance placeholder-like outputs.\n\nDebug artifacts:\n\n- Every request/response attempt is written into `episodes/<N>/cover_art_debug/<RUN_ID>/`.\n- Final selected endpoint/model/output metadata is written to:\n    - `episodes/<N>/cover_art_debug/<RUN_ID>/final_selection.txt`\n\nValidation:\n\n- `cover_art.png` must be non-empty and image-readable.\n- Final output dimensions and file size are printed by the script.\n- For batch verification across episodes:\n\n```bash\nfor n in 3 4 5; do\n  ./.agents/skills/episode-generate-cover-art/scripts/generate_cover_art_elevenlabs.sh --episode-dir \"episodes/$n\"\ndone\n```\n\n- Fail the run if any episode fails to produce valid cover art.\n"},"lastSynced":"2026-03-07T04:19:56.927Z","agentAnalysis":{"suitability":{"en":"Perfect for Media Agents needing automated cover art generation for episode content using the ElevenLabs API.","zh":"非常适合需要使用ElevenLabs API自动为剧集内容生成封面艺术的媒体代理。","ja":"ElevenLabs APIを使用してエピソードコンテンツの自動カバーアート生成が必要なメディアエージェントに最適です。","ko":"ElevenLabs API를 사용하여 에피소드 콘텐츠의 자동 커버 아트 생성이 필요한 미디어 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Medios que necesitan generación automática de arte de portada para contenido de episodios utilizando la ElevenLabs API.","fr":"Parfait pour les agents de médias ayant besoin de génération automatique d''images de couverture pour le contenu d''épisodes en utilisant l''ElevenLabs API.","de":"Perfekt für Media-Agenten, die automatisierte Erstellung von Cover-Art für Episodeninhalte mit der ElevenLabs API benötigen.","pt":"Perfeito para Agentes de Mídia que precisam de geração automática de arte de capa para conteúdo de episódios usando a ElevenLabs API.","ru":"Идеально подходит для Медийных Агентов, которым требуется автоматизированное создание обложек для контента эпизодов с использованием ElevenLabs API.","ar":"مثالي للوكلاء الإعلاميين الذين يحتاجون إلى إنشاء فن الغلاف التلقائي لمحتوى الحلقات باستخدام ElevenLabs API."},"recommendation":{"en":"Empowers agents to generate cover art in PNG format by leveraging the ElevenLabs API, utilizing environment variables for API key management, and creating debug artifacts for troubleshooting purposes.","zh":"通过利用ElevenLabs API、使用环境变量管理API密钥以及为故障排除目的创建调试工件，赋予代理生成PNG格式封面艺术的能力。","ja":"ElevenLabs APIを利用し、環境変数を使用してAPIキーを管理し、トラブルシューティングのためにデバッグアーティファクトを作成することで、エージェントがPNG形式のカバーアートを生成できるようにします。","ko":"ElevenLabs API를 활용하고 환경 변수를 사용하여 API 키를 관리하며 디버깅을 위해 디버그 아티팩트를 생성함으로써 에이전트가 PNG 형식의 커버 아트를 생성할 수 있도록 합니다.","es":"Habilita a los agentes a generar arte de portada en formato PNG mediante la utilización de la ElevenLabs API, la utilización de variables de entorno para la gestión de claves de API y la creación de artefactos de depuración para fines de solución de problemas.","fr":"Permet aux agents de générer des images de couverture au format PNG en exploitant l''ElevenLabs API, en utilisant des variables d''environnement pour la gestion des clés d''API et en créant des artefacts de débogage à des fins de dépannage.","de":"Ermöglicht es Agenten, Cover-Art im PNG-Format zu generieren, indem sie die ElevenLabs API nutzen, Umgebungsvariablen für die API-Schlüsselverwaltung verwenden und Debug-Artefakte für Fehlerbehebungszwecke erstellen.","pt":"Habilita os agentes a gerar arte de capa no formato PNG, aproveitando a ElevenLabs API, utilizando variáveis de ambiente para gerenciamento de chaves de API e criando artefatos de depuração para fins de solução de problemas.","ru":"Наделяет агентов возможностью генерировать обложки в формате PNG, используя ElevenLabs API, переменные окружения для управления ключами API и создавая отладочные артефакты для целей отладки.","ar":"يمنح الوكلاء القدرة على إنشاء فن ال