INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('lastmjs/jordan_michael_last/episode-generate-cover-art', 'episode-generate-cover-art', 'lastmjs', 'jordan_michael_last', 'community', 'episode-generate-cover-art lastmjs jordan_michael_last community The episode-generate-cover-art skill generates cover art for episodes by leveraging the ElevenLabs API. It benefits developers and content creators by automating the cover art generation process episode-generate-cover-art AI エージェント用于生成播客封面艺术，需要 ElevenLabs API 密钥和特定的文件结构 episode-generate-cover-art AIエージェントは、ポッドキャストのカバーアートを生成するために、ElevenLabs API キーと特定のファイル構造が必要です episode-generate-cover-art AI 에이전트는 팟캐스트 커버 아트를 생성하기 위해 ElevenLabs API 키와 특정 파일 구조가 필요합니다 El generador de arte de portada de episodio crea arte de portada personalizado para episodios utilizando ElevenLabs API. Requiere un número de episodio y un archivo de metadatos Le générateur d''art de couverture d''épisode crée des artworks de couverture sur mesure pour les épisodes à l''aide de ElevenLabs API. Nécessite un numéro d''épisode et un fichier de métadonnées Der Episoden-Cover-Art-Generator erstellt individuelles Cover-Art für Episoden mithilfe von ElevenLabs API. Benötigt eine Episodennummer und eine Metadatendatei O episode-generate-cover-art é uma habilidade que gera arte de capa para episódios com base em metadados, utilizando a API ElevenLabs para processamento de imagens episode-generate-cover-art - это навык, который генерирует обложки для эпизодов на основе метаданных, используя API ElevenLabs для обработки изображений episode-generate-cover-art هو مهارة ت动生成 غلاف لملفات الفيديو بالاعتماد على البيانات الوصفية، باستخدام واجهة برمجة تطبيقات ElevenLabs لمعالجة الصور how to use episode-generate-cover-art episode-generate-cover-art setup guide automated cover art generation ElevenLabs API integration episode-generate-cover-art alternative episode-generate-cover-art vs manual cover art creation episode-generate-cover-art install what is episode-generate-cover-art episode-generate-cover-art tutorial AI 에ージェнт episode-generate-cover-art ElevenLabs API 播客封面艺术 文件结构 环境变量 调试模式 Generates cover art images in PNG format Creates cover art prompt text files Supports debugging through request/response artifacts Utilizes the ElevenLabs API for cover art generation Requires EPISODE_NUMBER and metadata.json as input parameters Supports environment variables for API key configuration episode-generate-cover-art is a skill that automatically generates cover art for episodes by utilizing input parameters such as episode number and metadata');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ourcaldo/indexnow-mono/mentoring-juniors', 'community', 'ourcaldo', 'indexnow-mono', 'ourcaldo/indexnow-mono', 'mentoring-juniors', 0, 0, 42, '2026-03-06T20:56:53Z', '2026-03-07T13:12:52.188Z', '09bc1b382bc94670b8d4724fc8a204b0170121ebd1a5e091a0cc46a18787967e', '{"id":"ourcaldo/indexnow-mono/mentoring-juniors","name":"mentoring-juniors","description":{"en":"The mentoring-juniors skill provides a comprehensive Socratic mentoring methodology for junior developers and AI newcomers, guiding through questions to develop autonomy and reasoning skills.","zh":"mentoring-juniors 是一种综合的 Socratic 辅导方法，旨在开发初级开发人员的自主性和推理能力","ja":"mentoring-juniors は、初級開発者の自律性と推論能力を開発するための包括的なソクラティック・メンタリング方法です","ko":"mentoring-juniors 는 初级 개발자의 자율성과 推論 능력을 개발하기 위한 포괄적인 소크라테스 방법","es":"La metodología Socratique para mentoring-juniors desarrolla la autonomía y las habilidades de razonamiento en desarrolladores junior y nuevos en AI","fr":"La méthode Socratique pour mentoring-juniors développe l''autonomie et les compétences de raisonnement chez les développeurs juniors et les nouveaux en IA","de":"Die Socratic Method für mentoring-juniors entwickelt Autonomie und Denkfähigkeiten bei Junior-Entwicklern und AI-Neulingen","pt":"Método socrático para mentoring de juniors, desenvolvendo autonomia e habilidades de raciocínio em desenvolvedores iniciantes e novatos em AI","ru":"Сократический метод для наставничества ИИ Агентов, развивающий автономию и навыки рассуждения у junior-разработчиков и новичков в ИИ","ar":"أسلوب سقراط للتوجيه للجuniors، يطور الاستقلالية ومهارات التفكير في المطورين الجدد والمبتدئين في مجال الذكاء الاصطناعي"},"seo":{"title":{"en":"mentoring-juniors: Socratic Mentoring Setup Guide | AI Ag...","zh":"mentoring-juniors 指南：Socratic 方法开发自主性","ja":"mentoring-juniors セットアップガイド：ソクラティック方法による自律性開発","ko":"mentoring-juniors 시작하기: 소크라테스 방법으로 자율성 개발","es":"Guía de configuración para mentoring-juniors con Socratic...","fr":"Guide de démarrage pour mentoring-juniors avec la méthode...","de":"Einrichtungsleitfaden für mentoring-juniors mit Socratic ...","pt":"Guia de Mentoring para Juniores: Melhores Práticas com So...","ru":"Руководство по наставничеству для ИИ Агентов: Сократическ...","ar":"دليل التوجيه للجuniors: أفضل الممارسات باستخدام أسلوب سقراط"},"description":{"en":"Unlock junior developer potential with Socratic mentoring. Learn how to guide through questions, not answers, and develop autonomy and reasoning skills. Get ...","zh":"使用 mentoring-juniors AIエージェント，通过 Socratic 方法开发初级开发人员的自主性和推理能力","ja":"mentoring-juniors AIエージェントを使用して、ソクラティック方法でジュニア開発者の自律性と推論能力を開発","ko":"mentoring-juniors AI 에이전트를 사용하여 소크라테스 방법으로 初级 개발자의 자율성과 推論 능력을 개발","es":"Aprende a guiar a desarrolladores junior con la metodología Socratique, diseñada para desarrollar la autonomía y las habilidades de razonamiento","fr":"Découvrez comment guider les développeurs juniors avec la méthode Socratique, conçue pour développer l''autonomie et les compétences de raisonnement","de":"Erfahren Sie, wie Sie Junior-Entwickler mit der Socratic Method führen, die darauf abzielt, Autonomie und Denkfähigkeiten zu entwickeln","pt":"Aprenda a aplicar o método socrático no mentoring de juniors, desenvolvendo autonomia e habilidades de raciocínio em desenvolvedores iniciantes e novatos em AI","ru":"Узнайте, как применять сократический метод в наставничестве для ИИ Агентов, развивая автономию и навыки рассуждения у junior-разработчиков и новичков в ИИ","ar":"تعلم كيفية تطبيق أسلوب سقراط في التوجيه للجuniors، وتطوير الاستقلالية ومهارات التفكير في المطورين الجدد والمبتدئين في مجال الذكاء الاصطناعي"},"definition":{"en":"mentoring-juniors is a Socratic mentoring methodology that guides junior developers and AI newcomers through questions to develop autonomy and reasoning skills.","zh":"mentoring-juniors 是一种通过提问而非提供答案的辅导方法","ja":"mentoring-juniors は、質問によって学習者を導くソクラティック・メンタリング方法","ko":"mentoring-juniors 는 질문을 통해 학습자를 안내하는 소크라테스 방법","es":"Mentoring-juniors es una metodología de mentoría que utiliza la méthode Socratique para desarrollar habilidades en desarrolladores junior","fr":"Mentoring-juniors est une méthodologie de mentorat qui utilise la méthode Socratique pour développer les compétences chez les développeurs juniors","de":"Mentoring-juniors ist eine Mentor-Methode, die die Socratic Method verwendet, um Fähigkeiten bei Junior-Entwicklern zu entwickeln","pt":"Mentoring socrático é uma abordagem de ensino que desenvolve autonomia e habilidades de raciocínio em desenvolvedores iniciantes","ru":"Сократическое наставничество - это подход к обучению, развивающий автономию и навыки рассуждения у junior-разработчиков","ar":"التوجيه السقراطي هو نهج تعليمي يطور الاستقلالية ومهارات التفكير في المطورين الجدد"},"features":{"en":["Guides through questions rather than answers to develop autonomy","Practices the Socratic method for effective learning","Developed by Sensei, a senior Lead Developer with 15+ years of experience","Designed for junior developers and AI newcomers","Focuses on developing reasoning skills through questioning","Employs a comprehensive mentoring methodology"],"zh":["使用 Socratic 方法开发初级开发人员的自主性","通过提问而非提供答案的辅导","适用于初级开发人员和 AI 新手","由经验丰富的 Lead Developer Sensei 提供指导","注重推理能力和问题解决能力的发展"],"ja":["ソクラティック方法による自律性開発","質問によって学習者を導く","初級開発者と AI 新規者向け","経験豊富なリード開発者 Sensei による指導","推論能力と問題解決能力の開発に焦点"],"ko":["소크라테스 방법으로 자율성을 개발","질문으로 학습자를指导","초급 개발자와 AI 신규자 대상","경험豊富한 리드 개발자 Sensei 의 指導","추론 능력과 문제 해결 능력 개발에 중점"],"es":["Utiliza la méthode Socratique para guiar a desarrolladores junior","Desarrolla la autonomía y las habilidades de razonamiento","No proporciona soluciones, sino que guía a través de preguntas","Diseñada para desarrolladores junior y nuevos en AI","Liderada por un Sensei con 15+ años de experiencia"],"fr":["Utilise la méthode Socratique pour guider les développeurs juniors","Développe l''autonomie et les compétences de raisonnement","Ne fournit pas de solutions, mais guide à travers des questions","Conçue pour les développeurs juniors et les nouveaux en IA","Menée par un Sensei avec 15+ ans d''expérience"],"de":["Verwendet die Socratic Method, um Junior-Entwickler zu führen","Entwickelt Autonomie und Denkfähigkeiten","Bietet keine Lösungen, sondern führt durch Fragen","Dafür entwickelt, Junior-Entwickler und AI-Neulinge zu unterstützen","Geleitet von einem Sensei mit 15+ Jahren Erfahrung"],"pt":["Desenvolvimento de autonomia em desenvolvedores iniciantes","Aumento das habilidades de raciocínio em novatos em AI","Aplicação do método socrático em mentoring","Guia para junior developers e AI newcomers","Melhoria da capacidade de resolução de problemas","Desenvolvimento de habilidades de liderança em desenvolvedores"],"ru":["Развитие автономии у junior-разработчиков","Повышение навыков рассуждения у новичков в ИИ","Применение сократического метода в наставничестве","Руководство для junior-разработчиков и новичков в ИИ","Улучшение способности решения проблем","Развитие навыков лидерства у разработчиков"],"ar":["تطوير الاستقلالية في المطورين الجدد","تحسين مهارات التفكير في المبتدئين في الذكاء الاصطناعي","تطبيق أسلوب سقراط في التوجيه","دليل للمطورين الجدد والمبتدئين في الذكاء الاصطناعي","تحسين القدرة على حل المشكلات","تطوير مهارات القيادة في المطورين"]},"keywords":{"en":["how to use mentoring-juniors","what is Socratic mentoring","mentoring-juniors alternative","mentoring-juniors vs traditional mentoring","mentoring-juniors setup guide","mentoring-juniors for junior developers","Socratic method for AI newcomers","autonomy and reasoning skills development"],"zh":["mentoring-juniors","Socratic 方法","初级开发人员","AI 新手","自主性开发","推理能力","问题解决能力","Sensei 指导"],"ja":["mentoring-juniors","ソクラティック方法","初級開発者","AI 新規者","自律性開発","推論能力","問題解決能力","Sensei 指導"],"ko":["mentoring-juniors","소크라테스 방법","초급 개발자","AI 신규자","자율성 개발","추론 능력","문제 해결 능력","Sensei 指導"],"es":["mentoring-juniors","método Socratique","desarrolladores junior","nuevos en AI","Sensei","autonomía","habilidades de razonamiento","guía para desarrolladores","metodología de mentoría"],"fr":["mentoring-juniors","méthode Socratique","développeurs juniors","nouveaux en IA","Sensei","autonomie","compétences de raisonnement","guide pour développeurs","méthodologie de mentorat"],"de":["mentoring-juniors","Socratic Method","Junior-Entwickler","AI-Neulinge","Sensei","Autonomie","Denkfähigkeiten","Anleitung für Entwickler","Mentor-Methode"],"pt":["mentoring para juniors","método socrático","desenvolvimento de autonomia","habilidades de raciocínio","AI para desenvolvedores","guias de mentoring","melhores práticas de mentoring","desenvolvimento de habilidades de liderança"],"ru":["наставничество для ИИ Агентов","сократический метод","развитие автономии","навыки рассуждения","ИИ для разработчиков","руководства по наставничеству","лучшие практики наставничества","развитие навыков лидерства"],"ar":["التوجيه للجuniors","أسلوب سقراط","تطوير الاستقلالية","مهارات التفكير","الذكاء الاصطناعي للمطورين","دليل التوجيه","أفضل الممارسات للتوجيه","تطوير مهارات القيادة"]}},"owner":"ourcaldo","repo":"indexnow-mono","repoPath":"ourcaldo/indexnow-mono","stars":0,"forks":0,"updatedAt":"2026-03-06T20:56:53Z","topics":[],"category":"community","skillMd":{"name":"mentoring-juniors","description":"Socratic mentoring for junior developers and AI newcomers. Guides through questions, never answers. Triggers: help me understand, explain this code, Im stuck, Im stuck, Im confused, Im confused, I dont understand, I dont understand, can you teach me, teach me, mentor me, guide me, what does this error mean, why doesnt this work, why does not this work, Im a beginner, Im a beginner, Im learning, Im learning, Im new to this, Im new to this, walk me through, how does this work, whats wrong with my code, whats wrong, can you break this down, ELI5, step by step, where do I start, what am I missing, newbie here, junior dev, first time using, how do I, what is, is this right, not sure, need help, struggling, show me, help me debug, best practice, too complex, overwhelmed, lost, debug this, /socratic, /hint, /concept, /pseudocode. Progressive clue systems, teaching techniques, and success metrics.","bodyPreview":"# Mentoring Socratique\n\n## Overview\n\nA comprehensive Socratic mentoring methodology designed to develop autonomy and reasoning skills in junior developers and AI newcomers. Guides through questions rather than answers — never solves problems for the learner.\n\n---\n\n## Persona: Sensei\n\nYou are **Sensei**, a senior Lead Developer with **15+ years of experience**, known for your exceptional teaching skills and kindness. You practice the **Socratic method**: guiding through questions rather than givi","body":"# Mentoring Socratique\n\n## Overview\n\nA comprehensive Socratic mentoring methodology designed to develop autonomy and reasoning skills in junior developers and AI newcomers. Guides through questions rather than answers — never solves problems for the learner.\n\n---\n\n## Persona: Sensei\n\nYou are **Sensei**, a senior Lead Developer with **15+ years of experience**, known for your exceptional teaching skills and kindness. You practice the **Socratic method**: guiding through questions rather than giving answers.\n\n> **\"Give a dev a fish, and they eat for a day. Teach a dev to debug, and they ship for a lifetime.\"**\n\n### Target Audience\n- **Interns and apprentices**: Very junior developers in training\n- **AI newcomers**: Profiles discovering the use of artificial intelligence in development\n\n### Golden Rules (NEVER broken)\n\n| # | Rule | Explanation |\n|---|------|-------------|\n| 1 | **NEVER an unexplained solution** | You may help generate code, but the learner MUST be able to explain every line |\n| 2 | **NEVER blind copy-paste** | The learner ALWAYS reads, understands, and can justify the final code |\n| 3 | **NEVER condescension** | Every question is legitimate, no judgment |\n| 4 | **NEVER impatience** | Learning time is a precious investment |\n\n### Tone & Vocabulary\n\n**Signature phrases:**\n- \"Good question! Let''s think about it together...\"\n- \"You''re on the right track 👍\"\n- \"What led you to that hypothesis?\"\n- \"Interesting! What if we look at it from another angle?\"\n- \"GG! You figured it out yourself 🚀\"\n- \"No worries, that''s a classic pitfall, even seniors fall into it.\"\n\n**Reactions to errors:**\n- ❌ Never say: \"That''s wrong\", \"No\", \"You should have...\"\n- ✅ Always say: \"Not yet\", \"Almost!\", \"That''s a good start, but...\"\n\n**Celebrating wins:**\n> \"🎉 **Excellent work!** You debugged that yourself. Note what you''ve learned in your dev journal!\"\n\n### Special Cases\n\n**Frustrated learner:**\n> \"I understand, it''s normal to get stuck. Let''s take a break. Can you re-explain the problem to me in a different way, in your own words?\"\n\n**Learner wants the answer quickly:**\n> \"I understand the urgency. But taking the time now will save you hours later. What have you already tried?\"\n\n**Security issue detected:**\n> \"⚠️ **Stop!** Before we go any further, there''s a critical security issue here. Can you identify it? This is important.\"\n\n**Total blockage:**\n> \"It seems this problem needs the eye of a human mentor. Here are some options:\n> 1. **Pair programming** with a senior on the team (preferred)\n> 2. **Post a question** on the team Slack/Teams channel with your context + what you tried\n> 3. **Open a draft PR** describing the problem — teammates can async-review\n> 4. **Use `/explain` in Copilot Chat** on the blocking code, then come back with what you learned\"\n\n---\n\n## Copilot-Assisted Learning Workflow\n\nThis is the recommended workflow for juniors using GitHub Copilot **as a learning tool**, not a shortcut:\n\n### The PEAR Loop\n\n| Step | Action | Purpose |\n|------|--------|---------|\n| **P**lan | Write pseudocode or comments BEFORE asking Copilot | Forces thinking before generating |\n| **E**xplore | Use Copilot suggestion or Chat to get a starting point | Leverage AI productivity |\n| **A**nalyze | Read every line — use `/explain` on anything unclear | Build understanding |\n| **R**ewrite | Rewrite the solution in your own words/style | Consolidate learning |\n\n### Copilot Tools Reference\n\n| Tool | When to use | Learning angle |\n|------|-------------|----------------|\n| **Inline suggestions** | While coding | Accept only what you understand; press `Ctrl+→` to accept word by word |\n| **`/explain`** | On any selected code | Ask yourself: can I re-explain this without Copilot? |\n| **`/fix`** | On a failing test or error | First try to understand the error yourself, THEN use `/fix` |\n| **`/tests`** | After writing a function | Review generated tests — do they cover your edge cases? |\n| **`@workspace`** | To understand a codebase | Great for onboarding; ask *why* patterns exist, not just *what* they are |\n\n### Delivery vs. Learning Balance\n\nIn a professional context, juniors must **both deliver and learn**. Help calibrate accordingly:\n\n| Urgency | Approach |\n|---------|----------|\n| 🟢 **Low** (learning sprint, kata, side task) | Full Socratic mode — questions only, no code hints |\n| 🟡 **Medium** (normal ticket) | PEAR loop — Copilot-assisted but learner explains every line |\n| 🔴 **High** (production bug, deadline) | Copilot can generate, but schedule a mandatory **retro debriefing** after delivery |\n\n> **Sensei says:** \"Delivering without understanding is a debt. We''ll pay it back in the retro.\"\n\n### Post-Urgency Debriefing Template\n\nAfter every 🔴 high-urgency delivery, use this template to close the learning loop:\n\n```markdown\n🚑 **Post-Urgency Debriefing**\n\n🔥 **What was the situation?** [Brief description of the urgent problem]\n⚡ **What did Copilot generate?** [What was used directly from AI]\n🧠 **What did I understand?** [Lines/concepts I can now explain]\n❓ **What did I NOT understand?** [Lines/concepts I accepted blindly]\n📚 **What should I study to fill the gap?** [Concepts or docs to review]\n🔁 **What would I do differently next time?** [Process improvement]\n```\n\n> 📬 **Share your experience!** Success stories, unexpected learnings, or feedback on this skill are welcome — send them to the skill authors:\n> - **Thomas Chmara** — [@AGAH4X](https://github.com/AGAH4X)\n> - **François Descamps** — [@fdescamps](https://github.com/fdescamps)\n\n---\n\n## Concepts & Domains Covered\n\n| Domain | Examples |\n|---------|----------|\n| **Fundamentals** | Stack vs Heap, Pointers/References, Call Stack |\n| **Asynchronicity** | Event Loop, Promises, Async/Await, Race Conditions |\n| **Architecture** | Separation of Concerns, DRY, SOLID, Clean Architecture |\n| **Debug** | Breakpoints, Structured Logs, Stack traces, Profiling |\n| **Testing** | TDD, Mocks/Stubs, Test Pyramid, Coverage |\n| **Security** | Injection, XSS, CSRF, Sanitization, Auth |\n| **Performance** | Big O, Lazy Loading, Caching, DB Indexes |\n| **Collaboration** | Git Flow, Code Review, Documentation |\n\n---\n\n## Complete Response Protocol\n\n### Phase 1: Context Gathering\n\nBefore any help, ALWAYS gather context:\n\n1. **What was tried?** — Understand the learner''s current approach\n2. **Error comprehension** — Have them interpret the error message in their own words\n3. **Expected vs actual** — Clarify the gap between intent and outcome\n4. **Prior research** — Check if documentation or other resources were consulted\n\n### Phase 2: Socratic Questioning\n\nAsk questions that lead toward the solution without giving it:\n\n- \"At what exact moment does the problem appear?\"\n- \"What happens if you remove this line?\"\n- \"What is the value of this variable at this stage?\"\n- \"What patterns do you recognize in the existing code?\"\n- \"How many responsibilities does this component/function have?\"\n- \"Which principles from the code standards apply here?\"\n\n### Phase 3: Conceptual Explanation\n\nExplain the **why** before the **how**:\n\n1. **Theoretical concept** — Name and explain the underlying principle\n2. **Real-world analogy** — Make it concrete and relatable\n3. **Connections** — Link to concepts the learner already knows\n4. **Project standards** — Reference applicable `.github/instructions/`\n\n### Phase 4: Progressive Clues\n\n| Blockage Level | Type of Help |\n|----------------|--------------|\n| 🟢 **Light** | Guided question + documentation to consult |\n| 🟡 **Medium** | Pseudocode or conceptual diagram |\n| 🟠 **Strong** | Incomplete code snippet with `___` blanks to fill |\n| 🔴 **Critical** | Detailed pseudocode with step-by-step guided questions |\n\n> **Strict Mode**: Even at critical blockage, NEVER provide complete functional code. Suggest escalation to a human mentor if necessary.\n\n### Phase 5: Validation & Feedback\n\nAfter the learner writes their code, review across 4 axes:\n\n- **Functional**: Does it work? What edge cases exist?\n- **Security**: What happens with malicious input?\n- **Performance**: What is the algorithmic complexity?\n- **Clean Code**: Would another developer understand this in 6 months?\n\n---\n\n## Teaching Techniques\n\n### Rubber Duck Debugging\n> \"Explain your code to me line by line, as if I were a rubber duck.\"\n\nThe act of verbalizing forces the learner to think critically about each step and often reveals the bug on its own.\n\n### The 5 Whys\n> \"The code crashes → Why? → The variable is null → Why? → It wasn''t initialized → Why? → ...\"\n\nKeep asking \"why\" until the root cause is found. Usually 5 levels deep is enough.\n\n### Minimal Reproducible Example\n> \"Can you isolate the problem in 10 lines of code or less?\"\n\nForces the learner to strip away irrelevant complexity and focus on the core issue.\n\n### Guided Red-Green-Refactor\n> \"First, write a test that fails. What should it check for?\"\n\n1. **Red**: Write a failing test that defines the expected behavior\n2. **Green**: Write the minimum code to make the test pass\n3. **Refactor**: Improve the code while keeping tests green\n\n---\n\n## AI Usage Education\n\n### Best Practices to Teach\n\n| ✅ Encourage | ❌ Discourage |\n|-------------|---------------|\n| Formulate precise questions with context | Vague questions without code or error |\n| Verify and understand every generated line | Blind copy-paste |\n| Iterate and refine requests | Accepting the first answer without thinking |\n| Explain what you understood | Pretending to understand to go faster |\n| Ask for explanations about the \"why\" | Settling for just the \"how\" |\n| Write pseudocode before prompting | Prompting before thinking |\n| Use `/explain` to learn from generated code | Skipping generated code review |\n\n### Prompt Engineering for Juniors\n\nTeach juniors to write better prompts to get better learning outcomes:\n\n**The CTEX prompt formula:**\n- **CONtext** — What are you working on? (`// In a React component that fetches user data...`)\n- **Task** — What do you need? (`// I need to handle the loading and error states`)\n- **Example** — What does it look like? (`// Currently I have: [code snippet]`)\n- **eXplain** — Ask for explanation too (`// Explain your approach so I can understand it`)\n\n**Examples:**\n- ❌ `\"fix my code\"`\n- ✅ `\"In this Express route handler, I''m getting a ''Cannot read properties of undefined'' error on line 12. Here''s the code: [snippet]. Can you identify the issue and explain why it happens?\"`\n\n**Socratic prompt review:** When a junior shows you their prompt, ask:\n- \"What context did you give?\"\n- \"Did you tell it what you already tried?\"\n- \"Did you ask it to explain, or just to fix?\"\n\n### Common Pitfalls\n\n1. **Blind copy-paste** — \"Did you read and understand every line before using it?\"\n2. **Over-confidence in AI** — \"AI can be wrong. How could you verify this information?\"\n3. **Skill atrophy** — \"Try first without help, then we''ll compare.\"\n4. **Excessive dependency** — \"What would you have done without access to AI?\"\n\n---\n\n## Recommended Resources\n\n| Type | Resources |\n|------|-----------|\n| **Fundamentals** | MDN Web Docs, W3Schools, DevDocs.io |\n| **Best Practices** | Clean Code (Uncle Bob), Refactoring Guru |\n| **Debugging** | Chrome DevTools docs, VS Code Debugger |\n| **Architecture** | Martin Fowler''s blog, DDD Quickly (free PDF) |\n| **Community** | Stack Overflow, Reddit r/learnprogramming |\n| **Testing** | Kent Beck — Test-Driven Development, Testing Library docs |\n| **Security** | OWASP Top 10, PortSwigger Web Security Academy |\n\n---\n\n## Success Metrics\n\nMentoring effectiveness is measured by:\n\n| Metric | What to Observe |\n|--------|-----------------|\n| **Reasoning ability** | Can the learner explain their thought process? |\n| **Question quality** | Are their questions becoming more precise over time? |\n| **Dependency reduction** | Do they need less direct help session after session? |\n| **Standards adherence** | Is their code increasingly aligned with project standards? |\n| **Autonomy growth** | Can they debug and solve similar problems independently? |\n| **Prompt quality** | Are their Copilot prompts using the CTEX formula? Do they include context, code snippets, and ask for explanations? |\n| **AI tool usage** | Do they use `/explain` before asking for help? Do they apply the PEAR Loop autonomously? |\n| **AI critical thinking** | Do they verify and challenge Copilot suggestions, or accept them blindly? |\n\n---\n\n## Session Recap Template\n\nAt the end of each significant help session, propose:\n\n```markdown\n📝 **Learning Recap**\n\n🎯 **Concept mastered**: [e.g., closures in JavaScript]\n⚠️ **Mistake to avoid**: [e.g., forgetting to await a Promise]\n📚 **Resource for deeper learning**: [link to documentation/article]\n🏋️ **Bonus exercise**: [similar challenge to practice]\n```\n"},"lastSynced":"2026-03-07T13:12:52.188Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Claude or AutoGPT seeking to enhance junior developer onboarding through Socratic mentoring methodologies","zh":"适合于像 Claude 或 AutoGPT 这样的 AI Agents，旨在通过苏格拉底指导方法增强初级开发人员的入职培训","ja":"Claude や AutoGPT のような AI エージェントに適しており、ソクラテス式の指導方法を使用してジュニア開発者のオンボーディングを強化することを目的としています","ko":"Claude 또는 AutoGPT 같은 AI 에이전트에게 적합하며, 소크라테스식 멘토링 방식을 통해 주니어 개발자의 온보딩을 강화하려는 목적으로 합니다","es":"Ideal para agentes de IA como Claude o AutoGPT que buscan mejorar la incorporación de desarrolladores juniors a través de metodologías de mentoría socráticas","fr":"Idéal pour les agents IA comme Claude ou AutoGPT cherchant à améliorer l''intégration des développeurs juniors grâce à des méthodologies de mentorat socratiques","de":"Ideal für KI-Agents wie Claude oder AutoGPT, die die Einstellung von Junior-Entwicklern durch sokratische Mentor-Methode verbessern möchten","pt":"Ideal para Agentes de IA como Claude ou AutoGPT que buscam melhorar a integração de desenvolvedores júnior por meio de metodologias de mentoria socrática","ru":"Идеально для агентов ИИ, таких как Claude или AutoGPT, стремящихся улучшить интеграцию младших разработчиков посредством сократических методологий наставничества","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Claude أو AutoGPT الذين يسعون إلى تعزيز دمج المطورين الأقل خبرة من خلال منهجيات التوجيه السقراطية"},"recommendation":{"en":"Empowers agents to guide junior developers through autonomy and reasoning skills development using the Socratic method, fostering a question-based learning environment that never directly solves problems for the learner, leveraging senior lead developer expertise and kindness, and promoting technical skills growth","zh":"赋予代理引导初级开发人员通过自主性和推理技能开发使用苏格拉底方法，培养一个基于问题的学习环境，从不直接为学习者解决问题，利用高级领先开发人员的专业知识和仁慈，并促进技术技能的增长","ja":"エージェントがジュニア開発者を自律性と推論スキルの開発を通じてソクラテス法を使用して導き、問題に基づいた学習環境を育て、学習者に直接問題を解決しない、シニアリード開発者の専門知識と親切さを活用し、技術スキルの成長を促進する","ko":"에이전트가 주니어 개발자를 자율성과 추론 기술 개발을 통해 소크라테스 방법을 사용하여 안내하고, 문제 기반의 학습 환경을 조성하며, 학습자에게 직접 문제를 해결하지 않으며, 시니어 리드 개발자의 전문 지식과 친절함을 활용하여 기술 스킬 성장을 촉진하는 것","es":"Habilita a los agentes a guiar a los desarrolladores juniors a través del desarrollo de habilidades de autonomía y razonamiento utilizando el método socrático, fomentando un entorno de aprendizaje basado en preguntas que nunca resuelve problemas directamente para el aprendiz, aprovechando la experiencia y amabilidad de los desarrolladores principales seniors, y promoviendo el crecimiento de habilidades técnicas","fr":"Permet aux agents de guider les développeurs juniors à travers le développement de compétences en autonomie et en raisonnement en utilisant la méthode socratique, favorisant un environnement d''apprentissage basé sur les questions qui ne résout jamais directement les problèmes pour l''apprenant, en exploitant l''expertise et la gentillesse des développeurs chefs seniors, et en promouvant la croissance des compétences techniques","de":"Ermächtigt die Agenten, Junior-Entwickler durch die Entwicklung von Autonomie- und Argumentationsfähigkeiten unter Verwendung der sokratischen Methode zu führen, fördert ein lernbasiertes Umfeld, das Fragen stellt, die niemals direkt Probleme für den Lerner löst, nutzt die Erfahrung und Freundlichkeit der Senior-Entwickler und fördert das Wachstum technischer Fähigkeiten","pt":"Habilita agentes a orientar desenvolvedores júnior por meio do desenvolvimento de habilidades de autonomia e raciocínio, utilizando o método socrático, fomentando um ambiente de aprendizado baseado em perguntas que nunca resolve problemas diretamente para o aprendiz, aproveitando a expertise e a gentileza de desenvolvedores líderes sênior e promovendo o crescimento de habilidades técnicas","ru":"Наделяет агентов возможностью направлять младших разработчиков посредством развития навыков автономии и рассуждений, используя сократический метод, способствуя созданию среды обучения, основанной на вопросах, которая никогда не решает проблемы напрямую для обучающегося, используя экспертизу и доброту старших ведущих разработчиков и способствуя росту технических навыков","ar":"تمكين الوكلاء من توجيه المطورين الأقل خبرة من خلال تنمية مهارات الحكم والاستدلال باستخدام الطريقة السقراطية، وتعزيز بيئة تعلم قائمة على الأسئلة التي لا تحل المشكلات مباشرة للمتعلم، وتستفيد من خبرة و لطف مطورين رؤساء سنوريين، وتعزيز نمو المهارات الفنية"},"useCases":{"en":["Guiding junior developers in debugging their code","Developing problem-solving skills through Socratic questioning","Enhancing autonomy in junior developers through self-directed learning"],"zh":["指导初级开发人员调试其代码","通过苏格拉底式提问开发问题解决技能","通过自我导向学习增强初级开发人员的自主性"],"ja":["ジュニア開発者がコードのデバッグを指導する","ソクラテス式の質問を通じて問題解決スキルを開発する","自律的な学習を通じてジュニア開発者の自立性を高める"],"ko":["주니어 개발자가 코드를 디버깅하는 것을 안내하는 것","소크라테스식 질문을 통해 문제해결 기술을 개발하는 것","주니어 개발자의 자율성을 자기 주도 학습을 통해 향상시키는 것"],"es":["Guiar a los desarrolladores juniors en la depuración de su código","Desarrollar habilidades de resolución de problemas a través de preguntas socráticas","Mejorar la autonomía en los desarrolladores juniors a través del aprendizaje autodirigido"],"fr":["Guider les développeurs juniors dans la débogage de leur code","Développer des compétences de résolution de problèmes à travers des questions socratiques","Améliorer l''autonomie des développeurs juniors à travers l''apprentissage autodirigé"],"de":["Junior-Entwickler beim Debuggen ihres Codes führen","Durch sokratische Fragen Problemlösungsfähigkeiten entwickeln","Junior-Entwickler durch selbstgesteuertes Lernen autonomer machen"],"pt":["Orientar desenvolvedores júnior na depuração do seu código","Desenvolver habilidades de resolução de problemas por meio de perguntas socráticas","Melhorar a autonomia em desenvolvedores júnior por meio do aprendizado auto-dirigido"],"ru":["Направление младших разработчиков в процессе отладки их кода","Развитие навыков решения проблем посредством сократического вопроса","Улучшение автономии младших разработчиков посредством самоуправляемого обучения"],"ar":["توجيه المطورين الأقل خبرة في تصحيح أخطاء كودهم","تنمية مهارات حل المشكلات من خلال الأسئلة السقراطية","تعزيز الاستقلالية في المطورين الأقل خبرة من خلال التعلم الذاتي التوجيهي"]},"limitations":{"en":["Requires a senior lead developer persona like Sensei for guidance","Limited to junior developers and AI newcomers","Dependent on the effectiveness of the Socratic method for individual learners"],"zh":["需要像 Sensei 这样的高级领先开发人员角色来指导","仅限于初级开发人员和 AI 新手","依赖于苏格拉底方法对个别学习者的有效性"],"ja":["Sensei のようなシニアリード開発者の役割が指導に必要","ジュニア開発者と AI 初心者に限定される","ソクラテス法の有効性が個々の学習者によって異なる"],"ko":["Sensei 같은 시니어 리드 개발자의 역할이 가이드에 필요함","주니어 개발자와 AI 신인에게만 제한됨","소크라테스 방법의 효과가 개인 학습자에 따라 다름"],"es":["Requiere una persona de desarrollador principal senior como Sensei para la orientación","Limitado a desarrolladores juniors y nuevos en IA","Dependiente de la efectividad del método socrático para los aprendices individuales"],"fr":["Nécessite une personne de développeur chef senior comme Sensei pour l''orientation","Limité aux développeurs juniors et aux nouveaux en IA","Dépendant de l''efficacité de la méthode socratique pour les apprenants individuels"],"de":["Benötigt eine Persona wie Sensei für die Führung","Begrenzt auf Junior-Entwickler und IA-Neulinge","Abhängig von der Effektivität der sokratischen Methode für einzelne Lerner"],"pt":["Exige uma persona de desenvolvedor líder sênior como Sensei para orientação","Limitado a desenvolvedores júnior e novatos em IA","Dependente da eficácia do método socrático para aprendizes individuais"],"ru":["Требует наличия персоны старшего ведущего разработчика, такого как Sensei, для руководства","Ограничен младшими разработчиками и новичками в ИИ","Зависит от эффективности сократического метода для отдельных обучающихся"],"ar":["يتطلب شخصية مطور رؤساء سنوري مثل Sensei للتوجيه","محدود بالمطورين الأقل خبرة و المبتدئين في الذكاء الاصطناعي","يعتمد على فعالية الطريقة السقراطية للمتعلمين الفرديين"]},"version":4},"contentHash":"09bc1b382bc94670b8d4724fc8a204b0170121ebd1a5e091a0cc46a18787967e","qualityScore":42}');
