INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ourcaldo/indexnow-mono/mentoring-juniors', 'mentoring-juniors', 'ourcaldo', 'indexnow-mono', 'community', 'mentoring-juniors ourcaldo indexnow-mono community The mentoring-juniors skill provides a comprehensive Socratic mentoring methodology for junior developers and AI newcomers, guiding through questions to develop autonomy and reasoning skills. mentoring-juniors 是一种综合的 Socratic 辅导方法，旨在开发初级开发人员的自主性和推理能力 mentoring-juniors は、初級開発者の自律性と推論能力を開発するための包括的なソクラティック・メンタリング方法です mentoring-juniors 는 初级 개발자의 자율성과 推論 능력을 개발하기 위한 포괄적인 소크라테스 방법 La metodología Socratique para mentoring-juniors desarrolla la autonomía y las habilidades de razonamiento en desarrolladores junior y nuevos en AI La méthode Socratique pour mentoring-juniors développe l''autonomie et les compétences de raisonnement chez les développeurs juniors et les nouveaux en IA Die Socratic Method für mentoring-juniors entwickelt Autonomie und Denkfähigkeiten bei Junior-Entwicklern und AI-Neulingen Método socrático para mentoring de juniors, desenvolvendo autonomia e habilidades de raciocínio em desenvolvedores iniciantes e novatos em AI Сократический метод для наставничества ИИ Агентов, развивающий автономию и навыки рассуждения у junior-разработчиков и новичков в ИИ أسلوب سقراط للتوجيه للجuniors، يطور الاستقلالية ومهارات التفكير في المطورين الجدد والمبتدئين في مجال الذكاء الاصطناعي how to use mentoring-juniors what is Socratic mentoring mentoring-juniors alternative mentoring-juniors vs traditional mentoring mentoring-juniors setup guide mentoring-juniors for junior developers Socratic method for AI newcomers autonomy and reasoning skills development mentoring-juniors Socratic 方法 初级开发人员 AI 新手 自主性开发 推理能力 问题解决能力 Sensei 指导 Guides through questions rather than answers to develop autonomy Practices the Socratic method for effective learning Developed by Sensei, a senior Lead Developer with 15+ years of experience Designed for junior developers and AI newcomers Focuses on developing reasoning skills through questioning Employs a comprehensive mentoring methodology mentoring-juniors is a Socratic mentoring methodology that guides junior developers and AI newcomers through questions to develop autonomy and reasoning skills.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('samarv/Shanon/notes-processor', 'community', 'samarv', 'Shanon', 'samarv/Shanon', 'notes-processor', 17, 2, 42, '2026-02-24T21:24:13Z', '2026-03-06T06:42:22.782Z', 'f87ee9f37a0d98d6e3faaaeecc52e05b8e05c7b083b83c77acd5211997ebbcb7', '{"id":"samarv/Shanon/notes-processor","name":"notes-processor","description":{"en":"The notes-processor skill systematizes daily notes using the LNO framework for strategic focus and priority. It benefits developers and product managers by surfacing high-leverage work.","zh":"Notes Processor是一种模块化的PM系统，使用LNO框架系统地组织日常笔记，并优化任务优先级","ja":"Notes Processorは、LNOフレームワークを使用して日常のノートを体系的に整理し、タスクの優先順位を最適化するモジュラPMシステム","ko":"Notes Processor는 LNO 프레임워크를 사용하여 일상적인 노트를 체계적으로 정리하고, 작업 우선순위를 최적화하는 모듈식 PM 시스템","es":"El procesador de notas es un sistema modular de gestión de productos asistida por IA que utiliza el marco LNO para mantener el enfoque estratégico.","fr":"Le processeur de notes est un système modulaire de gestion de produits assistée par IA qui utilise le cadre LNO pour maintenir la focalisation stratégique.","de":"Der Notizprozessor ist ein modulares System für das KI-gestützte Produktmanagement, das den LNO-Rahmen verwendet, um die strategische Ausrichtung beizubehalten.","pt":"O notes-processor é um sistema modular de gerenciamento de produtos que ajuda a organizar notas diárias com o framework LNO, priorizando tarefas com base no ROI.","ru":"Notes-processor — это модульная система управления продуктами, которая помогает организовать ежедневные заметки с помощью фреймворка LNO, расставляя приоритеты задач на основе ROI.","ar":"notes-processor هو نظام إدارة منتجات تعاوني يساعد في تنظيم الملاحظات اليومية باستخدام إطار LNO ، ويتحديد الأولويات للعمل بناءً على العائد على الاستثمار"},"seo":{"title":{"en":"notes-processor: LNO Framework Setup Guide | AI Agent Skill","zh":"Notes Processor Setup Guide - AIエージェント笔记组织系统","ja":"Notes Processor 導入ガイド - AIエージェントによるノート整理","ko":"Notes Processor 설정 가이드 - AI 에이전트 노트 프로세서 시스템","es":"Configuración del Procesador de Notas: Guía de Implementa...","fr":"Mise en place du Processeur de Notes: Guide d''Installatio...","de":"Einrichtung des Notizprozessors: Leitfaden für die Implem...","pt":"Guia de Configuração do notes-processor: Organize suas No...","ru":"ИИ Агенты: Настройка notes-processor для Управления Замет...","ar":"دليل إعداد notes-processor: تنظيم الملاحظات باستخدام إطار..."},"description":{"en":"Transform ad-hoc notes into strategic prioritization with notes-processor. Learn how to invoke features like ''add action items to notes.md'' and ''categorize t...","zh":"使用Notes Processor Skill实现AI驱动的产品管理，优化笔记组织和任务优先级","ja":"Notes Processor Skillを使用してAI駆動の製品管理を実現し、ノートの整理とタスクの優先順位を最適化","ko":"Notes Processor Skill을 사용하여 AI 기반의 제품 관리를 구현하고, 노트 정리 및 작업 우선순위를 최적화","es":"Aprenda a configurar el procesador de notas para una gestión de productos asistida por IA. Descubra cómo transformar la toma de notas ad-hoc en un sistema de...","fr":"Découvrez comment configurer le processeur de notes pour une gestion de produits assistée par IA. Apprenez à transformer la prise de notes ad-hoc en un systè...","de":"Erfahren Sie, wie Sie den Notizprozessor für ein KI-gestütztes Produktmanagement einrichten. Entdecken Sie, wie Sie die ad-hoc-Notizen in ein strategisches P...","pt":"Aprenda a usar o notes-processor para organizar suas notas diárias com o framework LNO e priorizar tarefas com base no ROI","ru":"Узнайте, как использовать notes-processor для систематизации ваших ежедневных заметок с помощью фреймворка LNO и расстановки приоритетов задач на основе ROI","ar":"تعرف على كيفية استخدام notes-processor لتنظيم ملاحظاتك اليومية باستخدام إطار LNO وتحديد الأولويات للعمل بناءً على العائد على الاستثمار"},"definition":{"en":"notes-processor is a modular PM system for AI-assisted product management, utilizing the LNO framework to organize notes and prioritize tasks.","zh":"Notes Processor是一种AI驱动的笔记组织系统，使用LNO框架优化任务优先级","ja":"Notes Processorは、LNOフレームワークを使用してタスクの優先順位を最適化するAI駆動のノート整理システム","ko":"Notes Processor는 LNO 프레임워크를 사용하여 작업 우선순위를 최적화하는 AI 기반의 노트 정리 시스템","es":"Un procesador de notas es un sistema de gestión de notas que utiliza IA para priorizar tareas y mantener el enfoque estratégico.","fr":"Un processeur de notes est un système de gestion de notes qui utilise l''IA pour prioriser les tâches et maintenir la focalisation stratégique.","de":"Ein Notizprozessor ist ein System zur Notenverwaltung, das KI verwendet, um Aufgaben zu priorisieren und die strategische Ausrichtung beizubehalten.","pt":"O notes-processor é um sistema de gerenciamento de notas que utiliza o framework LNO para organizar e priorizar tarefas diárias","ru":"Notes-processor — это система управления заметками, которая использует фреймворк LNO для организации и расстановки приоритетов ежедневных задач","ar":"notes-processor هو نظام لإدارة الملاحظات الذي يستخدم إطار LNO لتنظيم وتحديد الأولويات للمهام اليومية"},"features":{"en":["Utilizes the LNO framework for strategic note organization","Supports trigger phrases like ''add action items to notes.md'' and ''process notes''","Transforms ad-hoc note-taking into a strategic prioritization system","Surfaces ROI-based work categorization for high-leverage tasks","Updates notes using commands like ''update my notes'' and ''categorize these tasks''"],"zh":["使用LNO框架系统地组织日常笔记","优化任务优先级和ROI-based工作分类","支持触发短语如\"add action items to notes.md\"","实现AI驱动的产品管理","模块化的PM系统设计"],"ja":["LNOフレームワークを使用して日常のノートを体系的に整理","タスクの優先順位とROIベースの作業分類を最適化","トリガー短語として\"add action items to notes.md\"をサポート","AI駆動の製品管理を実現","モジュラPMシステムの設計"],"ko":["LNO 프레임워크를 사용하여 일상적인 노트를 체계적으로 정리","작업 우선순위와 ROI 기반의 작업 분류를 최적화","트리거 단어 seperti \"add action items to notes.md\"를 지원","AI 기반의 제품 관리를 구현","모듈식 PM 시스템의 설계"],"es":["Utiliza el marco LNO para la priorización estratégica","Transforma la toma de notas ad-hoc en un sistema de priorización","Permite la categorización de tareas basada en ROI","Soporta la invocación a través de frases desencadenantes","Integra la gestión de productos asistida por IA"],"fr":["Utilise le cadre LNO pour la priorisation stratégique","Transforme la prise de notes ad-hoc en un système de priorisation","Permet la catégorisation des tâches basée sur le ROI","Supporte l''invocation via des phrases déclenchantes","Intègre la gestion de produits assistée par IA"],"de":["Verwendet den LNO-Rahmen für die strategische Priorisierung","Wandelt die ad-hoc-Notizen in ein Priorisierungssystem um","Ermöglicht die Kategorisierung von Aufgaben basierend auf ROI","Unterstützt die Invocation durch Auslöserphrasen","Integriert das KI-gestützte Produktmanagement"],"pt":["Organização de notas diárias com o framework LNO","Priorização de tarefas com base no ROI","Integração com comandos de voz para adicionar e atualizar notas","Categorização de tarefas com base no ROI","Suporte a comandos como ''add action items to notes.md'' e ''update my notes''"],"ru":["Организация ежедневных заметок с помощью фреймворка LNO","Расстановка приоритетов задач на основе ROI","Интеграция с голосовыми командами для добавления и обновления заметок","Категоризация задач на основе ROI","Поддержка команд seperti ''add action items to notes.md'' и ''update my notes''"],"ar":["تنظيم الملاحظات اليومية باستخدام إطار LNO","تحديد الأولويات للعمل بناءً على العائد على الاستثمار","التكامل مع أوامر الصوت لإضافة وتحديث الملاحظات","تصنيف المهام بناءً على العائد على الاستثمار","دعم أوامر مثل ''add action items to notes.md'' و ''update my notes''"]},"keywords":{"en":["how to use notes-processor","notes-processor setup guide","LNO framework for product management","notes-processor alternative","notes-processor vs trello","install notes-processor","what is notes-processor","notes-processor for AI agents","ROI-based work categorization"],"zh":["AIエージェント","笔记组织系统","LNO框架","任务优先级","ROI-based工作分类","产品管理","模块化PM系统","Notes Processor Skill"],"ja":["AIエージェント","ノート整理システム","LNOフレームワーク","タスクの優先順位","ROIベースの作業分類","製品管理","モジュラPMシステム","Notes Processor Skill"],"ko":["AI 에이전트","노트 정리 시스템","LNO 프레임워크","작업 우선순위","ROI 기반의 작업 분류","제품 관리","모듈식 PM 시스템","Notes Processor Skill"],"es":["procesador de notas","gestión de productos asistida por IA","priorización estratégica","LNO","ROI","invocación por frases desencadenantes","desarrollo de software","herramientas de IA","productividad"],"fr":["processeur de notes","gestion de produits assistée par IA","priorisation stratégique","LNO","ROI","invocation par phrases déclenchantes","développement de logiciels","outils IA","productivité"],"de":["Notizprozessor","KI-gestütztes Produktmanagement","strategische Priorisierung","LNO","ROI","Invocation durch Auslöserphrasen","Softwareentwicklung","KI-Tools","Produktivität"],"pt":["notes-processor","LNO framework","gerenciamento de notas","priorização de tarefas","ROI","comandos de voz","organização de notas","ferramentas de produtividade"],"ru":["notes-processor","ИИ Агенты","фреймворк LNO","управление заметками","расстановка приоритетов задач","ROI","голосовые команды","организация заметок","инструменты продуктивности"],"ar":["notes-processor","إدارة الملاحظات","إطار LNO","تحديد الأولويات","العائد على الاستثمار","أوامر الصوت","تنظيم الملاحظات","أدوات الإنتاجية"]}},"owner":"samarv","repo":"Shanon","repoPath":"samarv/Shanon","stars":17,"forks":2,"updatedAt":"2026-02-24T21:24:13Z","topics":[],"category":"community","skillMd":{"name":"notes-processor","description":"|","bodyPreview":"# Notes Processor Skill\n\n**Version**: 1.0.0\n**Last Updated**: January 27, 2026\n\n## Purpose\n\nSystematically organize daily notes using the LNO framework to maintain strategic focus and ensure high-leverage work gets appropriate priority. This skill transforms ad-hoc note-taking into a strategic prioritization system that surfaces ROI-based work categorization.\n\n## Invocation\n\n**Trigger phrases**:\n- \"add action items to notes.md\"\n- \"update my notes\"\n- \"process notes\"\n- \"categorize these tasks\"\n- \"","body":"# Notes Processor Skill\n\n**Version**: 1.0.0\n**Last Updated**: January 27, 2026\n\n## Purpose\n\nSystematically organize daily notes using the LNO framework to maintain strategic focus and ensure high-leverage work gets appropriate priority. This skill transforms ad-hoc note-taking into a strategic prioritization system that surfaces ROI-based work categorization.\n\n## Invocation\n\n**Trigger phrases**:\n- \"add action items to notes.md\"\n- \"update my notes\"\n- \"process notes\"\n- \"categorize these tasks\"\n- \"organize my daily tasks\"\n- \"sync action items from [brain]\"\n\n**Usage**:\n```\nInvoked by agents (brain-tracker, meeting-notes-router) or directly when user requests notes organization\n```\n\n## Framework: LNO Prioritization\n\n### Core Philosophy\n\n**The Problem**: Not all work is equal. PMs often treat all tasks as equally important, leading to strategic work being crowded out by tactical firefighting.\n\n**The Solution**: Shreyas Doshi''s LNO framework categorizes work by ROI potential:\n\n- **🟢 Leverage (L)**: 10x-100x ROI potential\n  - Strategic initiatives, experiments, research\n  - Documentation systems, templates, automation\n  - Work that compounds over time\n  - *Example*: \"Design experiment to test new onboarding flow\"\n\n- **🟡 Neutral (N)**: 1x ROI (equal effort to return)\n  - Regular meetings, standard project work\n  - Planning, coordination, reviews\n  - Necessary but not amplifying\n  - *Example*: \"Weekly sync with engineering team\"\n\n- **🔴 Overhead (O)**: <1x ROI (necessary but low return)\n  - Administrative work, required responses\n  - Urgent fixes, firefighting\n  - Work that must be done but doesn''t move strategic goals\n  - *Example*: \"Respond to expense report request\"\n\n### Why This Matters\n\n**Customer Value**: By surfacing high-leverage work, PMs spend more time on initiatives that compound customer value rather than reacting to daily noise.\n\n**Trade-off**: Requires discipline to categorize honestly. Accepting that not all work is strategic enables better resource allocation.\n\n**Outcome**: Over time, ratio of L:N:O work shifts toward leverage, driving disproportionate impact.\n\n## Execution Protocol\n\n### Phase 1: UNDERSTAND - Read Current State\n\n**CRITICAL**: Always read notes.md before modifying.\n\n1. Read `notes.md` to understand current structure\n2. Identify current date section (format: `# Jan 27:` or `# Jan 27 (Completed):`)\n3. Check for:\n   - Unformatted content at top of file\n   - Processing Queue items\n   - Incomplete tasks in previous date sections\n   - Tasks missing LNO categorization\n\n### Phase 2: CATEGORIZE - Apply LNO Framework\n\nFor each task or note item:\n\n**Step 1: Identify Task Type**\n- Action item with clear deliverable?\n- Meeting/coordination?\n- Administrative/reactive work?\n- Strategic/experimental work?\n\n**Step 2: Assess ROI Potential**\nAsk: \"If I complete this, what''s the multiplier effect?\"\n- >10x return? → Leverage\n- ~1x return? → Neutral\n- <1x return but necessary? → Overhead\n\n**Step 3: Apply Classification**\nUse keyword hints to guide categorization:\n\n**Leverage indicators**: \"strategic\", \"experiment\", \"optimize\", \"automate\", \"research\", \"design\", \"framework\", \"template\"\n**Neutral indicators**: \"meeting\", \"sync\", \"update\", \"coordinate\", \"plan\", \"review\"\n**Overhead indicators**: \"respond\", \"urgent\", \"required\", \"send message\", \"fix bug\", \"admin\"\n\n**Step 4: Validate Against Framework**\n- Am I being honest about ROI or inflating importance?\n- Would Shreyas Doshi agree with this categorization?\n- Does this serve strategic outcomes or just feel busy?\n\n### Phase 3: STRUCTURE - Organize in notes.md\n\n**Current Date Section Format**:\n```markdown\n# Jan 27:\n\n## 🟢 Leverage (L)\n- [ ] **[L]** High-leverage task description *(Created: Jan 20)*\n\n## 🟡 Neutral (N)\n- [ ] **[N]** Standard task description *(Created: Jan 27)*\n\n## 🔴 Overhead (O)\n- [ ] **[O]** Administrative task description *(Created: Jan 27)*\n```\n\n**Task Format Rules**:\n- Checkbox states:\n  - `[ ]` for incomplete (not started)\n  - `[>]` for in progress\n  - `[~]` for blocked/waiting\n  - `[-]` for cancelled/no longer needed\n  - `[X]` or `[x]` for completed\n- Label: `**[L]**`, `**[N]**`, or `**[O]**`\n- Creation date: `*(Created: [date])*` in abbreviated format (e.g., \"Jan 27\")\n- Completion date (when finished): `*(Completed: [date])*`\n- Cancellation date (when cancelled): `*(Cancelled: [date])*` with brief reason\n\n### Phase 4: DATE TRANSITIONS - Carry Forward Logic\n\n**When creating new date section:**\n\n**CRITICAL RULE**: Only carry forward active incomplete tasks `[ ]` and blocked tasks `[~]`. Never carry forward completed `[X]`, cancelled `[-]`, or in-progress `[>]` tasks from previous days.\n\n**Carryforward Protocol**:\n```\nFor each task in previous date section:\n  IF checkbox is [ ] (not started):\n    IF has *(Created: [date])*:\n      → Preserve *(Created: [date])* exactly as is\n    ELSE:\n      → Add *(Created: [previous-date])*\n    → Copy to new date section\n  ELSE IF checkbox is [~] (blocked/waiting):\n    → Carry forward (still active, waiting on external factors)\n    → Preserve creation date\n  ELSE IF checkbox is [X] or [x] (completed):\n    → Skip (done successfully, leave in original date section)\n  ELSE IF checkbox is [-] (cancelled/no longer needed):\n    → Skip (done by cancellation, leave in original date section)\n  ELSE IF checkbox is [>] (in progress from yesterday):\n    → Reset to [ ] and carry forward (new day, new start)\n    → Preserve creation date\n```\n\n**Why This Matters**: Preserving creation dates shows task age, helping identify:\n- Tasks lingering too long (need to be broken down or escalated)\n- Patterns of what gets delayed\n- True cycle time for work\n\n**Mark Previous Section Complete**:\n```markdown\n# Jan 26 (Completed):\n```\n\n### Phase 5: ROUTE - Brain-Specific Content\n\n**When notes reference specific brains**, route to brain CLAUDE.md:\n\n**Detection Keywords** (examples, dynamically discover actual brains):\n\n**Routing Protocol**:\n1. Identify brain-specific content (meetings, decisions, insights)\n2. Extract relevant notes\n3. Append to brain''s RunningNotes.md with date header\n4. Log routing in notes.md \"✅ Processed Notes\" section\n\n**Why Route**: Brains need context persistence. Daily notes are ephemeral; brain files are durable memory.\n\n### Phase 6: COMPLETION & CANCELLATION TRACKING\n\n**When task changes from incomplete to complete**:\n1. Change checkbox: `[ ]` → `[X]`\n2. Add completion timestamp: `*(Completed: Jan 27)*`\n3. Leave task in original date section (do NOT move)\n\n**Format**:\n```markdown\n- [X] **[L]** Completed task description *(Created: Jan 20)* *(Completed: Jan 27)*\n```\n\n**When task becomes cancelled/no longer needed**:\n1. Change checkbox: `[ ]` → `[-]`\n2. Add cancellation timestamp: `*(Cancelled: Jan 27)*`\n3. Add brief reason inline or as sub-bullet\n4. Leave task in original date section (do NOT move)\n\n**Format**:\n```markdown\n- [-] **[L]** Cancelled task description *(Created: Jan 20)* *(Cancelled: Jan 27)*\n  - Reason: Superseded by new unified approach\n```\n\n**Why Track Cancellations**:\n- Documents strategic pivots and evolution of thinking\n- Shows what was considered but not pursued (learning)\n- Explains why effort wasn''t invested (useful for retrospectives)\n- Transparency about changing priorities\n\n**Cancelled tasks behave like completed tasks**: They stay in their original date section and do NOT carry forward to future dates.\n\n### Phase 7: METADATA UPDATE\n\nUpdate \"Last Updated\" timestamp at bottom of notes.md:\n```markdown\n---\n**Last Updated**: 2026-01-27 14:30\n```\n\n## Integration with Brain Tracker\n\nWhen invoked by brain-tracker or meeting-notes-router:\n\n**Input**: List of action items with context\n```\nAction Items:\n- [Owner: Khushal] Follow up with design team on wireframes\n- [Owner: Khushal] Draft experiment brief for onboarding test\n- Context: From meeting about FCC Beta launch\n```\n\n**Processing**:\n1. Categorize each using LNO framework\n2. Add to current date section in notes.md\n3. Preserve context (note source/meeting if relevant)\n4. Apply proper formatting with creation date\n\n**Output**: Confirmation of items added with LNO classification\n\n## Quality Gates\n\nBefore completing any notes processing:\n\n- [ ] **Read First**: Did I read current notes.md state before modifying?\n- [ ] **LNO Categorization**: Are all tasks properly categorized by ROI potential?\n- [ ] **Honest Assessment**: Am I being truthful about leverage vs inflating importance?\n- [ ] **Carryforward Accuracy**: Did I ONLY carry forward incomplete tasks?\n- [ ] **Creation Dates Preserved**: Are original creation dates maintained on carried-forward tasks?\n- [ ] **Completion Timestamps**: Are completion dates added to all finished tasks?\n- [ ] **Brain Routing**: Did I route brain-specific content appropriately?\n- [ ] **Metadata Updated**: Is the \"Last Updated\" timestamp current?\n- [ ] **Strategic Alignment**: Does this organization serve the user''s strategic priorities?\n\n## Integration with Shannon\n\nThis skill embodies Shannon''s core philosophy:\n\n### Framework-Driven Thinking\n- LNO framework provides systematic approach to prioritization\n- Every task categorization is a trade-off decision\n- Framework reveals patterns: too much overhead? Need more leverage work.\n\n### Shreyas Doshi Quality Standards\n- **Customer-centric logic**: Leverage work directly serves customer value creation\n- **Explicit trade-offs**: Accepting honest categorization over optimistic inflation\n- **Outcome-focused**: LNO ratio shifts toward leverage drive real impact\n- **Framework application**: Every task gets systematic ROI assessment\n\n### Quality Standards Reference\nSee `.claude/rules/quality-gates.md` for full Shannon quality gates.\n\n### First Principles\n- Not all work is equal (fundamental truth)\n- Time is finite resource requiring allocation strategy\n- Strategic work gets crowded out without explicit prioritization\n- Honest categorization enables better resource allocation\n\n## Success Criteria\n\nThis skill succeeds when:\n\n1. ✅ All tasks in notes.md have clear LNO categorization\n2. ✅ Categorization reflects honest ROI assessment, not wishful thinking\n3. ✅ Date transitions preserve task history (creation dates maintained)\n4. ✅ Completed tasks stay in original date sections with completion timestamps\n5. ✅ Brain-specific content routed to appropriate CLAUDE.md files\n6. ✅ User can scan notes.md and immediately see leverage vs overhead ratio\n7. ✅ Over time, user''s work shifts toward more leverage activities\n8. ✅ Strategic work is visible and not buried in tactical noise\n\n## Anti-Patterns to Avoid\n\n❌ **False Leverage**: Categorizing everything as [L] to feel productive\n- *Reality check*: Most work is Neutral or Overhead. True Leverage is rare.\n\n❌ **Category Inflation**: \"This meeting is strategic\" when it''s coordination\n- *Fix*: Be brutally honest. Coordination = Neutral, even if important.\n\n❌ **Carrying Forward Completed/Cancelled Tasks**: Pollutes new date sections\n- *Fix*: Completed `[X]` and cancelled `[-]` tasks stay in their original date forever.\n- Both represent \"done\" - just in different ways (success vs obsolescence)\n\n❌ **Losing Task History**: Updating creation dates when carrying forward\n- *Fix*: Preserve original `*(Created: [date])*` to track task age.\n\n❌ **Skipping Categorization**: Adding tasks without LNO labels\n- *Fix*: Every task gets a category. No exceptions.\n\n❌ **Processing Without Reading**: Modifying notes.md without understanding current state\n- *Fix*: Always read first. Context matters.\n\n## Reference Materials\n\nFor detailed implementation rules, see:\n- **LNO Framework Deep Dive**: `.claude/reference/lno-framework.md` (if exists)\n- **Notes Structure Rules**: Original notes-processor agent for granular formatting rules\n- **Quality Framework**: `.claude/rules/quality-gates.md`\n\n## Error Handling\n\n### Missing Date Section\nIf current date section doesn''t exist:\n- Create it with proper LNO structure\n- Carry forward incomplete tasks from previous date\n- Mark previous section as \"(Completed)\"\n\n### Ambiguous Categorization\nIf task ROI is unclear:\n- Default to Neutral [N]\n- Add note: \"*(Category uncertain - review)*\"\n- User can recategorize later\n\n### Brain Routing Uncertainty\nIf brain mentioned but no matching folder found:\n- List discovered brains\n- Ask user which to route to, or skip routing\n\n### Invalid Task Format\nIf existing task lacks proper format:\n- Apply format corrections\n- Preserve task content\n- Add missing elements (creation date, LNO label)\n\n## Continuous Improvement\n\n**Over time, this skill enables**:\n- Pattern recognition: Am I drowning in overhead?\n- Strategic shifts: Consciously increase leverage work percentage\n- Honest assessment: Seeing true work composition\n- Prioritization: When overloaded, drop overhead first, protect leverage\n\n**This is the point**: Notes organization isn''t admin work. It''s strategic resource allocation made visible.\n"},"lastSynced":"2026-03-06T06:42:22.782Z","agentAnalysis":{"suitability":{"en":"Ideal for Productivity Agents requiring advanced note organization and prioritization capabilities using the LNO framework.","zh":"适用于需要使用LNO框架的高级笔记组织和优先级功能的生产力代理。","ja":"LNOフレームワークを使用した高度なノートの整理と優先順位付け機能を必要とする生産性エージェントに最適です。","ko":"LNO 프레임워크를 사용한 고급 노트 조직 및 우선 순위 기능을 필요로 하는 생산성 에이전트에 적합합니다.","es":"Ideal para Agentes de Productividad que requieren una organización de notas avanzada y capacidades de priorización utilizando el marco LNO.","fr":"Idéal pour les agents de productivité nécessitant une organisation de notes avancée et des capacités de priorisation utilisant le cadre LNO.","de":"Ideal für Produktivitätsagenten, die eine erweiterte Notizenorganisation und Priorisierungsfähigkeiten unter Verwendung des LNO-Frameworks erfordern.","pt":"Ideal para Agentes de Produtividade que requerem capacidades avançadas de organização e priorização de notas usando o framework LNO.","ru":"Идеально для агентов производительности, требующих расширенных возможностей организации и приоритизации заметок с использованием фреймворка LNO.","ar":"مثالي للوكلاء الإنتاجية الذين يحتاجون إلى إمكانيات متقدمة لتنظيم وتحديد الأولويات للملاحظات باستخدام إطار العمل LNO."},"recommendation":{"en":"Empowers agents to systematically categorize and prioritize tasks using ROI-based work categorization, leveraging trigger phrases like ''add action items to notes.md'' and file formats such as Markdown (.md) for seamless integration.","zh":"赋予代理系统地分类和优先任务的能力，使用基于ROI的工作分类，利用诸如''将操作项添加到notes.md''的触发短语，并使用Markdown (.md)等文件格式实现无缝集成。","ja":"エージェントに、ROIベースの作業分類を使用して、システム的にタスクを分類および優先順位付けする機能を付与します。たとえば、''アクションアイテムをnotes.mdに追加''などのトリガー句や、Markdown (.md)などのファイル形式を使用して、シームレスな統合を実現します。","ko":"에이전트가 ROI 기반 작업 분류를 사용하여 체계적으로 작업을 분류 및 우선 순위付け 할 수 있는 기능을 부여합니다. 예를 들어, ''작업 항목을 notes.md에 추가''와 같은 트리거 문구와 Markdown (.md)와 같은 파일 형식을 사용하여 무결점 통합을 구현합니다.","es":"Habilita a los agentes a categorizar y priorizar tareas de manera sistemática utilizando la categorización de trabajo basada en ROI, aprovechando frases desencadenantes como ''agregar elementos de acción a notes.md'' y formatos de archivo como Markdown (.md) para una integración sin problemas.","fr":"Permet aux agents de catégoriser et de prioriser les tâches de manière systématique en utilisant la catégorisation de travail basée sur le ROI, en exploitant des phrases déclenchantes comme ''ajouter des éléments d''action à notes.md'' et des formats de fichiers tels que Markdown (.md) pour une intégration sans problème.","de":"Ermächtigt Agenten, Aufgaben systematisch zu kategorisieren und zu priorisieren, indem sie eine ROI-basierte Arbeitskategorisierung verwenden, die Auslöserphrasen wie ''Aktionselemente zu notes.md hinzufügen'' und Dateiformate wie Markdown (.md) für eine nahtlose Integration nutzen.","pt":"Habilita os agentes a categorizar e priorizar tarefas systematicamente com base na categorização de trabalho com base em ROI, aproveitando frases de gatilho como ''adicionar itens de ação às notas.md'' e formatos de arquivo como Markdown (.md) para integração sem problemas.","ru":"Наделяет агентов возможностью систематически категоризировать и расставлять приоритеты задач на основе категоризации работы на основе ROI, используя триггерные фразы, такие как ''добавить действенные пункты в notes.md'' и форматы файлов, такие как Markdown (.md), для бесшовной интеграции.","ar":"يمنح الوكلاء القدرة على تصنيف المهام وتحديد الأولويات بشكل منهجي باستخدام تصنيف العمل على أساس ROI، مستفيداً من عبارات التنشيط مثل ''إضافة عناصر الإجراء إلى notes.md'' وشكلات الملفات مثل Markdown (.md) من أجل التكامل السلس."},"useCases":{"en":["Automating daily note processing for strategic focus","Categorizing tasks using the LNO framework for high-leverage work","Prioritizing action items based on ROI for efficient workflow management"],"zh":["自动化每日笔记处理以实现战略重点","使用LNO框架分类任务以实现高效工作","基于ROI优先处理操作项以实现高效工作流管理"],"ja":["戦略的焦点を維持するための毎日のノート処理の自動化","LNOフレームワークを使用したタスクの分類による高レバレンス作業","ROIベースのアクションアイテムの優先順位付けによる効率的なワークフローマネジメント"],"ko":["전략적焦점을 유지하기 위한 일일 노트 처리 자동화","LNO 프레임워크를 사용한 작업 분류에 의한 고효율 작업","ROI 기반의 작업 항목 우선 순위 지정에 의한 효율적인 워크플로우 관리"],"es":["Automatizar el procesamiento de notas diarias para el enfoque estratégico","Categorizar tareas utilizando el marco LNO para trabajar de alto impacto","Priorizar elementos de acción en función del ROI para una gestión eficiente del flujo de trabajo"],"fr":["Automatiser le traitement des notes quotidiennes pour la concentration stratégique","Catégoriser les tâches en utilisant le cadre LNO pour le travail à haut rendement","Prioriser les éléments d''action en fonction du ROI pour une gestion efficace du flux de travail"],"de":["Automatisieren des täglichen Notizverarbeitungsprozesses für strategische Konzentration","Kategorisieren von Aufgaben unter Verwendung des LNO-Frameworks für hochwertige Arbeit","Priorisieren von Aktionselementen basierend auf ROI für eine effiziente Arbeitsablaufverwaltung"],"pt":["Automatizar o processamento diário de notas para foco estratégico","Classificar tarefas usando o framework LNO para trabalho de alto impacto","Priorizar itens de ação com base em ROI para gestão de fluxo de trabalho eficiente"],"ru":["Автоматизировать ежедневную обработку заметок для стратегического фокуса","Категоризировать задачи с помощью фреймворка LNO для работы высокой отдачи","Приоритизировать пункты действий на основе ROI для эффективного управления рабочим процессом"],"ar":["توفير معالجة يومية 자동ية للملاحظات من أجل التركيز الإستراتيجي","تصنيف المهام باستخدام إطار العمل LNO من أجل العمل ذو التأثير العالي","تحديد الأولويات لعناصر الإجراء على أساس ROI من أجل إدارة تدفق العمل الفعالة"]},"limitations":{"en":["Requires Markdown file access for notes processing","Limited to text-based note inputs","Dependent on user-defined trigger phrases for invocation"],"zh":["需要Markdown文件访问权限以进行笔记处理","仅限于基于文本的笔记输入","依赖于用户定义的触发短语以调用"],"ja":["ノート処理のためにMarkdownファイルへのアクセスが必要","テキストベースのノート入力のみに対応","呼び出しのためにユーザー定義のトリガー句に依存"],"ko":["노트 처리를 위해 Markdown 파일 액세스가 필요함","텍스트 기반 노트 입력만 해당","호출을 위해 사용자 정의 트리거 문구에 의존"],"es":["Requiere acceso a archivos Markdown para el procesamiento de notas","Limitado a entradas de notas basadas en texto","Dependiente de frases desencadenantes definidas por el usuario para la invocación"],"fr":["Nécessite un accès aux fichiers Markdown pour le traitement des notes","Limité aux entrées de notes basées sur le texte","Dépend des phrases déclenchantes définies par l''utilisateur pour l''invocation"],"de":["Erfordert Zugriff auf Markdown-Dateien für die Notizverarbeitung","Begrenzt auf textbasierte Notizeneingaben","Abhängig von benutzerdefinierten Auslöserphrasen für die Aufruf"],"pt":["Requer acesso ao arquivo Markdown para processamento de notas","Limitado a entradas de notas baseadas em texto","Dependente de frases de gatilho definidas pelo usuário para invocação"],"ru":["Требует доступа к файлу Markdown для обработки заметок","Ограничен входными данными заметок на основе текста","Зависит от триггерных фраз, определенных пользователем, для вызова"],"ar":["يتطلب الوصول إلى ملف Markdown لمعالجة الملاحظات","محدود بالمدخلات النصية للملاحظات","يعتمد على عبارات التنشيط المحددة من قبل المستخدم للتنشيط"]},"version":4},"contentHash":"f87ee9f37a0d98d6e3faaaeecc52e05b8e05c7b083b83c77acd5211997ebbcb7","qualityScore":42}');
