INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('samarv/Shanon/notes-processor', 'notes-processor', 'samarv', 'Shanon', 'community', 'notes-processor samarv Shanon community The notes-processor skill systematizes daily notes using the LNO framework for strategic focus and priority. It benefits developers and product managers by surfacing high-leverage work. Notes Processor是一种模块化的PM系统，使用LNO框架系统地组织日常笔记，并优化任务优先级 Notes Processorは、LNOフレームワークを使用して日常のノートを体系的に整理し、タスクの優先順位を最適化するモジュラPMシステム Notes Processor는 LNO 프레임워크를 사용하여 일상적인 노트를 체계적으로 정리하고, 작업 우선순위를 최적화하는 모듈식 PM 시스템 El procesador de notas es un sistema modular de gestión de productos asistida por IA que utiliza el marco LNO para mantener el enfoque estratégico. Le processeur de notes est un système modulaire de gestion de produits assistée par IA qui utilise le cadre LNO pour maintenir la focalisation stratégique. Der Notizprozessor ist ein modulares System für das KI-gestützte Produktmanagement, das den LNO-Rahmen verwendet, um die strategische Ausrichtung beizubehalten. O notes-processor é um sistema modular de gerenciamento de produtos que ajuda a organizar notas diárias com o framework LNO, priorizando tarefas com base no ROI. Notes-processor — это модульная система управления продуктами, которая помогает организовать ежедневные заметки с помощью фреймворка LNO, расставляя приоритеты задач на основе ROI. notes-processor هو نظام إدارة منتجات تعاوني يساعد في تنظيم الملاحظات اليومية باستخدام إطار LNO ، ويتحديد الأولويات للعمل بناءً على العائد على الاستثمار how to use notes-processor notes-processor setup guide LNO framework for product management notes-processor alternative notes-processor vs trello install notes-processor what is notes-processor notes-processor for AI agents ROI-based work categorization AIエージェント 笔记组织系统 LNO框架 任务优先级 ROI-based工作分类 产品管理 模块化PM系统 Notes Processor Skill Utilizes the LNO framework for strategic note organization Supports trigger phrases like ''add action items to notes.md'' and ''process notes'' Transforms ad-hoc note-taking into a strategic prioritization system Surfaces ROI-based work categorization for high-leverage tasks Updates notes using commands like ''update my notes'' and ''categorize these tasks'' notes-processor is a modular PM system for AI-assisted product management, utilizing the LNO framework to organize notes and prioritize tasks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('nxy7/streampai-elixir/commit', 'community', 'nxy7', 'streampai-elixir', 'nxy7/streampai-elixir', 'commit', 3, 0, 42, '2026-02-15T09:36:25Z', '2026-03-07T01:53:16.029Z', 'c09b323fa3a88f12aabea7569e9d47bc0f95c356e9be4dbab9c79e0b95f460cc', '{"id":"nxy7/streampai-elixir/commit","name":"commit","description":{"en":"The commit skill generates professional git commit messages by analyzing changes in the working directory or subdirectory, helping developers manage their LiveStreams with Streampai.","zh":"Commit AI Agent是一个实时应用，帮助管理LiveStreams，生成专业的Git提交消息","ja":"Commit AIエージェントはリアルタイムアプリケーションであり、LiveStreamsを管理し、プロフェッショナルなGitコミットメッセージを生成する","ko":"Commit AI Tool은 실시간 애플리케이션으로 LiveStreams를 관리하고 전문적인 Git 커밋 메시지를 생성합니다","es":"El comando commit genera mensajes de confirmación de Git profesionales analizando los cambios en el directorio de trabajo o subdirectorio con Streampai","fr":"La commande commit génère des messages de validation Git professionnels en analysant les modifications dans le répertoire de travail ou le sous-répertoire avec Streampai","de":"Der Befehl commit erstellt professionelle Git-Commit-Nachrichten, indem er die Änderungen im Arbeitsverzeichnis oder Unterordner mit Streampai analysiert","pt":"O Streampai é uma aplicação em tempo real que ajuda a gerenciar LiveStreams, permitindo criar mensagens de commit profissionais","ru":"Streampai - это приложение реального времени, помогающее управлять LiveStreams, позволяющее создавать профессиональные сообщения коммита","ar":"Streampai هو تطبيق في الوقت الفعلي يساعد في إدارة LiveStreams، مما يسمح بإنشاء رسائل Commit احترافية"},"seo":{"title":{"en":"commit: Git Commit Message Generation for AI Agents | AI ...","zh":"Commit_SETUP_GUIDE_AIFramework","ja":"Commitベストプラクティス_AIEージェント","ko":"Commit설정 가이드_AITool","es":"Commit Setup Guide: Creación de Mensajes de Confirmación ...","fr":"Guide de Configuration de Commit: Génération de Messages ...","de":"Commit Einrichtungsleitfaden: Erstellung von Git-Commit-N...","pt":"Guia de Configuração do Commit: Melhores Práticas para De...","ru":"ИИ Агенты: Настройка Коммита для Разработчиков","ar":"إعداد Commit: دليل أفضل الممارسات για المطورين"},"description":{"en":"Discover how to generate professional git commit messages with commit. Learn how to analyze changes and create informative messages with this AI agent skill.","zh":"使用Commit AI Agent生成专业的Git提交消息，支持ash-framework、electricsql、elixir、nix、postgres和solidjs","ja":"Commit AIエージェントを使ってプロフェッショナルなGitコミットメッセージを生成しよう。ash-framework、electricsql、elixir、nix、postgres、solidjs対応","ko":"Commit AI Tool을 사용하여 전문적인 Git 커밋 메시지를 생성하세요. ash-framework, electricsql, elixir, nix, postgres, solidjs 지원","es":"Aprende a utilizar el comando commit para generar mensajes de confirmación de Git profesionales con Streampai y tecnologías como ash-framework y electricsql","fr":"Découvrez comment utiliser la commande commit pour générer des messages de validation Git professionnels avec Streampai et des technologies comme ash-framewo...","de":"Erfahren Sie, wie Sie den Befehl commit verwenden, um professionelle Git-Commit-Nachrichten mit Streampai und Technologien wie ash-framework und electricsql ...","pt":"Aprenda a criar mensagens de commit profissionais com o Streampai, analisando alterações no diretório de trabalho ou subdiretório","ru":"Создавайте профессиональные сообщения коммита с помощью Streampai, анализируя изменения в рабочем каталоге или подкаталоге","ar":"تعلم كيفية إنشاء رسائل Commit احترافية مع Streampai، من خلال تحليل التغييرات في الدليل العامل أو الدليل الفرعي"},"definition":{"en":"commit is a skill that generates git commit messages based on changes in the working directory, using commands like !git status and !git log for reference.","zh":"Commit AI Agent是一种生成专业的Git提交消息的工具","ja":"Commit AIエージェントはプロフェッショナルなGitコミットメッセージを生成するツールである","ko":"Commit AI Tool은 전문적인 Git 커밋 메시지를 생성하는 툴입니다","es":"Commit es una función de AI que genera mensajes de confirmación de Git profesionales","fr":"Commit est une fonction d''IA qui génère des messages de validation Git professionnels","de":"Commit ist eine AI-Funktion, die professionelle Git-Commit-Nachrichten erstellt","pt":"O commit é uma ferramenta que gera mensagens de commit profissionais, analisando alterações no diretório de trabalho ou subdiretório","ru":"Коммит - это инструмент, создающий профессиональные сообщения коммита, анализируя изменения в рабочем каталоге или подкаталоге","ar":"Commit هو أداة ت动生成 رسائل Commit احترافية، من خلال تحليل التغييرات في الدليل العامل أو الدليل الفرعي"},"features":{"en":["Generates git commit messages based on changes in the working directory or subdirectory","Analyzes changes using !git status --porcelain and !git log --oneline -5","Supports optional additional context about the changes","Works with Streampai, a realtime application for managing LiveStreams","Utilizes ash-framework, electricsql, elixir, nix, postgres, and solidjs technologies"],"zh":["支持ash-framework、electricsql、elixir、nix、postgres和solidjs","生成专业的Git提交消息","实时应用，帮助管理LiveStreams","支持自定义提交消息","集成Git状态和最近提交记录"],"ja":["ash-framework、electricsql、elixir、nix、postgres、solidjs対応","プロフェッショナルなGitコミットメッセージを生成","リアルタイムアプリケーション、LiveStreamsを管理","カスタムコミットメッセージをサポート","Git状態と最近のコミット履歴を統合"],"ko":["ash-framework, electricsql, elixir, nix, postgres, solidjs 지원","전문적인 Git 커밋 메시지를 생성","실시간 애플리케이션, LiveStreams 관리","커스텀 커밋 메시지 지원","Git 상태와 최근 커밋 기록 통합"],"es":["Análisis de cambios en el directorio de trabajo o subdirectorio","Generación de mensajes de confirmación de Git profesionales","Compatibilidad con tecnologías como ash-framework y electricsql","Integración con Streampai para aplicaciones en tiempo real","Soporte para comandos como !git status y !git log"],"fr":["Analyse des modifications dans le répertoire de travail ou le sous-répertoire","Génération de messages de validation Git professionnels","Compatibilité avec des technologies comme ash-framework et electricsql","Intégration avec Streampai pour des applications en temps réel","Prise en charge des commandes comme !git status et !git log"],"de":["Analyse von Änderungen im Arbeitsverzeichnis oder Unterordner","Erstellung von professionellen Git-Commit-Nachrichten","Unterstützung für Technologien wie ash-framework und electricsql","Integration mit Streampai für Echtzeit-Anwendungen","Unterstützung für Befehle wie !git status und !git log"],"pt":["Análise de alterações no diretório de trabalho ou subdiretório","Criação de mensagens de commit profissionais","Integração com ash-framework, electricsql, elixir, nix e postgres","Suporte a SolidJS","Análise de commits recentes para referência de estilo","Exibição do branch atual"],"ru":["Анализ изменений в рабочем каталоге или подкаталоге","Создание профессиональных сообщений коммита","Интеграция с ash-framework, electricsql, elixir, nix и postgres","Поддержка SolidJS","Анализ 최근них коммитов для ссылки на стиль","Отображение текущей ветки"],"ar":["تحليل التغييرات في الدليل العامل أو الدليل الفرعي","إنشاء رسائل Commit احترافية","التكامل مع ash-framework، electricsql، elixir، nix و postgres","دعم SolidJS","تحليل Commits الأخيرة لمصدر أسلوب","عرض الفرع الحالي"]},"keywords":{"en":["how to use commit","what is commit","commit alternative","commit vs git","commit install","commit setup guide","git commit message generation","Streampai commit","ash-framework commit","elixir commit"],"zh":["Commit AI Agent","Git提交消息","ash-framework","electricsql","elixir","nix","postgres","solidjs","LiveStreams管理","实时应用"],"ja":["Commit AIエージェント","Gitコミットメッセージ","ash-framework","electricsql","elixir","nix","postgres","solidjs","LiveStreams管理","リアルタイムアプリケーション"],"ko":["Commit AI Tool","Git 커밋 메시지","ash-framework","electricsql","elixir","nix","postgres","solidjs","LiveStreams 관리","실시간 애플리케이션"],"es":["commit","git commit","mensajes de confirmación de git","streampai","ash-framework","electricsql","elixir","nix","postgres","solidjs"],"fr":["commit","git commit","messages de validation git","streampai","ash-framework","electricsql","elixir","nix","postgres","solidjs"],"de":["commit","git commit","git-commit-nachrichten","streampai","ash-framework","electricsql","elixir","nix","postgres","solidjs"],"pt":["commit","Streampai","ash-framework","electricsql","elixir","nix","postgres","SolidJS","desenvolvimento de software","ferramentas de desenvolvimento","git commit"],"ru":["коммит","Streampai","ash-framework","electricsql","elixir","nix","postgres","SolidJS","разработка программного обеспечения","инструменты разработки","git коммит"],"ar":["Commit","Streampai","ash-framework","electricsql","elixir","nix","postgres","SolidJS","تطوير البرمجيات","أدوات التطوير","git Commit"]}},"owner":"nxy7","repo":"streampai-elixir","repoPath":"nxy7/streampai-elixir","stars":3,"forks":0,"updatedAt":"2026-02-15T09:36:25Z","topics":["ash-framework","electricsql","elixir","nix","postgres","solidjs"],"category":"community","skillMd":{"name":"commit","description":"Generate professional git commit message based on changes","bodyPreview":"Generate a professional git commit message analyzing all changes in the working directory or subdirectory\n\n**Usage**: `/commit` or `/commit [optional context]`\n\n**Arguments**: Optional additional context about the changes\n\n## Context\n- Git status: !git status --porcelain\n- Recent commits for style reference: !git log --oneline -5\n- Current branch: !git branch --show-current\n\n## Your task\n\nAnalyze the changes and create a git commit message following these guidelines:\n\n1. **Examine all changes**","body":"Generate a professional git commit message analyzing all changes in the working directory or subdirectory\n\n**Usage**: `/commit` or `/commit [optional context]`\n\n**Arguments**: Optional additional context about the changes\n\n## Context\n- Git status: !git status --porcelain\n- Recent commits for style reference: !git log --oneline -5\n- Current branch: !git branch --show-current\n\n## Your task\n\nAnalyze the changes and create a git commit message following these guidelines:\n\n1. **Examine all changes** by running:\n   - `git diff --staged` for staged changes\n   - `git diff` for unstaged changes\n   - Review our conversation history to understand the intent behind changes\n\n2. **Create a commit message** with this format:\n   ```\n   <type>: <concise descriptive title>\n\n   - <specific change 1>\n   - <specific change 2>\n   - <specific change 3>\n   ```\n\n3. **Commit type prefixes**:\n   - `feat:` for new features\n   - `fix:` for bug fixes\n   - `refactor:` for code restructuring\n   - `style:` for formatting changes\n   - `test:` for test additions/changes\n   - `docs:` for documentation updates\n   - `chore:` for maintenance tasks\n\n4. **Title guidelines**:\n   - Maximum 60 characters total\n   - Imperative mood (\"Add feature\" not \"Added feature\")\n   - No period at the end\n\n5. **Change list guidelines**:\n   - Simple flat list of bullet points\n   - Each item describes a specific change\n   - Focus on WHAT changed\n   - No section headers or groupings\n   - No sub-bullets\n   - No fluff or filler text\n\n6. **Do NOT**:\n   - Mention AI assistance, Claude, or any tooling\n   - Include co-author information\n   - Add section headers like \"Frontend:\", \"Backend:\", etc.\n   - Use vague descriptions like \"various changes\" or \"updates\"\n   - Mention count of changed files or lines of code\n\n## Example Output\n\n```\nfeat: Add accounting access for limited/restricted users\n\n- Show Accounting menu for users with fee access or in multi-user orgs\n- Hide Assignee column for users who only see their own data\n- Hide Qty./Perc. and Rate columns based on fee access permission\n- Add key prop to Datagrids to fix column mismatch on permission load\n- Add changelog entry for team commission access\n```\n\n```\nfix: Add missing residential fields to property enrichment\n\n- Add residential_ownership_type_id, residential_style_id to valid fields\n- Add residential bedroom/bathroom counts and gross living area\n- Include batch_data raw API response in property enrichment\n```\n\n$ARGUMENTS\n\nAnalyze the actual changes now and generate an appropriate commit message.\n"},"lastSynced":"2026-03-07T01:53:16.029Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing automated git commit message generation for streamlined repository management.","zh":"非常适合需要自动化 git 提交消息生成以实现流畅仓库管理的开发代理。","ja":"開発エージェントが自動化された git コミット メッセージの生成を必要とする場合に、ストリームライン化されたリポジトリ管理に最適です。","ko":"자동화된 git 커밋 메시지 생성을 필요한 개발 에이전트에게 최적화된 리포지토리 관리를 위한 것입니다.","es":"Perfecto para agentes de desarrollo que necesitan generación automática de mensajes de commit de git para una gestión de repositorio eficiente.","fr":"Parfait pour les agents de développement ayant besoin d''une génération automatisée de messages de commit Git pour une gestion de référentiel rationalisée.","de":"Perfekt für Entwicklungsmittel, die eine automatisierte Generierung von Git-Commit-Mitteilungen für eine gestreamte Repository-Verwaltung benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que precisam de geração automática de mensagens de commit do git para gerenciamento de repositório simplificado.","ru":"Идеально подходит для агентов разработки, которым требуется автоматическая генерация сообщений о коммитах git для упрощенного управления репозиторием.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى توليد رسائل Commit التلقائي لجيت من أجل إدارة مستودع مبسطة."},"recommendation":{"en":"Empowers agents to generate professional git commit messages by analyzing changes in the working directory or subdirectory, leveraging git status and recent commit history for context, and supporting optional additional context for more informative messages.","zh":"通过分析工作目录或子目录的更改、利用 git 状态和最近的提交历史作为上下文，并支持可选的额外上下文以生成更具信息的消息，从而使代理能够生成专业的 git 提交消息。","ja":"エージェントがワーキング ディレクトリまたはサブディレクトリの変更を分析し、git の状態と最近のコミット履歴をコンテキストとして利用し、さらに情報のあるメッセージを生成するためのオプションの追加コンテキストをサポートすることで、プロフェッショナルな git コミット メッセージを生成できるようにします。","ko":"작업 디렉토리 또는 서브 디렉토리의 변경 사항을 분석하고 git 상태 및 최근 커밋 기록을 컨텍스트로 사용하며 더 많은 정보를 가진 메시지를 생성하기 위한 선택적 추가 컨텍스트를 지원하여 에이전트가 전문적인 git 커밋 메시지를 생성할 수 있도록 합니다.","es":"Habilita a los agentes a generar mensajes de commit profesionales analizando los cambios en el directorio de trabajo o subdirectorio, aprovechando el estado de git y el historial de commits recientes para obtener contexto, y admitiendo contexto adicional opcional para mensajes más informativos.","fr":"Permet aux agents de générer des messages de commit professionnels en analysant les modifications dans le répertoire de travail ou le sous-répertoire, en exploitant l''état Git et l''historique des commits récents pour obtenir un contexte, et en prenant en charge un contexte additionnel facultatif pour des messages plus informatifs.","de":"Ermächtigt Agenten, professionelle Git-Commit-Mitteilungen zu generieren, indem Änderungen im Arbeitsverzeichnis oder Unterverzeichnis analysiert werden, Git-Status und aktuelle Commit-Historie für Kontext nutzen und optionalen zusätzlichen Kontext für aussagekräftigere Mitteilungen unterstützen.","pt":"Habilita os agentes a gerar mensagens de commit profissionais analisando as alterações no diretório de trabalho ou subdiretório, utilizando o status do git e o histórico de commits recentes para contexto, e suportando contexto adicional opcional para mensagens mais informativas.","ru":"Наделяет агентов возможностью генерировать профессиональные сообщения о коммитах, анализируя изменения в рабочем каталоге или подкаталоге, используя статус git и недавнюю историю коммитов для контекста, и поддерживая дополнительный контекст для более информативных сообщений.","ar":"يمنح الوكلاء إمكانية إنشاء رسائل Commit احترافية من خلال تحليل التغييرات في الدليل العمل أو الدليل الفرعي، واستخدام حالة جيت وتاريخ الإيداع الأخير للسياق، ودعم سياق إضافي اختياري لمزيد من المعلومات."},"useCases":{"en":["Automating commit messages for consistent repository history","Generating commit messages based on git status analysis","Creating informative commit messages with optional context"],"zh":["自动化提交消息以实现一致的仓库历史记录","基于 git 状态分析生成提交消息","使用可选上下文创建更具信息的提交消息"],"ja":["一貫したリポジトリ履歴を実現するためのコミット メッセージの自動化","git 状態分析に基づいてコミット メッセージを生成する","オプションのコンテキストを使用してより情報のあるコミット メッセージを作成する"],"ko":["일관된 리포지토리 기록을 위한 커밋 메시지 자동화","git 상태 분석을 기반으로 커밋 메시지를 생성하는 것","선택적 컨텍스트를 사용하여 더 많은 정보를 가진 커밋 메시지를 생성하는 것"],"es":["Automatizar mensajes de commit para un historial de repositorio coherente","Generar mensajes de commit en función del análisis del estado de git","Crear mensajes de commit informativos con contexto opcional"],"fr":["Automatiser les messages de commit pour un historique de référentiel cohérent","Générer des messages de commit en fonction de l''analyse de l''état Git","Créer des messages de commit informatifs avec un contexte facultatif"],"de":["Automatisieren von Commit-Mitteilungen für eine konsistente Repository-Historie","Generieren von Commit-Mitteilungen basierend auf der Analyse des Git-Status","Erstellen von informativen Commit-Mitteilungen mit optionalen Kontext"],"pt":["Automatizar mensagens de commit para histórico de repositório consistente","Gerar mensagens de commit com base na análise do status do git","Criar mensagens de commit informativas com contexto opcional"],"ru":["Автоматизация сообщений о коммитах для согласованной истории репозитория","Генерация сообщений о коммитах на основе анализа статуса git","Создание информативных сообщений о коммитах с дополнительным контекстом"],"ar":["توليد رسائل Commit تلقائي لتحقيق سجل مستودع متسق","إنشاء رسائل Commit بناءً على تحليل حالة جيت","إنشاء رسائل Commit إعلامية مع سياق إضافي"]},"limitations":{"en":["Requires git installation and configuration","Limited to analyzing changes in the working directory or subdirectory"],"zh":["需要 git 安装和配置","仅限于分析工作目录或子目录的更改"],"ja":["git のインストールと設定が必要","ワーキング ディレクトリまたはサブディレクトリの変更の分析のみ"],"ko":["git 설치 및 구성이 필요함","작업 디렉토리 또는 서브 디렉토리의 변경 사항 분석에만 제한됨"],"es":["Requiere instalación y configuración de git","Limitado a analizar cambios en el directorio de trabajo o subdirectorio"],"fr":["Nécessite l''installation et la configuration de Git","Limité à l''analyse des modifications dans le répertoire de travail ou le sous-répertoire"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf die Analyse von Änderungen im Arbeitsverzeichnis oder Unterverzeichnis"],"pt":["Requer instalação e configuração do git","Limitado à análise de alterações no diretório de trabalho ou subdiretório"],"ru":["Требует установки и настройки git","Ограничен анализом изменений в рабочем каталоге или подкаталоге"],"ar":["يتطلب تثبيت جيت وتفصيله","محدود بتحليل التغييرات في الدليل العمل أو الدليل الفرعي"]},"version":4},"contentHash":"c09b323fa3a88f12aabea7569e9d47bc0f95c356e9be4dbab9c79e0b95f460cc","qualityScore":42}');
