INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nxy7/streampai-elixir/commit', 'commit', 'nxy7', 'streampai-elixir', 'community', 'commit nxy7 streampai-elixir community ash-framework electricsql elixir nix postgres solidjs The commit skill generates professional git commit messages by analyzing changes in the working directory or subdirectory, helping developers manage their LiveStreams with Streampai. Commit AI Agent是一个实时应用，帮助管理LiveStreams，生成专业的Git提交消息 Commit AIエージェントはリアルタイムアプリケーションであり、LiveStreamsを管理し、プロフェッショナルなGitコミットメッセージを生成する Commit AI Tool은 실시간 애플리케이션으로 LiveStreams를 관리하고 전문적인 Git 커밋 메시지를 생성합니다 El comando commit genera mensajes de confirmación de Git profesionales analizando los cambios en el directorio de trabajo o subdirectorio con Streampai La commande commit génère des messages de validation Git professionnels en analysant les modifications dans le répertoire de travail ou le sous-répertoire avec Streampai Der Befehl commit erstellt professionelle Git-Commit-Nachrichten, indem er die Änderungen im Arbeitsverzeichnis oder Unterordner mit Streampai analysiert O Streampai é uma aplicação em tempo real que ajuda a gerenciar LiveStreams, permitindo criar mensagens de commit profissionais Streampai - это приложение реального времени, помогающее управлять LiveStreams, позволяющее создавать профессиональные сообщения коммита Streampai هو تطبيق في الوقت الفعلي يساعد في إدارة LiveStreams، مما يسمح بإنشاء رسائل Commit احترافية how to use commit what is commit commit alternative commit vs git commit install commit setup guide git commit message generation Streampai commit ash-framework commit elixir commit Commit AI Agent Git提交消息 ash-framework electricsql elixir nix postgres solidjs LiveStreams管理 实时应用 Generates git commit messages based on changes in the working directory or subdirectory Analyzes changes using !git status --porcelain and !git log --oneline -5 Supports optional additional context about the changes Works with Streampai, a realtime application for managing LiveStreams Utilizes ash-framework, electricsql, elixir, nix, postgres, and solidjs technologies commit is a skill that generates git commit messages based on changes in the working directory, using commands like !git status and !git log for reference.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('OneOffTech/parxy/parxy', 'community', 'OneOffTech', 'parxy', 'OneOffTech/parxy', 'parxy', 0, 0, 42, '2026-03-08T01:57:15.271Z', '2026-03-08T02:00:19.856Z', '67bf568e2de681e308876d915bedcfe28ee4cf73361e2a5763be3f2eb97c21c5', '{"id":"OneOffTech/parxy/parxy","name":"parxy","description":{"en":"Parxy is a document processing gateway that provides a unified model for accessing different parsers. It benefits developers by simplifying document parsing tasks.","zh":"Parxy 是一个文档处理网关，提供统一的模型访问不同解析器。使用 Parxy，您可以轻松地解析文档，并提取所需的信息。","ja":"Parxy はドキュメント処理ゲートウェイであり、統一されたモデルでさまざまなパーサーにアクセスできます。Parxy を使用すると、ドキュメントを解析して必要な情報を抽出できます。","ko":"Parxy는 문서 처리 게이트웨이로서,統一された 모델로 다양한 파서에 액세스할 수 있습니다. Parxy를 사용하면 문서를 파싱하고 필요한 정보를 추출할 수 있습니다.","es":"Parxy es una puerta de enlace de procesamiento de documentos que permite acceder a diferentes parseadores utilizando un modelo unificado","fr":"Parxy est une passerelle de traitement de documents qui permet d''accéder à différents parseurs en utilisant un modèle unifié","de":"Parxy ist eine Dokumentenverarbeitungsgateway, das den Zugriff auf verschiedene Parser mittels eines einheitlichen Modells ermöglicht","pt":"O Parxy é uma gateway de processamento de documentos que permite acessar diferentes parsers usando um modelo unificado. Isso facilita a extração de informações de documentos em diferentes formatos.","ru":"Parxy - это шлюз обработки документов, который позволяет доступ к разным парсерам с помощью единой модели. Это упрощает извлечение информации из документов в разных форматах.","ar":"Parxy هو بوابة معالجة الوثائق التي تمكن الوصول إلى محركات فك ترميز مختلفة باستخدام نموذج موحد. هذا يسهل استخراج المعلومات من الوثائق بأساليب مختلفة."},"seo":{"title":{"en":"Parxy: Unified Document Parsing Gateway for AI Agents","zh":"Parxy 文档处理网关设置指南","ja":"Parxy ドキュメント処理ゲートウェイのベストプラクティス","ko":"Parxy 문서 처리 게이트웨이 사용자 가이드","es":"Guía de configuración de Parxy para procesamiento de docu...","fr":"Configurer Parxy pour le traitement de documents","de":"Parxy-Setup-Leitfaden für Dokumentenverarbeitung","pt":"Guia de Configuração do Parxy - Processamento de Document...","ru":"Настройка Parxy: ИИ Агенты для Обработки Документов","ar":"دليل إعداد Parxy - معالجة الوثائق الذكية"},"description":{"en":"Unlock efficient document processing with parxy. Learn how to parse PDFs using pymupdf and llamaparse drivers. Get started now!","zh":"使用 Parxy 文档处理网关访问不同解析器，统一模型，提高开发效率","ja":"Parxy ドキュメント処理ゲートウェイを使用して、さまざまなパーサーにアクセスし、開発の効率を上げる","ko":"Parxy 문서 처리 게이트웨이를 사용하여 다양한 파서에 액세스하고 개발 효율성을 높여보세요","es":"Aprende a utilizar Parxy para procesar documentos con diferentes parseadores y niveles de extracción","fr":"Découvrez comment utiliser Parxy pour traiter des documents avec différents parseurs et niveaux d''extraction","de":"Erfahren Sie, wie Sie Parxy für die Verarbeitung von Dokumenten mit verschiedenen Parsern und Extraktionsniveaus verwenden","pt":"Aprenda a usar o Parxy para processar documentos com eficiência. Descubra como acessar diferentes parsers com um modelo unificado.","ru":"Узнайте, как использовать Parxy для обработки документов. Откройте для себя, как доступ к разным парсерам с помощью единой модели.","ar":"تعرف على كيفية استخدام Parxy لمعالجة الوثائق بفعالية. اكتشف كيفية الوصول إلى محركات فك ترميز مختلفة باستخدام نموذج موحد."},"definition":{"en":"parxy is a document processing gateway that enables unified access to various parsers for efficient document parsing","zh":"Parxy 是一个文档处理网关，提供解析文档和提取信息的功能","ja":"Parxy はドキュメント処理ゲートウェイであり、ドキュメントを解析して情報を抽出する機能を提供します","ko":"Parxy는 문서 처리 게이트웨이로서, 문서를 파싱하고 정보를 추출하는 기능을 제공합니다","es":"Parxy es un agente de procesamiento de documentos que utiliza un modelo unificado para acceder a diferentes parseadores","fr":"Parxy est un outil de traitement de documents qui utilise un modèle unifié pour accéder à différents parseurs","de":"Parxy ist ein Dokumentenverarbeitungstool, das ein einheitliches Modell verwendet, um auf verschiedene Parser zuzugreifen","pt":"O Parxy é um gateway de processamento de documentos que fornece acesso a diferentes parsers usando um modelo unificado.","ru":"Parxy - это шлюз обработки документов, который предоставляет доступ к разным парсерам с помощью единой модели.","ar":"Parxy هو بوابة معالجة الوثائق التي توفر الوصول إلى محركات فك ترميز مختلفة باستخدام نموذج موحد."},"features":{"en":["Supports parsing of PDF documents using pymupdf and llamaparse drivers","Offers flexible extraction levels, including page, block, and span levels","Allows parsing from bytes or BytesIO for efficient data processing","Provides a unified model for accessing different parsers","Enables specific driver and level selection for customized parsing"],"zh":["支持多种解析器，包括 pymupdf 和 llamaparse","提供统一的模型，方便访问不同解析器","支持多种解析级别，包括 page、block 和 span","可以从文件或字节流中解析文档","支持 Python 语言，方便集成到开发项目中"],"ja":["複数のパーサーをサポートしています、包括 pymupdf と llamaparse","統一されたモデルを提供し、異なるパーサーへのアクセスを容易にします","複数の解析レベルをサポートしています、包括 page、block、および span","ファイルまたはバイトストリームからドキュメントを解析できます","Python 言語をサポートしています、開発プロジェクトへの統合を容易にします"],"ko":["다양한 파서를 지원합니다, 포함하여 pymupdf 및 llamaparse","統一された 모델을 제공하여, 다른 파서에 액세스하기 쉽습니다","다양한 파싱 레벨을 지원합니다, 포함하여 page, block 및 span","파일 또는 바이트 스트림에서 문서를 파싱할 수 있습니다","Python 언어를 지원하여, 개발 프로젝트에 통합하기 쉽습니다"],"es":["Procesamiento de documentos con diferentes parseadores","Niveles de extracción personalizables (page, block, span)","Compatibilidad con diferentes formatos de archivo (PDF, bytes, BytesIO)","Uso de drivers específicos (pymupdf, llamaparse)","Integración con bibliotecas Python para un uso flexible"],"fr":["Traitement de documents avec différents parseurs","Niveaux d''extraction personnalisables (page, block, span)","Compatibilité avec différents formats de fichier (PDF, bytes, BytesIO)","Utilisation de drivers spécifiques (pymupdf, llamaparse)","Intégration avec des bibliothèques Python pour une utilisation flexible"],"de":["Dokumentenverarbeitung mit verschiedenen Parsern","Anpassbare Extraktionsniveaus (page, block, span)","Kompatibilität mit verschiedenen Dateiformaten (PDF, bytes, BytesIO)","Verwendung von spezifischen Treibern (pymupdf, llamaparse)","Integration mit Python-Bibliotheken für flexible Nutzung"],"pt":["Acesso a diferentes parsers com um modelo unificado","Extração de informações em níveis de página, bloco e span","Suporte a documentos em formatos diferentes","Integração com bibliotecas Python como pymupdf e llamaparse","Processamento de documentos a partir de bytes ou BytesIO"],"ru":["Доступ к разным парсерам с помощью единой модели","Извлечение информации на уровнях страницы, блока и спана","Поддержка документов в разных форматах","Интеграция с библиотеками Python như pymupdf и llamaparse","Обработка документов из байтов или BytesIO"],"ar":["الوصول إلى محركات فك ترميز مختلفة باستخدام نموذج موحد","استخراج المعلومات على مستويات الصفحة والكتلة والفاصل","دعم الوثائق بأساليب مختلفة","التكامل مع مكتبات Python مثل pymupdf وllamaparse","معالجة الوثائق من البايتات أو BytesIO"]},"keywords":{"en":["how to use parxy","parxy alternative","parxy install","parxy setup guide","what is parxy","parxy vs pymupdf","document parsing gateway","unified document parsing","parxy documentation"],"zh":["Parxy 文档处理网关","文档解析","统一模型","pymupdf","llamaparse","Python 开发","文档处理","AI 工具","AI 解析"],"ja":["Parxy ドキュメント処理ゲートウェイ","ドキュメント解析","統一されたモデル","pymupdf","llamaparse","Python 開発","ドキュメント処理","AI エージェント","AI 解析"],"ko":["Parxy 문서 처리 게이트웨이","문서 파싱","統一された 모델","pymupdf","llamaparse","Python 개발","문서 처리","AI 에이전트","AI 파싱"],"es":["parxy","procesamiento de documentos","parseadores","niveles de extracción","pymupdf","llamaparse","Python","PDF","bytes","BytesIO","agente de procesamiento de documentos","herramienta de procesamiento de documentos"],"fr":["parxy","traitement de documents","parseurs","niveaux d''extraction","pymupdf","llamaparse","Python","PDF","bytes","BytesIO","outil de traitement de documents","agent de traitement de documents"],"de":["parxy","Dokumentenverarbeitung","Parser","Extraktionsniveaus","pymupdf","llamaparse","Python","PDF","bytes","BytesIO","Dokumentenverarbeitungstool","Dokumentenverarbeitungsagent"],"pt":["parxy","processamento de documentos","parsers","modelo unificado","extração de informações","pymupdf","llamaparse","Python","desenvolvimento de software"],"ru":["parxy","обработка документов","парсеры","единая модель","извлечение информации","pymupdf","llamaparse","Python","разработка программного обеспечения"],"ar":["parxy","معالجة الوثائق","محركات فك ترميز","نموذج موحد","استخراج المعلومات","pymupdf","llamaparse","Python","تطوير البرمجيات"]}},"owner":"OneOffTech","repo":"parxy","repoPath":"OneOffTech/parxy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.271Z","topics":[],"category":"community","skillMd":{"name":"parxy","description":"|","bodyPreview":"# Parxy Document Processing\n\n## Parsing Documents\n\n```python\nfrom parxy_core.facade.parxy import Parxy\n\n# Basic parsing (default: pymupdf driver, block level)\ndoc = Parxy.parse(\"document.pdf\")\n\n# With specific driver and level\ndoc = Parxy.parse(\"document.pdf\", driver_name=\"llamaparse\", level=\"span\")\n\n# From bytes or BytesIO\ndoc = Parxy.parse(pdf_bytes)\n```\n\n### Extraction Levels\n\n| Level | Description |\n|-------|-------------|\n| `page` | Page text only |\n| `block` | Text blocks (default) |\n| `li","body":"# Parxy Document Processing\n\n## Parsing Documents\n\n```python\nfrom parxy_core.facade.parxy import Parxy\n\n# Basic parsing (default: pymupdf driver, block level)\ndoc = Parxy.parse(\"document.pdf\")\n\n# With specific driver and level\ndoc = Parxy.parse(\"document.pdf\", driver_name=\"llamaparse\", level=\"span\")\n\n# From bytes or BytesIO\ndoc = Parxy.parse(pdf_bytes)\n```\n\n### Extraction Levels\n\n| Level | Description |\n|-------|-------------|\n| `page` | Page text only |\n| `block` | Text blocks (default) |\n| `line` | Individual lines |\n| `span` | Text spans with styling |\n| `character` | Individual characters |\n\n### Document Structure\n\n```python\ndoc.filename      # Original filename\ndoc.pages         # List of Page objects\ndoc.metadata      # Document metadata\n\npage.number       # Page number (1-indexed)\npage.text         # Full page text\npage.blocks       # List of TextBlock objects\n\nblock.text        # Block text content\nblock.bbox        # Bounding box (x0, y0, x1, y1)\nblock.role        # Semantic role (paragraph, heading, etc.)\n```\n\n## Available Drivers\n\n| Driver | Constant | Type | Best For |\n|--------|----------|------|----------|\n| PyMuPDF | `Parxy.PYMUPDF` | Local | Fast local processing |\n| PdfAct | `Parxy.PDFACT` | Self-hosted | Scientific papers, semantic roles |\n| LlamaParse | `Parxy.LLAMAPARSE` | Cloud | Complex docs with OCR/tables |\n| LLMWhisperer | `Parxy.LLMWHISPERER` | Cloud | Form extraction |\n| Unstructured | `Parxy.UNSTRUCTURED_LIBRARY` | Local | Multi-format (DOCX, HTML) |\n\n```python\n# List all drivers\ndrivers = Parxy.drivers()\n\n# Get specific driver\ndriver = Parxy.driver(Parxy.LLAMAPARSE)\n```\n\n## Batch Processing\n\n```python\nfrom parxy_core.facade.parxy import Parxy\nfrom parxy_core.models import BatchTask\n\n# Simple batch\nresults = Parxy.batch(\n    tasks=[\"doc1.pdf\", \"doc2.pdf\"],\n    drivers=[\"pymupdf\"],\n    workers=4,\n)\n\n# Per-file configuration\nresults = Parxy.batch(tasks=[\n    BatchTask(file=\"simple.pdf\"),\n    BatchTask(file=\"complex.pdf\", drivers=[\"llamaparse\"], level=\"line\"),\n])\n\n# Streaming results\nfor result in Parxy.batch_iter(tasks=[\"doc1.pdf\", \"doc2.pdf\"]):\n    if result.success:\n        print(f\"{result.file}: {len(result.document.pages)} pages\")\n    else:\n        print(f\"{result.file} failed: {result.error}\")\n```\n\n## PDF Manipulation\n\n### Merge PDFs\n\n```python\nfrom pathlib import Path\nfrom parxy_core.facade.parxy import Parxy\n\n# Merge entire PDFs\nParxy.pdf.merge(\n    inputs=[\n        (Path(\"doc1.pdf\"), None, None),  # All pages\n        (Path(\"doc2.pdf\"), None, None),\n    ],\n    output=Path(\"merged.pdf\"),\n)\n\n# Merge specific page ranges (0-indexed)\nParxy.pdf.merge(\n    inputs=[\n        (Path(\"doc1.pdf\"), 0, 4),   # Pages 1-5\n        (Path(\"doc2.pdf\"), 0, 0),   # Page 1 only\n    ],\n    output=Path(\"selected.pdf\"),\n)\n```\n\n### Split PDF\n\n```python\n# Split into individual pages\npages = Parxy.pdf.split(\n    input_path=Path(\"document.pdf\"),\n    output_dir=Path(\"./pages\"),\n    prefix=\"doc\",\n)\n# Returns: [Path(''pages/doc_page_1.pdf''), Path(''pages/doc_page_2.pdf''), ...]\n```\n\n### Optimize PDF\n\n```python\nresult = Parxy.pdf.optimize(\n    input_path=Path(\"large.pdf\"),\n    output_path=Path(\"small.pdf\"),\n    scrub_metadata=True,      # Remove metadata, thumbnails\n    subset_fonts=True,        # Keep only used glyphs\n    compress_images=True,     # Downsample and compress\n    dpi_target=72,\n    image_quality=60,\n    convert_to_grayscale=False,\n)\nprint(f\"Reduced by {result[''reduction_percent'']:.1f}%\")\n```\n\n## PDF Attachments\n\n```python\nfrom pathlib import Path\nfrom parxy_core.services.pdf_service import PdfService\n\nwith PdfService(Path(\"document.pdf\")) as pdf:\n    # List attachments\n    names = pdf.list_attachments()\n\n    # Add attachment\n    pdf.add_attachment(Path(\"data.csv\"), name=\"data\", desc=\"Sales data\")\n\n    # Extract attachment\n    content = pdf.extract_attachment(\"data\")\n\n    # Remove attachment\n    pdf.remove_attachment(\"data\")\n\n    # Save changes\n    pdf.save(Path(\"output.pdf\"))\n```\n\n## CLI Commands\n\nAssuming uvx is installed, pipx can be used as well.\n\n```bash\n# Parse document\nuvx parxy parse document.pdf --driver llamaparse --level block --format json\n\n# Convert to markdown\nuvx parxy markdown document.pdf -o output/\nuvx parxy markdown *.pdf --combine -o combined.md\n\n# PDF operations\nuvx parxy pdf split document.pdf --pages 1-5 -o output/\nuvx parxy pdf merge doc1.pdf doc2.pdf -o combined.pdf\n\n# List drivers\nuvx parxy drivers\n```\n"},"lastSynced":"2026-03-08T02:00:19.856Z","agentAnalysis":{"suitability":{"en":"Perfect for Document Analysis Agents needing unified document parsing capabilities with drivers like pymupdf and llamaparse.","zh":"非常适合需要统一文档解析能力的文档分析代理，支持像pymupdf和llamaparse这样的驱动程序。","ja":"ドキュメント分析エージェントが統一されたドキュメント解析機能を必要とする場合に最適で、pymupdfやllamaparseのようなドライバーをサポートしています。","ko":"문서 분석 에이전트가統一된 문서 파싱 기능을 필요로 할 때 적합하며, pymupdf 및 llamaparse와 같은 드라이버를 지원합니다.","es":"Perfecto para Agentes de Análisis de Documentos que necesitan capacidades de análisis de documentos unificadas con controladores como pymupdf y llamaparse.","fr":"Parfait pour les Agents d''Analyse de Documents ayant besoin de capacités d''analyse de documents unifiées avec des pilotes comme pymupdf et llamaparse.","de":"Perfekt für Dokumentenanalyse-Agenten, die einheitliche Dokumentenanalysefunktionen mit Treibern wie pymupdf und llamaparse benötigen.","pt":"Perfeito para Agentes de Análise de Documentos que necessitam de capacidades de análise de documentos unificados com drivers como pymupdf e llamaparse.","ru":"Идеально подходит для Агентов Анализа Документов, требующих объединенных возможностей парсинга документов с драйверами seperti pymupdf и llamaparse.","ar":"مثالي لعمليات تحليل الوثائق التي تحتاج إلى возможات تحليل الوثائق الموحدة مع السائقين مثل pymupdf و llamaparse."},"recommendation":{"en":"Empowers agents to parse documents at various levels, including page, block, and span, using libraries like parxy_core, facilitating advanced document processing and analysis with PDF files and bytes or BytesIO inputs.","zh":"赋予代理在不同级别（包括页面、块和跨度）解析文档的能力，使用像parxy_core这样的库，能够实现高级文档处理和分析，支持PDF文件和字节或BytesIO输入。","ja":"エージェントがページ、ブロック、スパンなどのさまざまなレベルでドキュメントを解析できるようにし、parxy_coreなどのライブラリを使用して、PDFファイルやバイトまたはBytesIO入力をサポートする高度なドキュメント処理と分析を可能にします。","ko":"에이전트가 페이지, 블록, 스팬 등의 다양한 레벨에서 문서를 파싱할 수 있는 능력을 부여하며, parxy_core와 같은 라이브러리를 사용하여 PDF 파일 및 바이트 또는 BytesIO 입력을 지원하는 고급 문서 처리 및 분석을 가능하게 합니다.","es":"Permite a los agentes analizar documentos en varios niveles, incluyendo página, bloque y span, utilizando bibliotecas como parxy_core, lo que facilita un procesamiento y análisis de documentos avanzados con archivos PDF y bytes o entradas BytesIO.","fr":"Permet aux agents d''analyser des documents à différents niveaux, notamment page, bloc et span, en utilisant des bibliothèques comme parxy_core, ce qui facilite un traitement et une analyse de documents avancés avec des fichiers PDF et des octets ou des entrées BytesIO.","de":"Ermöglicht es Agenten, Dokumente auf verschiedenen Ebenen zu analysieren, einschließlich Seite, Block und Span, unter Verwendung von Bibliotheken wie parxy_core, was ein erweitertes Dokumentenverarbeitung und -analyse mit PDF-Dateien und Bytes oder BytesIO-Eingaben ermöglicht.","pt":"Habilita os agentes a analisar documentos em vários níveis, incluindo página, bloco e span, usando bibliotecas como parxy_core, facilitando o processamento e análise avançados de documentos com arquivos PDF e bytes ou BytesIO.","ru":"Наделяет агентов возможностью парсить документы на различных уровнях, включая страницу, блок и диапазон, используя библиотеки seperti parxy_core, что облегчает продвинутую обработку и анализ документов с файлами PDF и байтами или входами BytesIO.","ar":"يمنح الوكلاء القدرة على تحليل الوثائق على مستويات مختلفة، بما في ذلك الصفحة والكتلة والمدى، باستخدام مكتبات مثل parxy_core، مما يسهل المعالجة والتحليل المتقدمين للوثائق مع ملفات PDF وBytes أو مدخلات BytesIO."},"useCases":{"en":["Parsing PDF documents for text extraction","Analyzing documents at different levels, such as block or span","Integrating document parsing with other AI tasks using parxy_core"],"zh":["解析PDF文档以提取文本","在不同的级别（如块或跨度）分析文档","使用parxy_core将文档解析与其他AI任务集成"],"ja":["テキスト抽出のためにPDFドキュメントを解析する","ブロックやスパンのようなさまざまなレベルでドキュメントを分析する","parxy_coreを使用してドキュメント解析を他のAIタスクと統合する"],"ko":["텍스트 추출을 위한 PDF 문서 파싱","블록 또는 스팬과 같은 다양한 레벨에서 문서 분석","parxy_core를 사용하여 문서 파싱을 다른 AI 태스크와 통합"],"es":["Análisis de documentos PDF para extracción de texto","Análisis de documentos en diferentes niveles, como bloque o span","Integración de análisis de documentos con otras tareas de IA utilizando parxy_core"],"fr":["Analyse de documents PDF pour extraction de texte","Analyse de documents à différents niveaux, tels que bloc ou span","Intégration de l''analyse de documents avec d''autres tâches d''IA en utilisant parxy_core"],"de":["Analyse von PDF-Dokumenten zur Textextraktion","Analyse von Dokumenten auf verschiedenen Ebenen, wie Block oder Span","Integration der Dokumentenanalyse mit anderen KI-Aufgaben unter Verwendung von parxy_core"],"pt":["Análise de documentos PDF para extração de texto","Análise de documentos em diferentes níveis, como bloco ou span","Integração da análise de documentos com outras tarefas de IA usando parxy_core"],"ru":["Парсинг документов PDF для извлечения текста","Анализ документов на различных уровнях, таких как блок или диапазон","Интеграция парсинга документов с другими задачами ИИ с помощью parxy_core"],"ar":["تحليل وثائق PDF لاستخراج النص","تحليل الوثائق على مستويات مختلفة، مثل الكتلة أو المدى","دمج تحليل الوثائق مع مهام الذكاء الاصطناعي الأخرى باستخدام parxy_core"]},"limitations":{"en":["Requires parxy_core library","Limited to supported drivers like pymupdf and llamaparse","Python compatibility required"],"zh":["需要parxy_core库","仅限支持的驱动程序，如pymupdf和llamaparse","需要Python兼容性"],"ja":["parxy_coreライブラリが必要","pymupdfやllamaparseのようなサポートされているドライバーのみ","Pythonの互換性が必要"],"ko":["parxy_core 라이브러리가 필요","pymupdf 및 llamaparse와 같은 지원되는 드라이버만","Python 호환성이 필요"],"es":["Requiere la biblioteca parxy_core","Limitado a controladores compatibles como pymupdf y llamaparse","Se requiere compatibilidad con Python"],"fr":["Nécessite la bibliothèque parxy_core","Limité aux pilotes pris en charge comme pymupdf et llamaparse","Compatibilité Python requise"],"de":["Benötigt die parxy_core-Bibliothek","Begrenzt auf unterstützte Treiber wie pymupdf und llamaparse","Python-Kompatibilität erforderlich"],"pt":["Requer a biblioteca parxy_core","Limitado aos drivers compatíveis como pymupdf e llamaparse","Compatibilidade com Python necessária"],"ru":["Требует библиотеки parxy_core","Ограничен поддерживаемыми драйверами như pymupdf и llamaparse","Требуется совместимость с Python"],"ar":["يتطلب مكتبة parxy_core","محدود بالسائقين المدعومين مثل pymupdf و llamaparse","متطلبات التوافق مع Python"]},"version":4},"contentHash":"67bf568e2de681e308876d915bedcfe28ee4cf73361e2a5763be3f2eb97c21c5","qualityScore":42}');
