INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('OneOffTech/parxy/parxy', 'parxy', 'OneOffTech', 'parxy', 'community', 'parxy OneOffTech parxy community Parxy is a document processing gateway that provides a unified model for accessing different parsers. It benefits developers by simplifying document parsing tasks. Parxy 是一个文档处理网关，提供统一的模型访问不同解析器。使用 Parxy，您可以轻松地解析文档，并提取所需的信息。 Parxy はドキュメント処理ゲートウェイであり、統一されたモデルでさまざまなパーサーにアクセスできます。Parxy を使用すると、ドキュメントを解析して必要な情報を抽出できます。 Parxy는 문서 처리 게이트웨이로서,統一された 모델로 다양한 파서에 액세스할 수 있습니다. Parxy를 사용하면 문서를 파싱하고 필요한 정보를 추출할 수 있습니다. Parxy es una puerta de enlace de procesamiento de documentos que permite acceder a diferentes parseadores utilizando un modelo unificado Parxy est une passerelle de traitement de documents qui permet d''accéder à différents parseurs en utilisant un modèle unifié Parxy ist eine Dokumentenverarbeitungsgateway, das den Zugriff auf verschiedene Parser mittels eines einheitlichen Modells ermöglicht O Parxy é uma gateway de processamento de documentos que permite acessar diferentes parsers usando um modelo unificado. Isso facilita a extração de informações de documentos em diferentes formatos. Parxy - это шлюз обработки документов, который позволяет доступ к разным парсерам с помощью единой модели. Это упрощает извлечение информации из документов в разных форматах. Parxy هو بوابة معالجة الوثائق التي تمكن الوصول إلى محركات فك ترميز مختلفة باستخدام نموذج موحد. هذا يسهل استخراج المعلومات من الوثائق بأساليب مختلفة. how to use parxy parxy alternative parxy install parxy setup guide what is parxy parxy vs pymupdf document parsing gateway unified document parsing parxy documentation Parxy 文档处理网关 文档解析 统一模型 pymupdf llamaparse Python 开发 文档处理 AI 工具 AI 解析 Supports parsing of PDF documents using pymupdf and llamaparse drivers Offers flexible extraction levels, including page, block, and span levels Allows parsing from bytes or BytesIO for efficient data processing Provides a unified model for accessing different parsers Enables specific driver and level selection for customized parsing parxy is a document processing gateway that enables unified access to various parsers for efficient document parsing');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('pmndrs/koota/koota', 'community', 'pmndrs', 'koota', 'pmndrs/koota', 'koota', 0, 0, 42, '2026-03-08T01:57:15.274Z', '2026-03-08T02:00:35.529Z', '7d75390892021b7230b21fd3e34342996508fa1b2346bcab2a583de187a2ef09', '{"id":"pmndrs/koota/koota","name":"koota","description":{"en":"Koota is a performant real-time state management system for React and TypeScript, utilizing entities with composable traits for efficient data management. It benefits developers seeking optimized state handling in their applications.","zh":"Koota 是一个为 React 和 TypeScript 提供实时状态管理的高性能解决方案，使用实体和特征进行状态管理","ja":"Koota は React と TypeScript のためのリアルタイム状態管理を提供する高パフォーマンスなソリューションで、エンティティと特性を使用して状態管理を行います","ko":"Koota 는 React 및 TypeScript 를 위한 실시간 상태 관리를 제공하는 고성능 솔루션으로 엔티티와 특성을 사용하여 상태 관리를 수행합니다","es":"Koota es una herramienta de gestión de estado en tiempo real para React y TypeScript que utiliza entidades con rasgos componibles.","fr":"Koota est un outil de gestion d''état en temps réel pour React et TypeScript qui utilise des entités avec des traits composables.","de":"Koota ist ein Tool für die performante Echtzeit-Zustandsverwaltung mit React und TypeScript, das Entitäten mit komponierbaren Eigenschaften verwendet.","pt":"Koota é uma solução de gerenciamento de estado em tempo real para React e TypeScript, utilizando entidades com traits compostáveis","ru":"Koota - это решение для управления состоянием в реальном времени для React и TypeScript, использующее сущности с составными чертами","ar":"كوتا هو حل لتدبير الحالة في الوقت الفعلي للرياكت و타입스크립트، يستخدم الكيانات مع سمات قابلة للتكوين"},"seo":{"title":{"en":"Koota: Performant Real-Time State Management for React an...","zh":"Koota 性能优化实时状态管理指南","ja":"Koota のリアルタイム状態管理ベストプラクティス","ko":"Koota 실시간 상태 관리 설정 가이드","es":"Guía de configuración de Koota para gestión de estado en ...","fr":"Guide de 