INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('pmndrs/koota/koota', 'koota', 'pmndrs', 'koota', 'community', 'koota pmndrs koota community Koota is a performant real-time state management system for React and TypeScript, utilizing entities with composable traits for efficient data management. It benefits developers seeking optimized state handling in their applications. Koota 是一个为 React 和 TypeScript 提供实时状态管理的高性能解决方案，使用实体和特征进行状态管理 Koota は React と TypeScript のためのリアルタイム状態管理を提供する高パフォーマンスなソリューションで、エンティティと特性を使用して状態管理を行います Koota 는 React 및 TypeScript 를 위한 실시간 상태 관리를 제공하는 고성능 솔루션으로 엔티티와 특성을 사용하여 상태 관리를 수행합니다 Koota es una herramienta de gestión de estado en tiempo real para React y TypeScript que utiliza entidades con rasgos componibles. Koota est un outil de gestion d''état en temps réel pour React et TypeScript qui utilise des entités avec des traits composables. Koota ist ein Tool für die performante Echtzeit-Zustandsverwaltung mit React und TypeScript, das Entitäten mit komponierbaren Eigenschaften verwendet. Koota é uma solução de gerenciamento de estado em tempo real para React e TypeScript, utilizando entidades com traits compostáveis Koota - это решение для управления состоянием в реальном времени для React и TypeScript, использующее сущности с составными чертами كوتا هو حل لتدبير الحالة في الوقت الفعلي للرياكت و타입스크립트، يستخدم الكيانات مع سمات قابلة للتكوين how to use koota koota vs redux koota install guide what is koota koota react integration koota typescript support koota state management koota entity component system Koota 实时状态管理 React TypeScript 实体 特征 高性能 状态管理解决方案 Manages state using entities with composable traits Supports schema-based (SoA) and callback-based (AoS) trait definitions Enables directional connections between entities via relations Utilizes archetypes for unique combinations of traits Provides a world context for all entities and their data Koota is a state management system that uses entities with composable traits, relations, and archetypes to manage data in React and TypeScript applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('glittercowboy/taches-cc-resources/create-mcp-servers', 'community', 'glittercowboy', 'taches-cc-resources', 'glittercowboy/taches-cc-resources', 'create-mcp-servers', 0, 0, 42, '2026-03-08T01:57:15.275Z', '2026-03-08T02:00:38.297Z', 'c774949f6c1b714f2817149634f40343628cdd8946edea9d38801b68b7830089', '{"id":"glittercowboy/taches-cc-resources/create-mcp-servers","name":"create-mcp-servers","description":{"en":"The create-mcp-servers skill helps developers create production-ready MCP servers with API integrations and OAuth authentication, making it easier to expose tools and resources.","zh":"本技能指导如何创建生产就绪的MCP服务器，包括API集成、OAuth认证、响应优化和正确的安装","ja":"このスキルでは、MCPサーバーの作成方法を学び、API統合、OAuth認証、レスポンス最適化などを実現する","ko":"이 스킬은 생산 준비가 된 MCP 서버를 생성하는 방법을指导합니다. API 통합, OAuth 인증, 응답 최적화 등","es":"Esta habilidad proporciona una guía para la creación de servidores MCP de producción con integraciones de API, autenticación OAuth y optimización de respuestas","fr":"Cette compétence fournit un guide pour la création de serveurs MCP de production avec des intégrations d''API, une authentification OAuth et une optimisation des réponses","de":"Diese Fähigkeit bietet eine Anleitung für die Erstellung von MCP-Servern mit API-Integrationen, OAuth-Authentifizierung und Antwortoptimierung","pt":"Crie servidores MCP personalizados com recursos avançados de API e autenticação","ru":"Создайте серверы MCP с расширенными возможностями API и аутентификации","ar":"أنشئ خوادم MCP مخصصة مع موارد متقدمة من واجهة برمجة التطبيقات والتحقق"},"seo":{"title":{"en":"create-mcp-servers: Production-Ready Setup Guide | AI Age...","zh":"创建MCP服务器设置指南","ja":"MCPサーバー作成ベストプラクティス","ko":"MCP 서버 생성.setup 가이드","es":"Guía de configuración de servidores MCP para Agentes de IA","fr":"Guide de création de serveurs MCP pour les outils d''IA","de":"Einrichtungsleitfaden für MCP-Server für KI-Tools","pt":"Guia de Configuração de Servidores MCP - Melhores Práticas","ru":"Настройка Серверов MCP - Руководство по Созданию","ar":"دليل إعداد خوادم MCP - إرشادات وتحسينات"},"description":{"en":"Unlock efficient MCP server creation with our expert guide. Learn how to expose tools and resources with API integrations and OAuth authentication.","zh":"了解如何创建生产就绪的MCP服务器，包括API集成、OAuth认证和响应优化","ja":"MCPサーバーの作成方法を学び、API統合、OAuth認証、レスポンス最適化などを実現する","ko":"생산 준비가 된 MCP 서버를 생성하는 방법에 대해 알아보세요. API 통합, OAuth 인증, 응답 최적화 등","es":"Aprende a crear servidores MCP para ampliar las capacidades de Claude con API, autenticación OAuth y optimización de respuestas","fr":"Découvrez comment créer des serveurs MCP pour étendre les capacités de Claude avec API, authentification OAuth et optimisation des réponses","de":"Erfahren Sie, wie Sie MCP-Server erstellen, um die Fähigkeiten von Claude mit API, OAuth-Authentifizierung und Antwortoptimierung zu erweitern","pt":"Aprenda a criar servidores MCP personalizados com integração de API, autenticação OAuth e otimização de resposta","ru":"Создайте серверы MCP с интеграцией API, аутентификацией OAuth и оптимизацией ответов","ar":"تعلم كيفية إنشاء خوادم MCP مخصصة مع دمج واجهة برمجة التطبيقات وتحقق OAuth وتحسين الاستجابة"},"definition":{"en":"create-mcp-servers is a collection of resources for creating custom MCP servers with Claude Code and Claude Desktop.","zh":"MCP服务器是一种扩展Claude功能的工具，提供API集成、OAuth认证和响应优化","ja":"MCPサーバーは、Claudeの機能を拡張するツールであり、API統合、OAuth認証、レスポンス最適化を提供する","ko":"MCP 서버는 Claude의 기능을 확장하는 도구로, API 통합, OAuth 인증, 응답 최적화를 제공합니다","es":"Un servidor MCP es un recurso personalizado que amplía las capacidades de Claude","fr":"Un serveur MCP est une ressource personnalisée qui étend les capacités de Claude","de":"Ein MCP-Server ist eine benutzerdefinierte Ressource, die die Fähigkeiten von Claude erweitert","pt":"Um servidor MCP é um recurso que estende as capacidades de Claude com ferramentas e recursos personalizados","ru":"Сервер MCP - это ресурс, который расширяет возможности Claude с помощью индивидуальных инструментов и ресурсов","ar":"خادم MCP هو مورد يوسع قدرات Claude مع أدوات ووسائل مخصصة"},"features":{"en":["Exposes tools and resources through API integrations","Implements OAuth authentication for secure server setup","Optimizes responses for efficient server performance","Utilizes ${VAR} expansion in configs for secure secret management","Leverages the `cwd` property for proper server installation","Supports installation in Claude Code and Claude Desktop"],"zh":["API集成","OAuth认证","响应优化","正确的安装","使用cwd属性","Never Hardcode Secrets"],"ja":["API統合","OAuth認証","レスポンス最適化","正しいインストール","cwd属性の使用","シークレットをハードコーディングしない"],"ko":["API 통합","OAuth 인증","응답 최적화","올바른 설치","cwd 속성 사용","시크릿을 하드코딩하지 않음"],"es":["Integraciones de API para ampliar las capacidades de Claude","Autenticación OAuth para asegurar el acceso a los servidores","Optimización de respuestas para mejorar el rendimiento","Uso de la propiedad `cwd` para configurar el servidor","Expansion de variables en configuraciones con `${VAR}`"],"fr":["Intégrations d''API pour étendre les capacités de Claude","Authentification OAuth pour sécuriser l''accès aux serveurs","Optimisation des réponses pour améliorer les performances","Utilisation de la propriété `cwd` pour configurer le serveur","Expansion de variables dans les configurations avec `${VAR}`"],"de":["API-Integrationen, um die Fähigkeiten von Claude zu erweitern","OAuth-Authentifizierung, um den Zugriff auf die Server zu sichern","Antwortoptimierung, um die Leistung zu verbessern","Verwendung der Eigenschaft `cwd`, um den Server zu konfigurieren","Expansion von Variablen in Konfigurationen mit `${VAR}`"],"pt":["Integração de API para expansão de funcionalidades","Autenticação OAuth para segurança avançada","Otimização de resposta para melhor desempenho","Uso de variáveis de ambiente para segurança","Propriedade ''cwd'' para configuração flexível"],"ru":["Интеграция API для расширения функциональности","Аутентификация OAuth для повышенной безопасности","Оптимизация ответов для лучшей производительности","Использование переменных окружения для безопасности","Свойство ''cwd'' для гибкой конфигурации"],"ar":["دمج واجهة برمجة التطبيقات لتوسيع الوظائف","تحقق OAuth لأمان متقدم","تحسين الاستجابة لأداء أفضل","استخدام متغيرات البيئة لأمان","خاصية ''cwd'' لتهيئة مرنة"]},"keywords":{"en":["how to create mcp servers","create-mcp-servers setup guide","mcp server api integrations","oauth authentication for mcp servers","create-mcp-servers vs claude code","create-mcp-servers install","mcp server response optimization","create-mcp-servers tutorial","what is create-mcp-servers","create-mcp-servers alternative"],"zh":["MCP服务器","AIエージェント","API集成","OAuth认证","响应优化","Claude Code","Claude Desktop","创建MCP服务器"],"ja":["MCPサーバー","AIエージェント","API統合","OAuth認証","レスポンス最適化","Claude Code","Claude Desktop","MCPサーバーの作成"],"ko":["MCP 서버","AI 도구","API 통합","OAuth 인증","응답 최적화","Claude Code","Claude Desktop","MCP 서버 생성"],"es":["servidores MCP","Agentes de IA","API integraciones","autenticación OAuth","optimización de respuestas"," Claude Code","desarrollo de servidores","integraciones de API"],"fr":["serveurs MCP","outils d''IA","intégrations d''API","authentification OAuth","optimisation des réponses","Claude Code","développement de serveurs","intégrations d''API"],"de":["MCP-Server","KI-Tools","API-Integrationen","OAuth-Authentifizierung","Antwortoptimierung","Claude Code","Serverentwicklung","API-Integrationen"],"pt":["servidores MCP","criação de servidores MCP","integração de API","autenticação OAuth","otimização de resposta","desenvolvimento de servidores MCP","ferramentas de desenvolvimento MCP","recursos de servidores MCP"],"ru":["серверы MCP","создание серверов MCP","интеграция API","аутентификация OAuth","оптимизация ответов","разработка серверов MCP","инструменты разработки MCP","ресурсы серверов MCP"],"ar":["خوادم MCP","إنشاء خوادم MCP","دمج واجهة برمجة التطبيقات","تحقق OAuth","تحسين الاستجابة","تطوير خوادم MCP","أدوات تطوير MCP","موارд خوادم MCP"]}},"owner":"glittercowboy","repo":"taches-cc-resources","repoPath":"glittercowboy/taches-cc-resources","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.275Z","topics":[],"category":"community","skillMd":{"name":"create-mcp-servers","description":"Create Model Context Protocol (MCP) servers that expose tools, resources, and prompts to Claude. Use when building custom integrations, APIs, data sources, or any server that Claude should interact with via the MCP protocol. Supports both TypeScript and Python implementations.","bodyPreview":"<objective>\nMCP servers extend Claude''s capabilities by exposing tools, resources, and prompts. This skill guides creation of production-ready MCP servers with API integrations, OAuth authentication, response optimization, and proper installation in Claude Code and Claude Desktop.\n</objective>\n\n<essential_principles>\n\n<the_5_rules>\nEvery MCP server must follow these:\n\n1. **Never Hardcode Secrets** - Use `${VAR}` expansion in configs, environment variables in code\n2. **Use `cwd` Property** - Isol","body":"<objective>\nMCP servers extend Claude''s capabilities by exposing tools, resources, and prompts. This skill guides creation of production-ready MCP servers with API integrations, OAuth authentication, response optimization, and proper installation in Claude Code and Claude Desktop.\n</objective>\n\n<essential_principles>\n\n<the_5_rules>\nEvery MCP server must follow these:\n\n1. **Never Hardcode Secrets** - Use `${VAR}` expansion in configs, environment variables in code\n2. **Use `cwd` Property** - Isolates dependencies (not `--cwd` in args)\n3. **Always Absolute Paths** - `which uv` to find paths, never relative\n4. **One Server Per Directory** - `~/Developer/mcp/{server-name}/`\n5. **Use `uv` for Python** - Better than pip, handles venvs automatically\n</the_5_rules>\n\n<security_checklist>\n- Never ask user to paste secrets into chat\n- Always use environment variables for credentials\n- Use ${VAR} expansion in configs\n- Provide exact commands for user to run in terminal\n- Verify environment variable existence without showing values\n- Never hardcode API keys in code or configs\n</security_checklist>\n\n<architecture_decision>\nOperation count determines architecture:\n\n- **1-2 operations** → Traditional pattern (flat tools)\n- **3+ operations** → On-demand discovery pattern (meta-tools)\n\nTraditional: Each operation is a separate tool\nOn-demand: 4 meta-tools (discover, get_schema, execute, continue) + operations.json\n</architecture_decision>\n\n<context>\nMCP servers expose:\n- **Tools**: Functions Claude can call (API requests, file operations, calculations)\n- **Resources**: Data Claude can read (files, database records, API responses)\n- **Prompts**: Reusable prompt templates with arguments\n\nStandard location: `~/Developer/mcp/{server-name}/`\n</context>\n\n</essential_principles>\n\n<routing>\nBased on user intent, route to appropriate workflow:\n\n**No context provided** (skill invoked without description):\nUse AskUserQuestion:\n- header: \"Mode\"\n- question: \"What would you like to do?\"\n- options:\n  - \"Create a new MCP server\" → workflows/create-new-server.md\n  - \"Update an existing MCP server\" → workflows/update-existing-server.md\n  - \"Troubleshoot a server\" → workflows/troubleshoot-server.md\n\n**Context provided** (user described what they want):\nRoute directly to workflows/create-new-server.md\n</routing>\n\n<workflows_index>\n| Workflow | Purpose |\n|----------|---------|\n| create-new-server.md | Full 8-step workflow from intake to verification |\n| update-existing-server.md | Modify or extend an existing server |\n| troubleshoot-server.md | Diagnose and fix connection/runtime issues |\n</workflows_index>\n\n<templates_index>\n| Template | Purpose |\n|----------|---------|\n| python-server.py | Traditional pattern starter for Python |\n| typescript-server.ts | Traditional pattern starter for TypeScript |\n| operations.json | On-demand discovery operations definition |\n</templates_index>\n\n<scripts_index>\n| Script | Purpose |\n|--------|---------|\n| setup-python-project.sh | Initialize Python MCP project with uv |\n| setup-typescript-project.sh | Initialize TypeScript MCP project with npm |\n</scripts_index>\n\n<references_index>\n**Core workflow:**\n- creation-workflow.md - Complete step-by-step with exact commands\n\n**Architecture patterns:**\n- traditional-pattern.md - For 1-2 operations (flat tools)\n- large-api-pattern.md - For 3+ operations (on-demand discovery)\n\n**Language-specific:**\n- python-implementation.md - Async patterns, type hints\n- typescript-implementation.md - Type safety, SDK features\n\n**Advanced topics:**\n- oauth-implementation.md - OAuth with stdio isolation\n- response-optimization.md - Field truncation, pagination\n- tools-and-resources.md - Resources API, prompts, streaming\n- testing-and-deployment.md - Unit tests, packaging, publishing\n- validation-checkpoints.md - All validation checks\n- adaptive-questioning-guide.md - Question templates for intake\n- api-research-template.md - API research document format\n</references_index>\n\n<quick_reference>\n```bash\n# List servers\nclaude mcp list\n\n# Add server (Python)\nclaude mcp add --transport stdio <name> \\\n  --env API_KEY=''${API_KEY}'' \\\n  -- uv --directory ~/Developer/mcp/<name> run python -m src.server\n\n# Add server (TypeScript)\nclaude mcp add --transport stdio <name> \\\n  --env API_KEY=''${API_KEY}'' \\\n  -- node ~/Developer/mcp/<name>/build/index.js\n\n# Remove server\nclaude mcp remove <name>\n\n# Check logs\ntail -f ~/Library/Logs/Claude/mcp-server-<name>.log\n\n# Find paths\nwhich uv && which node && which python\n```\n</quick_reference>\n\n<troubleshooting_quick>\n**Server not appearing:** Check `claude mcp list`, verify config in `~/.claude/settings.json`\n\n**\"command not found\":** Use absolute paths from `which uv` / `which node`\n\n**Environment variable not found:**\n```bash\necho $MY_API_KEY  # Check if set\necho ''export MY_API_KEY=\"value\"'' >> ~/.zshrc && source ~/.zshrc\n```\n\n**Secrets visible in conversation:** STOP. Delete conversation. Rotate credentials. Never paste secrets in chat.\n\nFull troubleshooting: workflows/troubleshoot-server.md\n</troubleshooting_quick>\n\n<success_criteria>\nA production-ready MCP server has:\n- Valid configuration in Claude Code (`claude mcp list` shows ✓ Connected)\n- Valid configuration in Claude Desktop config\n- Environment variables set securely in ~/.zshrc\n- Architecture matches operation count\n- OAuth stdio isolation if applicable\n- Response optimization for list/search operations\n- All validation checkpoints passed\n- No errors in logs\n</success_criteria>\n"},"lastSynced":"2026-03-08T02:00:38.297Z","agentAnalysis":{"suitability":{"en":"Perfect for Advanced AI Agents like Claude Code and AutoGPT needing to create production-ready MCP servers with API integrations and OAuth authentication","zh":"非常适合需要创建生产就绪的MCP服务器、API集成和OAuth身份验证的高级AI代理，如Claude Code和AutoGPT","ja":"Claude CodeやAutoGPTのようなAPI統合やOAuth認証を備えた本稼働可能なMCPサーバーを作成する必要がある高度なAIエージェントに最適","ko":"Claude Code와 AutoGPT 같은 고급 AI 에이전트에 적합하며, API 통합 및 OAuth 인증과 함께 생산 준비가 된 MCP 서버를 생성해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de IA Avanzados como Claude Code y AutoGPT que necesitan crear servidores MCP de producción listos con integraciones de API y autenticación OAuth","fr":"Parfait pour les Agents de l''IA Avancés comme Claude Code et AutoGPT ayant besoin de créer des serveurs MCP prêts pour la production avec des intégrations d''API et une authentification OAuth","de":"Perfekt für erweiterte KI-Agents wie Claude Code und AutoGPT, die produktionsbereite MCP-Server mit API-Integrationen und OAuth-Authentifizierung erstellen müssen","pt":"Perfeito para Agentes de IA Avançados como Claude Code e AutoGPT que precisam criar servidores MCP de produção com integrações de API e autenticação OAuth","ru":"Идеально для продвинутых агентов ИИ, таких как Claude Code и AutoGPT, которые нуждаются в создании серверов MCP, готовых к производству, с интеграциями API и аутентификацией OAuth","ar":"مثالي للوكلاء الذكاء الاصطناعي المتقدم مثل Claude Code و AutoGPT الذين يحتاجون إلى إنشاء خوادم MCP جاهزة للإنتاج مع دمج واجهة برمجة التطبيقات وأمان OAuth"},"recommendation":{"en":"Empowers agents to expose tools and resources with optimized response handling, utilizing environment variables for secure secret management and leveraging the `cwd` property for effective server configuration, all while integrating with OAuth for robust authentication protocols","zh":"赋予代理以优化的响应处理能力，利用环境变量进行安全的密钥管理，并利用`cwd`属性进行有效的服务器配置，同时与OAuth集成以提供强大的身份验证协议","ja":"エージェントにツールやリソースを公開する能力を与え、環境変数を使用したセキュアなシークレット管理や`cwd`プロパティを使用した効果的なサーバー構成を実現し、同時にOAuthと統合して強力な認証プロトコルを提供","ko":"에이전트에게 최적화된 응답 처리 능력을 부여하고 환경 변수를 사용하여 보안 비밀 관리를 수행하며, `cwd` 속성을 사용하여 효과적인 서버 구성이 가능하도록 하며,同時に OAuth와 통합하여 강력한 인증 프로토콜을 제공합니다.","es":"Habilita a los agentes a exponer herramientas y recursos con un manejo de respuestas optimizado, utilizando variables de entorno para una gestión segura de secretos y aprovechando la propiedad `cwd` para una configuración de servidor efectiva, todo mientras se integra con OAuth para protocolos de autenticación robustos","fr":"Permet aux agents d''exposer des outils et des ressources avec une gestion de réponses optimisée, en utilisant des variables d''environnement pour une gestion sécurisée des secrets et en exploitant la propriété `cwd` pour une configuration de serveur efficace, le tout tout en s''intégrant avec OAuth pour des protocoles d''authentification robustes","de":"Ermöglicht es Agents, Tools und Ressourcen mit optimierter Antwortverarbeitung zu exponieren, indem Umgebungsvariablen für eine sichere Geheimnisverwaltung verwendet werden und die Eigenschaft `cwd` für eine effektive Serverkonfiguration genutzt wird, all dies während der Integration mit OAuth für robuste Authentifizierungsprotokolle","pt":"Habilita os agentes a expor ferramentas e recursos com tratamento de respostas otimizado, utilizando variáveis de ambiente para gerenciamento seguro de segredos e aproveitando a propriedade `cwd` para configuração eficaz do servidor, tudo isso integrando com OAuth para protocolos de autenticação robustos","ru":"Наделяет агентов возможностью экспонировать инструменты и ресурсы с оптимизированной обработкой ответов, используя переменные окружения для безопасного управления секретами и利用уя свойство `cwd` для эффективной конфигурации сервера, все это интегрируя с OAuth для протоколов аутентификации","ar":"يمنح الوكلاء القدرة على إظهار الأدوات والموارد مع معالجة استجابة محسنة، مع استخدام متغيرات البيئة لإدارة السر المحفوظ بشكل آمن وتحقيق خاصية `cwd` لتكوين الخادم الفعال، مع دمج واجهة برمجة التطبيقات لأمان OAuth"},"useCases":{"en":["Automating MCP server setup for scalable tool exposure","Generating production-ready API integrations with secure OAuth authentication","Optimizing response handling for enhanced user experience in Claude Desktop and Claude Code"],"zh":["为可扩展工具公开自动化MCP服务器设置","生成生产就绪的API集成和安全的OAuth身份验证","在Claude Desktop和Claude Code中优化响应处理以增强用户体验"],"ja":["拡張可能なツール公開のためのMCPサーバー設定の自動化","本稼働可能なAPI統合とセキュアなOAuth認証の生成","Claude DesktopとClaude Codeでのレスポンス処理の最適化によるユーザーエクスペリエンスの向上"],"ko":["확장 가능한 툴公开을 위한 MCP 서버 설정 자동화","생산 준비가 된 API 통합 및 보안 OAuth 인증 생성","Claude Desktop 및 Claude Code에서 응답 처리 최적화를 통한 사용자 경험 향상"],"es":["Automatizar la configuración del servidor MCP para una exposición de herramientas escalable","Generar integraciones de API de producción listas con autenticación OAuth segura","Optimizar el manejo de respuestas para una experiencia de usuario mejorada en Claude Desktop y Claude Code"],"fr":["Automatiser la configuration du serveur MCP pour une exposition d''outils scalable","Générer des intégrations d''API prêtes pour la production avec une authentification OAuth sécurisée","Optimiser la gestion des réponses pour une expérience 