INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('openjavis/openclaw-python/gog', 'gog', 'openjavis', 'openclaw-python', 'community', 'gog openjavis openclaw-python community The gog skill is a Python clone of OpenClaw, designed to manage GOG.com games libraries. It benefits developers and gamers by providing a set of standard tools for executing commands and fetching web content. GOG游戏库管理是一个Python版的OpenCLaw，用于管理GOG.com游戏库。它使用bash、read_file、write_file、web_fetch和web_search等工具来提供帮助 GOGゲームライブラリ管理は、GOG.comゲームライブラリを管理するために使用されるPython版OpenCLawです。bash、read_file、write_file、web_fetch、web_searchなどのツールを使用してヘルプを提供します GOG 게임 라이브러리 관리는 GOG.com 게임 라이브러리를 관리하기 위해 사용되는 Python OpenCLaw 클론입니다. bash, read_file, write_file, web_fetch, web_search 등의 도구를 사용하여 도움을 제공합니다 GOG es una herramienta de gestión de biblioteca de juegos basada en Python, que utiliza herramientas estándar como bash, read_file y web_fetch para proporcionar una respuesta útil GOG est un outil de gestion de bibliothèque de jeux basé sur Python, qui utilise des outils standard tels que bash, read_file et web_fetch pour fournir une réponse utile GOG ist ein Python-basiertes Tool für die Bibliotheksverwaltung von Spielen, das standardmäßige Tools wie bash, read_file und web_fetch verwendet, um eine nützliche Antwort zu liefern O GOG é um clone Python do OpenClaw para gerenciamento de bibliotecas de jogos. Ele utiliza ferramentas como bash, read_file, write_file, web_fetch e web_search. GOG - это клон OpenClaw на Python для управления библиотеками игр. Он использует инструменты seperti bash, read_file, write_file, web_fetch и web_search. GOG هو نسخة بايثون من OpenClaw لادارة مكتبات الألعاب. يستخدم أدوات مثل bash، read_file، write_file، web_fetch و web_search. how to use gog gog alternative gog vs openclaw gog install gog setup guide gog games library management what is gog gog python clone gog ai agent skill GOG游戏库管理 Python版OpenCLaw 游戏库管理工具 bash read_file write_file web_fetch web_search Executes commands using bash Reads files with the read_file tool Writes files using the write_file tool Fetches web content with the web_fetch tool Performs web searches with the web_search tool gog is a Python-based AI agent skill that clones OpenClaw''s functionality for managing GOG.com games libraries, utilizing tools like bash and web_fetch.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('HeadyMe/Heady-pre-production-9f2f0642/heady-code-generation', 'community', 'HeadyMe', 'Heady-pre-production-9f2f0642', 'HeadyMe/Heady-pre-production-9f2f0642', 'heady-code-generation', 1, 0, 42, '2026-03-07T21:47:25Z', '2026-03-08T02:00:48.041Z', 'ba936efbe88c877f3fb67a24785e3eb6d2c3c34c1a7fb8e1c71d36aace02121e', '{"id":"HeadyMe/Heady-pre-production-9f2f0642/heady-code-generation","name":"heady-code-generation","description":{"en":"The heady-code-generation skill is designed for developers to generate, transform, document, or refactor code using Heady''s specialized code agents, including mcp_Heady_heady_coder and mcp_Heady_heady_codex.","zh":"Heady 代码生成工具提供全面的代码生成、转换和重构功能，帮助开发者提高开发效率","ja":"Heady Code Generation AIエージェントは、コード生成、変換、リファクタリングをサポートする公式HeadySystems Inc.リポジトリです","ko":"Heady 코드 생성 스킬은 코드 생성, 변환, 리팩토링을 지원하는 공식 HeadySystems Inc. 저장소입니다","es":"Heady Code Generation es una habilidad para generar, transformar y documentar código mediante agentes de IA especializados","fr":"Heady Code Generation est une compétence pour générer, transformer et documenter du code à l''aide d''agents d''IA spécialisés","de":"Heady Code Generation ist eine Fähigkeit zur Generierung, Transformation und Dokumentation von Code durch spezialisierte IA-Agenten","pt":"O Heady Code Generation é uma ferramenta oficial da HeadySystems Inc. que permite gerar, transformar e documentar código de forma eficiente.","ru":"ИИ Агенты Heady Code Generation - официальный репозиторий HeadySystems Inc., предназначенный для генерации, трансформации и документации кода.","ar":"Heady Code Generation هو أداة رسمية من HeadySystems Inc. تمكن من إنشاء و تحويل و توثيق الكود بفعالية."},"seo":{"title":{"en":"heady-code-generation: Code Transformation Setup Guide | ...","zh":"Heady 代码生成工具：快速开发指南","ja":"Heady Code Generation AIエージェント：セットアップガイド","ko":"Heady 코드 생성 스킬: 개발자 가이드","es":"Guía de Configuración de Heady Code Generation para Agent...","fr":"Paramétrer Heady Code Generation pour les Outils d''IA","de":"Heady Code Generation Einrichten: Leitfaden für Entwickler","pt":"Guia de Configuração do Heady Code Generation para Desenv...","ru":"Настройка ИИ Агентов Heady Code Generation: Руководство","ar":"دليل إعداد Heady Code Generation لتنمية التطبيقات"},"description":{"en":"Discover how to leverage HeadySystems Inc.''s code generation tools for efficient code transformation, documentation, and refactoring - get started now!","zh":"Heady 代码生成工具帮助开发者快速生成、转换和重构代码，提高开发效率","ja":"Heady Code Generation AIエージェントを使用して、コード生成、変換、リファクタリングを自動化します","ko":"Heady 코드 생성 스킬을 사용하여 코드 생성, 변환, 리팩토링을 간소화하고 개발 속도를 높이세요","es":"Aprende a utilizar Heady Code Generation para generar, transformar y documentar código de manera eficiente con nuestros agentes de IA especializados","fr":"Découvrez comment utiliser Heady Code Generation pour générer, transformer et documenter du code avec nos agents d''IA spécialisés","de":"Erfahren Sie, wie Sie Heady Code Generation nutzen können, um Code zu generieren, zu transformieren und zu dokumentieren mit unseren spezialisierten IA-Agenten","pt":"Aprenda a usar o Heady Code Generation para gerar, transformar e documentar código com eficiência. Descubra as melhores práticas e ferramentas.","ru":"Узнайте, как использовать ИИ Агенты Heady Code Generation для генерации, трансформации и документации кода. Получите лучшие практики и инструменты.","ar":"تعرف على كيفية استخدام Heady Code Generation لإنشاء و تحويل و توثيق الكود بفعالية. استكشف أفضل الممارسات والأدوات."},"definition":{"en":"heady-code-generation is a skill that utilizes HeadySystems Inc.''s tools for code generation, transformation, and documentation, streamlining development workflows.","zh":"Heady 代码生成工具是一种代码生成、转换和重构的AI工具","ja":"Heady Code Generation AIエージェントは、コード生成、変換、リファクタリングを自動化するAIエージェントです","ko":"Heady 코드 생성 스킬은 코드 생성, 변환, 리팩토링을 자동화하는 AI 스킬입니다","es":"Heady Code Generation es una habilidad de IA que genera, transforma y documenta código","fr":"Heady Code Generation est une compétence d''IA qui génère, transforme et documente du code","de":"Heady Code Generation ist eine IA-Fähigkeit, die Code generiert, transformiert und dokumentiert","pt":"O que é Heady Code Generation? É uma ferramenta de geração de código que ajuda desenvolvedores a criar e transformar código de forma eficiente.","ru":"Что такое ИИ Агенты Heady Code Generation? Это инструмент генерации кода, помогающий разработчикам создавать и трансформировать код эффективно.","ar":"ما هو Heady Code Generation؟ هو أداة لإنشاء الكود تساعد المطورين على إنشاء و تحويل الكود بفعالية."},"features":{"en":["Full code generation from descriptions using mcp_Heady_heady_coder","Code transformation and documentation generation via mcp_Heady_heady_codex","Support for multi-file changes and orchestrating complex code modifications","Medium-speed code generation and transformation for efficient development","Utilizes Heady''s specialized code agents for precise code manipulation"],"zh":["全面的代码生成功能","代码转换和重构支持","多文件变更的编排功能","代码文档生成功能","语言转换支持"],"ja":["コード生成機能","コード変換とリファクタリングのサポート","マルチファイル変更のオーケストレーション機能","コード文書生成機能","言語変換のサポート"],"ko":["전체적인 코드 생성 기능","코드 변환 및 리팩토링 지원","다중 파일 변경의 오케스트레이션 기능","코드 문서 생성 기능","언어 변환 지원"],"es":["Generación de código completo desde descripciones","Transformación de código y generación de documentación","Orquestación de cambios en varios archivos","Uso de herramientas como mcp_Heady_heady_coder y mcp_Heady_heady_codex","Compatibilidad con múltiples lenguajes de programación","Integración con sistemas de control de versiones"],"fr":["Génération de code complet à partir de descriptions","Transformation de code et génération de documentation","Orchestration de modifications dans plusieurs fichiers","Utilisation d''outils tels que mcp_Heady_heady_coder et mcp_Heady_heady_codex","Compatibilité avec plusieurs langages de programmation","Intégration avec des systèmes de contrôle de version"],"de":["Vollständige Code-Generierung aus Beschreibungen","Code-Transformation und Generierung von Dokumentation","Orchestrierung von Änderungen in mehreren Dateien","Verwendung von Tools wie mcp_Heady_heady_coder und mcp_Heady_heady_codex","Unterstützung für mehrere Programmiersprachen","Integration mit Versionskontrollsystemen"],"pt":["Geração de código completo a partir de descrições","Transformação de código e geração de documentação","Suporte a múltiplos arquivos e linguagens de programação","Ferramentas especializadas como mcp_Heady_heady_coder e mcp_Heady_heady_codex","Velocidade média de processamento"],"ru":["Генерация полного кода из описаний","Трансформация кода и генерация документации","Поддержка нескольких файлов и языков программирования","Специализированные инструменты như mcp_Heady_heady_coder и mcp_Heady_heady_codex","Средняя скорость обработки"],"ar":["إنشاء الكود الكامل من خلال الوصف","تحويل الكود وإنشاء توثيق","دعم الملفات المتعددة و لغات البرمجة","أدوات متخصصة مثل mcp_Heady_heady_coder و mcp_Heady_heady_codex","سرعة المعالجة المتوسطة"]},"keywords":{"en":["how to use heady-code-generation","heady-code-generation alternative","heady-code-generation setup guide","what is heady-code-generation","heady-code-generation vs competitors","heady-code-generation install","mcp_Heady_heady_coder tutorial","code transformation with heady-code-generation","heady-code-generation for AI agents"],"zh":["Heady 代码生成工具","代码生成","代码转换","代码重构","AI代码生成","代码开发工具","代码自动化"],"ja":["Heady Code Generation AIエージェント","コード生成","コード変換","コードリファクタリング","AIコード生成","コード開発ツール","コード自動化"],"ko":["Heady 코드 생성 스킬","코드 생성","코드 변환","코드 리팩토링","AI 코드 생성","코드 개발 도구","코드 자동화"],"es":["Heady Code Generation","Agentes de IA","Generación de código","Transformación de código","Documentación de código","Desarrollo de software","Herramientas de IA","Tecnologías de código","Programación de software"],"fr":["Heady Code Generation","Outils d''IA","Génération de code","Transformation de code","Documentation de code","Développement de logiciels","Outils d''IA","Technologies de code","Programmation de logiciels"],"de":["Heady Code Generation","IA-Agenten","Code-Generierung","Code-Transformation","Code-Dokumentation","Software-Entwicklung","IA-Tools","Code-Technologien","Software-Programmierung"],"pt":["Heady Code Generation","geração de código","transformação de código","documentação de código","desenvolvimento de software","ferramentas de desenvolvimento","mcp_Heady_heady_coder","mcp_Heady_heady_codex"],"ru":["ИИ Агенты Heady Code Generation","генерация кода","трансформация кода","документация кода","разработка программного обеспечения","инструменты разработки","mcp_Heady_heady_coder","mcp_Heady_heady_codex"],"ar":["Heady Code Generation","إنشاء الكود","تحويل الكود","توثيق الكود","تنمية البرمجيات","أدوات التنمية","mcp_Heady_heady_coder","mcp_Heady_heady_codex"]}},"owner":"HeadyMe","repo":"Heady-pre-production-9f2f0642","repoPath":"HeadyMe/Heady-pre-production-9f2f0642","stars":1,"forks":0,"updatedAt":"2026-03-07T21:47:25Z","topics":[],"category":"community","skillMd":{"name":"heady-code-generation","description":"Multi-model code generation, refactoring, and inline suggestions using Heady™Coder, HeadyCodex, HeadyCopilot, and HeadyRefactor.","bodyPreview":"# Heady Code Generation Skill\n\nUse this skill whenever a task requires **generating, transforming, documenting, or refactoring code** through Heady''s specialized code agents.\n\n## Tools Overview\n\n| Tool | Best For | Speed |\n|------|----------|-------|\n| `mcp_Heady_heady_coder` | Full code generation from descriptions, scaffolding, orchestrating multi-file changes | Medium |\n| `mcp_Heady_heady_codex` | Code transformation, documentation generation, language conversion | Medium |\n| `mcp_Heady_heady","body":"# Heady Code Generation Skill\n\nUse this skill whenever a task requires **generating, transforming, documenting, or refactoring code** through Heady''s specialized code agents.\n\n## Tools Overview\n\n| Tool | Best For | Speed |\n|------|----------|-------|\n| `mcp_Heady_heady_coder` | Full code generation from descriptions, scaffolding, orchestrating multi-file changes | Medium |\n| `mcp_Heady_heady_codex` | Code transformation, documentation generation, language conversion | Medium |\n| `mcp_Heady_heady_copilot` | Inline suggestions, cursor-aware completions, quick fixes | Fast |\n| `mcp_Heady_heady_refactor` | Improving existing code quality — readability, performance, security | Medium |\n\n## Tool Details\n\n### HeadyCoder — `mcp_Heady_heady_coder`\n\n| Parameter | Type | Default | Purpose |\n|-----------|------|---------|---------|\n| `prompt` | string | **required** | Natural language description of desired code |\n| `action` | enum | `generate` | `generate`, `orchestrate` (multi-assistant), `scaffold` (project structure) |\n| `language` | string | optional | Target language (e.g., `javascript`, `python`) |\n| `framework` | string | optional | Target framework (e.g., `express`, `react`, `fastapi`) |\n\n**Use `orchestrate`** when the task involves creating or modifying multiple interdependent files.\n**Use `scaffold`** when setting up a new project structure.\n\n### HeadyCodex — `mcp_Heady_heady_codex`\n\n| Parameter | Type | Default | Purpose |\n|-----------|------|---------|---------|\n| `code` | string | **required** | Code to transform, or a prompt for generation |\n| `action` | enum | `generate` | `generate`, `transform`, `document` |\n| `language` | string | optional | Programming language |\n\n**Use `transform`** to convert code between patterns (e.g., callbacks → async/await).\n**Use `document`** to auto-generate JSDoc, docstrings, or inline comments.\n\n### HeadyCopilot — `mcp_Heady_heady_copilot`\n\n| Parameter | Type | Default | Purpose |\n|-----------|------|---------|---------|\n| `code` | string | **required** | Current code context |\n| `action` | enum | `suggest` | `suggest`, `complete` |\n| `language` | string | optional | Programming language |\n| `cursor_position` | int | optional | Cursor position for context-aware completion |\n\n### HeadyRefactor — `mcp_Heady_heady_refactor`\n\n| Parameter | Type | Default | Purpose |\n|-----------|------|---------|---------|\n| `code` | string | **required** | Code to refactor |\n| `language` | string | optional | Programming language |\n| `goals` | array | optional | e.g., `[\"readability\", \"performance\", \"security\"]` |\n| `context` | string | optional | Additional codebase context |\n\n## Decision Matrix\n\n```\nNeed new code from scratch?           → heady_coder (action: generate)\nNeed to scaffold a project?           → heady_coder (action: scaffold)\nNeed multi-file coordinated changes?  → heady_coder (action: orchestrate)\nNeed to transform existing code?      → heady_codex (action: transform)\nNeed to add documentation to code?    → heady_codex (action: document)\nNeed quick inline suggestions?        → heady_copilot\nNeed to improve code quality?         → heady_refactor\n```\n\n## Chaining Patterns\n\n### Generate → Refactor → Document\n\n```\n1. mcp_Heady_heady_coder(prompt=\"build X\", language=\"javascript\")\n2. mcp_Heady_heady_refactor(code=\"{result}\", goals=[\"performance\", \"readability\"])\n3. mcp_Heady_heady_codex(code=\"{refactored}\", action=\"document\")\n```\n\n### Generate → Battle Validate\n\nFor critical code, validate quality through competitive evaluation:\n\n```\n1. mcp_Heady_heady_coder(prompt=\"implement Y\")\n2. mcp_Heady_heady_battle(action=\"evaluate\", code=\"{result}\", criteria=\"production-readiness\")\n```\n\n## Tips\n\n- **Always specify `language`** — it dramatically improves output quality\n- **Include `framework`** when generating web code — framework-specific idioms matter\n- **Use `heady_refactor` with specific goals** — don''t just say \"refactor\", specify what you''re optimizing for\n- **Chain with `heady_patterns`** before refactoring to understand the existing architecture\n"},"lastSynced":"2026-03-08T02:00:48.041Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing advanced code generation and transformation capabilities using Heady''s specialized code agents.","zh":"非常适合需要使用Heady的专业代码代理来进行高级代码生成和转换功能的开发人员代理。","ja":"Headyの専門的なコードエージェントを使用して高度なコード生成および変換機能を必要とする開発者エージェントに最適です。","ko":"Heady의 전문 코드 에이전트를 사용하여 고급 코드 생성 및 변환 기능을 필요한 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan capacidades de generación y transformación de código avanzadas utilizando los agentes de código especializados de Heady.","fr":"Parfait pour les Agents de Développeur ayant besoin de capacités de génération et de transformation de code avancées utilisant les agents de code spécialisés de Heady.","de":"Perfekt für Entwickleragenten, die erweiterte Code-Generierungs- und Transformationsfunktionen mit Headys spezialisierten Codeagenten benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de capacidades avançadas de geração e transformação de código usando os agentes de código especializados da Heady.","ru":"Идеально подходит для агентов-разработчиков, которым требуются продвинутые возможности генерации и преобразования кода с использованием специализированных кодовых агентов Heady.","ar":"مثالي لعميل المطور الذين يحتاجون إلى إمكانيات متقدمة لتوليد و تحويل الشفرة باستخدام وكلاء الشفرة المتخصصين من Heady."},"recommendation":{"en":"Empowers agents to generate, transform, document, or refactor code using mcp_Heady_heady_coder and mcp_Heady_heady_codex, supporting full code generation from descriptions, scaffolding, orchestrating multi-file changes, code transformation, documentation generation, and language conversion.","zh":"赋予代理生成、转换、文档化或重构代码的能力，使用mcp_Heady_heady_coder和mcp_Heady_heady_codex，支持从描述生成完整代码、脚手架、编排多文件更改、代码转换、文档生成和语言转换。","ja":"mcp_Heady_heady_coderおよびmcp_Heady_heady_codexを使用して、エージェントがコードを生成、変換、文書化、またはリファクタリングできるようにし、説明から完全なコードの生成、スキャフォールディング、複数ファイルの変更のオーケストレーション、コード変換、ドキュメントの生成、言語の変換をサポートします。","ko":"mcp_Heady_heady_coder와 mcp_Heady_heady_codex를 사용하여 에이전트가 코드를 생성, 변환, 문서화 또는 리팩토링 할 수 있도록 하며, 설명에서 완전한 코드 생성, 스캐폴딩, 여러 파일의 변경을 오케스트레이션, 코드 변환, 문서 생성 및 언어 변환을 지원합니다.","es":"Habilita a los agentes a generar, transformar, documentar o refactorizar código utilizando mcp_Heady_heady_coder y mcp_Heady_heady_codex, y admite la generación completa de código a partir de descripciones, la creación de scaffolding, la orquestación de cambios en varios archivos, la transformación de código, la generación de documentación y la conversión de lenguaje.","fr":"Permet aux agents de générer, de transformer, de documenter ou de refactoriser du code en utilisant mcp_Heady_heady_coder et mcp_Heady_heady_codex, et prend en charge la génération complète de code à partir de descriptions, la création de scaffolding, l''orchestration de modifications multi-fichiers, la transformation de code, la génération de documentation et la conversion de langage.","de":"Ermächtigt Agenten, Code zu generieren, zu transformieren, zu dokumentieren oder zu refaktorisieren, indem mcp_Heady_heady_coder und mcp_Heady_heady_codex verwendet werden, und unterstützt die vollständige Code-Generierung aus Beschreibungen, das Erstellen von Scaffolding, die Orchestrierung von Änderungen in mehreren Dateien, die Code-Transformation, die Generierung von Dokumentation und die Sprachkonvertierung.","pt":"Habilita os agentes a gerar, transformar, documentar ou reestruturar código usando mcp_Heady_heady_coder e mcp_Heady_heady_codex, com suporte à geração completa de código a partir de descrições, criação de estruturas, orquestração de alterações em vários arquivos, transformação de código, geração de documentação e conversão de linguagem.","ru":"Наделяет агентов возможностью генерировать, преобразовывать, документировать или рефакторить код с использованием mcp_Heady_heady_coder и mcp_Heady_heady_codex, поддерживая полную генерацию кода из описаний, создание каркаса, оркестровку изменений в нескольких файлах, преобразование кода, генерацию документации и конвертацию языка.","ar":"يمكن الوكلاء من توليد و تحويل و توثيق أو إعادة هيكلة الشفرة باستخدام mcp_Heady_heady_coder و mcp_Heady_heady_codex، مع دعم كامل لتوليد الشفرة من وصفات، وتوفير هيكل، وتنسيق التغييرات في ملفات متعددة، وتحويل الشفرة، وتوليد توثيق، وتحويل اللغة."},"useCases":{"en":["Generating full code from descriptions using mcp_Heady_heady_coder","Transforming and documenting code with mcp_Heady_heady_codex","Refactoring codebases through Heady''s specialized code agents"],"zh":["使用mcp_Heady_heady_coder从描述生成完整代码","使用mcp_Heady_heady_codex转换和文档化代码","通过Heady的专业代码代理重构代码库"],"ja":["mcp_Heady_heady_coderを使用して説明から完全なコードを生成する","mcp_Heady_heady_codexを使用してコードを変換および文書化する","Headyの専門的なコードエージェントを使用してコードベースをリファクタリングする"],"ko":["mcp_Heady_heady_coder를 사용하여 설명에서 완전한 코드를 생성하는 것","mcp_Heady_heady_codex를 사용하여 코드를 변환 및 문서화하는 것","Heady의 전문 코드 에이전트를 사용하여 코드베이스를 리팩토링하는 것"],"es":["Generación de código completo a partir de descripciones utilizando mcp_Heady_heady_coder","Transformación y documentación de código con mcp_Heady_heady_codex","Refactorización de bases de código a través de los agentes de código especializados de Heady"],"fr":["Génération de code complet à partir de descriptions en utilisant mcp_Heady_heady_coder","Transformation et documentation de code avec mcp_Heady_heady_codex","Refactorisation de bases de code via les agents de code spécialisés de Heady"],"de":["Generierung von vollständigem Code aus Beschreibungen unter Verwendung von mcp_Heady_heady_coder","Transformation und Dokumentation von Code mit mcp_Heady_heady_codex","Refaktorisierung von Codebasen durch Headys spezialisierte Codeagenten"],"pt":["Gerar código completo a partir de descrições usando mcp_Heady_heady_coder","Transformar e documentar código com mcp_Heady_heady_codex","Reestruturar bases de código por meio dos agentes de código especializados da Heady"],"ru":["Генерировать полный код из описаний с использованием mcp_Heady_heady_coder","Преобразовывать